window.QUIZ_INTANGIBLE = (window.QUIZ_INTANGIBLE||[]).concat([{"q":"서천 ○○○○○는 모시짜기로 유명한 한산지방을 중심으로 발달한 베짜기에 관한 민속놀이로 주로 부녀자들의 가내수공업이었다. 신라 유리왕(재위 24∼57)이 두 왕녀로 하여금 부내의 여자들을 나누어 길쌈을 하게 하고, 추석날에 결과를 심사하여 진 편에서 이긴 편에게 술과 음식을 대접하였다는 『삼국사기』기록으로 미루어 일찍부터 모시길쌈이 있었으며, 나라에서도 이를 장려하였다는 것을 알 수 있다. ○○○○는 모시를 베어다 모시베끼기, 모시삼기, 모시꾸리감기, 모시날기, 모시매기, 모시짜기 등으로 이어지는 일련의 과정을 노래와 행위로 표현하고 있다. 노래는 민요풍으로 여인네의…","a":"서천저산팔읍길쌈놀이","c":"시도무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643979.jpg"},{"q":"‘○○’는 바닷물이 일정하게 순환하는 것을 인지하는 전통지식으로, 지구와 달을 중심으로 한 천체운동의 결과로 발생하는 조석간만에 따라 조류(潮流)의 일정한 주기를 역법(曆法)화 한 것이다. ‘○○’의 체계 중에서 하루 단위인 ‘밀물·썰물’에 대한 지식은 『고려사』에서부터 등장하고 『태종실록』의 ‘육수(六水)’와 ‘십수(十水)’의 표기를 통해 조선초기부터 조류의 흐름을 독자적인 역법으로 체계화했음을 알 수 있다. 조선후기에는 ○○를 역법으로서 15일 단위의 순환형 조석표로 기록하였으며 『여암전서(旅菴全書)』, 『연경재전집(硏經齋全集)』 등의 문헌을 통해 확인할 수 있다…","a":"물때","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2026032710272400.jpg"},{"q":"옻칠은 옻나무에서 채취하는 수액을 용도에 맞게 정제하여 기물에 칠하는 것으로 방습, 방충, 방열 등으로 활용 할 수 있으며 특히 보존성과 아름다움이 우수하여 다양하게 활용 가능한 전통성을 간직한 칠이다. 옻칠은 나라마다 다양한 제작기법으로 완성해 왔는데, 중국은 조칠기법, 일본은 마끼에 시회기법, 우리나라는 나전칠기법과 건칠기법이 있다. 기능보유자 김성호는 1972 년입문하여 나전장 김봉룡과 이성운에게서 옻칠을 배워 연마해온 장인이다. 나전칠기법과 건칠기법기능을 섭렵하였고 특히 모시나 삼베를 심으로 하여 칠을 입히는 건칠기법에 뛰어난 솜씨를 지니고 있다. 건칠기법은…","a":"칠장","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643942.jpg"},{"q":"‘○○○’는 우리나라뿐만 아니라 전 세계적으로 존재하는 문화이나 우리나라의 ‘○○○’는 고대부터 지금까지 그 맥이 끊이지 않고 현재까지 이어지고 있다. 활을 만들고 다루는 방법, 활을 쏘는 방법, 그리고 활을 쏠 때의 태도 및 마음가짐 등에서 우리만의 고유성을 보유하고 있는 우리 민족의 문화적 자산이다. ‘○○○’에 대한 기록은 삼국시대부터 찾아 볼 수 있고, 각종 관찬(官撰) 자료는 물론 조선시대 선비들의 문집(文集), 당대 풍속화에서도 다양하게 찾아 볼 수 있으며, 특히 무예사를 연구하는 데 있어 학술적으로 중요한 역할을 담당하고 있다. 또한, 뽕나무·뿔·소힘줄·…","a":"활쏘기","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2020073010401300.jpg"},{"q":"○○○는 나라의 평안과 태평성대를 기리는 뜻을 춤으로 표현한 것이다. 유래는 확실치 않으나 1900년대의 무용가이며 명고수였던 한성준이 경기 무속춤을 재구성하여 추었던 춤의 하나로 알려져 있다. 남녀가 왕과 왕비의 복장을 하여 궁중풍의 웅장하고 화려함을 보여 주며, 춤장단은 진쇠, 낙궁, 터벌림, 도살풀이 등으로 다른 춤장단에 비해 구성이 복잡하고 까다롭다. 장단의 변화와 함께 겹걸음, 잔걸음, 무릎들어 걷기, 뒷꿈치 꺾기 등 디딤새의 기교가 현란하면서도 조급하지 않은 절제미를 보여준다. 동작이 섬세하고 우아하며 동작 하나하나에 절도가 있는데, 이동안류의 춤은 서민적…","a":"태평무","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623341.jpg"},{"q":"‘○○’이란 석조물을 제작하는 장인으로, 주로 사찰이나 궁궐 등에 남아있는 불상, 석탑, 석교 등이 이들의 작품이라 할 수 있다. 삼국시대부터 오늘에 이르기까지 다양하고 다채로운 석조문화유산이 전해지고 있어 우리나라의 석조물 제작 기술이 상당한 수준에 이르렀음을 알 수 있다. 석공예의 재료는 전국적으로 가장 많이 분포되어 있는 화강암을 비롯하여 납석과 청석, 대리석 등이 활용되고 있다. 전통적인 ○○들은 망치, 정 등 수공구를 사용하여 돌이라는 단단한 물질에 생명력을 불어넣어 수준 높은 석조문화를 탄생시키고 발전시켜왔다.","a":"석장","c":"시도무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644156.jpg"},{"q":"○○은 조선후기 연행문화 속에서 자리 잡은 춤으로 모든 춤의 기본이 되는 춤이며, 특히 김숙자 류(金淑子 流) ○○은 춤의 기법이 독특하고 체계적으로 구성되어 있는 전통춤으로 그 종목의 기능을 보존하기위해 무형유산으로 지정가치가 있다.","a":"입춤","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643596.jpg"},{"q":"○○○○○는 익산지역에서 전해 내려오는 민요로 지게를 진 나무꾼들이 작대기로 지게의 다리인 목발을 두드리며 부르던 노래이다. ○○○○란 산타령, 등짐노래, 지게○○○○, 작대기타령, 둥당기타령, 상사소리 등 6곡을 하나로 묶은 노래의 명칭을 말한다. ○○○○는 나무꾼들이 무거운 짐을 질 때, 가벼운 짐을 질 때, 빈 지게로 나갈 때 등에 따라 노래가 달라지므로 여러 가지 곡조의 장단이 나타나고 있다. 나무나 풀을 벨 때는 느린 진양조장단의 산타령을, 그 후 나무를 짊어지고 내려올 때는 느린 중모리장단의 등짐노래를 부른다. 마을로 돌아올 때나 나뭇짐을 지고 신바람이 나…","a":"익산목발노래","c":"시도무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644054.jpg"},{"q":"오광대는 남부지역의 탈춤을 가리키는 말로, 오광대란 이름은 오행설(五行說)에서 유래된 오(五)에서 온 것이라는 의견이 유력하다. 이 놀이는 정월 초하룻날 천룡제를 지낸 다음 지신밟기를 하다가 대보름날 밤에 행해진다. ○○○○○의 유래는 100년 전 어느 봄에 가산의 바닷가에 궤짝이 표류해 와 주민들이 열어보니 탈과 놀이의 대사가 적혀 있는 문서가 들어 있었으며 탈은 궤에 보관하다가 놀이 때에만 썼다고 한다. ○○○○○ 놀이는 오방신장무·영노춤·문둥이춤·양반춤·중춤·할미와 영감춤의 6마당으로 구성되어 있고, 민중의 삶의 모습을 반영하고 있으며 양반과 파계승에 대한 풍자…","a":"가산오광대","c":"국가무형유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624158.jpg"},{"q":"전통화살 죽시(竹矢)는 일곱가지 천연재료[대나무(시누대), 싸리나무, 도피(복숭아나무 껍질), 어교(물고기 부레 풀), 쇠심(소의 힘줄), 치우(꿩 깃털), 촉]로 이루어지는 것으로 특히, 곧고 단단한 시누대가 가장 중요한 재료이다. 대나무를 불에 구워 바르게 펴서 그 직선도가 오래 유지될 수 있도록 하는 것이 화살의 생명인 명중률을 높이는 관건이다. ○○○○○ 김병욱은 전통성을 이어받은 화살, 즉 죽시(竹矢) 제작 기술과 우수한 기량을 보유하고 있으며 이를 잘 이행하여 전통의 맥을 이어가고 있다.","a":"포항 궁시장","c":"시도무형유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018111209273400.JPG"},{"q":"방자유기는 불에 녹여낸 합금덩어리를 망치로 두드려서 만들어내는 유기를 말하며, 구리와 주석을 78:22로 합금하여 만든다. 이 비율이0.01%라도 틀리거나 아연이나 다른 합금이 조금이라도 섞이면 두드 리는 과정에서 터져버린다. 방자는 징과 꽹과리 같은 타악기를 만드는데 주로 사용되며 손으로 만져도 손자국이 나지 않고 독성이 없기때문에 식기류 전반에 쓰인다. 방자는 아무리 실력이 뛰어난 사람도 혼자서는 제작할 수 없고 6명이 한조를 이루어야 한다. 한사람은 화로에 바람을 넣어주는 풍금을 잡고, 한사람은 쇠를 다시 불에 달군다. 한사람이 달군 쇠를 집게로 잡으면서, 세…","a":"방짜유기장","c":"시도무형유산","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643624.jpg"},{"q":"김삼식씨는 1946년 9월 9일에 경상북도 ○○시 농암면 내서리 131번지에서 태어났으며, 9세때 아버지를 여의고 땅 한평 없는 막막한 처지에서 자형의 사촌인 유영운(남, 80세, 농암면 갈동리)씨가 운영하는 닥공장에 들어가 한지 만드는 일을 거들며 온갖 허드렛일을 하다가 11세때부터 한지와 본격적인 인연을 맺어 지금까지 48년간 선조들이 발달시킨 독특한 제조기법으로 한지를 만들고 있다. 30여년 전만해도 ○○지역에는 20여개소의 한지 공장이 있었으나 지금은 김삼식씨가 운영하는 한 곳 뿐이다.전통한지는 모든 작업이 수작업으로 이루어지는 등 만드는 과정이 너무 까다롭고…","a":"문경 한지장","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/0000000001644381.jpg"},{"q":"장도(粧刀)는 몸에 지니는 조그마한 칼로서 남녀 구별없이 호신용 또는 장신구로 사용되었다. 허리띠나 옷고름에 노리개와 함께 차고 다니기 때문에 패도(佩刀)라고도 하고, 장도 중에서 주머니속에 넣고 다니는 것은 낭도(囊刀)라고 한다. 이러한 장도를 만드는 기술과 그 기능을 가진 사람을 ○○○이라 한다. 고려시대부터 성인 남녀들이 호신용으로 지니고 다녔으며 특히 조선시대 임진왜란(1592) 이후부터는 사대부 양반가문의 부녀자들이 순결을 지키기 위해 필수적으로 휴대했다. 조선 후기 이후부터는 손칼로서의 실질적인 기능보다 상징성과 장식성이 강조되어 여인들의 노리개장식 일부가…","a":"장도장(은장도)","c":"시도무형유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644452.jpg"},{"q":"\"진다리는 광주 백운동의 옛 지명으로, 안종선씨의 할아버지가 진다리에 정착하여 붓을 만들면서 그 붓이 유명해져 진다리붓이라고 불리게 되었다. 진다리붓은 광주의 특산물 가운데 으뜸가는 것으로 안씨의 할아버지부터 아들에 이르기까지 4대에 걸쳐 이곳에서 진다리붓을 만들고 있다. 진다리붓 만들기 과정은 붓의 생명인 털에서 시작된다. 털은 첨(尖)·제(濟)·원(圓)·건(健)의 네가지 덕을 갖추어야 하는데, 이는 붓끝이 뾰족해야 하고 가지런해야 하며, 털은 원형을 이루고 힘이 있어서 한획을 긋고 난 뒤에 붓털이 다시 일어나야 한다는 것이다. 우리나라에서는 족제비 꼬리털을 많이…","a":"필장","c":"시도무형유산","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018103014145900.jpg"},{"q":"○○○는 말 그대로 풀로 피리를 연주하는 것을 말한다. 나뭇잎이나 풀잎을 접어 입술에 대고 휘파람을 불듯이 소리를 내어 연주하는데 한자로 초적草笛이라고 부르기도 한다. 복숭아나 유자 나무 잎을 많이 사용한다고 한다. ○○○에 대한 기록은 『수서』 「동이전東夷傳」에 등장하는 갈대피리 혹은 갈잎피리의 기록이 가장 오래 되었고, 고려시대 이규보의 ‘문가성’이라는 시의 ‘누가 숲속에서 푸른 잎 하나를 따다가, 입에 물고 불어서 맑은 소릴 내는고’라는 구절에도 초적 연주 모습이 그려지고 있다. 1493년 조선 성종 때 성현 등이 편찬한 『악학궤범樂學軌範』에는 향악기의 하나로…","a":"풀피리","c":"시도무형유산","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018012413072500.jpg"},{"q":"충청남도 공주시 신풍면 ○○○에서 전승되는 민속놀이로 지게가 농사일이나 땔나무를 하러 다닐 때 중요한 운반도구로 사용된 점에 착안하여 형성된 놀이로 알려져 있다. 놀이 방법에 따라 12종으로 구성되는데 「지게 상여」, 「지게 풍장놀이」, 「지게 장단노래」, 「지게 지네발놀이」, 「지게 걸음마」, 「작대기 걸음마」, 「지게 썰매」, 「작대기 싸움」, 「지게·작대기 꼬누기」, 「지게 힘자랑」, 「호맹이 끌기」 등이다. 2002년에는 전국민속예술경연대회에 참가하여 장려상을 수상하였고 2004년에는 이러한 의미와 가치를 인정받아 충청남도 무형유산으로 지정되었다.","a":"공주선학리지게놀이","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026022315174401.JPG"},{"q":"지승공예는 종이를 꼬아 엮어서 그릇을 만드는 것으로 일명 ’노엮개’라고도 한다. 발생연대는 정확히 알 수 없으나 조선시대에 종이로 된 그릇이 많았다는 기록으로 보아 그 이전부터 전해진 것으로 추측된다. 만드는 방법은 한지를 잘라 새끼를 꼬듯이 물에 적셔서 꼰다. 꼰 종이끈을 반으로 접어 한 올씩 엮어간다. 무늬나 형태는 자유자재로 바꿀 수 있으며, 형태를 갖춘 종이그릇에 본드를 칠한다. 마지막으로 페인트의 일종인 캐슈로 윤을 내면 완성된다. 지승(종이끈)으로 바구니, 쟁반, 멜빵, 신발(미투리) 등을 만든다. ○○○○는 전통공예기술로서 기술을 전승하고 보호하기 위해…","a":"지승제조","c":"시도무형유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643947.jpg"},{"q":"‘○○○’는 양편으로 나뉘어 윷가락 4개를 던져, 윷가락이 엎어지고 젖혀진 상태에 따라 윷판의 모든 말을 목적지에 먼저 도달시키는 편이 이기는 놀이로, 정초(正初)부터 정월대보름까지 가족 및 마을공동체를 중심으로 지속적으로 전승·유지되어 왔다. 또한, 산업화·도시화로 급격히 와해되는 사회변화에도 불구하고 오랜 역사와 전통 속에서 단절 없이 지금까지 우리 민족의 정체성과 가치를 담은 대표적인 전통 놀이문화로 자리매김해왔다. 역사문헌에서 ‘윷’의 유래와 역사를 살펴보면 삼국시대와 고려시대 문헌에서는 윷을 직접적으로 나타내는 용어를 발견하지 못하였으나, 윷을 ‘저포(樗蒲)…","a":"윷놀이","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2022111114442500.jpg"},{"q":"남진세는 1972년부터 석공의 길에 입문하여 외삼촌 박범칠로 부터 기술을 습득하였고, 1980년대 이후 지역에서 탁희열로 부터 불상조각을 배웠으며, 탁희열은 왜관출신 배상소-나진수로 이어지는 전승계보를 지녔다. 그는 현재까지 무수히 많은 작품을 제작하였으며, 다양한 종류의 정과 메. 도드락망치 등의 전통연장을 갖추고 전통방식으로 돌을 다듬으며 석공으로서 그 맥을 잇고 있다. 또한, 대한민국 명장(석공)으로 지정되었고, 공예대전에 수차례 입상하는 등 기량 면에서는 객관적인 자료가 입증하고 있으며, 현장조사 시연과정에서도 전반적으로 부족함이 없이 우수한 기능적 측면을 보…","a":"칠곡 석장","c":"시도무형유산","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022011416504800.png"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 농악을 공연하는 목적에 따라 종류를 나누어 보면 당산굿·마당밟이·걸립굿·두레굿·판굿·기우제굿·배굿 등으로 나눌 수 있고, 지역적 특성에 따라 분류하면 경기농악·영동농악·호남우도농악·호남좌도농악·경남농악·경북농악으로 갈라진다.경남농악의 한 종류인 ○○○○은 음력 1월 초에 집집마다 돌아가면서 농악을 치고 고사를 지내며 복을 빌어주는 걸립굿이 주류를 이룬다. 다른 농악에 비해 느린 4박자로 굿거리장단이 많고 춤이 많이 들어가 있다.강인함과 부…","a":"부산농악","c":"시도무형유산","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643416.jpg"},{"q":"자수(刺繡)는 여러 색깔의 실을 바늘에 꿰어 바탕천에 무늬를 수놓아 나타내는 조형활동이다. 자수의 유래는 직조기술의 발달과 함께 한 것으로 여겨지지만 기록상으로는 삼국시대부터 확인된다. 고려시대에는 일반백성의 의복에까지 ○○○식이 성행할 정도로 사치가 심해 여러 번 금지하기도 하였다. 조선시대에 들어서는 궁수(宮繡:궁중에서 수방나인에 의해 정교하게 만들어진 수)와 민수(民繡:민간에서 일반적으로 만들어진 수)로 크게 구분되는 뚜렷한 특징을 보이면서 발전하였다. 자수의 재료로는 바늘과 바탕천, 평사(平絲)·합사(合絲)·연사(撚絲)의 색실과 틀 등이 있다. 주요기법에는 돗…","a":"자수장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624402.jpg"},{"q":"○○○는 서울과 경기도 일대를 중심으로 전승되어 오는 마을신앙의 대표적인 갈래이다. ○○○의 세부적인 신앙형태와 의례 절차는 지역에 따라 차이가 있으나, 마을신을 제장에 모셨다 돌려보내는 구조적 측면에서는 공통성을 찾아 볼 수 있다. ○○○○○ 또한 도당할아버지와 도당할머니를 모셔 의례를 행한 후 돌려보내는 구조를 가지고 있다. 보유자가 없는 종목이며, 2010년 11월 4일에 ○○○○○보존회가 보유단체로 인정받았다.","a":"삼각산 도당제","c":"시도무형유산","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409280600.jpg"},{"q":"○○○○란 서울과 경기도 지방에서 전승되는 민요이지만, 국가무형유산으로 지정된 ○○○○는 '경기좌창'이라 불리는 '경기긴잡가'이다. 잡가는 가곡이나 가사와 같은 정가(正歌)와 대비되는 속가(俗歌)라는 뜻으로 쓰였으나, 오늘날에는 속가 중에서도 긴형식의 노래를 앉아서 부르는 것을 잡가라 한다. 경기잡가 가운데 느린 장단으로 된 12잡가를 긴잡가라 한다. 경기긴잡가는 유산가, 적벽가, 제비가, 소춘향가, 선유가, 집장가, 형장가, 평양가, 십장가, 출인가, 방물가, 달거리 등 12곡으로 구성되어 있다. 유산가는 산천경치를 노래한 것이고, 소춘향가, 집장가, 십장가, 형장…","a":"경기민요","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624346.jpg"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로 꽹과리·징·장고·북과 같은 타악기를 치며 벌이는 음악을 두루 가리킨다. 농악을 공연하는 목적에 따라 종류를 나누어 보면 당산굿·마당밟이·걸립굿·두레굿·판굿·기우제굿·배굿 등으로 나눌 수 있고, 지역적 특징에 따라 분류하면 경기농악·영동농악·호남우도농악·호남좌도농악·경남농악·경북농악으로 갈라진다. ○○○○은 마을 개척시기부터 해마다 정월 대보름 마을제사를 지내는 한 과정으로 행해져온 것이라 전해진다. 농악의 과정은 농기구를 앞세우고 상쇠를 선두로 징·북·장구·상모·잡색이 농악이 행해질 곳으로 향하는 길매구, 상쇠의 지…","a":"고산농악","c":"시도무형유산","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643463.jpg"},{"q":"○○○이란 활과 화살을 만드는 기능과 그 기능을 가진 사람을 말한다. 활을 만드는 사람은 궁장(弓匠), 화살을 만드는 사람은 시장(矢匠)이라 한다. 본래 우리 민족의 활 만드는 기술은 오래전 부터 세계 어느 민족보다 탁월한 기교를 가졌다고 전해진다. 중국에서는 한국 민족을 활을 잘 만들고 잘 쏘는 동쪽의 민족이라는 뜻에서 ‘동이’라고 하였다. 고구려 활의 형태는 벽화속에서 볼 수 있는데 현재 사용하는 국궁과 같은 모습을 하고 있어 한국의 전통활은 이때부터 변함없이 이어진 것으로 생각된다. 고려시대에도 활쏘기를 중요시했으며, 조선 전기에는 과거시험의 무과과목에 궁술이…","a":"궁시장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623557.jpg"},{"q":"청련사 ○○○○○는 매년 중양절마다 불교 악가무의 종합예술을 곁들여, 불자들이 내세를 위해 성전에 미리 공덕을 짓고, 수행하도록 불법으로 이끄는 불교의례이다. 청련사는 조선 초기 \"동백련 서백련\"의 양 열반계 사찰로 지정되어 도성의 비보사찰이자, 왕생발원사찰로서 왕실의 국태민안을 위한 다양한 재회가 발달하였고, 그 가운데 사후 정토왕생을 위해 미리 복을 짓는 예수재가 1960년대부터 설행되기 시작하였다. 2010년에 보존회가 발족하였으며, 보존회와 안정불교대학을 중심으로 예수재의 체계적인 전승과 교육이 이뤄지고 있다. 예수재의 활성화를 위해 설행시기를 \"윤달이 든 해…","a":"생전예수재","c":"시도무형유산","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022090519502900.png"},{"q":"‘○○○○’는 전문적인 장인이 궁중의 연희나 의례 목적에 맞게 비단, 모시 등으로 제작한 꽃으로 궁중에서 존중의 뜻을 표현하거나, 평화·장수·건강 등의 상징으로 꽃을 이용한 궁중 문화의 특징을 잘 보여주고 있다.","a":"궁중채화","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1787953.jpg"},{"q":"○○○○○는 구 전주부 우전면 계룡리 비아･정동･용산･함대마을(현재의 전주시 삼천동 2가) 일원에 수백 년간 이어진 민속놀이로, 다른 이름은 계룡리합굿이다. 합굿의 구성 중에 용기놀이가 널리 알려져 지금은 ○○○○○를 대표명칭으로 사용하고 있다. 일제 강점기에 단절된 다른 지역과 달리 해방 후까지 명맥을 이었다가 잠시 단절되었으나 1997년에 재현하여 현재까지 이어오고 있다. 한해 농사일이 마쳐 가는 7월 백중 즈음에 한 마을의 초대로 상･하촌이 한데 모여 힘과 기예를 겨루며, 농사일의 피로를 씻고 쌓인 허물과 다툼을 풀어내며 협동의 기반을 만들어 내는 전통민속문화이…","a":"전주기접놀이","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093016290600.jpg"},{"q":"○○○○○은 망자의 원혼을 위로하고 저승 천도를 위해 전남 ○○지역에서 벌이는 굿이다. ○○○의 구성은 전반부, 중반부, 후반부로 구성되어 있는데, ○○○○○은 전반부: 안당–선부리-오구굿-제석굿-손님굿, 중반부: 넋올리기-고풀이-씻김-길닦음, 후반부: 퇴송으로 구성되어 있다. ○○○○○은 오구굿이 중반부가 아닌 전반부에 연행된다는 점이 가장 특징이다. 인접지역인 진도에는 오구굿이 없고, 신안․순천 지역에서는 제석굿 다음에 중반부에서 오구굿을 진행한다. 또한 선부리에 성주풀이·액막이가 결부되어 있다는 점이 타 지역과 비교된다. ○○○○○ 보유자인 이수자는 9대째 뛰어…","a":"해남 씻김굿","c":"시도무형유산","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022090606591100.JPG"},{"q":"○○○는 한 명의 소리꾼이 고수의 장단에 맞추어 창(소리),말(아니리), 몸짓(너름새)을 섞어가며 긴 이야기를 엮어가는 것을 말한다. 보유자 정순임(鄭順任)의 박녹주바디 ○○○○○ 계보는 분명한 예능적의 보유자인 『송만갑 - 김정문 - 박녹주 - 박송희(박정자) - 정순임』으로 잇고 있으며, 무형유산 가야금병창 보유자였던 고)장순애(장월중선)의 장녀로 태어나 예술적 재능도 모친으로부터 물려받았다. 10세 전후에 벌써 심청가, 춘향가, 등을 배웠고, 계속해서 ○○○, 수궁가,열사가 등을 배웠다. 정순임은 뛰어난 ○○○ 기량으로 1985년 남도예술제 ○○○부 특장부 대상…","a":"판소리흥보가","c":"시도무형유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016042210122600.JPG"},{"q":"나전은 얇게 간 조개껍질을 여러 무늬로 만들어 물체에 붙이는 것으로 우리나라에서는 자개라는 고유어를 쓴다. 나전칠기는 나전무늬를 물체에 붙이고 위에 옻칠을 해서 만들어낸 공예품을 일컬으며 ○○○은 이러한 기술이나 기능을 가진 사람을 말한다. 나전칠기 기술은 중국 당나라에서 전래된 것으로 추측된다. 우리나라에서는 신라시대의 고분에서 칠기가 다량 출토되고 있으며 백제·삼한시대의 칠기도 출토되는 것으로 보아, 삼국시대에 이르러 일반적인 생활용기로 널리 사용했었던 것을 짐작할 수 있다. 제작과정을 보면 나무로 화장대, 교자상 등의 공예품 기본 틀인 백골을 짠다. 백골의 표면…","a":"나전장","c":"시도무형유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018110114535400.jpg"},{"q":"○○는 승복을 입고 추는 춤으로 우리나라의 대표적인 민속춤 가운데 하나이다. ○○는 흔히 무복(舞服) 때문에 중춤이라고도 하지만 불교의식에서 승려가 추는 춤과는 다르다. ○○의 유래는 불교문화사적 입장에서 본 불교설과 김만중 소설 중 구운몽에서 나왔다는 설, 탈놀음 중에서 노장춤과 파계승의 번뇌에서 비롯된 춤이라는 설 중 어느 것이 확실한지 알 수 없으나, 1910년대쯤 기방에서 발전되었다고 한다. 춤의 형태는 의식성이나 종교성, 생산성, 극성, 놀이성이 전혀 담겨 있지 않은 홀춤[독무(獨舞)]으로, 춤사위가 살풀이춤과 유사함을 지니고 있어 기녀들에 의해 예술적인 춤…","a":"승무","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624318.jpg"},{"q":"○○○이란 전통 신을 만드는 장인으로, 조선시대 신목이 있는 신발인 화(靴)를 제작하는 ‘화장(靴匠)’과 신목이 없는 신발인 혜(鞋)를 제작하는 ‘혜장(鞋匠)’을 통칭한 것이다. 조선시대『경국대전』의하면 중앙관청에 소속된 화장은 16명, 혜장은 14명이었다고 한다. 이 기록을 통해 볼때 당시 신에 대한 수요가 많았으며, 그 기능도 분화되어 있었음을 알 수 있다. 혜(鞋)의 제작과정은 여러 겹의 광목이나 모시를 붙인 백비 위에 공단을 붙여 신울(발등을 감싸는 부분)을 준비하고 소가죽으로 신 밑창을 만든 뒤 신울과 밑창을 맞바느질하여 연결한다. 이때 중심이 틀어져 신코가…","a":"화혜장","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623385.jpg"},{"q":"○○은 옻나무에서 채취하는 수액을 용도에 맞게 정제해 기물에 칠하는 장인을 말한다. 보유자 문재필은 전성규—심부길—정수화로 이어지는 전승 계보를 이었으며, 지난 1992년부터 정수화(국가무형유산 ‘○○’ 보유자)의 문하생으로 옻칠 정제에 대한 전통적 기능을 전수받았다. 옻칠의 역사는 매우 오래되었고, 삼국시대 이래 우리나라에서도 옻칠과 나전칠기의 기술이 독자적으로 발달되었다. 옻칠은 천연재료를 이용한 항균, 방부, 방수, 방취, 방염 및 접착제라고 할 수 있으며, 전통 옻칠공예의 아름다움과 실용적 가치는 그 우수함이 널리 알려졌다. 옻나무에서 채취한 생옻은 수분을 제…","a":"논산 칠장","c":"시도무형유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020062320124400.jpg"},{"q":"○○은 대장장이를 말한다. 철과 같은 금속을 녹여 망치로 두들겨 모양을 만들고 다듬어 농기구, 무기류 등을 만드는 장인이다. ○○ 보유자로 지정된 김한일은 1960년부터 대장간에서 일을 배우기 시작했다. 대장간은 과거 남부시장 등에 수십곳이 성행했으나 현재는 거의 사라졌으며, 몇몇 곳이 명맥을 잇고 있다. 주로 전통 칼이나 농사에 필요한 농기구, 생활용품 등을 제작하고 있으며, 주문제작도 하고 있다. 2008년 노동부 지정 전통기능전승자로 지정되었으며, 전라북도 공예품경진대회나 전승공예대전에서 입상하기도 하였다.","a":"야장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093016314200.jpg"},{"q":"산조아쟁은 우리민족의 독창성이 빚어낸 악기이며 산조 또한 판소리에 못지 않게 세계문화유산에 지정될만한 음악이다. 산조는 무속과 판소리에 뿌리를 둔만큼 우리민족의 역사와 전통을 그대로 담고 있으며, 산조의 형성과 발전과정을 통해 고도의 전문성과 예술성을 지니게 되었다. 현재 ○○○○는 전국 어느 시․도에서도 지정되지 않은 상태이며, 특히 부산에 근거를 둔 박용태의 산조는 저변인구의 부족으로 전수 희망자가 매우 적다. 게다가 경제적, 학습상의 어려움 때문에 청소년의 조기 전수 등 효과적인 전수가 이루어지지 못하고 있어 보존이 위기에 처해 있는 실정이다. 박용태는 ○○○○…","a":"아쟁산조","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643447.jpg"},{"q":"판소리란 소리하는 사람 한 명과 북치는 사람 한 명, 그리고 판을 이루는 구경꾼으로 이루어지는 무대예술을 말한다. 소리하는 사람은 소리와 대사(아니리), 몸짓(발림)을 하며, 북치는 사람은 소리하는 사람의 가락에 따라 북을 쳐서 장단을 맞추며 신명난 분위기를 이끌어 간다. 판소리는 지역적 특성과 전승계보에 따라 전라도 동북지역의 동편제·전라도 서남지역의 서편제·경기도와 충청도의 중고제로 나뉜다. 원래는 열두 마당이었으나 일제시대에 거의 사라졌고 춘향가·심청가·흥보가·수궁가·적벽가의 다섯 마당만 현재까지 남아있다. 판소리에 쓰이는 장단에는 느린 장단인 진양, 보통빠르기…","a":"남도판소리","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643526.jpg"},{"q":"○○○○○는 조선시대 후기부터 현재에 이르기까지 안동권씨 집성촌인 ○○○에 전래되고 있는 마을신앙으로서, 대전지역 민속문화의 전통을 보전하기 위해 대전광역시 무형유산으로 지정. ○○○가 일제강점기와 해방후 급격한 외래문물 유입 속에서도 ○○○○○보존회의 노력으로 인해 그 전통이 오늘까지 계승되고 있어 보유단체로 인정함.","a":"무수동산신제","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643594.jpg"},{"q":"입사란 금속공예의 일종으로 금속표면에 홈을 파고 금선(金線) 또는 은선(銀線)을 끼워넣어서 장식하는 기법을 말하며 이전에는 ‘실드리다’라는 말로 표현했다. 이러한 입사 기술과 그 기술을 가진 사람을 ○○○이라고 한다. 입사공예의 유래는 정확하지 않으나, 기원전 1, 2세기경의 낙랑(樂浪) 출토유물에서 처음으로 선보였고, 신라의 고분에서 나온 유물로 보아 신라시대에는 매우 발달했음을 짐작할 수 있다. 입사에는 크게 두 가지 기법이 있는데, 하나는 고려시대부터 전해지는 전통방법으로 청동표면에 정(釘) 끝으로 홈을 파고 그 안에 은선을 박아넣는 것이다. 다른 하나는 조선…","a":"입사장","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623286.jpg"},{"q":"모시는 오랜 기간동안 이용되어 온 직물로서 일명 저포·저치라고 하며, 모시풀 줄기를 꺾어 그 껍질을 벗긴 것을 재료로 한다. 통일신라 경문왕(재위 861∼875) 때 중국 당나라에 보낸 기록으로 보아 외국과의 교역품으로도 이용되었다. ○○○○○는 한산에서 만드는 모시로 예로부터 품질이 우수하며 섬세하고 단아하여 모시의 대명사로 불려왔다. 제작과정은 재배와 수확, 태모시만들기, 모시째기, 모시삼기, 모시굿만들기, 모시날기, 모시매기, ○○○○, 모시표백의 9과정으로 나뉜다. 우선 재배를 해서 수확을 한다. 태모시는 껍질을 벗겨 인피섬유를 만드는 것인데 모시째기는 태모시…","a":"한산세모시짜기","c":"시도무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643945.jpg"},{"q":"○○○이란 건물의 문, 창문이라든가 장롱, 궤, 경대, 책상, 문갑 등 목가구를 제작하는 기술과 그 기능을 가진 목수를 말하는 것으로 건축을 주로 하는 대목장(大木匠)에 대칭되는 말이다. ○○○이라는 명칭은 고려시대 때부터 나타나며, 조선시대에는 목장(木匠)이라고 하였으나 대목과는 구분하였던 것 같다. 조선 전기까지는 목가구가 주로 왕실과 상류계층을 위해 제작되었으나, 조선 후기에는 민간에 널리 보급되고 종류도 많아져 지역적인 특성이 현저히 나타나게 되었다. 예를 들면 남도(南道)지역의 경우 나무의 무늬를 귀하게 여겨 옻칠을 하지 않은 민장롱을 주로 제작하였는데, 통…","a":"소목장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317424100.jpg"},{"q":"○○○○○는 250여 년의 전부터 수영동 일원에서 정초에 가가호호를 돌며 마을의 안과태평과 주민들의 제액초복을 빌어 주던 의례이자 정월 대보름날 행해지는 수영야류의 경비조달을 위한 사전 준비과정의 성격을 가진 민속놀이이다. 참여 인원은 악사 30명, 잡색 21명이며, 당산풀이, 우물풀이, 인사굿, 마당밟기, 성주풀이, 조왕풀이, 장독풀이, 곡간풀이, 정낭풀이, 삽짝풀이, 판놀이, 기소각제 순으로 이루어져 있다. 가락은 단아하면서도 깊이가 있으며, 소리도 타 지역에 비해 시김새가 적어 꿋꿋한 경상도 메나리조의 소리 길을 확연하게 드러내는 특징이 있다. 특히, 모든 의식…","a":"수영지신밟기","c":"시도무형유산","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022090716220200.jpg"},{"q":"배무삼은 1973년부터 동래 전통연 제작 및 연날리기에 입문하여 40여 년간 동래연 제작에 종사해 오고 있다. 배무삼은 한태정, 박윤수로부터 10여년에 걸쳐 동래 전통연 제작 기능을 전수받았음을 동래야류 보유자였던 고 문장원 선생이 생전에 증언함에 따라 동래 전통연 분야 1세대 이수용과 2세대 한태정의 전승계보를 이어오고 있는 것으로 확인되었다. 우리나라 전통연은 크게 '방패연'과 '가오리연'으로 나눌 수 있다. 동래연의 경우 전통연과 크게 다르지 않으나, 바다를 낀 동래지역은 겨울에 골바람이 세게 부는 곳이므로 연의 규격은 황금분할 모양인 2:3, 5:7, 7:9…","a":"지연장","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2666155.jpg"},{"q":"소리꾼들이 서서 노래한다고 하여 ○○○라고 하며, 여러 명의 소리꾼들이 늘어서서 가벼운 몸짓과 함께 소고를 치며 합창하는 민속가요를 가리켜 ○○○이라고 한다. 노래패의 우두머리인 모갑이가 장구를 메고 앞소리를 부르면 나머지 소리꾼들은 소고를 치면서 여러가지 발림(손짓, 발짓을 섞은 동작)을 곁들여 뒷소리를 받는다. ○○○이란 곡명은 가사의 내용이 산천의 경치를 주제로 하고 있기 때문에 붙여진 것이며, 느리게 시작하여 뒤로 갈수록 점차 빨라지는 구조로 구성되어 있다. 오늘날의 ○○○○○은 남자들이 부르는 노래로 되어 있으나 그 근원은 여자들이 부르는 사당패소리에서 비롯…","a":"선소리산타령","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623155.jpg"},{"q":"○○○○○은 민요나 단가, 판소리 일부 대목을 가야금을 연주하면서 부르는 연주형태를 말한다. ○○○○○은 조선후기 명창인 신만엽과 김제철이 민요나 단가, 판소리의 한 대목을 가야금의 기악적 특성을 살려 소리의 선율을 가야금에 맞도록 기악화시켜 ○○○○○의 원류라 할 수 있는 판소리의 '석화제' 곧 ○○○○○제를 창안하였다. 이후 김창조, 오수암 등 초기의 가야금산조 명인들에 의해 다듬어지고 심상건, 강태홍, 오태석, 정남희 등 가야금 명인들에 의해 크게 발전하였다. ○○○○○곡으로 널리 알려진 대목은 새타령, 남원산성 같은 민요와 함께 <호남가>, <죽장망혜>, <녹…","a":"가야금병창","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643556.jpg"},{"q":"옻칠은 옻나무 진에 착색제·건조제 등을 넣어 나무그릇 등에 발라, 썩지않게하고 윤기나게 하는 것으로, 옻칠을 하는 기술과 그 기능을 가진 사람을 ○○○이라 한다. 남원시에서 전승되고 있는 옻칠은 지리산 실상사 창건으로 부처의 공양미를 담는 그릇과 제기 등의 목기제작을 함으로써 그 기원을 이룬 것으로 추정되고 있다. 그 후 일제시대에 한국 최초로 전라북도 목기기술학교 칠공과(漆工科)가 생기면서, 연구 및 기술개발이 이루어졌으며, 자연산 옻칠대가인 양기수씨에 의하여 전통적인 옻칠비법 등이 개발되었다. 옻칠은 수액을 채취하는 방법에 따라 생칠, 화칠 등 다양한 색상으로 만…","a":"옻칠장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644115.jpg"},{"q":"○○○○○은 함경남도 북청군에서 정월 대보름에 사자탈을 쓰고 놀던 민속놀이로, 사자에게는 사악한 것을 물리칠 힘이 있다고 믿어 잡귀를 쫓고 마을의 평안를 비는 행사로 널리 행해졌다. 이 지방에서는 동네마다 사자를 꾸며서 놀았는데 각 동네에서 사자가 모여들어 자연스럽게 경연이 벌어졌다. 관원놀음과 함께 행해진 토성리의 ○○○○이 강세를 보이면서 다른 곳의 ○○○○은 점차 사라지게 되었다. 삼국시대 이래 민속놀이로 정착된 가면놀이로, 한국전쟁 이후 월남한 연희자들에 의해 현재는 서울을 중심으로 전승되고 있다. ○○○○○은 음력 1월 14일 밤에 장정들의 횃불싸움으로 시작…","a":"북청사자놀음","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623136.jpg"},{"q":"○○○○은 청자로 대표되는 고려자기를 만드는 사람 또는 기술을 말한다. 고려비색으로 일컬어지는 청자는 오랜 세월의 흐름속에서 기술이 단절되었으나 고려비색을 찾아내기 위한 노력은 계속되고 있다. 광주를 중심으로 한 강진과 부안은 청자요지로 그 명성이 자자하다. 제작과정은 제토(製土)·성형(成形)·조각(彫刻)·시유(施釉)·소성(燒成) 등의 과정을 거친다. 제토과정은 돌을 깨뜨려 가루로 만든 뒤 흙을 풀어서 배합하는데 청자의 경우 거칠고 나쁜 조악점토와 백토를 7 : 3의 비율로 섞는다. 섞은 후 불순물을 제거하는 수비과정을 거치며, 이후에 바탕흙(태토)을 짓이긴다. 짓이…","a":"청자도공","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643529.jpg"},{"q":"갯벌은 예로부터 어민(漁民)들에게 ‘갯벌밭’·‘굴밭’으로 불리는 등 농경의 밭에 상응(相應)하여 ‘바다의 밭’으로 인식되어 왔다. 또한, 갯벌을 공동재산으로 여겨 마을 사람들이 함께 관리하는 등 현재에도 어촌공동체(어촌계)를 중심으로 어민들 생업의 중추적 역할을 하고 있다. 특히, 우리나라의 갯벌은 굴, 조개, 낙지, 새우 등 다양한 해산물의 보고(寶庫)로서 한국 음식문화의 기반이 되어왔다. 우리나라 ○○○○의 역사를 살펴보면 ○○○○를 직접적으로 언급한 문헌은 확인하기 힘들지만, 서·남해안에서 발굴된 신석기·청동기·철기·고려 시대 패총에서 갯벌에서 채취한 패류(참굴…","a":"갯벌어로","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2021122111243800.jpg"},{"q":"○○지역에서 불려지는 ○○○는 몇가지 다른 명칭으로 사용하는데 배 내리는 소리를 ‘든대질소리’ ‘자아소리’라 하고, 배를 올리는 소리를 ‘든대질소리’, ‘야하소리’라고 한다. 또한 고기뜯어내는소리를 ‘베끼소리’라 하고, 명태를 가래로 떠넘기면서 부르는 소리를 ‘배지우는소리’ 노 젓는소리를 ‘어기여차소리’ ‘에이야소리’라고 한다. 고기푸는 소리를 ‘가래소리’ ‘산대질소리’ ‘에이야소리’라 하고 그물당기는 소리를 ‘에샤소리’ 그물터는소리를 ‘도리깨질소리’ 명태세는 소리를 ‘장자요 부자요’ 라 한다. 배내리고 올리는 소리 (든대질소리), 노젓고 그물내리는 소리, 그물 당기…","a":"고성 어로요","c":"시도무형유산","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016011910040601.jpg"},{"q":"○○○○○ 노래란 제주도에서 연자방아의 웃돌(굴리어 가는 맷돌)과 알돌 (바닥돌)을 들이나 산에서 만든 후, 마을 주민들이 마을 안으로 굴려 오면서 부르던 민요를 말하며, 솔깃소리라고도 한다. 연유를 보면, ○○○을 ○○○ 일은 엄청난 힘을 필요로 하고, 많은 사람이 동원되기 때문에 단결된 힘을 돋우기 위하여 부르게 되었다. 이 민요는 한 사람의 선소리에 따라 일꾼들 모두가 일제히 ‘어기영차’하며 후렴을 받는 선후창형식으로, 가사는 작업실태에 대한 것이 대부분이다. 단장형의 리듬꼴이 자주 나타나는 편이고, 속도는 대체로 느리며, 리듬적 변화가 많은 만큼 선율장식도 자…","a":"방앗돌굴리는노래","c":"시도무형유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644694.jpg"},{"q":"○○○○○은 고려왕조의 전통을 이어 온 조선시대 궁궐에서 차리던 음식으로 전통적인 한국음식을 대표한다. 궁중에서의 일상식은 아침과 저녁의 수라상(임금이 드시는 진지상)과 이른 아침의 초조반상(初朝飯床), 점심의 낮것상의 네 차례 식사로 나뉜다. 탕약을 드시지 않는 날에는 이른 아침(7시이전)에 죽과 마른찬을 차린 초조반상을 마련한다. 아침과 저녁의 수라상은 12가지 반찬이 올라가는 12첩 반상차림으로, 원반과 곁반, 전골상의 3상으로 구성되어 있다. 밥은 흰쌀밥과 팥밥 두가지와 육류, 채소류, 해물류의 다양한 재료로 여러 가지 조리법을 고르게 활용하여 반찬을 마련하고…","a":"조선왕조궁중음식","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623184.jpg"},{"q":"내용 조선시대 국가기관인 사옹원(司甕院)에 소속되어 사기를 만드는 장인을 ○○○이라 불렀다. 조선 전기에는 경기도 광주에 관영 사기제조장(官營沙器製造場) 분원(分院)이 있어 왕실에서 쓸 도자기를 만들다가 조선 후기에 관요(官窯)가 폐쇄되면서 도공들이 흩어져 민간에서 도자기를 만들게 되었다. 현대 고령에서 그 맥을 잇고 있는 대표적인 ○○○으로 백영규를 들 수 있다. [출처] 한국학중앙연구원 - 향토문화전자대전 소개 [경상북도 무형유산 백영규] 백영규는 1938년 일본 홋카이도에서 태어났으며, 호는 토인(土人)이다. 해방이 되던 1945년 아버지를 따라 귀국하였다. 백…","a":"사기장-백자장","c":"시도무형유산","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/0000000001644424.jpg"},{"q":"배첩(褙貼)이란 글씨나 그림에 종이·비단 등을 붙여 족자·액자·병풍 등을 만들어서 아름다움은 물론 실용성 및 보존성을 높여주는 전통적인 서화처리기법을 가리킨다. 일제 때 들어온 말로 오늘날에는 ‘표구(表具)’라고도 한다. ○○○은 조선 초기에 도화서(圖畵署)소속으로 궁중의 서화처리를 전담하던 사람을 말한다. 중국 한나라 때가 기원으로 알려진 배첩은 중국 당나라 때에 한층 발전하여 정립단계에 이른다. 우리나라에 어떻게 전해졌는지는 모르지만 고구려 고분벽화의 병풍그림으로 보아 삼국시대 때 전해져서 한국 배첩의 기초가 형성되었을 것으로 추정된다. 배첩은 통일신라와 고려를…","a":"배첩장","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643877.jpg"},{"q":"제주도는 논이 매우 귀한 섬이라 쌀로 술을 빚지 않으며, 술의 재료는 밭곡식인 ‘조’다. 제주도는 근래까지도 청주나 소주를 좁쌀로 빚는 것이 정통으로 되어 있는 것으로 보아 좁쌀로 술을 빚어 온 역사는 조의 경작만큼 오래되었다. 제주도에서는 좁쌀로 탁주와 청주 등을 빚어 왔는데 탁주를 두고 ‘○○○○’이라고 한다. ○○○○은 탁주를 만드는 술떡의 이름인 ‘○○○’에서 비롯된 것으로 이 떡으로 만든 술이라는 의미를 갖는다. ○○○○을 만드는 데는 여러 단계를 거쳐야 한다. 보통 40되들이 밑술을 담는데 메좁쌀 12되와 누룩을 만들 밀과 보리 10되가 든다. 술은 언제라…","a":"성읍민속마을오메기술","c":"시도무형유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644676.jpg"},{"q":"마도 ○○○○○는 전어잡이 그물에 갈물을 드리는 작업 시에 부르는 노동요로서 전어잡이 그물 당기는 소리를 합하여 공연하고 있다. 전승이 어려운 어업 노동요가 온전히 계승되어서 귀중한 문화적 가치가 있을 뿐만 아니라, 어촌의 생활양상을 재현하여 협동화합의 모습을 보이는 것은 전통문화의 현재적인 전승이라는 의의를 지니고 있어서 더욱 가치가 있다. 마도 ○○○○○는 이 섬사람들의 주된 생계수단인 전어잡이와 함께 오래전부터 전승되어 온 특색 있는 일 소리이다. 그 발생연대는 알 수 없으나 소리의 가락이나 노랫말에 자신들의 삶의 애환이 잘 드러나 있으며 전승상태가 양호하여 전…","a":"사천마도갈방아소리","c":"시도무형유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644546.jpg"},{"q":"삼베는 베라고도 불리며 한자어로는 마(麻)·마포(麻布)·포(布)라고도 한다. 삼베는 신석기시대의 궁산패총에서 뼈로 된 바늘에 마사가 감긴 것이 출토된 것으로 보아 그 이전에 사용된 것을 알 수 있다. 고려시대에는 기술이 발달되어 중국으로 수출되었고 문물교환의 수단으로 모시와 함께 사용되었다. 조선시대에는 면 생산이 시작되면서 삼베의 생산이 약간 줄게된다. 제작과정은 우선 삼나무를 재배해서 수확을 한 후, 잎을 훑은 삼단을 쪄서 껍질을 벗기고 햇볕에 말린다. 삼을 쪼갠 후 실을 한올 한올 길게 이은 다음 베 한필의 길이와 폭에 따라 몇 올의 실이 들어갈지 결정한다. 마…","a":"청도삼베짜기","c":"시도무형유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644384.jpg"},{"q":"불교의식에 사용하는 노래를 범패라 하고, 춤을 작법, 또는 ○○○라 한다. 인천에서의 ○○○○○는 조선 태조 대왕(1398)이 팔만대장경을 강화 선원사에서 지천사로 옮길 때 이운의식으로 행하면서 처음 행해졌다. 그 후 면면히 이어오다가 1928년부터 약사사, 묘향사, 해광사 등지에서 법회에 ○○○○○인 바라춤, 나비춤, 법고춤 등이 추어지게 된다. 바라춤은 일체의 모든 마장을 끊고 부처님의 정법을 찬탄하는 무용으로 ○○○라 한다. 인천 바다의 기상을 담아 힘차고 우렁차며 선이 굵은 것이 특징이며, 호국영령을 위해서도 봉행한 점이 타 지역과 다르다. 구양사에서는 능화스…","a":"범패와 작법무(바라춤)","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010411473900.JPG"},{"q":"조도 ○○○○는 진도군 조도일원의 어민들이 칠산어장, 안마도어장 등에 진출하여 조기잡이를 하면서 전승해온 민요로서 조기잡이와 관련된 서해안의 대표적 민요이다. 현재는 닻배를 이용한 어로작업이 사라지고 노래만 남아 조도를 중심으로 연행되고 있어 보존할 필요성이 있다. 김연호는 15세 무렵부터 닻배를 타기 시작했다. 닻배를 타면서 선배 선원들로부터 ○○○○를 배웠다. 목구성이 좋아 앞소리를 맡아서 했다고 한다. 닻배에서는 나이든 선원들이 뒷소리를 주로 하고, 젊은 선원들에게 앞소리를 맡기는 경향이 있어 김연호는 젊을 때부터 앞소리를 주로 맡았다고 한다. 1958년 당시…","a":"조도닻배노래","c":"시도무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101615135700.JPG"},{"q":"수영에서는 ‘농청’이라는 자치단체를 만들어 농민들의 기술향상과 협동심을 높여 생산증진을 도모하였다. 급격한 도시화에 따라 농청의 풍습뿐 아니라 그에 따르는 농요도 사라지게 되자 농청원들이 농악을 치고 농요를 부르며 농사짓는 과정을 놀이화하였다. ○○○○○는 집합신호에 의해 모인 농청원들이 농기, 농악대, 소, 농부들, 부인들 순으로 정렬하면 남녀 두 사람이 차례로 풀노래를 부르고, 일동은 농악장단에 맞추어 춤을 추며 일터로 상징되는 놀이마당으로 들어간다. 농사를 짓는 과정에 맞추어 가래소리, 모찌기소리, 모심기, 도리깨타작소리 순으로 모심기가 끝나면 남자 농청원들이…","a":"수영농청놀이","c":"시도무형유산","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643402.jpg"},{"q":"○○○은 나무를 재료로 하여 제기(祭器) 등 다양한 용기를 제작하는 기능이다. ○○○ 보유자로 인정받은 김인규씨는 60여 년간 한 분야에 종사하면서 제작 과정 전체를 능숙하게 구현할 충분한 기량을 보유하고 있으며, 본고장인 남원에서도 사용하지 않는 전통 수동식 족답기(족답기)를 비롯하여 부친으로부터 이어 받은 연장을 소장 및 활용하고 있다.","a":"목기장","c":"시도무형유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101116193500.jpg"},{"q":"이 ○○○는 경북 경산시 자인면 일대에서 불려오던 11가지의 농요를 하나로 묶은 것으로 경상도 농요의 일반적 특징인 메나리조와 덧배기 장단이 그대로 살아 있다 또한, 자인은 경상도 내륙에 위치하여 타 지역의 영향을 적게 받아 이지방만의 선율을 그대로 유지하고 있다. 또한, 경상도 지역의 주민기질과 말씨의 억양을 닮아 꿋꿋하며 투박한 역동감이 넘치는 특징을 가지고 있다.","a":"자인계정들소리","c":"시도무형유산","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644399.jpg"},{"q":"< ○○○○○ 보존회 현황 > . 회원수 : 70여명 市 무형유산 22호 지정(○○○○○) : 2014. 7. 24. 유래 : 용전동 일대에서 불려지던 들소리(노동요)로 60년대 말까지 구전되어 오다 그 맥이 끊겼으나 사)○○○○○보존회 전 김동언회장과,故)지춘상, 故)범대순 전남대 명예교수가 2년여 고증 통해 발굴재현(’99.6) 단체명 변천사 : 사)지산○○○○○보존회 → 사)지산용전들소리보존회 → 사)○○○○○보존회(’12.6) 주요수상실적 - 제1회(’99.7), 제9회(’07.6) 광주광역시 민속예술축제 대상 - 제40회 한국민속예술축제 종합우수상(국무총리상…","a":"용전들노래","c":"시도무형유산","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101118404000.jpg"},{"q":"○○는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로 ‘들노래’ 또는 ‘농사짓기소리’라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수도 있다. ○○○○○는 오랜 옛날부터 입에서 입으로 전해져 오는 노래로 모찌기, 모심기, 논매기소리가 있다. 모찌기는 모를 찌면서 부르는 노래이고, 모심기는 모를 심으면서 부르는 노래이다. 논매기 노래는 초벌매기와 두벌매기로 나뉘는데, 한 사람이 메기면 여럿이 받아 부르는 형식이다. 메기는 사람은 의미있는 내용을, 받는 사람은 의미없는 여음을 담당한다. 이러한 차이는…","a":"영동 설계리 농요","c":"시도무형유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643870.jpg"},{"q":"○○○은 집짓는 장인을 일컫는다. 목수 또는 목장으로도 불리었으며, 이들 가운데 전체 일을 주관하여 이끄는 장인을 도편수 또는 도대목으로 지칭하였다. 한국은 넓은 산림에서 구하기 쉬운 목재로 지은 나무집이 발달하였으며, 민가는 물론 궁궐과 사찰도 나무로 지어졌다. 따라서 나무를 다루는 목수의 소임이 매우 요긴하였다. 『경국대전經國大典』에는 ○○○과 소목장의 구별 없이 목장으로만 기록되었으나 고려시대에도 집을 짓고 가구를 짜는 두 분야의 영역은 따로 있었다. 목수의 일은 과정이 복잡한 만큼 소임에 따라 여러분야로 체계화된 조직을 구성하여 활동하였다. 전체를 총괄하는 도…","a":"대목장(도편수)","c":"시도무형유산","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018090714183200.jpg"},{"q":"체는 장 담그기로부터 각종 요리가루 및 곡식류를 선별하고, 곡식을 씻을 때, 건조할 때 등 다양하게 쓰이는 가정의 필수 도구이다. 틀을 만드는 재료는 소나무 또는 미루나무, 솔뿌리, 대나무 등이 쓰이고, 체메우는 재료로는 말꼬리털, 소꼬리털 등이 사용되는데, 천연재료로 만든 것은 오랜 보관이 어렵다. 헝겊 또는 나일론천이나 철사 등으로 메우기도 한다. 체를 메우는 구멍에 따라 어레미, 도듸미, 중거리, 가루체, 고운체 등으로 나뉜다. 어레미는 구멍이 제일 넓은 체로 철사나 가늘게 쪼갠 대나무로 메운다. 도듸미는 어레미 보다 좁은 체로 철사로 엮는 것이 보통이다. 중거…","a":"체장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1776116.jpg"},{"q":"전남 구례(求禮)지방에서 전승되는 현악영산회상(絃樂靈山會相) 이란 기악곡을 「○○○○○」라 한다. 영산회상은 여러 음악이 조곡과 같이 구성된 합주곡을 가리키는데 「풍류(風流)」라고도 한다. 관악기가 중심이 되는 영산회상을 관악영산회상 또는 대풍류라 하고 현악기가 중심이 되는 영산회상을 현악영산회상 또는 ○○○라고 한다. ○○○에는 서울에서 전승되는 것과 지방에서 전승되는 것이 어느정도 다르게 연주되었는데, 지방에서 전승되는 ○○○를 서울에서 전승되는 ○○○와 구별하기 위해서 「향제(鄕制)○○○」라 한다. 풍류, 즉 영산회상은 조선 초기에「나례(儺禮)」라는 궁중 축제에…","a":"구례향제줄풍류","c":"국가무형유산","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623917.jpg"},{"q":"고대부터 철의 생산지로 이름이 높았던 울산 부구 달천 철장은 철을 채취하고 가공하는 ○○○ 문화가 발달했다. ○○○○○는 고된 ○○○ 과정에서 노동의 힘을 돋우거나 한 조를 이뤄 일하는 사람들의 합을 맞추기 위해 내었던 소리인 노동요이다. 여기에는 철 생산의 과정 외에도 풍부한 철의 생산을 염원하는 풍철(豊鐵) 의례가 고스란히 녹아 있다. ○○○○○는 작업의 강도와 속도에 따라 다양한 장단과 리듬으로 불린다. ○○○ 작업에서 용광로의 온도를 높이기 위해 바람을 넣어주는 불매(풀무)를 밟으며 부르는 ○○○ 불매소리를 필두로, 금줄을 걷어 용광로에 태우며 부르는 ○○○…","a":"울산쇠부리소리","c":"시도무형유산","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020031719232000.jpg"},{"q":"한반도 지역의 ○○○○는 청동기시대를 거쳐 원삼국시대 부뚜막식 화덕과 연도가 설치된 원시적 형태의 난방방식에서 기원한 것으로 추정되고 기원전 3세기~1세기경의 유적으로 추정되는 원시적 온돌 유적들이 한반도 전역에서 발견된 점들로 미루어 보아 한반도에서 ○○○○는 약 2천년이상 전승되었다고 추정할 수 있다. 우리 온돌은 서양 벽난로와 다르게 연기를 높은 굴뚝으로 바로 내보내지 않고 불을 눕혀 기어가게 만들어서, 불의 윗부분을 깔고 앉아 사용하는 탈화좌식(脫靴坐式) 바닥 난방이 특징으로 방내부에 연기를 발생시키지 않고 오래 난방할 수 있는 장점이 있다. ○○○○는 한국의…","a":"온돌문화","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2021072914540300.jpg"},{"q":"○○은 기본재료인 털과 대나무를 사용하여 붓을 만드는 장인이다. 붓은 짐승의 털을 추려모아 원추형으로 만들어 붓자루에 고정시킨 것으로, 주로 염소털, 족제비털 등 동물의 털을 사용한다. 붓 제작기능은 전국 어디서나 같다는 특성을 지닌 기능으로, 최근 그 수가 급격히 줄어들고 있을 뿐 아니라 중국산 붓과 재료(염소털)의 유입으로 우리나라 붓 제작의 전통이 단절될 수도 있는 상황이다. 강원특별자치도 지역의 염소털과 대나무를 사용하여 붓을 제작하는 전통기능의 보존⋅전승이 필요하다는 점에서 지정가치가 크다. 보유자 박경수는 1985년 ○○에 정착한 이후 오랜 기간 붓을 제작…","a":"춘천 필장","c":"시도무형유산","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643841.jpg"},{"q":"‘○○○○’은 기존의 신분질서와 사회적 통념의 가치에 대하여 부정하고 반문하며 그 안에서 자연스러운 웃음을 담아내는 서도의 재담소리이다. 사회가 금기시했던 것들은 자연스러움을 거스르고 있다. 하지만 ‘○○○○’은 기존 질서와 다른 변화된 사회의식을 싹트게 하고 있다. 기존 사회의 가치와 질서를 파괴하고 있지만, 그 순간의 상황이 불편하게 다가오는 것이 아니라 자연스럽게 해학적으로 받아들여지게 된다. ‘○○○○’은 서도지방에 전해 내려오는 판소리 형태의 재담소리이다. 청중이 모인 소리판에서 소리광대가 고수의 장구 반주에 맞춰서 연행하는 1인 창극이며, 서사적인 소재의…","a":"평안도 배뱅이굿","c":"이북5도 무형유산","r":"평안남도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2022120815412700.JPG"},{"q":"김제시 백산면 ○○○에서 옹기 만들기에 매진하고 있는 ○○○인 안시성씨는 1992년 ○○○ 옹기마을에 옹기만들기에 명망이 높았던 故변동순선생에게 전통작업방식과 ○○○인으로서의 정신을 사사받았고 국내 유일하게 보존되어있는 ○○○ 옹기가마와 작업장을 20년이상 지켜오며 국가등록문화유산으로 지정되는데 기여하였으며, 김제 ○○○에서 전승되어온 전통제작방식을 그대로 재현함과 동시에, 실생활에 필요한 상품개발에도 끊임없는 연구를 지속해온 인물이다. 또한 과거 유교사회 신분제의 산물로서, 옹기가마에 대한 마을사람들의 부정적 인식을 각종 문화행사를 주최하며 점차로 마을사람들과 함께…","a":"부거리옹기장","c":"시도무형유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018082310443600.JPG"},{"q":"○○○○는 경기도 지역에서 자리가심, 방가심 등 여러 가지 용어가 쓰이지만 이것이 일반적인 용어이다. ○○○○는 서울과 경기지역에서 장례를 치룬 당일 밤에 행하는 의례 중 하나로, 일종의 정화의식이다. 무속신앙에서의 ‘주검’과 주검을 둘러싼 것을 부정不淨하다고 정의하는데, 이는 산 사람의 관점에서 보는 관념이다. 부정을 정화하는 절차가 필요하다는 의식에서 ○○○○가 행해지며, 이러한 죽음 의례 배경은 죽은 자를 위한 의례를 통해 산 자들의 길복을 추구한다는 것이다. ○○○○는 소규모 의례로 절차와 내용이 복잡하지 않으며, 크게 ‘부정청배’, ‘○○○○’, ‘뒷전’으로…","a":"자리걷이","c":"시도무형유산","r":"경기도","s":"부천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018081010210102.jpg"},{"q":"○○○○○ 보유자 이희옥(법명 靑苑)은 15세에 불교조각에 입문하여 수많은 목조불상을 조성하는 등 40여년을 조각장으로 활동하고 있다. 조각승으로서 법맥과 ○○○○ 전승계보도 분명하게 계승하고 있으며, 조선 후기 조각승의 계보도 계승하고 있다. ○ 특히 전통 도구와 전통 제작방식에 입각하여 작품 활동을 하고 있는데, 전통 도구의 쓰임새와 불교 도상에 대한 철저한 연구와 이해를 바탕으로 전통적인 봉안 방식을 고수하고 있을 뿐만 아니라, 새롭게 창건되는 사찰의 환경에 적합한 불상을 조성하기 위해 꾸준히 노력하고 있는 등 기능이 상당한 수준에 도달하였다. 그리고 그의 작품…","a":"목조각장","c":"시도무형유산","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643459.jpg"},{"q":"○○○은 24방위를 원으로 그려 넣은 풍수 지남침(指南針)을 제작하는 장인이다. 윤도는 남북방향을 가리키는 자석바늘을 이용하여 지관이 풍수(집터 또는 묘자리를 정함)를 알아볼 때나 천문과 여행분야에서 사용되는 필수도구이다. 명칭의 유래는 알 수 없으나 조선시대 문헌에 처음 나오고, 일명 나침반, 지남철, 지남반, 패철이라고도 한다. 우리나라에서는 풍수지남침이 신라 후기부터 발달하였고, 고려 전기에는 풍수음양지리와 연결되어 땅의 형세를 보는 풍수가나 지관들에게 가장 중요한 기구로 사용되었다. 조선시대부터는 풍수가의 전용물에서 벗어나 여행자들도 사용하였으며, 특히 천문학…","a":"윤도장","c":"국가무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623795.jpg"},{"q":"○○○이란 활과 화살을 만드는 기능과 그 기능을 가진 사람을 말하는데, 활을 만드는 사람을 궁장(弓匠), 화살을 만드는 사람을 시장(矢匠)이라 한다. 기능보유자 양태현梁泰鉉은 16세부터 고 조명제(趙命濟, 전 국가무형유산 ○○○ 보유자)와 조기선의 문하생으로 입문하여 1966년부터 11년간 전수를 받았다. 1977년 강원도 원주시로 이주하여 죽시 제작을 종사하던 중 1983년 청주시로 이주하여 현재까지 전통적인 방법으로 죽시를 제작하고 있다. 화살은 목전(木箭), 철전(鐵箭), 편전(片箭), 동개살, 장군전(將軍箭), 세전(細箭) 등이 있었으나, 현재 주로 사용되고…","a":"궁시장","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643907.jpg"},{"q":"탈춤이란 한 사람 또는 여러 사람이 가면으로 얼굴이나 머리 전체를 가리고 다른 인물, 동물 또는 초자연적 존재(신) 등으로 분장한 후 음악에 맞추어 춤과 대사로써 연극하는 것을 말한다. 탈춤은 조선 전기까지 각 지방에서 행해지던 가면놀이이다. 17세기 중엽에 이르러 궁중의 관장하에 “산대”라 불리는 무대에서 공연되던 산대도감극(山臺都監劇)의 형태로, 인종 12년(1634)에 궁중에서 상연이 폐지되자 민중에게 유입되어 전국으로 전파되었다. ○○○○은 약 200년전부터 매년 단오와 하지날 밤에 행해졌다. 놀이는 4상좌춤·8목중춤·사당춤·노장춤·사자춤·양반춤·미얄춤의 7과…","a":"봉산탈춤","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623145.jpg"},{"q":"거창 ○○○○○는 ○○○의 지루함을 달래기 위해 불려지는 노동요이다. 경남 거창군은 예로부터 삼베의 고장이었다. 삼베가 생산되기까지는 삼 씨앗을 뿌려서 베를 짜기까지 여러 과정의 노동이 뒤따르게 된다. 이러한 전 과정을 길쌈이라고 하는데, 이곳에서 ○○○이라고도 하는 삼베 길쌈에서는 남성보다 여성이 하는 노동이 더 많다. ○○○○○는 7개 과정으로 구성되어 있으며 밭매기소리, 삼잎치기소리, 삼곳소리, 물레소리, 삼삼기소리, 베메기소리, 베짜기소리 등으로 진행된다. 거창 ○○○○○는 고된 농사일을 잊게 하는 노동요로 이말주씨가 그 맥을 이어가고 있다.","a":"거창삼베일소리","c":"시도무형유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644482.jpg"},{"q":"고깔을 쓰고 소고를 놀리면서 추는 ○○○○○은 경기도 농악에 삽입된 소고가락을 양식화한 민속춤으로 경쾌한 농악의 일부였다. 그러나 농악이 가지는 거칠거나 흥에 겹다는 느낌보다는 동작이 부드러워 손에 든 소고마저도 마치 손의 일부인 양 아름다움이 피어난다. 발동작과 손동작이 정제되고 조용하여 남성의 춤이지만 한 폭의 춤사위를 보는 즐거움이 크다. 다른 지역과 달리 재인들이 춰서 체계화돼 있을 뿐만 아니라 이 춤에만 있는 동작도 있다. 거울을 보는 동작인 ‘색경북’, 다리 동작인 ‘제기북’, 실을 감는 것 같은 동작인 ‘꾸리북’ 등이다. 춤을 출 때는 전립 위에 꽃을 얹…","a":"경기고깔소고춤","c":"시도무형유산","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091413524500.jpg"},{"q":"○○○○○는 고려시대부터 양반사회의 모순을 풍자하면서 서민층에서 즐겨 놀았던 민속극으로 꼭두각시놀음, 홍동지놀음, 꼭두○○○○음 등으로 불리우며 남사당패에 의해 전해 왔다. 인형을 매체로 한 사회풍자극인 ○○○ 놀이의 ‘박’은 인형을 바가지로 만들었다는데서 비롯되었고 ‘첨지’는 벼슬 이름으로 양반을 해학적으로 풍자하여 붙여진 이름이다. 현재는 고(故) 주연산씨를 거쳐 서산 음암 마을주민 20여 명으로 구성된 보존위원회에서 명절날 마을 놀이로 행하고 있다. 이 놀이는 ○○○마당 네거리와 평안감사마당 세거리의 2마당 7거리로 구성되는 마당극으로 막 뒤에서 여러 사람이 인…","a":"서산박첨지놀이","c":"시도무형유산","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644007.jpg"},{"q":"목조각은 목재를 소재로 나무가 가진 양감과 질감을 표현하는 조각으로 재료로는 결이 아름답고 견실한 오동나무, 소나무, 전나무, 은행나무, 느티나무, 회화나무 등이 사용되었고, 그 기원은 삼국시대 불교가 전해지면서 사찰건축과 불상 등 불교의식과 관련된 조각들이 제작되기 시작한 것으로 추정된다 기능보유자 하명석씨는 1975년 불교조각에 입문한 이래 현 경상북도문화재전문위원인 청원스님에게 5년간 사사를 받아 전통불교조각에 대한 기능을 보유하고 있으며 1989년 문화재수리기능공 자격을 취득하여 법주사 목조관음 보살좌상 수리 등 문화재수리업무에도 종사하고 있다. 매년 각 사찰…","a":"목불조각장","c":"시도무형유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643913.jpg"},{"q":"○○은 조선시대 상류사회에서 애창된 시조 및 가사와 함께 정가(正歌)에 드는 성악곡으로서 만년장환지곡(萬年長歡之曲)이라고도 한다. 시조의 시를 5장 형식에 얹어서 부르는 ○○은 피리·젓대·가야금·거문고·해금의 관현 반주에 맞추어 불리며, 그 예술성은 시조와 가사에 비하여 아주 뛰어나다. 전통○○은 16박 또는 10박의 장구장단 반주에 의하여 연주되고, 우조(羽調)와 계면조(界面調)로 짜여졌으며, 24곡으로 한 바탕을 이루고 사람의 구분에 따라서 남창○○·여창○○·남녀창○○ 등으로 나뉜다. ○○의 기원은 조선 전기이며, 현재의 ○○은 말기에 형성된 것이다. 조선 후기…","a":"가곡(여창가곡)","c":"시도무형유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643585.jpg"},{"q":"단청은 사찰이나 궁원건축의 내외벽의 미관과 부식방지를 위해 광물질 안료로써 장식문양을 그리는 것이다. 특히 불교건축에 장식된 단청은 교리의 이해를 바탕으로 장엄한 불(佛)세계를 구현하여 신도들로 하여금 신앙심을 불러일으키는 것이 중요한 목적이다. 때문에 우리나라에서는 불교의 시작과 함께 무수히 많은 건물에 단청이 장식되었고 ○○○ 또한 많아 현재까지 그 맥이 면면이 이어져오고 있다.","a":"단청장","c":"시도무형유산","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016080811070800.JPG"},{"q":"○○○는 대전지역 대표적 문중인 은진송씨 동춘당 종택(恩津宋氏 同春堂 宗宅)에서 전승적으로 제조되어 제주(祭酒), 접빈(接賓)의 용도로 사용되던 가양주(家釀酒)로 주식시의(酒食是儀), 우음제방(禹飮諸方) 등 문헌에도 기록이 있는 가치 있는 무형유산이다. 아울러 ○○○ 제조와 관련된 기능 실현과 전승자 양성 등 보존․전승을 위하여 동 기능을 가지고 있는 김정순을 기능보유자로 인정하였다.","a":"국화주","c":"시도무형유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101116270100.jpg"},{"q":"백광훈은 누대에 걸쳐 ○○ 지방 옹기제조법을 전수하였고, 전통적인 옹기제조방법을 비교적 잘 고수하고 있으며, 옹기의 품질이 아주 우수할 뿐만 아니라 40여년간 외길로 옹기를 만들고 있다. 더구나 경북에서 옹기업이 가장 성행한 ○○지방 옹기일의 마지막 보루이다.","a":"영덕 옹기장","c":"시도무형유산","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019061311200700.jpg"},{"q":"○○○는 국화, 찹쌀, 누룩, 비슬산의 맑은물 등을 사용하여 빚은 술로 연꽃향기가 난다 하여 ○○○로 부르게 되었다고 한다. 신라 중기 무렵 비슬산 중턱에 위치한 도성암(道成庵)이 병란(兵亂)으로 모두 타버렸는데, 성덕왕(재위 702∼737) 때 도성암을 다시 지으면서 인부들에게 제공하기 위하여 임시로 토주를 빚기 시작한 것이 그 시초라 한다. 그 후 조선 광해군(재위 1608∼1623) 때 비슬산이 천년요새로 군사가 주둔하고 있을 때 주둔대장이 왕에게 이 술을 드렸더니 독특한 맛과 향이 천하약주라 칭찬받았다. 이후 10월 상달에는 조정에 바쳤다는 설화가 전해지고 있…","a":"하향주","c":"시도무형유산","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643484.jpg"},{"q":"○○○○○에 쓰이는 악기는 대금, 피리, 해금, 장구, 북으로 편성되며 단소를 곁들이기도 한다. 대금은 삼현대금을 쓰며, 피리는 향피리를 쓴다. ○○○○은 향교의 제향, 사가의 회갑 및 혼인, 절에서 제사 지낼 때, 혹은 상량 올릴 때, 춤을 출 때, 활을 쏠 때 등 다양한 행사에 연주되었다. 전라의 ○○○○에는 전국 유일하게 농삼현과 민삼현이 있다. 농삼현은 무용 반주용으로 연주하기 위해 세련되게 정비한 삼현이며, 민삼현은 본래부터 민가에서 쓰던 삼현이다. ○○○○○에 쓰이는 악곡에는 본영산, 중영산, 잔영산, 허두, 꺽두리, 돌가락, 삼현, 염불, 삼현돌장, 타령…","a":"전라삼현육각","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644169.jpg"},{"q":"◦ 생전○○○의 정의와 유래 - 한국의 불교의식에서 행하는 재(齋)의식으로는 트게 상주권공재(常住勸公齋)시왕각배재(十王各拜齋) 생전○○○, 수륙재(水陸齋), 영산재(靈山齋)등으로 다양하게 전해지고 있는데, 이 중 생전○○○는 생전(生前)에 미리 닦기 위해서 드리는 재 의식으로 죽은 뒤의 명복을 빌기 위하여 살아 있을 당시에 자기 자신이 전생에서 진 빚을 미리 갚고 또 재를 드려서 죽기 전에 미리 닦아놓는 불사이다 ◦ 현재 팔공산제 범패의 맥을 잇고 있는 ○○○○○의 어장스님인 원봉스님은 그동안 단절되었다 고 알려져 왔던 영남의 팔공산재의 불교의식 음악을 이어오고 있는…","a":"밀양 작약산 예수재","c":"시도무형유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023053016103400.jpg"},{"q":"옻칠은 선사시대부터 우리나라를 비롯하여 중국, 일본 등지에서 천연도료로 널리 이용되었다. 옻칠은 목기에 칠하면 갈라지고 터지는 결점을 보완하고 수분의 침투를 막아 오랜 기간동안 사용할 수 있고 인체에도 무해하다는 특징이 있다. 옻칠 공예품 제작과정을 세분화하면 칠을 하는 과정과 나전을 붙이고 마무리하는 과정으로 나눌 수 있는데, ○○이란 옻칠을 하여 깨끗한 표면을 만들어 내는 작업을 주로 하는 장인을 말한다. 아름답고 견고하게 칠을 하면 자체로도 훌륭한 공예품이 될 뿐만 아니라 나전·칠화 등의 장식기법 사용이 가능하다. 김상수씨는 1979년부터 1987년까지 국가무형…","a":"칠장","c":"시도무형유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643760.jpg"},{"q":"망건은 갓을 쓰기 전에 머리카락이 흘러내리지 않도록 하기 위해 말총으로 엮어 만든 일종의 머리띠이다. 망건은 윗부분을 졸라매는 당(살춤), 아랫부분을 졸라매는 편자(선단), 그믈처럼 얽혀져 이마부분을 감싸는 앞, 뒤통수를 싸매는 뒤로 구성된다. 이 밖에 계급을 표시하거나 장식하기 위해 관자와 풍잠을 메달기도 한다. 망건의 재료로는 말의 꼬리털이나 사람의 머리카락을 사용하며, 만드는 과정은 편자짜기에서 앞, 뒤뜨기로 이어지며 당을 걸고 망건을 삶아서 부드럽게 한 다음 염색을 하고 조립해 완성한다.","a":"망건장","c":"국가무형유산","r":"제주특별자치도","s":"제주도","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624190.jpg"},{"q":"○○○는 산신령에게 지내는 제사로 ○○○○○는 매년 음력 동짓달에 마을사람들의 나쁜 기운을 막고, 평화와 번영을 축원하는 제사의 하나이다. ○○○○○의 역사는 정확하지 않으나 일부 주민들에 의하면 약 450년 전부터 지내왔다고 한다. 당시 산제당이 선 자리는 보문산의 좋은 기운을 받는 곳으로 인근의 다른 지역보다 유독 높이 솟아 있어 산제당을 짓고 ○○○를 시작한 것이 오늘에 이른다고 한다. ○○○는 매년 동짓달에 길일을 택하여 지내오다가 20여 년 전부터는 동짓달 초삼일로 정해 놓았다. 예전에는 ○○○를 앞두고 부정한 일이 생기면 일주일쯤 제일을 연기하여 지냈으나…","a":"유천동산신제","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643571.jpg"},{"q":"단청은 청색·적색·황색·백색·흑색 등 다섯 가지 색을 기본으로 하여 궁궐·사찰·사원 등에 여러 가지 무늬와 그림을 그려 장엄하게 장식하는 것을 말한다. 단청은 단벽(丹碧)·단록(丹綠)·진채(眞彩)·당채(唐彩)·오채(五彩)·화채(畵彩)·단칠(丹漆) 등의 다른 이름이 있고, 이에 종사하는 사람을 ○○○·화사(畵師)·화원(畵員)·화공(畵工)·가칠장(假漆匠)·도채장(塗彩匠) 등으로 부른다. 승려인 경우에는 화승(畵僧), 불화에 숙달된 승려는 금어(金魚), 단순한 ○○○은 어장(魚杖)이라고도 일컫는다. 우리나라 단청은 삼국시대의 고분 등에서 기원을 살필 수 있고, 불교의 수용…","a":"단청장","c":"국가무형유산","r":"경상남도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623230.jpg"},{"q":"○○○○○은 해마다 정월 보름 해가 떠오를 시각에 맞추어 행해진다. 당제를 지내는 당집은 두 곳인데 한 곳은 마을에서 300m 떨어진 장도라는 섬에 있고 다른 한 곳은 마을 안 사장나무거리에 있다. 당집 안에는 가운데에 송징 장군과 오른쪽에 정연 장군, 그리고 왼쪽에는 혜일 대사를 모셔오다가, 1982년부터 장보고 장군을 추가하여 모시고 있다. 당제의 절차는 다음과 같다. 제상을 차린 후 향을 사르고 신이 내려오게 하여 축문을 읽는다. 다음에는 술잔을 세 번 올린 후 신령 앞에 비는 뜻에서, 얇은 종이를 오려서 불을 붙여 공중으로 날린다. 제사에 썼던 술을 제사관들이…","a":"완도 장좌리 당제와 당굿","c":"시도무형유산","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102217272600.JPG"},{"q":"「○○○○○」은 오래 전부터 ○○○ 지방에서 전승되고 있는 사령(死靈) 굿으로 돌아가신 망자(亡者)의 한을 강신무(降神巫)를 통해 풀고 이승의 미련을 떨쳐버리고 저승에 편안히 안주하기를 비는 굿이다. 이와 같은 굿의 형태는 지방에 따라 오구 굿(경상도), 망뭇이 굿(함경도), 씻김 굿(전라도)등으로 비슷하게 치러지고 있지만「○○○○○」은 굿의 규모가 크고 불교적인 색채가 강한 것이 특징이다.","a":"평안도 다리굿","c":"이북5도 무형유산","r":"평안북도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669665.jpg"},{"q":"이 춤은 하규일-정소산-백년욱의 전승계보로 1940년대 후반부터 1970년대 후반까지 대구 무용사에서 주도적인 역할을 하였던 정소산 선생의 춤 원형이 보존된 입춤 형식의 작품이다. 궁중무용과 민속무용이 결합된 독특한 형태의 ○○○으로서 춤사위는 장중함과 단아함, 절제미가 있으며 보는 이로 하여금 절로 흥을 돋운다. 보유자로 인정된 백년욱은 1955년부터 정소산 선생의 문하생으로 입문하여 근대기 대구지역의 대표적인 춤꾼인 정소산의 전통을 이어오며 지금까지 전승하고 있다.","a":"수건춤","c":"시도무형유산","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2505067.jpg"},{"q":"○○○○○은 죽은 사람의 혼을 천도하는 위령마당굿(천도제)으로 집안굿, 방안굿 형태를 지니고 있으며, 부정굿부터 시석까지 총 열두거리로 구성되어 있다. 염불이나 고삼, 자삼, 가락 등 불교적인 내용과 색채가 짙게 혼융되어 있어 불교의 재(齋) 양식과도 비교 가능한 독특함을 띄고 있으며, 한국인 특유의 사생관을 보여 주고 있다. 또한 해원과 축원의 사설풀이와 함께 노래, 춤, 각양의 조형형상으로 살풀이의 극점인 신명을 불러 일으켜 죽음을 맞이하고 망자를 보내는 한국 샤머니즘 특유의 생명사상과 가무정신을 지니고 있어 민족적 무의식과 미의식의 원류를 살펴볼 수 있는 귀중한…","a":"부산 기장 오구굿","c":"시도무형유산","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052209555100.bmp"},{"q":"우리민족은 예로부터 관혼상제의 4대 의례를 가장 귀한 것으로 생각하고 실행해 왔다. 그 중 상례의 절차는 전국적으로 비슷하나 지방에 따라 변형되어 다소 다른 모양으로 바뀐 것을 볼 수 있다. ○○○○○은 지세가 고르지 못할 뿐 아니라 경기도, 황해도와 인접해 있으며 생활수단도 어업으로 이어가고 있어 ○○○○도 경기도, 황해도의 민요와 뱃노래의 영향을 많이 받고 있다. ○○○○는 초혼 및 운구, 행상, 산오름과 외나무다리 넘어가기, 가래소리와 회다지소리, 고별소리로 구성된다.","a":"인천근해 도서지방 상여소리","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643519.jpg"},{"q":"청양○○○는 한 해의 시작을 앞둔 정초에 치러지는 전통적 민속축제로 약 400년 전부터 칠갑산을 중심으로 주변 마을에서 전승되어 왔다. 유래에 대하여는 임진왜란(1592) 때 왜적에 대항하기 위해 불을 이용한데서 비롯된 것으로 추측된다. 매년 음력 1월 14일 저녁에 마을 사람들은 정성들여 목욕재계하고 산에 가서 나무를 한 짐씩 베어다가 동화대를 세운다. 달이 뜨면 마을신에게 제사를 올리며 마을의 평안과 풍년을 기원하고, 모든 부정한 것은 불에 태워 액운을 제거한다. 제사가 끝나면 주민들이 한데 어우러져 준비된 음식과 술을 나누어 먹으며 흥겹게 노는데 지게가마타기,…","a":"청양정산동화제","c":"시도무형유산","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026061910595302.jpeg"},{"q":"영산재(靈山齋)는 49재(사람이 죽은지 49일째 되는 날에 지내는 제사)의 한 형태로, 영혼이 불교를 믿고 의지함으로써 극락왕생하게 하는 의식이다. 불교 천도의례 중 대표적인 제사로 일명 ‘영산작법(靈山作法)’이라고도 한다.까마득한 2500년 전 법회 장면이 오늘날까지 영산작법으로 보존되고 전승된 것이 국가무형유산 영산재이다. 또한 그 가치를 인정받아 2009년 유네스코는 세계 무형문화유산으로 등재되었으며, 지난 2014년 7월 광주광역시는 ‘○○○○○’를 시의 무형유산으로 지정했다.","a":"광주영산재","c":"시도무형유산","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020030615561100.jpg"},{"q":"산조란 장구반주에 맞추어 다른 악기를 독주형태로 연주하는 것을 말하며, 4∼6개의 악장을 구분하여 느린 장단에서 빠른 장단 순서로 연주한다. 가야금으로 연주하는 산조를 ○○○○○라 하고, 직접 가야금을 타면서 노래부르는 것을 가야금○○이라 한다. 모든 산조는 느린 장단으로 시작하여 차츰 빠른 장단으로 바뀌는데, 이는 듣는 사람을 서서히 긴장시키며 흥겨움을 끌어올리게 한다. ○○○○○는 4∼6개의 장단으로 짜여지는데, 진양조는 아주 느리고 서정적이며 중모리는 안정적이다. 중중모리는 흥취를 돋우며, 자진모리는 밝고 경쾌하다. 휘모리는 흥분과 급박감이 있다. 가야금○○은…","a":"가야금산조 및 병창","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624312.jpg"},{"q":"목기는 나무로 만든 그릇을 말하며, 목기를 만드는 기술과 그 기술을 가진 사람을 ○○○이라 한다. 목기는 남원의 특산품으로서 특유한 향기를 자랑하며 모양이 정교하고 아름답다. 목질이 단단하고, 벗겨지지 않는 옻칠 등으로 조선 전기부터 다른 지방의 목기와는 비교가 안될 정도로 높이 평가되고 있다. 목기의 재료는 오리목, 물뿌리나무, 박달나무, 은행나무 등이다. 목기의 제작과정은 나무를 자른 후 대충 만들고자 하는 형태로 구조만 잡는다. 이것을 초가리라하며, 그 후 40일 가량 그늘에서 말려 틈이 나지 않도록 하고, 재가리에 들어간다. 재가리에서 그릇모양이 형성되는데,…","a":"목기장","c":"시도무형유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644110.jpg"},{"q":"○○○은 구리와 니켈의 합금인 백동을 소재로 비녀, 촛대, 화로, 담뱃대 등 공예품을 제작하는 장인이다. 조선시대 고종과 순종 때 백동으로 주조된 백동전이 통용되었고, 현재에도 100원과 500원 동전 주조에 백동이 사용되고 있다. 우리나라에서 구리에 니켈을 기반으로 하는 현대적 의미의 백동 합금 기술은 백년 이상 사용되었다. 백동은 강도가 높고 산화되는 속도가 더디며 광택을 잘 유지하는 장점 때문에 장신구나 생활용품의 소재로 인기가 높아 한때 한국 금속공예문화 전통을 이루는 중요한 공예기술이었다. 현재 백동은 다른 구리 합금과 비교하여 단단하고 다루기가 힘들어 백동…","a":"백동장","c":"시도무형유산","r":"서울특별시","s":"강동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025070416402100.jpg"},{"q":"○○○는 소리꾼 한 명이 고수(북치는 사람)의 장단에 맞추어 창(소리)ㆍ아니리(말)ㆍ몸짓(너름새)을 섞어가며 긴 이야기를 엮어가는 것을 말한다. 조선 중기 이후 남도지방 특유의 곡조를 토대로 발달하였으며, 지역에 따라 동편제(전라도 동북지역), 서편제(전라도 서북지역), 중고제(경기도·충청도) 등으로 나뉘어졌다. 현재는 ○○○ 다섯마당 또는 ○○○ 다섯바탕이라 하여 ‘춘향가, 심청가, 수궁가, 흥보가, 적벽가’만이 전승되고 있으며, 유네스코 인류무형문화유산으로 지정된 민속예술이다. 대구의 ○○○는 지역에 따른 창제의 명칭은 따로 없지만 예로부터 많은 명창들이 대구지역…","a":"판소리","c":"시도무형유산","r":"대구광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643477.jpg"},{"q":"○○○은 각 지방에 제조법이 구전되어온 술인데, 1955년 <양곡관리법>에 의한 곡주생산 금지조처로 생산이 중단되어 오다가 1986년 후부터 다시 우리의 ○○○을 발굴하고 보존하는 사업이 활발하게 진행되고 있다. 송순주는 25°내외의 맑은 담황색을 내는 술로 위장병, 신경통에 특효가 있고, 풍치예방에도 효과가 있다고 한다. 양조물, 곡자, 송순, 소주를 재료로 하여 만든다. 송순주가 제조 전승되게 된 유래는 조선 선조(1567∼1608) 때 병조정랑을 지낸 김탁이 위장병과 신경통으로 고통을 겪고 있자 부인인 완산 이씨가 산사의 여승으로부터 송순주가 위장병과 신경통에…","a":"향토술담그기","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644087.jpg"},{"q":"○○○○○은 다도해의 문화적 특징을 잘 간직하고 있는 민속예술이다. 바다를 벗 삼아 살아가던 ○○ 사람들의 마지막 길을 배웅하고, 남아있는 가족들의 슬픔을 어루만져 주던 해원과 치유의 굿판이 바로 ○○○이다. 장산도의 ○○○을 전승하는 무속 예인으로는 이귀인, 강부자 부부와 조카며느리 진금순 등 세 명이 있다. 그중 강부자는 장산도들노래로 예능보유자로 지정(1988년) 됐다. 이들은 대대로 무속에 종사해 왔으며, 이귀인은 악사를 맡아왔고, 강부자와 진금순은 무녀로 활동했다. 비금도 ○○○을 전승하는 유점자는 20대에 비금도로 이거한 이후 평생 비금·도초의 무굿 전통을…","a":"신안 씻김굿","c":"시도무형유산","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023062714083700.JPG"},{"q":"○○○○ 탑제는 정월 대보름을 전후해서 마을의 대동신에게 마을의 안녕과 풍년을 비는 민간토속신앙의 하나이다. ○○○○ 입구에는 할아버지탑과 할머니탑으로 불리우는 돌탑 한 쌍이 있어 마을을 보호하고 지켜주는 서낭신의 구실을 한다. ○○○○ 탑신제의 제주(제사를 주관하는 사람)를 공양주라 하며, 부정하지 않고, 덕이 있는 사람을 따져 정한다. 제사를 지내는 날까지 제사를 지내는 사람과 마을사람들은 부정을 멀리하며 근신한다. 음력 1월 14일이면 마을 입구에 금줄을 쳐서 부정한 것을 막는다. 저녁이 되면 풍물을 치며 농기를 모시고 풍년을 기원하는 농신제와 용왕제를 지낸다.…","a":"장동산디마을탑제","c":"시도무형유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643573.jpg"},{"q":"○○○○○은 구례군 구례읍 신월리 신촌마을에서 전승되는 농악으로 호남 좌도농악의 성격과 특징을 갖고 있다. 이 농악은 기본적으로 당산제만굿, 마당밟이, 판굿으로 구성되어 마을굿으로서의 전통을 잘 간직하고 있다. 당산제만굿은 매년 정월 초사흗날 농악대가 오전 10시부터 마을의 당산을 돌면서 제만굿을 하는 형태로 이루어져 있다. 이 굿을 마친 후에 농악대는 마을의 각 가정집을 다니면서 액을 물리치기위한 마당밟이를 하며 이것이 끝난 후에 전 마을 사람들이 동참하는 판굿으로 이어진다. ○○○○○은 전문적인 농악집단에 의해서 전승되는 것이 아니고 마을 사람들을 중심으로 운영되…","a":"구례잔수농악","c":"국가무형유산","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623815.jpg"},{"q":"농악은 농부들이 두레(마을의 공동 작업을 하기 위한 조직)를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 호남우도농악의 일종인 ○○○○은 호남우도농악과 경남농악·경기농악의 특색을 고루 지녀 음악·춤사위 놀이가 완벽한 짜임새를 갖추고 있다. 장단 또한 호남우도농악과 경상도농악의 중간적인 성격을 띠어 생동감 넘치는 가락이 많다. 현재 ○○○○의 예능보유자인 나모녀씨는 쇠가락으로 농악대를 총지휘하는 상쇠의 예능인으로서, 춤사위나 그 짜임새가 다양하고 기교가 넘쳐난다. 그의 쇠소리는 신령이 감동하는 소리라고 평가…","a":"부안농악","c":"시도무형유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644097.jpg"},{"q":"○○는 우리나라 전통 성악곡의 한 갈래로, ○○체(산문에 가까운 문체)의 긴 사설(글)을 담은 장편 가요를 일컫는다. 언제 발생되었는지는 정확하지 않으나 여러 ○○집의 기록으로 미루어 보아 조선 영조(재위 1724∼1776) 이후부터 불리기 시작했으리라 추측된다. 오늘날까지 전래되고 있는 곡은 백구사, 죽지사(건곤가), 황계사, 어부사, 춘면곡, 상사별곡, 길군악(노요곡), 권주가, 수양산가, 처사가, 양양가, 매화타령(매화가) 등 12곡이며, 이를 12○○라고 한다. 이 곡들의 작사자나 작곡가는 알려져 있지 않으나 한말에 전통이 성립된 것으로 보고 있다. ○○의 사…","a":"가사","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623206.jpg"},{"q":"초고공예는 오랜 농경생활과 함께 쓰임과 영역에서 보편성을 지닌 생활공예로 공예문화의 가치와 중요성이 날로 부각되는 시점에서 고유성 짙은 초고공예의 가치를 재고하고 향후 이 분야의 발전을 위한 주도적 역할이 필요하기에, 산업화로 단절될 위기에 있는 실정인 초고공예의 기능 보존을 위하여 무형유산으로 지정하였다. 아울러 초고공예의 보존․전승을 위하여 전통기법으로 생활기물에서 완상품까지 고루 제작하는 탁월한 기능을 지닌 양중규를 ○○○ 기능보유자로 인정하였다.","a":"초고장(양중규)","c":"시도무형유산","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643590.jpg"},{"q":"○○○은 문방사우(文房四友)의 하나인 붓을 만드는 사람과 그 기술을 말한다. 붓은 붓털과 붓대, 붓뚜껑으로 이루어지는데 붓털의 재료로는 양, 사슴, 토끼, 족제비, 호랑이, 노루 등의 털이 사용되며, 붓의 대는 대나무를 많이 사용하였으나 금·은 조각을 새긴 장식붓대와 옥, 상아 등을 사용하기도 하였다. 붓의 제작과정은 붓의 핵심인 붓털에서 시작된다. 붓털은 털이 빳빳하고 뾰족한 것, 털이 많으며 가지런한 것, 털 윗 부분이 끈으로 잘 묶여서 둥근 것, 오래 써도 털에 힘이 있는 것이 기본 조건이다. 이인훈씨는 할아버지로부터 삼대에 걸쳐 붓을 가업으로 만들고 있다. 이…","a":"모필장","c":"시도무형유산","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643490.jpg"},{"q":"광주 ○○○○ 소주는 ○○○○에서 전승된 민속주이다. ○○○○은 ‘작은 서울’이라 불릴 정도로 숙종 때 번성했던 곳이다. ○○○○ 일대는 서울에 근접해 부자가 많았으며 여유 있는 생활을 하던 이들이 만들어 마시면서 유래되어 조선후기까지 널리 애용됐다고 한다. 최초로 빚은 시기는 ○○○○을 축조한 선조(재위 1567~1608) 때로 추정되며, 그 후 임금께도 진상되었다고 한다. 양조재료는 ○○○○에서 흘러 내려오는 물과 이곳에서 생산되는 쌀, 그리고 재래종 통밀로 만든 누룩, 다른 토속주에서는 찾아볼 수 없는 재래식 엿을 고아 사용한다. 누룩을 빚을 때 조청을 푼물로…","a":"남한산성소주","c":"시도무형유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643633.jpg"},{"q":"망상지역에서는 새해를 맞이하는 시기에 마을에서는 정월대보름날 고청제사를 드리고 서낭당에서 서낭굿을 치기 전까지는 일체의 악기를 치지 않는 금기가 이어져오고 있다. 서낭신을 모시고 서낭쇠를 치고 나서 고청제농악으로 신과 인간을 연결하는 한바탕 축제의 놀이를 펼친 후부터 각 마을에서는 자유로이 쇳소리를 울리며 가가호호 돌아다니며 지신을 밟아주며 가정의 평화와 안녕을 기원하는데 이 때 각 가정에서는 술과 안주를 내고 쌀이나 돈을 내놓는데 이러한 금품은 모두 모아 마을의 공동기금으로 사용한다. ○○○○은 이렇듯 한 해의 농사가 시작되는 정월대보름날 아침에 서낭당에 인사하고…","a":"동해 망상농악","c":"시도무형유산","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019050214230800.jpg"},{"q":"봉화유기는 500여년의 장구한 역사를 가지고 있으며, 전국의 많은 장인들에게 유기제조 기술을 전파한 우리나라 유기제조의 발상지이다. 특히, 안성의 유기제조법도 봉화로 부터 전래되었다고 한다. 19세기초까지만 해도 봉화유기의 명성은 전국적으로 널리 알려져 이곳을 놋점거리라고 불리기도 했다. 이는 쇠를 녹이는데 필요한 숯의 생산이 쉽고 내성천의 풍부한 물이 천혜적인 입지조건이었기 때문이다. 그러나 1919년 태백산 일대의 산림벌채 금지조치와 일제말기의 시대적 변화에 이기지 못하여 쇠퇴해 버렸고 현재 두가구만 겨우 옛 명성의 명맥을 유지하고 있는 실정이다. 타 지방의 경우…","a":"봉화유기장","c":"시도무형유산","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018103110000200.JPG"},{"q":"충청남도 공주시 탄천면 송학리 소라실에서 마을 평안과 풍년을 기원하는 ○○○이다. 소라실 ○○○의 연원은 정확히 알 수 없다. 마을에는 장승을 세우게 된 유래에 대해서 크게 두 가지 설이 전해내려온다. 하나는 마을의 허(虛)한 방위를 막고자 하는 비보(裨補) 장승이며, 다른 하나는 화기(火氣)를 막기 위한 화재맥이 장승이라는 것이다. ○○○는 마을사람들의 정성을 모아 중단되지 않고 거행되었는데 일제강점기 일본인들이 무기를 만들기 위해 농기구, 수저 등 모든 쇠붙이들을 가져가는 가운데서도 소라실 마을사람들은 ○○○에 필요한 꽹과리, 징 등을 끝까지 숨겨 ○○○를 지냈다…","a":"공주탄천장승제","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026022314395201.jpg"},{"q":"○○○은 도자기 기술자 중에서 숙련된 기술을 가졌거나 높은 명성으로 무형유산으로 지정된 사람을 말한다. 충주시 엄정면에 거주하는 이종성(李鐘誠, 1958~ )은 1974년 전통도예 백자 기술에 입문 한 후 백자와 청자 제작 기법뿐만 아니라 뛰어난 투각(透刻)기법에 능통한 장인이다. 이종성은 19세때인 1974년 인천 선암도예에서 입문한 후, 백자 기술 계승에 중점을 두고 활동하고 있다. 경기도 무형문화유산 고(故) 안동오(1919~1989) 선생 기문에 입문한 후 최고 난이도 기술로 일컬어지는 투각기술을 익혀 뛰어난 투각 작품을 제작하였다. 그 후 안동오 선생 문하의…","a":"사기장","c":"시도무형유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643895.jpg"},{"q":"야류(들놀음)는 경상남도 내륙지방에서 행해지던 오광대가 바닷길을 따라 수영·동래·부산진 등에 전래된 것으로, 야류란 이름은 넓은 들판같은 곳에서 놀기 때문에 붙여진 것이라고 한다. 오광대가 전문연예인에 의해 행해진 도시가면극이라면 야류는 비직업적인 연희자들, 즉 마을사람들에 의해 토착화된 놀이이다. ○○○○는 정월 대보름에 산신령과 샘물, 그리고 최영 장군 묘에 제사를 지낸 후 달이 뜨기를 기다려 행해진다. 약 200년전 좌수영 수사의 직책을 맡았던 관리가 초계 밤마리(현재 합천군 덕곡면 율지리)의 대광대패들을 불러다가 놀게 하였는데 부하들이 이를 보고 배운데서 시작…","a":"수영야류","c":"국가무형유산","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623437.jpg"},{"q":"○○○○○는 경상남도 창녕군 영산면에서 전승되는 민속놀이로 현재는 3·1문화제 행사의 하나로 ○○○○를 하고 있다. ○○○○는 마을을 동·서로 갈라 두패로 편을 짜서 노는 편싸움으로, 동서 양편은 각각 남성과 여성으로 상징되며, 생산의 의미에서 여성을 상징하는 서편이 이겨야 풍년이 든다고 전한다. ○○○○는 줄쌈이라고도 하며 영산지방에서는 ‘줄땡기기’ , ‘갈전(葛戰)’이라고도 하는데 이는 산의 칡넝쿨보다 길게 줄을 만들어 당겼다는 옛이야기에서 나온 말이다. ○○○○는 주로 정월 대보름을 전후해 벼농사를 위주로 하는 중부 이남지역에서 널리 행해지는 농경의식의 하나로…","a":"영산줄다리기","c":"국가무형유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624134.jpg"},{"q":"나전칠기란 옻칠을 한 표면에 소라, 전복, 조개 등을 이용하여 문양을 만들어 붙인 공예품으로 오색영롱한 자연색과 은은한 광택을 자랑하는 옻칠이 잘 조화된 우리 민족의 대표적인 공예품이라 할 수 있다. 광주는 칠과 먹, 목탄이 많이 생산되어 3흑(黑)의 고장으로 일컬어졌으며 사적 375호인 신창동 유적에서 칠기용기와 도구가 발견되어 칠 공예의 오랜 역사를 증명하고 있다. 김기복은 나전과 칠 제작 기법과 조형미 등이 두루 뛰어난 명인이다. 통영에서 태어나 16세기부터 50여 년 넘게 나전칠기의 맥을 잇고 있다. 통영 나전칠기 기술학교에 입학해 기술을 전수 받았고 19세…","a":"나전칠장","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643560.jpg"},{"q":"○○○○은 포괄적으로 ○○○○이라고 하였지만, 양주 고을 전체에 전승되는 몇 가지 농악이 기반이 되었다. 그 농악 전승의 주맥을 이루는 것은 양주지역의 광적면 석우리 박달동 농악, 광석리 농악, 덕도리 농악 등으로, 이러한 농악이 합쳐져서 오늘날의 ○○○○에 이르렀다. 경기 북부 지역 농악의 성격을 온전하게 갖추고 있으며, 경기도의 농사풀이 농악의 전형적인 면모를 구현하고 있는 농악이다. ○○○○은 기본적 성격이 농사과정을 마치고 하는 ‘호미씨세’와 관련이 있다. 이 고장에서는 두레를 짜서 마을곳곳마다 두레가 극성스러웠다고 한다. 두레가 근간이 되어 농사일을 마칠 때…","a":"양주농악","c":"시도무형유산","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411400500.jpg"},{"q":"「○○○○○」은 탑의 내부에 사리 등을 봉안하듯이 불상･불화 등을 조성하여 모시기 전에 불상 내부나 불화 틀 안에 사리와 오곡 등 불교와 관련한 물목(物目)을 봉안함(불복장)으로써 예배의 대상으로 전환시키는 의식이다. 이러한 의식을 통해 세속적인 가치의 불상･불화에 종교적 가치가 부여되어 예배의 대상으로 전환하는 것이다. 고려 시대부터 설행(設行, 베풀어 행함)되어 700년 이상의 전통을 갖고 있으며 해당 의례의 저본(底本)인 『조상경(造像經)』이 1500년대부터 간행되어 조선 시대에 활발히 설행되었으며, 일제강점기에도 비전(秘傳)되어 현재까지 전승의 맥을 이어온 점…","a":"불복장작법","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2019050215444300.JPG"},{"q":"○○○는 공중에 맨 줄 위에서 재미있는 이야기와 발림을 섞어가며 여러 가지 재주를 보여주는 놀이이다. 줄 위를 마치 얼음지치듯 미끌어지며 나가는 재주라 하여 '어름' 또는 '줄얼음타기'라고도 한다. 주로 음력 4월 15일이나 단오날, 추석 등 명절날에 연희되었으며, 개인의 초청에 응해서 돈을 받고 놀아 주는 경우도 있었다. ○○○는 조선시대에 두 계통으로 나뉘어 발달했다. 하나는 주로 양반층을 위해 공연되었던 광대○○○로 순수하게 ○○○로만 구성되어 기술의 종류나 솜씨에서 뛰어났다. 다른 하나는 남사당패의 어름○○○로 서민들을 위해 공연되었던 만큼 재담이나 오락성이…","a":"줄타기","c":"국가무형유산","r":"경기도","s":"과천시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623578.jpg"},{"q":"서민들이 삶의 현장에서 노동의 피로를 줄이고 일의 능률을 배가시키기 위해 자연스럽게 발생한 삶의 소리임. 그 사설의 내용에는 그들의 일상생활이 진솔하게 표현되어 있는 까닭에 그것을 통해서 우리 조상들의 정서를 이해하고 생활의 모습을 짐작하는데 매우 귀중한 자료가 됨.","a":"거창일소리","c":"시도무형유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644560.jpg"},{"q":"○○○○○는 경상북도 경산시 자인면에서 전승되고 있는 단오행사이다. 마을의 전설에 의하면, 신라(혹은 고려) 때 왜적이 침범하여 마을사람들을 괴롭히자, 한장군이 꾀를 내어 여자로 변장하고 누이동생과 함께 화려한 꽃관을 쓰고 춤을 추어 왜병들을 무찔렀다고 한다. 이후 한장군이 죽은 다음 자인마을 주민들이 한장군의 사당을 짓고 해마다 단오날이면 제사를 지내고 성대한 놀이를 즐겼다고 전해진다. ○○○○○는 제사와 가장행렬 여원무로 이어진다. 옛날에는 전쟁터까지 가서 여원무를 추고 사당에 올라가 제사를 지냈으나, 지금은 시장의 넓은 광장에 모여 한장군 묘를 향해 행렬을 하는…","a":"경산자인단오제","c":"국가무형유산","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623997.jpg"},{"q":"○○○은 주로 홍화꽃을 이용해 붉은 색을 들이는 장인으로, 조선시대 상의원(尙衣院)과 제용감(濟用監)에 각각 10명씩 속해 있었다. 홍색은 조선시대 왕실의 권위 등을 상징하던 색으로, 홍색으로 된 관복은 왕세자와 당상관 이상만 착용할 수 있었고, 홍색 가운데 가장 진한 색인 대홍색은 홍화염색을 8번 이상 반복하여야만 만들어 낼 수 있는 색으로서 왕실에서 주로 사용한 조선 최고의 색이었다. 2017년 4월 13일에 김경열이 보유자로 인정받아 활동해 오고 있다.","a":"홍염장","c":"시도무형유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102609421000.jpg"},{"q":"○○○란 고소설 작품을 읽어주는 전문가를 말한다. 조선 후기 출현한 이들은 고소설 낭독을 생업으로 삼아 활동하였다. 그리고 이러한 전통이 후대에 이어지면서 전국 방방곡곡에 소설을 읽어주는 문화가 출현하였다. 특히 일제 강점기에 이와 같은 문화가 확산되었다. 읍치나 읍면을 비롯해 작은 단위의 마을에도 이야기 선생이나 이야기꾼이 있어 고소설 낭독을 주도하였다. 그들은 오일장을 따라 이동해 활동하기도 하고 도의 경계를 넘어 교류하며 소설을 읽었다. 충청도 이야기꾼이 전라도나 경상도로 넘어가 이야기 낭독을 주고받으며 실력을 겨루기도 하였다. ○○○는 전통예능으로서 그 기예를…","a":"계룡 강독사","c":"시도무형유산","r":"충청남도","s":"계룡시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020061214362600.jpg"},{"q":"○○○○는 충청도 일부지방에 전승되는 민요의 하나로 농부들이 김을 매면서 피로를 잊고 능률을 올리기 위해 부른 노동요이다. 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수 있다. ○○○○는 메나리라고도 부르는데 이는 산유화를 풀어서 ‘뫼놀이’라 한 것이 메나리로 되었다는 설과 옛 민요 ‘미나리꽃은 한철이라’하는 데에서 나왔다는 설이 있다. 또 다른 명칭으로는 뫼놀꽃, 미나리 등이 있다. 이 민요는 노인분들에 의해서 토막토막 구전되어 왔다. 나라(백제)를 잃은 슬픔과 조국에 대한 그리움을 담은 노래이기 때문에 구슬프고 처량한 느낌을 준다. 남녀가 주고 받…","a":"산유화가","c":"시도무형유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643954.jpg"},{"q":"‘○○○○’는 훈민정음이 창제되고 반포된 15세기부터 현대에 이르기까지 종이에 국한하지 않고 금석(金石), 섬유 등 다양한 재질의 매체에 한국인의 삶을 기록하는 중요한 수단으로 전해져왔다. 왕실에서 민간에 이르기까지, 한글로 쓴 문학작품의 필사본이나 일상적으로 주고받는 편지글에서도 자연스럽게 사용되었으며, 전통적인 판본체, 궁체 외에 개인화된 필체인 민체를 통해 다양한 서체와 필법으로 오늘날까지 이어져오고 있다. ‘○○○○’는 문자를 이용한 독창적인 조형예술로서 다양한 서예 작품을 통해 시대별로 변화하는 미적 감각과 사회상을 담고 있으며, 이러한 예술적 의미와 기능은…","a":"한글서예","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2025012309331590.jpg"},{"q":"○○○○은 동래지방에서 전승되어오는 학춤이다. 주로 정월대보름날 동래야류나 줄다리기를 할 때 추던 춤으로, 어떤 춤꾼이 도포에 갓을 쓰고서 덧배기 춤을 추는 모습이 “학이 춤추는 것과 같다”라고 한데서 학춤이라 이름 붙여졌다 한다. ○○○○은 의상을 따로 갖추지 않고 일상의 옷인 도포에 갓을 쓰고 바지저고리, 버선과 미투리를 신고 즉흥적으로 춘다. 반주악기는 꽹과리와 장구, 징, 북 등의 농악편성으로 되어 있고 장단은 굿거리 장단이다. 춤사위에는 양손을 너울거리는 날아가는 사위, 한 발 들고 서 있는 발 드는 사위, 학이 날개를 폈다가 오므리는 모습의 펴는 사위와 오…","a":"동래학춤","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643405.jpg"},{"q":"○○○○○은 한지제작의 전 과정을 전통방식으로 재현하여 한지제작의 전형을 계승하고 있으며, 한지의 유래와 활용에 있어 ○○의 지역적 특징과 뚜렷한 고유성을 보여주는 기.예능이라는 점에서 강원 전통문화의 체계적 보존, 전승을 진행하고 있다.","a":"원주 한지장","c":"시도무형유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052116093500.bmp"},{"q":"\"소목장(小木匠)이란 건물의 문, 창문이라든가 장롱, 궤, 경대, 책상, 문갑 등 목가구를 제작하는 기술과 그 기술을 가진 목수를 말하는 것으로 건축을 주로 하는 대목장(大木匠)에 대칭되는 말이다. 화류(樺榴)는 모과나무를 말하는 것으로 고급가구 재료로 많이 쓰인다. 소목장이라는 명칭은 고려시대부터 나타나며, 조선시대에는 목장(木匠)이라고 하였으나 대목장과는 구분하였던 것 같다. 조선 전기까지는 목가구가 주로 왕실이나 상류계층을 위해 만들어졌으나 조선 후기에는 민간에 널리 보급되고 종류도 많아져 지역적인 특성이 현저히 나타나게 되었다. 현재 무형유산으로 인정된 조기종…","a":"화류소목장","c":"시도무형유산","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643547.jpg"},{"q":"영산재란 부처가 영취산에서 행한 설법회를 재현하는 의식으로 불교에서 영혼천도를 위한 의식 가운데 규모가 가장 큰 의식이다. 의식의 절차는 우선 부처가 그려진 그림(괘불)을 야외에 내어 거는 괘불이운과 천도받을 대상을 절 밖에서 모셔오는 시련(侍輦)을 행한다. 의식이 행해지는 장소를 정화하고 참여인들의 마음을 가다듬고 정화하는 의식을 행한 후에, 불단과 제사를 받게될 영혼에게 제사드릴 3개의 단에 제물을 올리고 소원을 비는 의식을 행한다. 그런 다음 영산재를 마련한 사람들의 보다 구체적인 소원을 비는 축원문을 낭독한다. 낭독이 끝나면 의식을 진행한 스님을 선두로 모든…","a":"부산영산재","c":"시도무형유산","r":"부산광역시","s":"사상구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643428.jpg"},{"q":"활쏘기는 활과 화살을 사용하여 과녁을 맞추는 전통무술 또는 경기이다. 활쏘기는 고대부터 주요한 무술의 하나로 사용되었으며, 사대부가를 중심으로 기품 있는 운동 또는 놀이로 전승되었다. ○○○○는 편을 짜서 활쏘기 경기를 하는 놀이로 터편사·골편사·○○○○·사랑편사·한량편사 등이 있었으며, 각각 갑·을·병 3등급으로 나누어 경기를 했다. 이 중 ○○○○○는 도성 안이 한편이 되고 변두리 몇 개의 활터가 한편이 되어 경기를 하는 것이다. 활쏘기를 하는 장소를 활터, 사장 또는 살터라고도 하며 활터에는 정자가 있는데 이를 사정(射亭)이라 한다. 조선 전기에는 관청에서 사정…","a":"장안편사놀이","c":"시도무형유산","r":"서울특별시","s":"중랑구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018110114490300.JPG"},{"q":"○○○○○은 강림신앙의 한 형태로써 고려 충신 ○○○○ 및 여타 신들을 강림시켜 ○○○○을 초모함은 물론 여타의 신령들을 대접하기 위한 무속의례이다. ○○○○이 무교의 신으로 받아들여진 것은 조선 세종때인 것으로 추정되며, ○○○○을 모시고 나라의 태평과 국태민안을 축원함은 물론 무당들이 장군으로부터 영험력을 얻기 시작한 것으로 알려지고 있다. ○○○○처럼 무속신앙에서 모셔시는 영웅신은 대부분 국가적 차원에서 깊은 애국심을 갖고 활동하다가 죽음과 함께 민중들로부터 영웅시되어진 경우가 많으며, 특히 황해도 굿으로 치러지는 ○○○○○은 굿이 ‘드는 날’, ‘묵는 날’,…","a":"최영장군 당굿","c":"이북5도 무형유산","r":"황해도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669670.jpg"},{"q":"도자기는 흙으로 빚은 그릇을 구워내는 방법에 따라 도기(陶器), 자기(瓷器)로 나누어 지는데, 백토 등이 혼합되어 높은 온도에서 구워낸 그릇을 사기(자기)라 한다. ○○○이란 사옹원(司饔院)에서 사기를 제작한던 장인을 일컫는 말이다. 우리나라 도자기는 고려시대부터 천하제일의 비색청자로서 그 명성을 떨쳤다. 조선시대에는 국가기관인 사옹원(司甕院)에서 자기를 제작하였는데, 경기도에 분원을 설치하여 왕실에서 사용하는 자기를 특별히 제작하였다. 조선 후기 관요(정부 관리하에 도자기를 만드는 곳)가 폐쇄되면서 도공들이 문경, 괴산, 단양 등 지방으로 흩어져 민요(민간에서 도자…","a":"사기장","c":"국가무형유산","r":"경상북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624048.jpg"},{"q":"○○○○○는 ○○시 모전동 일대에서 전승해온 노동요와 의식요 및 유희요를 뜻한다. 가래질소리를 시작으로 목도질소리, 모심는소리 등 총 10가지 마당으로 구성되어 있으며, 2010년 창립한 ○○○○○보존회에 의해 전승 보존되고 있다. ○○○○○보존회의 모태는 '모전중신기농악대'로, 1900년경부터 빈농들이 이 지역에 모이면서 연희되어 오다가 1940년대에 농악대가 정식으로 형성되어 현재까지 이어지고 있다. 일제강점기의 농악대는 양수봉이라는 3대 상쇠를 통해 전승되어 현재 소리꾼 중심인물 5명 중 4명에게 전수되고 있다. 음악적 측면에서 선율은 대부분 경상도 지역의 메나…","a":"문경 모전들소리","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020062408551100.jpg"},{"q":"승무(僧舞)는 승복을 입고 추는 춤으로 우리나라의 대표적인 민속춤 가운데 하나이다. 승무는 흔히 무복(舞服) 때문에 중춤이라고도 하지만 불교의식에서 승려가 추는 춤과는 다르다. 승무의 유래는 불교문화사적 입장에서 본 불교설과 김만중 소설 중 구운몽에서 나왔다는 설, 탈놀음 중에서 노장춤과 파계승의 번뇌에서 비롯된 춤이라는 설 중 어느 것이 확실한지 알 수 없으나, 1910년대쯤 기방에서 발전되었다고 한다. 춤의 형태는 의식성이나 종교성, 생산성, 극성, 놀이성이 전혀 담겨 있지 않은 홀춤[독무(獨舞)]으로, 춤사위가 살풀이춤과 유사함을 지니고 있어 기녀들에 의해 예술…","a":"전라삼현승무","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093013200500.jpg"},{"q":"송광무(宋光武, 승명 현담現潭, 대한불교 법륜종)는 1954년 광주 광산구 운수동에서 출생하여 12세 때인 1966년 부친인 구봉(龜峰) 송복동(宋福東, 1911∼1998)으로부터 불화 공부를 시작하였다. ○○○으로 지정되던 해에 광산구에서 북구 화암동으로 거주지를 옮겼다. 그는 부친으로부터 불사 전반의 기능을 사사 받아 전통의 명맥을 이어오면서 오대산, 백양사, 선운사 등 전국 100여 개 사찰에서 탱화, 단청, 조상(불상), 개금(불상에 금칠을 다시 함)을 하였고, 최근에는 제작기법이 전승되지 못한 천연석채의 복원을 위해 재료의 발굴과 재현 작품을 통해 전통 불화…","a":"탱화장","c":"시도무형유산","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643561.jpg"},{"q":"청화백자는 1200℃ 이상의 고온 번조를 통해 에서 번조하면 푸른색으로 발색하는 산화코발트로 문양을 장식한 백자이다. 흰 바탕과 푸른 문양이 어우러져 청신하고도 세련된 장식미를 나타내는 청화백자는 중국에서 원대(元, 1279~1368)부터 백자의 장식에 본격적으로 사용되기 시작하여 명·청대까지 성행적으로 제작되었다. 그 영향으로 우리나라에서도 조선 초 15세기 중반 무렵 청화백자가 만들어지기 시작하여 조선후기까지 왕실을 대표하는 도자기로 경기도 광주지역에 설치된 관요官窯를 중심으로 제작되었다. 『신증동국여지승람新增東國輿地勝覽』 「토산조土産條」에 의하면 왕실의 화원畵員…","a":"사기장(청화백자)","c":"시도무형유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091017320900.jpg"},{"q":"○○○○○는 부리면 어재마을을 중심으로 하여 인근 마을은 물론 제원면 일대까지 여러 마을이 모여 행하는 기우제이다. 하지가 지나도록 비가오지 않아 모내기를 하지 못하면 마을 사람들은 큰 걱정에 쌓여 가뭄을 해결하기 위하여 기우제를 지내게 된다. 자연의 재해를 인간의 힘으로 해결하지 못하면 어떤 초월적 존재나 여러 주술을 통하여 해결하고자 하는 마을 공동체적인 집단의식의 하나로 기우제를 지낸다. 기우제는 마을 모든 사람들이 비가오지 않아서 쌓인 심리적인 갈등을 풀고 깨어진 생활 리듬에서 오는 충격을 막거나 적게 하면서 현실의 어려움을 함께 나누며 극복하려는 공동체 사회…","a":"금산농바우끄시기","c":"시도무형유산","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644022.jpg"},{"q":"○○○○는 주철(무쇠)로 솥과 쟁기날을 제작하는 공예기술이다. 제주도는 예로부터 본토와의 교역이 불편했기 때문에 생활필수품이나 농기구의 대부분을 자급자족해 왔는데 ○○○의 ○○○○가 대표적인 것이다. 제주도 주물공예의 형태는 손의 힘으로 바람을 일으켜 쇠를 녹이거나 달구는 손풀무와 땅바닥에 골을 파서 중간에 굴대를 박고 그 위에 널빤지를 걸쳐놓아 한쪽에 세 사람씩 서서 널빤지를 널뛰기하듯 디뎌가며 바람을 일으키는 골풀무가 있다. 손풀무는 다시 똑딱불미와 토불미로 구분한다. 똑딱불미에서는 달군 쇠를 두들겨 주로 칼이나 호미 등을 만든다. 토불미에서는 둑(용광로)에서 녹…","a":"덕수리불미공예","c":"시도무형유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644686.jpg"},{"q":"○○玉匠은 여러 종류의 옥석류와 보패류를 가공하여 왕실의 기물류와 남녀 장식류 등을 금·은 세공하여 만드는 장인을 말한다. 옥석 및 보패류로는 경옥·연옥·산호·호박·마노·수정·공작석·유리제옥·상아·대모·서각·흑각·진주·석웅황 등이 있다. 이러한 옥석패물은 궁중에서부터 사대부 그리고 일반 서민까지 널리 사용되어 왔으며 그 종류로는 노리개·떨잠·뒤꽂이·비녀·귀걸이·가락지·장도·동곳·관자·선추·침낭·풍잠·단추·갓끈 등 다양하게 쓰였고 왕실의 장식물로는 왕과 왕비의 옥대, 어보, 옥류, 면류관, 패옥,대수장신구 등에 사용되었다. 전통적인 제작공정은 채석 → 디자인→ 절단 →…","a":"옥장","c":"시도무형유산","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091316563500.jpg"},{"q":"목재를 다루는 장인을 목수木手라 하고, 궁궐·사찰·집을 짓은 목수를 대목장大木匠이라 하고, 가구·창호 등을 만드는 목수를 ○○○이라 한다. ○○○에게는 나무가 가진 아름다움을 최대한 살려 한국 고유의 조형미를 창출해 내는 능력이 요구된다. 즉 나무 자체에 대한 이해는 물론 목구조에 대한 지식도 필요하며, 무엇보다도 예술적 감각을 갖추어야 한다. 아울러 완성된 가주는 실용성과 함께 예술성을 갖추어야 하며, 무엇보다도 기후의 변화 등에도 잘 견딜 수 있게 내구성이 강해야 한다. 목가구의 제작 과정은 다양하고 복잡하며 정교하다. 짜임기법만도 주먹장짜임, 연귀짜임, 장부짜임…","a":"소목장(가구)","c":"시도무형유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643635.gif"},{"q":"○○○은 놋쇠로 각종 기물을 만드는 기술과 그 기술을 가진 사람을 말한다. 우리나라 유기의 역사는 청동기시대부터 시작되었고 신라시대에는 유기를 만드는 국가의 전문기관이 있었다. 고려시대에는 더욱 발달하여 얇고 광택이 아름다운 유기를 만들었다. 조선 전기에는 기술이 퇴화한 듯하였으나 18세기에 이르러 다시 성행하여 사대부 귀족들은 안성지역에 유기를 주문하여 생산하도록 하였다. 유기는 대표적인 구리 합금 금속으로서 각 성분비율에 따라 여러 종류가 있는데, 구리에 주석을 섞는 비율에 따라 이름이 달라지기도 한다. 구리와 아연을 합금하여 만든 그릇은 황동유기라 하는데 노르스…","a":"유기장","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624385.jpg"},{"q":"○○○이란 옷감을 재료로 바늘에 실을 꿰어 바느질하는 기술과 그 기술을 가진 사람을 말한다. 침선의 범위는 옷을 말려서 바느질하는 봉제, 무늬를 수놓은 자수 옷에 곁들여 장식하기 위해 만드는 장신구 등 옷을 만들고 관리하는 과정 모두를 뜻하나 여기서는 옷감의 마름질, 바느질, 다림질 등의 과정을 말한다. 우리나라는 상고시대부터 수준 높은 복식문화를 형성하였다. 우리나라 전통복식은 변화와 발전을 거듭하면서 현재까지도 그 명맥을 유지하고 있는데 기후나 풍토 등의 자연조건과 지역성, 생활환경에 따른 지역적인 토착문화를 형성하면서 차이를 보인다. 침선에 필요한 재료는 명주를…","a":"침선장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644137.jpg"},{"q":"경기도 남부에 해당하는 부천, 시흥, 안산, 오산, 화성, 수원, 경기 광주, 안성 등의 마을굿을 경기도당굿이라 한다. 이 마을굿에는 집안 대대로 무업을 세습하는 세습무들에 의해서 굿을 진행하는데 이들 세습무의 남자들을 화랭이 또는 산이라 부르고, 여자들을 미지라 부른다. 경기 남부 화랭이패 또는 산이들이 중심이 되는 경기도당굿의 춤은 넓은 의미로는 경기도당굿 굿판에서 추어지던 춤을 의미하기도 하고, 좁은 의미로는 굿판을 떠나 공연 예술화된 경기도당굿○○○○을 말하기도 한다. 또한 이 춤의 반주음악이 경기도당굿 무악인 섭채, 반설음장단, 오니굿거리, 진쇠장단, 올림채…","a":"경기시나위춤","c":"시도무형유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018081010043300.jpg"},{"q":"농요는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로 들노래 또는 농사짓기 소리라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며 지방에 따라서 노래가 달라질 수도 있다. ○○○○는 금곡천 유역에 인류가 정착하여 농경문화가 발달하면서 크게 발달하였다. 내용은 용신제·모내기·건젱이·뚝매기·아시매기(논매기)·쉴참·만물 등으로 구성되어 있다. 모내기소리인 ‘어럴럴럴상사리’와 논매기소리인 ‘얼카덩어리’또는 두레소리 등은 이 지방에서 자생한 소리이다. ○○○○는 순수 우리 가락이며, 근래에 들어와 예전의 농요와 두레(공동작업을 하기위한 조직…","a":"결성농요","c":"시도무형유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643995.jpg"},{"q":"전통사회에서 농악은 크게 세 가지 존재방식을 갖는다. 첫째, 대보름 무렵에 하는 당산굿이나 마당 밟기와 같은 의식과 관련된 농악, 둘째, 두레꾼과 함께 김매기 등에서 치던 두레굿과 같이 노동과 관련된 농악, 셋째 판굿과 같이 놀이와 관련된 농악이 그것이다. 현재 전승되는 “○○○○ 농악”은 이 중 놀이와 관련된 판굿 형태의 농악이며, 이 안에서 농사일을 놀이로 재현하는 농사굿 놀이가 주 내용을 이룬다. 이런 농사굿은 경상북도와 강원특별자치도 일부 지역에서 보이는데 지역적으로 먼 강화에서 비슷한 내용의 농악이 보존되고 있다는 점이 큰 특징이라 할 수 있다.","a":"갑비고차농악","c":"시도무형유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643521.jpg"},{"q":"어산은 불교 의식을 구성하는 소리를 뜻하며 흔히 범패라고도 하고 범음이라고도 한다. 어산을 범패라 칭하는 이유는 불교 음악이 인도에서 발생했기 때문인데, 이는 부처님의 공덕을 찬탄ㆍ찬양하는 것을 노래로 부른 것에서 유래되었다. 어산이라는 용어가 사용되어진 것은 중국 삼국시대 위나라 때이다. 진사왕 조식(A.D 192~232)이 처음으로 범패를 지었다고 전하는데 조식이 어느 날 산동지방의 어산(魚山)을 거닐다가 공중에서 범천이 찬탄하는 소식을 듣고 이것을 모방하여 후세에 전했다고 하며 중국에서 범패가 최초로 만들어진 곳이 어산이기 때문에 이후 불교음악을 총칭할 때 어산…","a":"경제어산","c":"시도무형유산","r":"서울특별시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409290500.jpg"},{"q":"○○○○○는 안동지방에서 정월 대보름에 행해지던 여성들만의 민속놀이로 ‘○○○놀이’ 또는 ‘기와밟기’라고 부르기도 한다. 놀이에 대하여는 고려 공민왕(재위 1351∼1374)이 홍건적의 난을 피해 공주를 데리고 안동으로 피난을 와 개울을 건널 때 마을의 부녀자들이 허리를 굽혀 다리를 놓았다는데서 유래되었다는 설이 전해진다. ○○○○○는 동부와 서부로 패를 나누어 서로 겨루기도 하지만 일반적으로 길을 비켜서 놀이를 해나간다. 맨 앞에 창립(創立)이라고 부르는 5, 60대 할머니가 서고, 다음에 장년(壯年)이라 해서 30대 부인들이 뒤를 따른다. 장년 뒤에 ○○○의 역할…","a":"안동놋다리밟기","c":"시도무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644306.jpg"},{"q":"○○○○는 부산시 동래구에 전승되는 북춤이다. 고려 전기 궁중악을 관장했던 교방청(敎坊廳)의 기생들에 의해 추어졌으나, 조선시대 때 동래감영의 교방으로 전해지면서 지역의 특성에 따라 ○○○○라는 이름으로 불리게 되었다. 『고려사』「악지」에 기록된 내용을 보면, 고려 충렬왕(재위 1274∼1308) 때 귀양살이를 하던 이혼이라는 양반이 바다에 떠내려오는 뗏목으로 북을 만든 것이 북춤의 기원이 되었다고 한다. ○○○○는 중앙에 큰 북을 놓고 4명의 무용수가 영산회상곡인 잔영산, 염불도드리, 타령군악에 맞추어 북을 치면서 춤을 추면, 다른 4명의 무용수가 지화자를 노래하면…","a":"동래고무","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643432.jpg"},{"q":"부채에 대한 문헌상의 기록은 『삼국사기』에 후백제의 견훤(재위 892∼935)이 고려 태조(재위 918∼943)에게 공작선을 바쳤다는 기록이 가장 오래된 것이다. 부채는 원선과 접부채로 크게 구분되는데 공작선은 원선에 속한다. 일명 방구부채라고도 불리우는 원선에는 오엽선, 연엽선, 좌초선, 태극선, 공작선 등이 있으며 이중에 공작선은 화려하면서 품위가 있어 옛부터 귀한 공예품으로 사랑을 받아왔다. 부채기능보유자인 이한규씨는 그의 부친 이을용씨에게서 공작선 제작기술을 전수받아 공작선 제작의 명맥을 이어가고 있다.","a":"서천부채장","c":"시도무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643996.jpg"},{"q":"전각은 단단한 물질에 글자나 문양을 새겨 변형되지 않게 찍어 자신의 표지를 나타내는 것으로 고대의 글자가 전서(篆書)여서 전자(篆字)를 새긴다는 뜻에서 전각이라 하였다. 새기는 작업은 인장에서 출발 하였으나 현판, 주련(柱聯), 제액(題額) 등이 모두 전각을 기초로 하고 있으며, 최근에는 사군자를 비롯한 회화도 각(刻)을 하는 등 전각 자체가 하나의 독립적인 예술로 자리 잡고 있다. 전각의 재료는 나무, 돌을 비롯하여 금, 은, 동, 청동, 황동 등의 금속류와 청옥, 황옥, 백옥, 적옥 등의 옥석류 및 청자, 백자 등의 도자류, 상아, 무소뿔, 백각(白角), 대모(玳…","a":"전각장","c":"시도무형유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052014534100.png"},{"q":"○○○는 한 명의 소리꾼이 고수(북치는 사람)의 장단에 맞추어 창(소리), 말(아니리), 몸짓(너름새)을 섞어가며 긴 이야기를 엮어가는 것을 말한다. 유래는 정확히 알 수 없으나 조선 영조 30년(1754)에 유진한이 지은 춘향가의 내용으로 보아 적어도 숙종(재위 1674∼1720) 이전에 발생하였을 것으로 추측하기도 하고, 조선 전기 문헌에 보이는 광대소학지희(廣大笑謔之戱)가 토대가 되었을 것으로 보기도 한다. 또한 ○○○가 본래 여러 가지 놀이와 함께 판놀음으로 공연되던 것이어서 판놀음이 있었던 신라 때까지 거슬러 올라가기도 한다. ○○○는 느린 진양조, 중모리,…","a":"판소리","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624267.jpg"},{"q":"함안 ○○○○는 함안면 괴항마을에 전승되어온 고유의 놀이로 매년 부처님 오신 날 마을입구 이수정에서 개최되어 왔으며, 그 유래는 정확히 전하여지지는 않지만 문헌과 조사를 통해 본 결과 17세기 조선중엽부터 유래된 것으로 추정되고 있다. 현재는 2000년대에 들어서부터 함안면민을 중심으로 한 ○○○○○보존위원회가 결성되어 지금까지 전승되고 있다. ○○○○의 형태는 마을 자체에서 제작한 숯가루를 한지에 돌돌말아 낙화를 만들어, 이수정에 준비한 줄에 낙화를 걸어 불을 붙임으로써 숯가루가 불을 머금고 타면서 바람에 날리는 장관을 연출하는 함안군의 대표적인 민속놀이이다.","a":"함안낙화놀이","c":"시도무형유산","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644645.jpg"},{"q":"불화는 불탑, 불상 등과 함께 불교의 신앙 대상으로, 제작 형태에 따라 탱화(幀畵), 경화(經畵), 벽화(壁畵) 등으로 분류할 수 있다. 특히 탱화는 복장식(服裝式), 점안식(點眼式) 등의 신앙 의식 절차를 거쳐 불단(佛檀)의 주요 신앙대상물로 봉안된다. 우리나라 전통사찰에 전해오는 탱화는 불화의 주류를 이루고 있으며, 불화 제작을 담당하는 장인을 특별히 금어(金魚), 화승(畵僧), 화사(畵師), 화원(畵員)이라 부르기도 하였다. 그동안 불화 제작기능은 단청보유자에 의해 전승되어 왔으나 종목의 특성을 고려해 단일종목으로 분리하여 ○○○으로 지정하였다. ○○○ 김종섭은…","a":"불화장","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019052917540200.jpg"},{"q":"‘○○○○○’은 동해안 일대에 분포하고 있는 대표적인 여성놀이의 하나이다. 소리와 춤으로 구성되어 있으며, 群舞는 일반적으로 ‘○○○○○’으로 부르고 있으나, ‘토연노래’, ‘생금생금 생가락지’ 등 일정한 가락을 가지고 있는 歌舞이다. 또 일견 다른 노래춤과 같이 보이지만, 이 놀이 사이사이에 달넘세, 대문열기, 산지띠기, 동애따기, 재밟기, 실꾸리감기/풀기, 절구세 등이 ○○○○○에 합성되기도 하는 女性群舞이며, 圓舞이다.","a":"영덕 월월이청청","c":"시도무형유산","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019061311443900.jpg"},{"q":"1935년 부안에서 태어난 김정락은 어린시절부터 도편수 김형오․김영선․고택영 등에게 한옥건축을 사사받았다. ○○○은 재목으로 하여 집짓는 일에서부터 재목을 마름질하고 다듬는 공술(工術)을 기법에 따라 발휘하는 목수를 말하는데, ○○○의 아래에는 좌우 편수가 소속되고 있다. 김정락은 50여년간 전북 등 호남지역 한옥건축에 종사해 왔으며, 특히 서원․향교․재실 등 유교건축에 두드러진 활동을 보이고 있다.","a":"대목장","c":"시도무형유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644150.jpg"},{"q":"서부면 판교리 ○○○ 마을의 안녕과 풍어를 기원하는 일종의 풍어제로서, 약 400년 전부터 시작 전승되었다고 전한다. ○○○ 당제에서 모셔지는 오당(五堂)과 그에 대한 제의는 서해안 도서 및 해안지방 당제의 전형적인 한 유형이다.","a":"홍성수룡동당제","c":"시도무형유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644038.jpg"},{"q":"○○은 보통 대장장이라 하며 망치나 집게 등을 이용해 철을 단조(鍛造)하여 물건을 만들어내는 사람이다. 보통 대장장이라고 부른다. 철이 농기구를 비롯한 각종 생활용구로 다양하게 활용되면서, 철을 다루고 철제 도구를 만드는 대장간은 5일장이 서는 시장을 중심으로 전국으로 확산되기 시작하였다. 많은 사람들이 5일장에 나오는 길에 필요한 농기구 등을 구입하고 또한 훼손된 농기구 등을 수선하였다. 대장간에는 이곳의 운영자인 대장장이를 비롯하여 쇠를 두드리는 메질꾼, 메질을 돕는 집게잡이, 화덕의 불을 조절하는 풀무꾼 등이 있다. 이들은 쇠를 달구는 화덕, 바람을 일으키는 풀…","a":"야장","c":"시도무형유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023061415513401.jpg"},{"q":"밀양 ○○○○는 바쁜 농사일을 끝내고 고된 일을 해오던 머슴들이 음력 7월 15일경 용날을 선택하여 지주들로부터 하루 휴가를 얻어 흥겹게 노는 놀이를 말한다. 이러한 놀이는 호미씻기라 해서 벼농사를 주로 했던 중부 이남지방의 농촌에서는 흔히 볼 수 있다. 밀양에서는 머슴날이라고 하며 지주들이 준비해 주는 술과 음식을 일컫는 꼼배기참을 먹으며 논다해서 꼼배기참놀이라고도 부른다. 밀양 ○○○○는 농신제, 작두말타기, 춤판, 뒷놀이 등으로 짜여져 진행된다. 농악을 치며 오방진굿으로 농신제가 시작되면 마당에는 삼대로 만든 농신대를 세우고 새끼를 꼬아서 만든 용을 매단다. 농…","a":"밀양백중놀이","c":"국가무형유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624144.jpg"},{"q":"금강 상류의 평촌리 ○○○ 마을은 비가 조금만 오면 물에 잠겨 '○○○'라 하였다고 한다. ○○○ 농요는 농사 시작부터 끝까지의 과정을 노래와 동작으로 표현한 이 마을의 농요로서, 토신고사(土神告祀), 모심는소리, 두렁밟기, 아시매기, 두렁고치기, 재벌매기, 방아소리, 쌈싸는 소리, 장원놀이 등으로 구성되어 있다. 먼저 두레가 났다는 나팔소리가 나면 마을입구에 모여 토지신에게 고사를 지내는 것으로 시작되어, 모 심으면서 노래르 부르는 소리가 이어진다. 다음으로 쥐 두더지 등이 논두렁을 뚫지 못하게 두렁밟기를 하고, 15~20일 후에 호미로 논을 매면서 노래를 부르는데…","a":"금산 물페기농요","c":"시도무형유산","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643983.jpg"},{"q":"맹인들의 독경(讀經)은 옥추경 등과 같은 여러 경문(經文)을 읽으며 복을 빌거나 질병 치료 등을 목적으로 하는 전통신앙 의례이다. 이러한 독경은 20세기 초반까지 전국에 분포했으나 현재는 급격히 줄어들어 서울을 중심으로 독경에 종사하는 일부 태사(太師, 맹인세계에서 독경하는 사람을 지칭)들에 의해 행해지고 있다. 조선시대에 서울의 4대문 안에는 무당이 살 수 없었고 굿도 도성 밖에서만 했으며 승려들의 출입이 금지되었었으나, 맹인들의 독경의례는 17세기 후반까지 국행기우제로 열렸고, 궁중과 양반층, 민간의 대표적인 의례로 이어져 왔다. 이러한 사실은 서울의 대표적인 세…","a":"서울맹인독경","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2017022216542700.jpg"},{"q":"‘○○○○○’는 일제강점기와 6.25를 거치면서 면면히 이어져 내려오던 것을, 1969년 주지로 부임한 만화(萬化)스님이 전통적 ○○○를 복원해 체계화 시켜나갔다. 이후 ‘○○○○○’는 1980~90년대 침체기를 거치다가 2004년 오대산불교문화축전에서 시연한 이후 매년 봉행되기 시작했다. 2013년 이후에는 매월 보름과 초파일 등에 지속적으로 ○○○ 행사가 진행돼 왔다. ○○○는 ○○○뿐만 아니라 ‘법주사팔상전○○○’, ‘충주중앙탑○○○’, ‘통도○○○○’, ‘만복○○○○’ 등이 행해지고 있으나, 무형유산으로 지정된 것은 ‘○○○○○’가 유일하다. ○○○는 하나의…","a":"월정사 탑돌이","c":"시도무형유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052016483200.JPG"},{"q":"○○○은 나무, 금속, 돌 등에 글자를 새기는 장인을 말한다. 주로 인쇄를 목적으로 하는 목판과 전통 건축물의 현판, 문갑, 책장 등의 목가구 작품을 제작한다. ○○○○○ 박학류 선생은 1971년 임병선 선생 수하에서 전통 목각을 배우기 시작하여 40년이 넘는 기간 동안 전통 재료와 기법을 사용하여 각자에 심혈을 기울였다.","a":"예산 각자장(목각)","c":"시도무형유산","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2015122917354600.jpg"},{"q":"우리나라는 소금산지가 없어 고대로부터 현재까지 바닷물을 원료로 하여 소금을 생산함. 자염에 대한 기록은 고려시대부터 찾아 볼 수 있고, 현재까지 이어져온 천일염전은 1907년에 도입되어 100여년 지속되어왔다. 조선시대까지 이어진 자염법(煮鹽法)은 갯벌 흙, 바닷물, 햇볕을 이용하여 얻은 함수를 소금가마에 붓고 불을 지피는 방식이고, 천일○○법은 오로지 햇볕과 바람만으로 수분을 증발시키면서 소금을 생산하는 방식이다. 우리나라 자염이나 천일염은 갯벌에 조성되었다는 점이 가장 큰 특징으로 세계적으로 우리나라가 갯벌 천일염 생산량 중에 86%을 차지하고 있다. 그리고 소금…","a":"제염","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2019100715163300.jpg"},{"q":"우리 전통신발인 화혜(靴鞋)는 원래 화(靴)는 목이 있는 장화형태의 신발이고, 혜(鞋)는 목이 짧고 운두가 없는 신발을 일컫는 것이라 하여 별도의 장인으로 구분하였으나 현대에는 이 두 가지 기술을 통칭해 새롭게 붙여 ○○○이라 한다. ○○○ 보유자 안해표는 조선말기 조부 때부터 대대로 전통신인 화혜를 만드는 것을 가업으로 삼아온 전승계보가 뚜렷하다. 즉, 조부는 1880년대에 사대부와 관리들의 신발인 흑혜를 제작하였으며, 부친 역시 가업을 이어받아 평생 전통 신을 만들었고, 안해표는 부친으로부터 12세 때인 1962년부터 전통신발 제작 기능을 전수받기 시작하여 196…","a":"화혜장","c":"시도무형유산","r":"부산광역시","s":"사하구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643449.jpg"},{"q":"○○○는 농사일을 할 때 부르는 민요로, ○○○○○는 신안군 장산면에서 여자들이 논일을 하며 부른 노래이다. ○○○○○는 부녀자들의 고달픈 삶과 한이 서린 ○○○이나 박진감이 있고 경쾌하다. 또한 섬이다 보니 다른 지역 민요와 섞이지 않아 토속적이고, 가락이 여성스럽다. 구성은 모를 찌면서 부르는 모찌기노래, 모를 심을 때 부르는 모심기노래, 논에서 논매기를 할 때 부르는 논매기노래, 논을 다 매고 돌아올 때 부르는 길꼬내기로 되어 있다. 늦은 가락에서 중모리, 중중모리, 자진모리 등의 빠른 가락으로 변화하기 때문에 지루하지 않으며, 진도 ○○○와 육지의 남도 노동요…","a":"장산도들노래","c":"시도무형유산","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644209.jpg"},{"q":"○○○○○는 공주 연안이씨 가문에서 15대째 전해오는 전통주이다. 전해오는 이야기에 의하면, 1623년 반정에 성공한 인조는 일등공신 중 한 명인 이귀(李貴, 1557 ~ 1633)에게 궁중에서 빚은 백일주와 함께 양조비법을 하사하였는데 이귀는 이 술의 비법을 부인인 인동장씨를 통해 이어가도록 했다. 인동장씨는 솜씨가 좋았던지 그녀가 제조한 술은 궁중에서 하사한 술보다 맛이 더 좋아 오히려 임금에게 진상했다고도 하며, 1989년 이러한 의미와 가치를 인정받아 충청남도 무형유산으로 지정되었다. 이후 연안이씨 가문의 며느리를 통해서 400여 년째 전승되고 있으며, 현재는…","a":"계룡백일주","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026022314345100.jpg"},{"q":"○○기와 김은동은 1953년부터 선대인 김영하 선생이 설립한 <○○한와>부터 현재의 <○○기와>에 이르기까지 70년동안 지역에서 기와제작 와장으로 중요국가유산의 수제전통기와 및 전돌을 제작하고 있었다. 그는 입문 이후 1990년부터 복원된 경복궁의 강녕전과 교태전을 비롯한 주요 전각의 지붕에 30여년간 전통기와를 제작하여 올렸는데, 이는 시대별로 복원과 함께 색상과 문양 크기에 따라 세분화되어 제작됨으로서 그 상징성과 의미를 더하고 있다. 전통기와의 고유한 제작기법`과 완벽한 복원을 위하여 전통가마인 등요를 복원하였으며 전통기와 제작소를 운영, 전통 기와제작 기법을…","a":"고령 제와장","c":"시도무형유산","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060209515100.jpg"},{"q":"산조란 장구반주에 맞추어 다른 악기를 연주하는 독주형태의 음악으로, 4∼6개의 악장을 구분하여 느린 장단에서 빠른 장단 순서로 연주한다. ○○○○는 대금으로 연주하는 산조를 일컫는다. 산조연주에 쓰이는 대금은 시나위나 남도무악 등 다양한 가락을 연주할 수 있도록 만든 것으로, 음의 변화가 없어 합주에 사용되고 있는 정악대금과는 크기, 잡는 방법, 음높이가 다르다. ○○○○는 20세기 초 박종기에 의해 만들어졌다고 하며, 음악적 특징으로는 가락에 리듬과 장단을 더하기 위한 장식법(바로붙임, 엇붙임, 완자걸이, 잉어걸이), 농음(꺾고, 평으로 내고, 흘러내리고, 밀어 올…","a":"대금산조","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624343.jpg"},{"q":"○○○이란 쇠를 녹여 쇳물을 거푸집에 부어 원하는 물품을 만드는 주물기술을 가진 장인을 말한다. 정밀하게 유물을 복제, 복원하기 위해 밀랍(벌집)을 이용해 형상을 만드는 밀랍주형법을 사용하는데, 이것은 정밀한 문양들을 섬세하게 나타낼 수 있는 기법으로 2400년전 청동주물의 대표적인 기술이라 할 수 있다. ○○○ 불구佛具 보유자 이완규는 1970년대 금속 공예조각의 대가 오해익 선생의 공방에서 청동주물 일을 시작하였다. 그는 불교미술의 영역에 속하는 호신불護身佛을 비롯해 촛대, 향로 등 부처 앞에 쓰는 온갖 불교용품의 제작에 매진해 왔고, 관련 분야 명장의 반열에 올…","a":"주성장(불구)","c":"시도무형유산","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643696.jpg"},{"q":"◦ ○○○○○는 마음씨 착한 동생 흥보와 못된 형 놀부가 제비가 물어다 준 박씨를 통해 복과 벌을 받는다는 권선징악과 형제애를 강조한 내용으로, 노래를 부르는 소리꾼 한 명이 북을 치는 고수의 장단에 맞추어 노래와 말에 몸짓을 섞어가며 이야기를 전달하는 것이다. ◦ 현재 전승되는 ○○○의 계보는 송만갑(宋萬甲, 1865~1939), 김정문(1887~1935), 박녹주(朴綠珠,1906~ 1979), 한농선(韓弄仙, 1934~ 2002)으로 이어지는데 한농선은 2002년 2월 국가무형유산 ○○○○○ 예능보유자로 지정되었다. ◦ 한농선의 제자 임영이는 동편제 특유의 대마디…","a":"판소리 흥보가","c":"시도무형유산","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023050113113600.JPG"},{"q":"○○○○○는 홍역신인 서신(西神), 마을 수호신인 토신(土神), 손님신인 포신에게 제사를 지내 마을의 평화를 기원하는 마을단위의 제사이다. 매년 봄과 가을에 제사를 지내오다가 30여 년 전부터는 봄에만 지내고 있다. 제사는 제물을 제삿상에 올리는 전폐례(奠幣禮)로 시작된다. 술을 올리고 절하는 초헌례(初獻禮)와 축문을 읽는 독축(讀祝), 다시 술을 올리고 절하는 아헌례(亞獻禮)를 행한 후에 마지막으로 술을 올리고 절하는 종헌례(終獻禮)를 거쳐 제삿상의 그릇들을 물리는 철변두와 향을 피우는 그릇과 위패를 물리는 망료위(望燎位)의 순서로, 유교적 제사방법에 따라 이루어진…","a":"납읍리마을제","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644682.jpg"},{"q":"우리나라 음식 중 한과는 후식으로 먹는 과자류인 동시에 제사나 혼사, 잔치 때에 반드시 쓰이던 필수적인 음식으로 유밀과와 다식, 정과, 숙실과, 엿강정 등을 통틀어 말한다. ○○지역에서는 예로부터 혼수나 제사 등에 과줄(산자)이나 강정을 널리 사용하여 왔다. 그 솜씨의 우수함은 널리 알려져 있으며, ○○○○은 ○○시 사천면 노동리 일대의 갈골마을에서 백여년전부터 전통적인 기법으로 대를 이어 제조하는 과줄이라는 점에서 전통문화의 체계적 보존⋅전승을 위해 지정가치가 크다. 보유자 최봉석은 ○○ 사천면 갈골마을에서 집안 대대로 거주해 오면서 동해안에서 생산된 모래를 사용하…","a":"강릉 갈골과줄","c":"시도무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643831.jpg"},{"q":"자수와 관련된 유물 중 가장 오래된 것은 신라시대 경주 황남대총 및 백제시대 공주 무령왕릉에서 출토된 단편斷片의 사슬수가 있다. 이 유물은 비록 단편으로 출토되었으나 당시 동아시아에서 가장 많이 사용된 기법인 사슬수를 삼국시대에 사용하고 있었음을 알 수 있는 귀한 유물이다. 이외에 고려시대로 추정되는 자수 사계분경도 병풍刺繡四季盆景圖屛風과 자수 아미타여래도刺繡阿彌陀如來圖 등이 있다. 아미타여래는 극락세계에 머물면서 죽은 이의 영혼을 극락왕생의 길로 이끌어 주는 부처로 고려시대에는 호국 신앙으로 불교가 크게 융성하여 자수불화도 번성했을 것으로 짐작된다. 조선시대 복식…","a":"자수장(궁수)","c":"시도무형유산","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018092711255400.jpg"},{"q":"상원은 정월 대보름을 이르는 말로 정월 대보름에 행해졌던 놀이를 ○○○○라고 말한다. 옛날 당산나무에서 곡성이 들려오고, 마을에 나쁜 일이 자주 일어나 마을 사람들이 당집을 세우고 대보름날 제를 지내자 마을이 평안해졌다는 전설이 전해지고 있다. 법흥 ○○○○를 세 마당으로 나누면 첫마당에서 마을과 집안의 평안과 풍년을 비는 당산제를 지내고, 각 집을 돌며 지신밟기를 한다. 둘째마당은 놀이마당으로 윷놀이, 널뛰기, 연날리기를 하고, 다리에 병이 나지 않는다는 믿음으로 다리밟기를 한다. 뒷마당에서는 달맞이를 하면서 달집을 태워 마을의 모든 재앙이 불타 없어지고 새 복이…","a":"밀양법흥상원놀이","c":"시도무형유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644480.jpg"},{"q":"붓과 먹, 종이, 벼루는 가장 오래된 필기도구의 하나이다. 우리나라에서도 삼국시대의 유물이 출토되었지만, 실제로는 그 이전부터 사용되었을 것이다. 벼루의 품격은 벼루를 만드는 원석의 질과 벼루에 새기는 조각의 수준에 의해 결정된다. 일반적으로 벼루의 원석은 경도가 낮아서 생동감 있는 조각이 불가능하다. 이 한계를 극복하게 해 준 것이 ○○○ 보유자 신근식이 소유하고 있는 단양의 자석紫石이다. 이 돌은 색채도 독특하고 아름답지만, 다른 벼루 원석보다 경도가 2~3도나 강해서 입체적인 조각이 가능하다. 자석을 사용한 벼루는 실용적이다. 다른 원석으로 만든 벼루는 먹이갈릴…","a":"벼루장","c":"시도무형유산","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643663.gif"},{"q":"○○○○은 나무로 불상을 깎는 일을 맡아 하는 장인이다. 불상은 불교의 전래와 함께 들어왔으며, 불상을 제작하는 기술 또한 전래 당시부터 시작되었다. 다만 나무로 만든 불상은 청동제에 비해 시대가 오랜 유물이 많지 않으나 고려시대의 유물은 봉정사 목조관음보살좌상을 비롯하여 10여점이 남아 전한다. ○○○○이 갖춰야할 기본 요건은 숙련된 기술뿐 아니라 예배대상으로서 신심을 돕는 조형적 감각과 높은 안목이 필수적이다. 일반조각과 다른 점은 불상이 감상용이 아니라는 사실이다. 따라서 불상의 품격을 판단하는 기준도 일반조각과 다르게 적용된다. 형태를 구축하는데 필요한 입체감…","a":"목조각장","c":"시도무형유산","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091413331100.jpg"},{"q":"○○○○○이란 불상을 조각하는 기술과 그 기술을 가진 사람을 말한다. 대전시에 사는 불상조각 기능보유자인 이진형씨는 전국에 있는 크고 작은 사찰의 불상을 조각하는 일에 참여하였고, 불교조각의 형태, 비례, 색채 등 조각기능을 전수·연마함으로써 전문적인 작품을 보여주고 있다. 또한 자신만의 독창적인 창작활동과 더불어 기능전수를 목적으로 불교조각원에 전념하고 있다. ○○○○○은 전통적인 공예기술로서 무형유산에 지정되었다.","a":"불상조각장","c":"시도무형유산","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643575.jpg"},{"q":"고윤학 보유자는 현장에서 전통 ○○○○○을 배우고 익힌 장인으로 전통 불·보살상의 복원과 불구를 전통방식으로 제작하는 전 과정을 구연하는 등 ○○○○○ 기법을 전형대로 체득·실현할 수 있는 기반과 전승기반을 갖추고 있을 뿐만 아니라 전승실적이 우수함","a":"불교목조각장","c":"시도무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018103011291500.jpg"},{"q":"○○는 흔히 중춤이라고 하지만, 불교의식에서 승려가 추는 춤과는 다른 춤이다. 불교의식에서 승려가 추는 춤으로는 법고(法鼓)춤, 바라춤, 나비춤 등이 있는데, 이를 작법(作法) 또는 법무(法舞)라 일컫는다. 현전 ○○는 한성준에서 한영숙(韓英淑 : 1920∼1989), 이애주(李愛珠 : 1947∼)로 이어지는 경기·충청지역의 ○○와 이대조(李大祚)에서 이매방(李梅芳 : 1927∼)으로 전승되고 있는 호남지역의 ○○로 나누어진다. 전자의 ○○를 보통 한성준계 또는 한영숙류 ○○라 하고, 후자를 이대조계 또는 이매방류 ○○라 한다. 송재섭씨는 김제 금산사로 출가하여 송월…","a":"승무","c":"시도무형유산","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643588.jpg"},{"q":"○○○○은 대구광역시 수성구 욱수동에서 발원 전승되어온 농악이다. ○○○○은 동제 때 동제당에서 신내림을 축원하는 천왕받이굿과 이 내림굿에 이어 연행하던 판굿, 정월대보름때의 지신밟기 그리고 달불놀이때의 마당놀이가 하나의 틀이 되어 전승되어 왔다. 판굿의 주요한 연행놀이는 살풀이, 둥글레미, 외따기놀이, 호호굿등이 있으며 이중 특히 “외따기놀이”는 ○○○○에서만 볼 수 있는 놀이로 외따기는 참외따기의 줄임말로 참외를 서리하던 농촌정경을 농악놀이화한 독특한 연행이 특징이다. ○○○○은 경상북도와 대구시의 경계에 위치하여 두지역 농악의 특징이 같이 엿보이며 단순화면서도…","a":"욱수농악","c":"시도무형유산","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643468.jpg"},{"q":"○○○○○는 서해안의 외딴섬에 행하지는 마을 신앙으로, 매년 음력 2월 15일 거행되는 전통행사이다. ○○○○○는 전통문화의 상징 요소가 다수포함되어 충남 해안의 민속신앙의 전형으로 볼 수 있으며, ○○, 풍어제, 전횡장군 사○○ 등 여러 제향행사가 거행되며, 제물마련 절차, 도서지역만의 특색이 담긴 풍물소리 등이 특정이다. 이러한 제향은 유교식 축문 독축 없이 헌작과 재배, 무당의 고사덕담이 추가된 비유교식 제의 절차를 갖추고 있어 보다 민중적인 신앙 양상을 보여준다. ○○는 조선시대 중기 이후 ○○○에 주민들이 거주하기 시작하면서부터 거행되었다고 추정하며,1970…","a":"보령 외연도 당제","c":"시도무형유산","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019042714095300.jpg"},{"q":"○○○으로 지정된 허창구씨는 국민학교(현 초등학교) 졸업후 우마차 공장에서 이만복(사망)씨에게서 담금질을 익힌 후 신길득씨에게서 대장간일을 배워 약 50여년 가까이 대장간을 운영하며 전통적인 우리의 금속품을 생산하고 있음","a":"대장장(아산)","c":"시도무형유산","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019052217393700.jpg"},{"q":"○○○○은 현재의 지리적 조건 위에서 철산동, 소하동, 학온동 등을 중심으로 광명시의 현대적 바탕에서 성립된 농악이다. 논농사, 농악, 두레 등이 서로 밀접한 관련을 지니고 있으며, 이러한 농사의 전통이 결과적으로 ○○○○의 근간이 된다. ○○○○은 용기 2개, 농기 1개, 영기 2개, 오방기 5개, 태평소 2개, 꽹과리 4개, 징 2개, 장구 6~8개, 북 4개, 채상소고 12개와 잡생(농악판에서 정해진 틀을 가지지 않고 자유자재로 흥을 돋구는 사람들)으로 양반 1명, 아낙 1명, 포수 1명, 피조리 6명으로 구성되어 있다. 의상은 광명을 포함한 경기 및 충청도지방…","a":"광명농악","c":"시도무형유산","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643645.jpg"},{"q":"○○○○○는 숯을 생산하는 작업의 과정에서 불려졌던 애환의 ○○○○를 모은 것이다. 따라서 노래의 전개 순서를 보면 숯을 생산하는 작업의 과정을 알 수 있다. 숯을 생산하는 기간은 상당히 길다. 따라서 ○○○○에는 각 장르의 노래가 섞여있다. 의식을 거행할 때는 의식요, 휴식을 취할 때는 유희요, 노동을 할 때는 노동요가 불려졌다. 따라서 노래는 일에 참여하는 사람이 공동작업을 할 때는 단체요를 개별적으로, 작업할 때는 개별요를 불렀는데 이처럼 다양한 방식의 가창과 다양한 장르이 노래가 함께 공존하는 것이 ○○○○의 가장 두드러진 특징이다.","a":"광려산숯일소리","c":"시도무형유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019052009573000.JPG"},{"q":"○○○○는 황해도와 평안도 지방(서도지역)에서 전승되던 민요나 잡가 등을 말하며, 언제부터 부르기 시작하였는지 정확한 시기는 알 수 없다. ○○○○는 평안도 민요와 황해도 민요, 서도잡가, 한시를 읊은 시창(詩唱), 극적 구성을 띠고 있는 배뱅이굿이 있다. 평안도 민요에는 수심가, 엮음수심가, 긴아리, 자진아리, 안주애원성 등이 있는데, 조선 전기부터 서도지방 사람들의 벼슬길이 막히자 그 설움을 푸념으로 읊은 수심가가 가장 유명하다. 평안도 소리는 일반적으로 레, 미, 솔, 라, 도의 다섯 음으로 구성되어 있는데, 떠는 음인 ‘라’에서 완전 5도 내려가는 것으로 선율…","a":"서도소리","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624335.jpg"},{"q":"○○○○은 기방인妓房人들에 의해 그 호칭이 입춤, 즉흥무・수건춤 등으로 불려지면서 보편화 된 춤사위 가생성되어 오늘에 이르렀다고 한다. 문헌상으로는 1934년에 한성준이 〈조선음악무용연구소〉를 창립하고 1936년에 부민관에서 제1회 한성준무용발표회를 하면서 방안춤을 극장무대에 올려 최초로 ○○○○이라는 명칭을 사용하였다. 그 후로 점차 대중 사이에서 본격적인 ○○○○이 등장하여 우리 민족의 정서를 대변하는 춤으로서 예술성이 인정되어 계승되고 있다. 2015년 1월 29일에 이은주가 보유자로 인정받아 활동하고 있다.","a":"살풀이춤","c":"시도무형유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102609383600.jpg"},{"q":"농요는 토속민요의 한 종류로 개인 또는 집단적으로 불린다. 농사터에서 농사를 지으며 부르거나 농사일을 마친 후 집으로 돌아오면서 부르기도 하며, 호미나 낫 같은 농기구를 만들면서 부르기도 한다. 지방에 따라서 종류나 노랫말의 내용, 노래부르는 방법 등이 다르다. 안동 ○○○○○는 ○○○ 농민들이 오래 전부터 불러오던 것으로 농사일의 피로를 덜고 능률을 올리기 위하여 부르던 이 지방 특유의 구전민요이다. 농요의 내용이나 가락이 독특하고 고유성이 있다고 평가된다.","a":"안동저전동농요","c":"시도무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644264.jpg"},{"q":"'○○○○○'는 전라남도 영광군 ○○○ 일대에서 단오 무렵 지역 주민에 의해 전승되어 온 전통적인 민속축제이다. ○○○에는 조선시대 한양으로 올라가는 세곡을 관리하는 조창(漕倉)이 있었으며, 조기 파시(波市)의 중심지였기에 오래전부터 상권(商圈)이 발달한 지역이었다. 이러한 사회·경제적인 배경을 바탕으로 파시가 형성되는 시기에 난장(亂場)이 크게 섰으며, 이 지역에서 자연스럽게 ○○○가 발생하는 계기가 되었다. 특히, 뱃사람들의 안전을 기원하는 용왕제, 부녀자들이 중심으로 즐겼던 선유(船遊)놀이를 비롯해 '숲쟁이'(○○○ 숲)에서 벌어지는 예인들의 경연행사는 ○○○○…","a":"법성포단오제","c":"국가무형유산","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623984.jpg"},{"q":"함경남도 북청의「○○○○」는 명절(설, 한식, 단오, 추석등)에 마을마다 신명나게 놀아온 민속놀이로, 어원은 '동틀 날'이며, '회전'을 의미하며 '제자리로 되돌아온다.'는 뜻이며, 圓(원)을 상징하기도 한다. 이런「○○○○」는 북청군을 비롯하여 함경남도 함흥, 함주, 정평, 이원, 풍산, 단천, 삼수, 갑산, 함경북도 길주, 명천, 성진 등에서 널리 불리어진 민요이다. 특히 북청군에「○○○○」놀이는 한식 이튿날을 중심으로 속후면 모래산에서 부녀자들이 달래를 캐는 풍습이 오랜 기간 동안 전래되었다. 부녀자들은 달래를 캐고 나서 마을 사람들과 함께 심신을 달래는 대동놀…","a":"돈돌날이","c":"이북5도 무형유산","r":"함경남도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669643.jpg"},{"q":"입사는 금속 표면에 금실이나 은실을 박아 무늬를 장식하는 기예로 전 세게 여러 곳에서 활용하고 있는 기술이며 입사는 우리 고유의 명칭이다. 흔히 함께 쓰이는 상감이란 용어는 재료에 상관없이 다른 재료를 넣어 무늬를 내는 기법을 지칭하는 것으로 중국에서는 양감이라 하였다. 상감은 일본에서 들어온 용어이다. 입사에 쓰이는 전통 문양은 식물문, 동물문, 기하문, 문자문이 있으며 이들을 조합하여 바탕은 도안화된 무늬를 넣고 중앙에 회화적 무늬를 넣는 등 조화롭게 주성한다. ○○○은 고도의 정밀한 작업기술과 기물과 문양에 대한 높은 안목이 요구되는 기예이다. 2006년 1월…","a":"입사장","c":"시도무형유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409153300.jpg"},{"q":"○○○은 전통 가옥을 짓는 과정에서 재목을 마름질하고 다듬는 기술설계는 물론 공사의 감리까지 겸하는 목수로서 궁궐, 사찰, 군영시설 등을 건축하는 도편수를 가리킨다. ○○○은 문짝, 난간 등의 건물 안의 부속적인 목공일을 하는 소목장과 구분하는 명칭으로 기와장, 드잡이, 석장, 미장이, 단청장 등과 함께 주요 건물을 짓는 총 책임자를 의미한다. 통일신라, 고려시대, 조선시대에는 벼슬이 주어졌다. 오늘날에는 사찰이나 서원, 향교, 전통한옥 등을 짓는 것으로 ○○○ 기술이 전수되어 오고 있다. ○○○은 그 기법이 엄격히 전승되기 때문에 기문技門이 형성되어 있다. 기문은…","a":"대목장","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643922.jpg"},{"q":"사기沙器란 흔히 유약을 시유하지 않은 도기陶器의 상대적 개념으로 유약을 시유하여 1250℃ 이상의 고온에서 번조한 자기磁器를 포괄적으로 지칭한다. ○○○은 바로 백자·청자·분청사기와 같은 자기를 만드는 장인을 의미한다. 조선시대에는 왕실의 식사를 담당했던 사옹원司饔院에 ○○○沙器匠 360명이 소속되어 경기도 광주지역에 설치되었던 관요官窯에서 왕실용 백자의 제작을 담당하였다. 백자는 산화철 성분이 적은 백토를 태토로 사용하고 장석계의 고화도 유약을 시유하여 고온에서 번조한 것으로 자기磁器를 대표한다. 백자는 고려시대에 초기청자와 함께 제작되기 시작하였는데, 고려백자는…","a":"사기장(순백자)","c":"시도무형유산","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091017442600.JPG"},{"q":"○○○○○는 ○○군 강현면의 ○○○에서 전승되고 있는 농요로, 산간지방의 좁은 들이나 골짜기 다락논에서 농사를 지으면서 부르는 소리인데, 「논삶는 소리, 모찌는 소리, 논매는 소리, 벼베기 소리」등 논 농사 전 과정의 순서에 따른 소리가 잘 보존되어 있는 특성을 보이고 있다. 보유자 조광복은 오랫동안 농사를 지으면서 현장에서 소리를 배우고 익힌 이 마을 태생의 소리꾼으로, 힘이 좋은 청으로 ○○○○○ 전 과정을 부르는 등 기량이 우수하다.","a":"양양 상복골농요","c":"시도무형유산","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643844.jpg"},{"q":"이종덕은 1961년에 충남 부여에서 태어나, 김약환이봉주박임모송광호박일동곽선재 등에게 사사받았으며, 전승공예대전, 전북공예품경진대회 등에서 입상하였다. 유기란 놋쇠로 만든 그릇을 말하는데, 그 가운데 방짜유기는 구리 78%, 주석 22%를 섞어서 녹인 다음 두드려 만든 유기를 말한다. 놋쇠의 기원은 청동기 시대로 거슬러 올라가며, 철기시대와 삼국시대를 거쳐 고려시대에 와서 불교와 상류층을 중심으로 사용되다가 조선시대에 와서는 일반인 등도 사용하였다. 방짜유기는 얼마 전까지만 해도 전북지역을 대표하는 토산품 가운데 하나였으며, 『경국대전』에도 외공장을 전주와…","a":"방짜유기장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644166.jpg"},{"q":"정악은 궁정이나 관아 또는 각 지방의 풍류객들이 음악을 즐기려고 모였던 풍류방에서 연주되던 음악을 가리킨다. 대풍류란 즐기기 위한 감상 위주의 관악기 연주라는 뜻으로 궁중음악용 향피리나 정악대금과 같은 관악기가 중심이 되는 음악을 말한다. 기본 대풍류는 향피리 2, 대금, 해금, 장구, 북으로 편성되어 있다. 주요 연주곡목으로는 상영산, 중영산, 세영산, 가락털이, 삼현도드리, 염불도드리, 타령, 군악 등의 8곡으로 구성된 표정만방지곡(表正萬方之曲:관악영산회상 또는 삼현영산회상이라고도 함)이 있으나, 삼현도드리, 염불도드리, 타령은 무용반주 음악으로 사용되고 있다.…","a":"대금정악(대풍류·대금)","c":"시도무형유산","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643498.jpg"},{"q":"○○○이란 삼금(대금·중금·소금) 가운데 하나인 대금을 만드는 기술을 가지고 있는 사람 또는 기술을 말한다. 대금은 대나무로 만든 관악기로 ‘저’ 혹은 ‘젓대’라고도 한다. 대금 제작에 사용되는 재료로는 황죽(黃竹)이나 쌍골죽(雙骨竹)이 쓰인다. 제작과정을 살펴보면 먼저 황죽 또는 쌍골죽을 불에 구워 기름을 제거하고, 구부러진 부분을 바로 잡아 약 2개월간 건조시킨다. 이어 대나무 안에 소금물을 부어 약 24시간 경과시킨 다음 소금물은 제거하여 10일간 건조시킨다. 이러한 과정을 거친 대나무에 구멍을 뚫고 갈라짐을 방지하기 위해 마디 위치에 따라 10군데를 낚시줄로…","a":"대금장","c":"시도무형유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010411235900.JPG"},{"q":"민요는 백성들 사이에서 저절로 생겨난 노래로 입에서 입으로 전해진다. 직업·풍속·놀이 등을 기능으로 하여 생활과 밀접한 관련이 있으며, 지역이나 부르는 사람의 취향에 맞게 또는 즉흥성에 의해 달라질 수도 있다. ○○○○는 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노동요이다. 민요의 내용은 모심기소리, 논매기소리, 타작소리로 구성되어 있다. 모심기소리는 모심기 때 부르는 노래로 일명 공갈못노래·채련요(採蓮謠)라고도 하며, 경상북도 지방의 대표적 민요이다. 논매기소리는 김을 매며 부르는 노래이고 타작소리는 보리를 타작하면서 부르는 노래이다. 이 민요는 남녀노소…","a":"상주민요","c":"시도무형유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644330.jpg"},{"q":"○○○○○는 제주도 여러 마을의 당신(堂神)들의 원조인 벡주또마누라신에게 제사를 지내 마을의 평화를 기원하는 마을단위의 제사이다. 매년 음력 1월 13일·2월 13일·7월 13일·10월 13일에 행하여진다. 벡주또마누라신은 서울 남산 송악산에서 태어나 다섯 곡식의 씨앗을 가지고 제주도에 온 산육·농경의 여신으로 한라산에서 솟아난 수렵·목축의 남신인 소로소천국과 결혼하여 아들 8명과 딸 28명을 낳았는데, 그 자손들이 고루 뻗어 제주도 전 지역 368개 마을의 당신이 되었다고 한다. ○○○는 마을사람들이 제사를 지낼 수 있도록 신문(神門)을 열어 달라고 비는 궷문열림으…","a":"송당리마을제","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644680.jpg"},{"q":"○○○○○ 액막놀이는 ○○면 대소리 대소,대티,가정마을 중심으로 계승해온 전통민속놀이다. 지금으로부터 약 250여년(1750년경) 전 마을에 전염병이 돌고 나서 한 해의 무병장수와 풍년, 마을의 번영을 기원하기 위한 액막이다. ○○○○ 액막놀이는 다섯 마당으로 이루어져 있는데 놀이장면마다 음악적 이름을 붙였다. 제1놀이마당은 길거리 굿, 제2놀이마당은 창거리 굿, 제3놀이마당은 짓거리 굿, 제4놀이마당은 합거리 굿, 제5놀이마당은 뒤풀이 굿으로 구성되는 등 춤, 농악, 제례의식 등을 곁들인 종합 민속놀이이다.","a":"무주 부남 디딜방아 액막이놀이","c":"시도무형유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020051113382500.jpg"},{"q":"○○○은 집 짓는 일의 전과정, 즉 재목을 마름질하고 다듬는 기술설계는 물론 공사의 감리까지의 전과정을 책임지는 목수로서 궁궐이나 사찰, 군영시설 등을 건축하는 도편수를 지칭하기도 한다. ○○○은 문짝, 난간 등 소규모의 목공일을 맡아 하는 소목장과 구분한 데서 나온 명칭이며, 와장·드잡이·석장·미장이·단청장 등과 함께 집의 완성까지 모두 책임을 지고 있기 때문에 현대의 건축가라고 할 수 있다. 우리나라는 예로부터 목조건축이 발달하여 궁궐과 사찰건물이 모두 목조였다. 따라서 목수에 주어진 벼슬 또한 상당하였다. 통일신라의 관직을 보면 목척(木尺)이 70인이라 하였는데…","a":"대목장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624370.jpg"},{"q":"전북 ○○은 오래전부터 굿으로서 ‘농악’이 성행하고, 유명 굿쟁이들이 왕성하게 활동한 곳으로 ○○○○은 전북 동부산간지역 사람들의 문화를 대표하는 굿이다. 이 마을의 농악은 굿으로서 사람살이의 일상인 제의·놀이·노동·의례에서 나타나고, 무용·연극·음악의 예술요소가 풍성하다. 농악 형태는 마당밟이(당산굿·지신밟기), 마당판굿, 걸립굿이 있으며, 가락마다 의미를 가지고 다양한 절차로 질서 있게 풀어간다. 복장은 삼색띠를 두르고 모두 상모를 쓴다. 1992년에 굿쟁이들은 김봉열 상쇠를 중심으로 ‘전라좌도○○○○굿보존회’를 결성하여, 전수와 공연과 대회 참여로 전통을 살리고…","a":"진안 중평농악","c":"시도무형유산","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023051211285001.png"},{"q":"○○은 농부들이 두레를 짜서 일할 때 치는 음악으로, 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 굿·매구·풍장·금고·취군 등으로도 불린다. ○○○○은 강서 1동 지동마을에서 걸립·두레·백중·연의적 농사풀이굿으로 사용되면서 전해져온 ○○으로 쇠꾼들이 열지어 움직이는 진풀이, 법고놀이와 인사굿, 꽃봉오리굿, 채상굿, 갈지굿 등으로 구성되어 있다. 다른 지방보다 여러 채 굿의 변화가 다양하고 ○○의 가락이 빠르며 진법놀이가 다양하고 돌모를 머리 뒤에 쓰고서 상모를 돌리는 것이 특징이다.","a":"청주 농악","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643848.jpg"},{"q":"1년 24절기 가운데 하나인 청명일(양력 4월 5, 6일경)에 사용하기 위해 빚어진 민속주이다. 조선시대에 한강 상류의 돛단배 집결지인 ○○지방 일대에 오가는 손님들이 즐겨 마시기 시작하여 옛 사대부들을 위한 손님 접대용은 물론 명절과 제삿날에 애용하던 술로 궁중에 올리기도 했다고 한다. 순찹쌀과 재래종 통밀로 제조한 누룩만을 사용하여 낮은 온도에서 약 100일 동안 발효 숙성시켜 빚는다. ○○○○○는 알콜 농도가 높고, 색·향·맛이 뛰어나다. 현재 보유자 김영섭씨에 의해 전승되고 있다.","a":"충주 청명주","c":"시도무형유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643851.jpg"},{"q":"○○○이란 천연염료로 옷감을 물들이는 장인을 말한다. 조선시대 궁중에서는 염색을 담당하는 전문적인 장인이 있었을 정도로 염색은 전문적인 기술이 필요하다. 옷감을 물들이는데 사용하는 천연염료는 식물, 광물, 동물 등에서 채취한 원료를 그대로 사용하거나 약간의 가공을 통해 만든 염료를 사용한다. 염색에는 여러 종류가 있는데, 그 중 쪽염색은 쪽이라는 식물에서 추출한 염료를 가지고 옷감 등을 물들이는 것으로 염색과정이 가장 어렵고 까다로우며 고도의 기술이 필요하다. 나주지역의 쪽염색 작업과정을 살펴보면 팔월 초순경 60~70㎝정도 자란 쪽을 베어 항아리에 넣고 삭힌다. 이…","a":"염색장","c":"국가무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623974.jpg"},{"q":"소목장이란 목조건축의 집을 짓는 대목장 이외에 건물의 문, 창문이라든가 장롱, 궤, 경대, 책상, 문갑 등 ○○○를 만드는 기술과 그 기술을 가진 목수를 말한다. 한국 ○○○의 특성은 화려한 칠이나 정교한 조각보다는 아름다운 자연 무늬결을 대칭으로 사용하여 자연의 아름다움을 나타내는 것이다. 기능보유자인 조석진이 제작한 가구들 또한 무늬결이 좋은 느티나무 판재를 좌우 대칭으로 배치하여 안정되어 보이면서도 자연의 아름다움을 잘 나타내고 있다. 장, 농, 문갑 등 옛가구 그대로인 전승가구를 만드는 것이 주된 작업이나 한편으로는 이불장, 옷장 등 현대에 사용되는 장롱들을…","a":"목가구","c":"시도무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644124.jpg"},{"q":"○○은 옥을 갈아서 다양한 장신구와 기물을 만드는 기예나 장인을 일컫는다. 옥은 인, 의, 지, 용, 각의 덕목을 상징하는 장신구로 쓰였으며 사회계급의 신분을 구분하는 벽, 종, 규, 장, 호, 황 등과 병기, 악기인 옥경을 비롯하여 약재 및 의료용구 등 쓰임새가 많았다. 옥에는 크게 연옥과 경옥이 있고, 좋은 옥은 희소한 것으로 재료 확보가 쉽지 않았다. 옥의 제작 과정은 크게 여섯단계로 나뉘는데, 채석, 도안, 절단, 성형, 세부조각, 광택의 과정을 거친다. ○○은 옥을 고르는 안목과 원석을 도안할 때의 정확한 예측, 섬세하고 정교한 조각을 위한 숙련된 기술과 함…","a":"옥장","c":"시도무형유산","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409165600.jpg"},{"q":"전통 한지에 전통 안료를 천연 염색하여 전통의례 및 불교의례에 사용하는 의례용『종이꽃(지화)』를 제작하는 기․예능 - 기능보유중인 지화는 목단, 모란 등을 비롯하여 총 17종이 있으며, 식물에서 채취되는 안료 13종을 서로 혼합하여 염색에 사용. 염색된 종이를 접고, 자르고, 풀로 붙이고 끈으로 묶는 과정을 반복하여 제작 - 재료로는 꽃임과 꽃모양을 만드는 한지와 천염색 안료, 꽃대 제작에 필요한 대나무, 싸리나무, 접착을 위한 풀이 필요함.","a":"지화장","c":"시도무형유산","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018090714244600.jpg"},{"q":"김영식은 8대조 김취정선생으로부터 이어진 조선후기 ○○○의 후예로, 자연스럽게 어린시절부터 흙 굽는 기술을 어깨너머로 배웠으며, 초ㆍ중ㆍ고교 시설에는 부친인 7대 ○○○ 김천만의 망댕이 사기요에서 허드렛일을 돕고 그의 옆에서 도예 기술을 배웠다. 그가 본격적으로 도공의 길을 선택한 계기는 1989년 부친(김천만)이 작고한 후로, 이때부터 가업을 계승하기 위하여 부친인 7대 김천만 ○○○의 도예 기술 전수를 바탕으로 망댕이 사기요에서 3년간 도예 기술 연마 후 1991년 조선요를 열어 대한민국 전통도예의 맥을 이어왔다. 그는 지난 1989년 입문해 1996년 국가무형유…","a":"사기장-백자","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2017112114011400.gif"},{"q":"오광대는 남부지역(낙동강 서쪽지역)의 탈춤을 가리키는 말로, 초계 밤마리 마을 장터에서 놀던 광대패들에 의해 시작되었다고 한다. 낙동강을 중심으로 부산 동래, 수영 지방에서는 야류(들놀음), 통영·고성·가산 지방에서는 오광대로 불린다. ○○○○○는 길놀이를 시작으로 제1과장 문둥탈, 제2과장 풍자탈, 제3과장 영노탈, 제4과장 농창탈, 제5과장 포수탈 등 5개 과장으로 구성되어 있으며, 문둥이․말뚝이․양반․팔선녀․영노․사자 등 31명의 인물이 등장한다. 양반과 파계승의 풍자, 처와 첩의 문제 등 민중의 생활상을 반영하고 있다. 가장 특징이 있는 춤은 문둥이춤으로 꽹과…","a":"통영오광대","c":"국가무형유산","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624065.jpg"},{"q":"○○○의 제조 유래는 지금으로부터 530여 년 전에 조선시대 5현 중의 한 분인 일두 정여창 선생의 집안에서 제조하여 음용되어온 전통 명주이다. 정여창 선생의 태생지인 ○○군 지곡면 개평마을은 하동 전씨 일가의 집성촌으로 집안에서 내방객과 경조사 때에 ○○○를 빚어 대접하였는데 찹쌀로 빚어 감칠맛 나는 술맛과 솔잎 고유의 은은한 향으로 인하여 한양뿐 아니라 전국적으로 유명하게 되자 임금님께도 진상하게 이르렀고 훌륭한 술맛으로 칭찬이 자자하여 매년 진상하였다고 전해지고 있다. 정여창 선생의 종가에서는 끊임없는 내방객으로 자연스럽게 음식문화가 많이 발달하였으며, 특히 1…","a":"함양 송순주","c":"시도무형유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644658.jpg"},{"q":"안동지역에서 제작된 대마포로서 삼베라고도 한다. 안동은 기후와 토질이 삼베재배에 적합하고 베짜는 기술이 우수하여 조선시대에는 궁중진상품으로 사용되기도 했다. 제작과정은 재배와 수확으로부터 베짜기까지 8과정으로 나뉜다. 우선 재배를 해서 7월에 수확을 하는데 수확한 삼베는 물에 불려서 껍질을 벗긴 후 말린다. 말린 삼껍질을 물에 적셔서 손과 삼톱으로 째고 훑어내려 가닥(실)을 만들고 삼베를 짤 틀에 실과 새로 만든 실을 잇는다. 이어 굵은 실과 가는 실을 결정하여 한 폭에 몇 올이 들어갈지 결정한 다음 실을 물레에 올려 실을 감아 놓을 타래를 만든다. 풀먹이기 과정을…","a":"안동포짜기","c":"시도무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644260.jpg"},{"q":"○○○○○는 경기도 포천시 가산면 일대에서 논을 맬 때 불렀던 농업노동요이다. 포천 지역에는 여러 종류의 노동요가 전해오고 있지만 그 중에도 논맬 때 부르는 메나리가 매우 독특하여 포천의 노동요를 묶어 ○○○○○라고 명명하게 되었다. 메나리는 악곡 명으로서 강원특별자치도에서도 널리 논매는 소리로 노래되는 곡이다. 강원특별자치도에서는 보통 교환창交換唱이나 윤창輪唱, 독창獨唱으로 노래되는데, 포천의 메나리는 다섯 조를 나누어 소리를 부르는 독특한 가창방식이 사용되고 있다. 또한 메나리는 음악학에서는 한반도 동부지역의 음악 양식을 이르는 말로도 사용되고 있다. ○○○○○는…","a":"포천메나리","c":"시도무형유산","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018081009505200.jpg"},{"q":"○○○○은 조선시대 궁중무용과 행악, 지방관아의 연회, 높은 관리나 귀인의 행차, 향교의 제향 및 각 지방에서 신에게 제사 지낼 때 두루 쓰이던 악기편성을 뜻한다. 향피리 2명과 대금·해금·장구·북 각 1명의 6인조를 원칙으로 하고 있다. 경우에 따라서 악기의 종류나 편성인원에 다소의 차이가 있으며 지역(경기·호남·해서·영남 등)에 따라 음악적 특징, 악곡구성에 다소 차이를 보이고 있다. 연주형태는 가로 1줄로 앉아서 연주하거나, 세로 2줄로 서서 연주하거나, 세로 2줄로 걸어가면서 연주하거나, 말 위에서 연주하는 것이 보통이다.","a":"삼현육각","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643493.jpg"},{"q":"임성안은 1958년에 태어나, 조선불교미술의 맥인 금호 - 보응 - 일섭 - 우일스님으로 내려오는 계보를 잇는 허길량 문하생으로 입문하여 사사받았다. 임성안은 마산 관음사, 무주 안국사․백련사, 김제 금산사․ 귀신사, 장수 신광사, 완주 화암사․ 위봉사, 광주 원광사, 군산 은적사, 인천 지선사, 해남 대흥사 등 여러 불사에 주도적으로 참여하였다.","a":"불교목조각장","c":"시도무형유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2021060710494000.jpg"},{"q":"○○○에서 경객이 앉아서 북과 징을 두드리며 무경을 외우며 하는 굿이다. ○○○의 유래는 고려시대 맹승盲僧에서 기원하여 조선시대 독경하던 명통시明通寺 선사禪師들이 명통시의 폐지로 생활방편으로 민간에서 독경사讀經師로 활동하면서 형성되었다. 청주지역의 ○○○은 조선시대 문의현 지금의 청주시 문의면 구룡산에 있었던 노인성전老人星殿의 경사에 의하여 시작되었다고 한다. ○○○은 크게 기복굿과 양재굿으로 나누어진다. 무경은 ○○○에서 좌무가 외는 경문인데, 충북지역의 무경은 서경序經으로 굿의 첫머리에 송경하는 정화무경淨化巫經, 제신을 영신 새신 송신하는 본경인 청신무경請神巫經…","a":"충청도 앉은굿","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643911.jpg"},{"q":"죽세공예품으로 유명했던 전라도에서 예부터 ○○은 대표적인 산지로 유명하였다. ○○의 죽세공예품은 참빗에서 유래되었다고 구전되고 있지만 공식적인 기록으로 볼 때 ○○ 죽세공예의 시작은 부채로 나타나고 있다. 17세기 초에 이미 ○○에는 중앙(工曹)에서 파견된 ○○○이 활동하고 있었다. ○○은 인근 고을의 장인들을 모아 편죽(片竹)을 다듬어 공조에 올려 보내는 역할을 책임지는 도회관(都會官)이었다. ○○에서 올려보낸 편죽으로 공조에서는 부채를 만들었다. 18세기 중엽의 『여지도서(輿地圖書)』에 ○○산 부채가 상납되었다는 기록으로 보아 완제품을 진상하는 단계에 진입하였음을…","a":"담양 선자장","c":"시도무형유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026032415420490.jpg"},{"q":"○○○○란 ‘분장회○○○’의 줄임말로 그릇의 표면을 백토로 바른후 다양한 기법을 활용하여 문양을 장식한 것이 특징이며, 고려 말 상감청자에 연원을 두고 조선 초에 성행적으로 제작되었다. 특히, 세종연간에는 인화분청이 절정을 이루며 관용官用자기로 공납貢納되어 왕실과 관청에서도 사용되었고, 지역별로 다양한 장식기법이 특색을 나타내며 절정을 이루었는다. 그러나 15세기 후반 경기도 광주지역에 사옹원司饔院 소속의 분원分院, 즉 관요官窯가 설치되어 백자의 생산이 본격화되면서 ○○○○는 점차 백토 분장을 위주로 백 자화의 경향을 나타내며 점차 쇠퇴하여 16세기 후반부터는 거의…","a":"사기장-분청사기","c":"시도무형유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411063300.jpg"},{"q":"○○○○○는 만가의 일종으로 만가는 상여를 메고 갈 때에 하는 노래이다. 죽은 자의 명복을 빌고, 살아있는 사람이 오랫동안 살고 싶은 소망을 담은 구전민요로 상례의식에서 부르는 상례의식요이다. 만가를 기능별로 분류하면 축원하는 축원만가, 상여가 나갈 때 하는 출상만가, 무덤을 만들 때 하는 성분만가로 나눌 수 있다. ○○○○○의 경우는 축원만가가 없는 대신 희귀한 대도둠소리가 있고, 출상만가인 상여소리가 있으며, 성문만가인 덜구소리가 있다. ○○○○○는 민족의 정서와 문화를 알 수 있는 민요이기에 무형유산에 지정되었다. 故 예능 보유자 신상경(申相京)의 예능을 이어…","a":"청송 추현 상두소리","c":"시도무형유산","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644392.jpg"},{"q":"○○○이란 법사(經客, 정각, 정각쟁이, 독경자)가 의관을 정제하고 앉아서 북과 꽹과리를 두드리면서 독경을 진행하는 의례로 2020년 충청남도 무형유산 ○○○ 보유자로 인정받은 이용구 보유자는 충남 공주시의 의당면, 반포면, 지금은 세종시로 편입된 장기면 일원에서 오랫동안 세거해온 유력 성씨 가문 중에 하나인 전주이씨 덕천군파 후손이다. 이용구 보유자는 16세에 신병체험을 통해 법사의 길에 들어섰는데 특히 그의 사종조(四從祖)인 이은학 법사(1904년생, 공주군 장기면 산학리)는 독경 뿐만 아니라 육효점에 능하였다. 그는 김연태 법사(공주 반포면 온천리)에게 독경을…","a":"앉은굿(공주앉은굿)","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2024110516250602.png"},{"q":"○○○○○은 정선 산간마을 주민들의 생활감정이 담긴 정선지방 특유의 민요로 ‘아라리’라고도 한다. 고려왕조를 섬기던 선비들이 고려가 망하자 정선지방에 숨어 지내면서 두 임금을 섬기지 않는 충절과 고향에 대한 그리움이 담긴 시를 지어 부르는 것을 지방의 선비들이 듣고 한시(漢詩)를 이해하지 못하는 주민들에게 풀어 알려주면서 부르기 시작한 것이 ○○○○○의 맨 처음이라고 전해진다. 노랫말의 내용은 남녀의 사랑, 이별, 신세한탄, 시대상 또는 세태의 풍자 등이 주를 이루나 일제강점기 때에는 나라 없는 민족의 설움과 울분을 애절한 가락에 실어부르는 등 가락과 노랫말이 일정하…","a":"정선아리랑(아라리)","c":"시도무형유산","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643708.jpg"},{"q":"송서는 한적(漢籍)이나 시문(詩文)을 '글 읽는 소리'로 암송하는 전통 방식이다. 이때의 '글 읽는 소리'란, 뜻글자인 어려운 한자를 유년기부터 보다 쉽게 익히기 위해 음률을 넣어 낭송하는 방법이다. 예를 들어 천자문을 처음 배울 때 “하늘 천, 땅 지”와 같이 율동을 곁들여 좌우로 몸을 흔들며 읊조리는 방식은, 리듬감 속에서 자연스럽게 한자를 익히도록 돕는다. 이러한 낭독 방식은 점차 발전해 내용의 감정에 따라 애절하게, 화평하게, 혹은 근엄하고 장엄하게 소리를 내는 ‘독서성(讀書聲)’의 기초가 된다. 이 소리는 노래처럼 들릴 수 있지만, ‘노래(歌)’가 아닌 ‘소…","a":"경기송서(송서·율창)","c":"시도무형유산","r":"경기도","s":"동두천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643702.jpg"},{"q":"○○○이란 끈목[多繒]을 사용하여 여러 종류의 매듭을 짓고, 술을 만드는 기술 또는 그러한 기술을 가진 사람을 가리킨다. 끈목은 여러 가닥의 실을 합해서 3가닥 이상의 끈을 짜는 것을 말하는데, 그 종류에는 둘레가 둥근 끈으로 노리개나 주머니끈에 주로 쓰이는 동다회와 넓고 납짝한 끈으로 허리띠에 자주 사용되는 광다회가 있다. 복식이나 의식도구 장식으로 사용되는 매듭은 격답·결자라고 한다. 우리나라의 전통매듭은 단색의 끈목을 이용하여 모양을 맺고 아래에 술을 달아 비례미와 율동미를 추구한 것이 특징이다. 또한 연봉매듭과 국화매듭, 잠자리매듭 등 동식물에서 따온 형태와…","a":"매듭장","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624293.jpg"},{"q":"○○ 신전 ○○○는 ○○ 신전면 벌정리 논정마을과 용월리 등 신전일대를 중심으로 전승되는 탐진강 유역의 대표적 ○○○로서, 남해안 지역 농경문화와의 연계성이 높고 ○○○ 본연의 신명과 예술 세계를 잘 담고 있다","a":"강진 신전들노래","c":"시도무형유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101118300900.jpg"},{"q":"○○○○란 제주도 해녀들이 배를 타고 나가거나 들어올 때 노를 저으면서 부르는 민요를 말한다. 이 민요와 노를 젓는 동작은 밀착되어 나타나며 노동을 한결 가볍고 즐겁게 이끌어 주는 역할을 한다. 해녀들은 일할 때 사용하는 테왁, 망사리, 빗창 등으로 장단을 치면서 부른다. 내용을 보면 일의 고됨과 일상생활을 정감있게 표현한 것으로 생업에 대한 강렬한 기백이 나타나 있고, 역동적이며 직설적인 색채가 강하다. 두 사람이 교대로 선소리를 하면 나머지 사람들은 ‘이여싸’등의 후렴으로 받는다. 때로는 어부가 선소리를 하고 해녀들이 뒷소리를 하기도 한다. 가창형태가 복잡해 선소…","a":"해녀노래","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644666.jpg"},{"q":"‘○○’은 오랜 역사와 전통 속에서 다양한 형태로 지속하여 왔으며, 우리 민족의 정체성과 가치를 대표해 온 전통생활관습이자 전통지식이다. ○○은 봄을 대표하는 명절로, 동지 후 105일째 되는 날이며 성묘, 벌초, ○○ 제사 등 조상 추모 의례가 강조되어 전승되고 있다. ○○에는 조상의 선영(先塋)을 찾아 제사 지내고, 묘소의 떼를 입히는 개사초(改莎草)나 무덤을 보수하는 날로 요즘에도 각 문중(門中)에서는 ○○ 성묘를 하고 제사를 지내고 있다. ○○에 대한 최초 기록은 『고려사』, 「예지」 9대 속절에 언급되고, 왕실제사나 ○○성묘가 확인되는 등 고려시대 명절로서…","a":"한식","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2023121814045500.jpg"},{"q":"숭선전은 가락국 시조왕과 왕비 허씨의 신위를 봉안하고 향화를 받드는 전각이다. 이 전각은 국조단군과 고구려 시조 동명왕을 모신숭영전, 기자의 숭인전, 신라 시조 혁거세왕의 숭덕전, 탈해왕의 숭신전, 알지왕·문무왕·경순왕의 숭혜전, 백제 시조 온조왕의 숭열전, 고려 시조왕의 숭의전과 함께 팔전의 하나이다. 숭선전 대제는 춘추향 2회로 춘향은 음력 3월 15일, 추향은 음력 9월 15일이며 시간은 상오 10시부터 약 1시간 거행된다. 당초에는 정월 3일과, 7일, 5월5일, 8월5·15일에 년중 5회의 묘향을 받들기 시작하여 제10대 구형왕(구해 또는 구충왕) 12년(5…","a":"숭선전제례","c":"시도무형유산","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644456.jpg"},{"q":"○○○은 얼레빗을 만드는 장인을 말한다. 우리나라의 전통 빗인 얼레빗은 한자로 「소(梳)」라고 하며, 주로 나무로 만들어졌기 때문에 「목소(木梳)」라고 부른다. 얼레빗은 길고 엉킨 머리를 가지런히 빗어 내릴 때 사용하는데 머리 모양과 용도에 따라 크기와 모양이 다르며, 빗살 역시 성근 것과 촘촘한 것으로 구분된다. 전통 얼레빗들은 장식 없이 단순하게 목재로만 만든 것이 대부분이지만, 대모·뿔 등의 값비싼 재료로 만들거나 옻칠, 화각, 옥 등으로 빗면을 장식하기도 한다. 2010년 충청남도 무형유산 ○○○○○ 보유자로 인정받은 이상근 보유자는 처음엔 소목일 전반을 다루…","a":"공주 목소장","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2024110516235901.png"},{"q":"‘○○’는 오랜 역사와 전통 속에서 다양한 형태로 지속하여 왔으며, 우리 민족의 정체성과 가치를 대표해 온 전통생활관습이자 전통지식이다. ○○는 24절기의 22번째 절기로 1년 가운데 밤이 가장 길고 낮이 가장 짧은 날로 겨울의 대표 명절이다. 예로부터 ○○는 아세(亞歲)라고 하여 ‘작은 설’로 불렸으며, 건자월(建子月), 고월(辜月), 중동(仲冬), 지월(至月), 주정(周正), 창월(暢月), 일지일(一之日) 등 여러 이칭이 있었다. ○○는 역(曆) 계산의 기산점(起算點)으로서 대단히 중요하게 인식되어 왔다. 태양이 황도의 가장 남쪽 지점을 통과하는 시점으로 일 년…","a":"동지","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2023121814585000.jpg"},{"q":"○○○○은 익산(옛 이리)지방에서 전승되는 농악으로 호남우도농악에 속한다. 익산시 새실마을은 예로부터 마을농악이 왕성했고, 김제·정읍 등지에서 전문적인 농악을 배워온 사람들을 받아들여 오늘과 같은 높은 수준의 농악단을 배출할 수 있었다. ○○○○은 용기, 농기, 쇄납, 나팔, 사물(쇠4, 징2, 북2, 장고4), 법고(불교의식에서 쓰는 작은 북), 잡색(양반, 대포수, 조리중, 창부, 각시, 무동)으로 편성된다. 농악수들은 치배 또는 군총이라고도 하는데 흰 바지 저고리에 색동달린 반소매의 검은색 쇠옷이나 조끼를 입고 삼색띠를 두르며 머리에는 상모와 고깔을 쓴다. 쇠가…","a":"이리농악","c":"국가무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623765.jpg"},{"q":"생칠이란, 옻나무 수액을 채취하여 그것을 기물에 칠하는 것을 말한다. 생칠 작업을 하면 수분이 말랐을 때 반투명의 조청 빛깔이 나며 은은한 색과 아름다움이 오래도록 지속되는 우수한 칠기공예에 속한다. 우리나라 칠기의 역사는 청동기시대 유적에서도 발견되며 삼국시대를 거쳐 고려 시대에는 나전칠기가 발달하였고 조선 시대에는 여러 종류의 칠기 제품이 다양하게 사용되었다. 현재 주된 옻칠 공예품은 상 종류와 목재 식기류, 좌대 등이 있다. 고(故) 송복남(1936년생) 선생은 13세부터 친구의 권유로 옻칠 분야에 입문하여 서울시 무형유산 1호인 고(故) 홍순태 선생의 제자로…","a":"생칠장","c":"시도무형유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025120115051590.JPG"},{"q":"○○○는 멥쌀과 찹쌀로 빚은 맑은 술로, 조선시대 양온서라는 관청에서 빚어 대궐안으로 들여보내던 전통 궁중주이다. ○○○를 빚을 때는 궁중어의들의 관리 아래 항상 어의들이 처방을 내려 빚었고, 임금이 신하에게 하사하였다고 한다. 조선시대 문헌인『고사촬요』, 『규곤시의방』에 제조법이 기록되어 있는데, 누룩 만드는 법이 특이한 것이 특징이다. 녹두와 보리, 밀을 섞어 빻아 누룩을 만들고 일주일 동안 밤이슬을 맞혀 누룩 냄새를 없앴다. 발효가 끝나면 덧술을 여러번 거치고 한달 가량 후숙을 하고, 소줏고리에 넣어 증류시킨다. 증류가 끝나서도 옹기 항아리에 넣어 보관시켜 6개…","a":"향온주","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018110114513700.jpg"},{"q":"○○○○○은 2016년 12월 28일 부산광역시 지정 무형유산으로 지정되었고, 우리 지역의 전통 배인 ○○○○를 만드는 장인을 말한다. ○○○○○ 보유자 김창명은 증조부 때부터 하단 토박이로 살며 4대째 가업으로 배 만드는 일을 이어 왔으며 1955년부터 현재까지 낙동강 하구 인근의 황포돛배, 나룻배, 소구엔진 배 등의 100여척의 목선을 만들어 왔다. 김창명 장인의 황포돛배는 낙동강 역사의 상징물 중 하나로 전통선박의 선형과 제작기법의 발달과정, 목선제작 도구, 낙동강 하류 생활문화의 이해 등의 측면에서 중요한 의미가 함축되어 있다고 할 수 있다. 하단의 황포돛배인…","a":"하단돛배 조선장","c":"시도무형유산","r":"부산광역시","s":"사하구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101513075500.jpg"},{"q":"○○○이란 단소를 만드는 사람 또는 기술을 말하며, 단소는 세로로 부는 악기로 관악기의 하나이다. 단소를 만드는 재료로는 황죽이나 오죽을 사용한다. 제작방법은 대나무를 소금물에 10시간 정도 삶아 기름을 제거하고 절인 다음 열을 가하여 구부러진 부분을 바로 잡는다. 이어 찬물에 10분 정도 담가둔 후 통풍이 잘되는 그늘에서 3개월 이상 건조시킨다. 건조시킨 대나무는 길이 500㎜로 잘라서 안을 뚫고 다시 420㎜로 자른 다음 반달 모양의 취구를 만들고 지공을 뚫는다. 취구는 입김을 불어넣는 곳이며, 지공은 손가락으로 음정을 조절하는 부분이다. ○○○은 전통공예기술로서…","a":"단소장","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643495.jpg"},{"q":"발이란 갈대 또는 가늘게 쪼갠 대나무를 실로 엮어서 만든 가리개로 여름날 창문이나 대청에 쳐서 햇볕을 가리거나 실내장식 등에 사용되는 것을 말한다. 죽렴(竹簾)은 대나무를 삼끈이나 실로 엮어 만든 대발을 말하는 것이다. 대발은 보통 길이가 6척인데 외창은 3척, 쌍창은 4척 5촌의 너비이다. 종류는 쪽발, 가마발, 겉세렴(죽피렴), 속세렴(내죽렴), 귀문렴, 보통조각렴, 장조각렴, 족자발, 김발, 붓발, 병풍발 등이 있다. 제작과정은 채취한 2∼3년 생 대를 저장하여 순색이 되도록 그늘에서 말린 뒤 절단, 쪽살내기, 마디훑음질, 잔살내기, 조름질, 엮음질의 순서로 제…","a":"담양죽렴장","c":"시도무형유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644217.jpg"},{"q":"○○○○○량은『○○○』,『○○○』,『놀량』등 여러가지 이름 으로 불려 왔으며 서울‧경기를 중심으로 전승된 경기○○○○○과 황해도를 중심으로 발달된 서도○○○○○으로 나뉘며, 17C 무렵에 원형이 성립된 것으로 보이는 황해도지역의 대표적인 향토문화이다. 특히, 놀량은 노래와 발림 춤으로 구성된 판에서 연행되는 마당소리 한바탕으로 고도의 음악성과 대중예술성을 지녔으며, 두 옥타브의 넓은 음역을 가지고 있고, 소리가 박진감이 넘치고 씩씩한 멋을 풍기며 흥을 돋구는 남성적인 음악이다.","a":"서도선소리산타령‘놀량사거리’","c":"이북5도 무형유산","r":"황해도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669678.jpg"},{"q":"농악은 농부들이 두레농악은 농부들이 두레(마을의 공동 작업을 하기 위한 조직)를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. ○○○○은 호남우도농악의 한 종류로 김제 전역에 분포되어 있는 농악을 말한다. 일찍부터 각 마을에서 대동굿의 형태로 농악을 전승해 오다가 좀더 전문적인 예인집단에 의한 농악으로 발전하였다. 농악대의 구성에 있어서 쇠 ·장구를 주된 악기로 사용하고 큰 북을 사용하지 않으며, 평야지역의 두레굿이 발달되어 있다는 것이 특징이다. 현재 ○○○○은 박동근과 김해순이 설장고 예능보유자로 인정되…","a":"김제농악","c":"시도무형유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644099.jpg"},{"q":"경기의 문화에는 민중의 문화를 기저로 하면서도 고급스럽고 세련된 궁중 문화가 녹아있다. 이를 잘 보여주고 있는 무형유산이 ‘○○○○’다. ○○○○○는 경기도 남양주시 ○○○ 지역에서 전승되고 있는 탈놀음을 일컫는다. 조선시대 ○○○은 교통의 중심지로 상업이 발달했던 곳이다. 한양으로 들어가는 길목으로 사람들의 왕래가 잦은 곳이었기 때문에 ○○○○ 연희가 성행할 수 있었다. 놀이꾼들은 정규 공연 시기를 정해 상인과 부호들의 지원을 받았으며, 이를 바탕으로 다른 지역으로 순회공연을 나서기도 했다. ○○○○○는 다른 가면극과 마찬가지로 음악 반주에 춤과 노래를 하는 가무와…","a":"퇴계원산대놀이","c":"시도무형유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643700.jpg"},{"q":"◦ 내포○○○은 내포지역의 무사안녕을 위한 기원과 풍어제, 산신제 등의 민속(무속)문화 등에 깊은 영향을 끼치며 현재까지 계승되고 있으며, 향후 지역 민속문화의 전승 및 활용 등 보존가치가 큼. ◦ 1964년 충남 내포지역에서 당대 최고라 불렸던 이내황 선생으로부터 내포○○○을 사사하며 입문한 (명예)보유자 정종호는 전통 ○○○ 문화 전승기량을 보유하고, 경문집을 풀이한 경문요람을 발간하는 등 약 40여 년간 ○○○의 체계적 전승 및 후계자 양성에 적극 정진하고 있으며, 현재는 보유자 조부원 선생님을 중심으로 보존되고 있음.","a":"앉은굿(내포 앉은굿)","c":"시도무형유산","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023041311065100.jpg"},{"q":"석구조물은 목조건축물이 세워지는 기단, 석축, 석단, 육축 등의 기초부을 말한다. 석구조물을 축조하기 위해서는 돌의 강도와 수압, 지압을 고려해야 하고 기하학적 원리도 이해하고 있어야 한다. 석구조물 장인이 되기 위해서는 기나긴 수습 기간을 거쳐야 하고, 육체적 고단함도 이겨내야 하며, 오랜 경험과 타고난 자질이 있어야 한다. 보유자 임동조는 우리나라 석구조물 축조의 전통을 잇고 있는 몇 안 되는 장인 중 한 명이다. 그는 1969년, 당시 15세 나이로 석구조물 일을 하던 매형을 따라 일을 배우기 시작했다. 특히 매형의 스승인 안기호 선생은 1968년에 일제 강점기…","a":"석장(석구조물)","c":"시도무형유산","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411212200.jpg"},{"q":"○○○는 한량과 승려가 한 여인을 유혹하는 내용을 춤으로 표현한 무용극이다. 한량이란 일정한 벼슬없이 놀고 먹는 양반을 말한다. 유래는 정확히 알 수 없으나 조선 후기에 생긴 사당패에 의해 연극으로 행해졌고, 고종(재위 1863∼1907) 때 정현석의 『교방가요』에 기록된 것으로 보아 조선 말엽에 유행된 것으로 추정된다. 1910년 이후에는 기방(기생집)에서 성행하였다. ○○○에는 악사, 한량, 승려, 색시, 주모, 별감, 상좌, 마당쇠가 등장하는데, 배역에 따라 성격이 다른 춤사위와 옷차림으로 구성된다. 한량의 경우에는 도포에 정자관을 쓰고, 별감은 궁중별관복을 입…","a":"한량무","c":"시도무형유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644433.jpg"},{"q":"○○○은 건물의 문, 창호, 장, 궤, 경상, 문갑, 경대, 소반 등 목가구를 제작하는 기술과 기능을 가진 목수를 말한다. 소목제작의 전통 기법은 목재의 선택, 건조, 자르기, 밑그림 그리기로 나뉜다. 각 단계별 과정은 다음과 같다. ① 목재의 선택 및 채취 - 목재는 성장기와 정지기가 반복하게 되므로 나이테가 생겨난다. 나이테는 성장년수를 보여주는 것이며 나이테에 따라서 목재의 재질도 큰 차이를 지닌다. 외피의 목질부는 비교적 여린 목재이고 수액도 많은 상태이다. 그런 반면 수심에 가까운 부분은 강하고 단단하여 온도, 건습에 따른 변화가 적다. ② 건조 - 목재작업…","a":"소목장","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022090510170100.jpg"},{"q":"1940년 순창에서 태어난 이정호는 박홍규, 양학구, 설동근 등에게 들소리를 사사받았다. 전북예술경연대회, 전국민속예술제, 전국민요경창대회, 전국시조가사경창대회 등 다수 대회에서 입상하였다. ○○○○○는 500여년 전부터 모정을 중심으로 동전․대장 들녘에서 불리던 ○○○○○는 힘든 농사일을 상호부조의 품앗이를 통해 극복하면서 풍년을 기원하는 소박한 마음이 고스란히 담겨져 있는 이 지역의 대표적인 농요이다. 이정호는 ○○○○○ 선소리꾼으로서 물품기소리, 상사소리, 문열가, 연꽃타령, 방아타령, 사호소리, 장원질소리 등으로 논에 물을 대고, 모를 심고, 김을 매는 등의…","a":"금과들소리","c":"시도무형유산","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644152.jpg"},{"q":"○○○○○은 진주·○○○ 지역에 전래되고 있는 농악으로 영남농악에 속한다. ○○○○○에 쓰이는 악기에는 꽹과리, 징, 장구, 북, 법고가 있으며, 편성은 기수(旗手)와 쇠, 징, 북, 장구, 법고 그리고 양반과 포수로 되어 있다. 모두가 흰바지와 색깔있는 저고리의 농악복에 색띠를 두루고, 모자(상모)를 쓴 채 연주하는데 개인놀이가 비교적 발달하였다. 판굿에서는 채상모놀이가 돋보이며, 군사놀이인 팔진해식진(八陣解式陣)굿이 특이하다. 빠른 가락을 모는 경우가 많아 힘차고 가락이 다채로워 흥겹다. ○○○○○은 판굿의 전통을 이어받고 있어 예술적 가치가 높으며, 팔진법이라든…","a":"진주삼천포농악","c":"국가무형유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624088.jpg"},{"q":"악기< 樂器>는 음악을 연주하는데 쓰이는 기구의 통칭으로 전통음악에 상용되는 국악기는 삼국시대를 전후해서 부터 우리나라에서 만들어져 전해오는 고유한 악기와 중국을 비롯하여 서역 및 기타 지방에서 수입되어온 외래 악기를 포함하여 약 60여종이 전해오고 있다. 우리나라는 북방대륙과 인접하였던 관계로 삼국시대에 이미 중국계 및 서역계의 음악들이 들어왔고, 특히 신라가 삼국을 통일한 이후로는 당나라 음악이 수입되었다. 고려시대 이르러서는 송나라 속악< 俗樂 >과 아악< 雅樂 >이 수입되었는데, 예종때 아악이 들어옴으로써 거기에 편성된 아직도 대량으로 들어왔다. 이 악기들은…","a":"악기장","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643546.jpg"},{"q":"속초 ○○○○는 쌍천을 따라 형성된 넓은 뜰을 바탕으로 형성된 농경마을인 도문마을에서 전승되고 있는 농요로 영북지방의 특성이 잘 나타나 있으며, 특히 근대화 과정에서 많은 농요들이 사라져 가는 실정속에서도 마을주민들에 의해 잘 보존되어온 농요라는 점에서 전통문화의 체계적인 보존·전승을 위해 지정가치가 큼.","a":"속초도문농요","c":"시도무형유산","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643825.jpg"},{"q":"1938년 태어난 김년임은 어머니 문명식과 장형욱에게 사사받았다. 전주비빔밥의 맛은 천혜의 지리적 조건에서 생산되는 질 좋은 재료, 장맛, 뛰어난 요리솜씨, 움식에 드리는 정성이 잘 조화된 결과라 하겠으며, 특히 음식재료의 질적인 우수성과 음식재료의 특성에 맞는 적절한 요리법의 활용이다. 김년임은 원형을 체득 보전하고 있으며, 칼 다루는 법, 불 조절법, 맛내는 법, 은행 볶는 법 등 자신만의 조리기술을 잘 갖추고 있다.","a":"전통음식","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644160.jpg"},{"q":"옻칠은 선사시대부터 우리나라를 비롯하여 중국, 일본 등지에서 천연도료로 널리 이용되었다. 옻칠은 목기에 칠하면 갈라지고 터지는 결점을 보완하고 수분의 침투를 막아 오랜 기간동안 사용할 수 있고 인체에도 무해하다는 특징이 있다. 나전칠기란 옻칠을 한 표면에 소라, 전복, 조개 등을 이용하여 문양을 만들어 붙인 공예품으로 오색영롱한 자연색과 은은한 광택을 자랑하는 옻칠이 잘 조화된 우리 민족의 대표적인 공예품이라 할 수 있다. 박귀래씨는 1977년부터 이형만(국가무형유산 나전장)씨 문하에서 나전칠기 제작기법을 사사받아 1998년에는 전국 기능경기대회 나전칠기 분야에서 은…","a":"나전칠기장","c":"시도무형유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643768.jpg"},{"q":"○○○○는 노동요로서 어부들이 바다에서 사용하는 닻줄을 만들 때 불려지던 노래이다. 내용은 나무타령·자우소리·줄 놓는 소리·꼼새소리·순레소리·채짓는 소리·여사소리·사리소리 등으로 구성되어 있다. 나무타령은 나무를 벨 때 부르는 소리, 자우소리는 줄을 단단하게 꼴 때 부르는 소리이다. 줄 놓는 소리는 굵지 않은 세 가닥의 줄을 꼬아나갈 때, 꼼새소리는 줄이 단단하고 수평을 유지하도록 하는 과정에서 부른다. 순레소리, 채짓는 소리는 가는 3개의 줄을 하나의 굵은 줄로 만들 때 부르며, 굵게 꼬여진 줄을 둘둘말 때 여사소리, 사리소리 등을 부른다.","a":"주대소리","c":"시도무형유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643500.jpg"},{"q":"‘불화’는 불교의 종교적 이념을 표현한 그림이다. 불화의 제작 시기에 대해서는 정확히 알 수 없으나, 전문가들은 원시불교 사찰의 하나인 ‘기원정사’에 그림을 그려 넣었다는 기록을 토대로 불교 도입 초기부터 제작했다고 추측하고 있다. 불화는 불교의 교리를 담고 있기 때문에, 불화를 제작하는 장인을 특별히 ‘금어金魚’, ‘화승畵僧’, ‘화사畵師’, ‘화원畵員’으로 높여 부르기도 했다. 불화 제작기능은 1972년 단청장丹靑匠이 국가무형유산으로 지정된 이래, 줄곧 단청장 보유자에 의해 전승되었으나, 2006년부터 국가무형유산으로 분리 지정해 운영하고 있다. 경기도무형유산 ○…","a":"불화장","c":"시도무형유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091413560200.jpg"},{"q":"○○○○는 한국 전통차 문화를 복원·계승하여 인천지역을 중심으로 일상생활 속에서 차(茶)문화와 생활예절을 복원·정립한 것이다. 그 유래는 기능보유자인 이귀례 선생이 어릴적부터 동학운동(東學運動)을 하던 조부(祖父)에게서 차(茶) 예절을 접한 이래 1973년 성균관대학 유학장(儒學長) 유승국 교수에게서 생활 법도와 형식을, 전주 이씨 종친 인천지원장인 이덕유에게서 전주 이씨 제례예법을 전수 받았다. 1974년 다경·다신권·동다송·국조오례의 주자가례 등 각종 문헌과 전통사찰의 다례를 수학하였고, 1978년 한국차인회, 1980년 한국 차 문화협회 활동 등으로 한국의 ○○…","a":"규방다례","c":"시도무형유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643509.jpg"},{"q":"○○○는 소리꾼 한 명이 고수(북치는 사람)의 장단에 맞추어 창(소리), 말(아니리), 몸짓(너름새)을 섞어가며 긴 이야기를 엮어가는 것을 말한다. ○○○는 순조(재위 1800∼1834) 무렵부터 ○○○ 8명창이라 하여 권삼득, 송흥록, 모흥갑, 염계달, 고수관, 신만엽 등이 유명하였는데 이들에 의해 장단과 곡조가 오늘날과 같이 발전하였고, 동편제(전라도 동북지역)·서편제(전라도 서남지역)·중고제(경기도·충청도) 등 지역에 따라 나누어졌다. ○○○가 발생할 당시에는 한 마당의 길이가 그리 길지 않아서 ○○○ 열두 마당이라 하여 그 수가 많았으나 현재는 ○○○ 다섯마당…","a":"판소리춘향가(동초제)","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643552.jpg"},{"q":"○○○란 소리하는 사람 한 명과 북치는 사람 한 명, 그리고 판을 이루는 구경꾼으로 이루어지는 무대예술을 말한다. 소리하는 사람은 소리와 대사(아니리), 몸짓(발림)을 하며, 북치는 사람은 소리하는 사람의 가락에 따라 북을 쳐서 장단을 맞추며 신명난 분위기를 이끌어 간다. ○○○는 지역적 특성과 전승계보에 따라 전라도 동북지역의 동편제·전라도 서남지역의 서편제·경기도와 충청도의 중고제로 나뉜다. 원래는 열두 마당이었으나 일제시대에 거의 사라졌고 춘향가·심청가·흥보가·수궁가·적벽가의 다섯 마당만 현재까지 남아있다. ○○○에 쓰이는 장단에는 느린 장단인 진양, 보통 빠르…","a":"판소리","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/0000000001644058.jpg"},{"q":"색지를 오려 가구 및 상장, 함 등을 만드는 한지공예로, 조형미와 색채미가 뛰어나다. ○○○ 보유자로 지정된 김혜미자는 1987년 한지공예에 입문하여 현재까지 활동하고 있으며, 1987년 호진 상기호 선생에게 전지공예를 전수받고, 1990년 최영준 선생(충남 무형유산 보유자)에게 지승공예를 전수받았다. 1995년 전주한지공예대전에서 대상을 받고, 한지 공예 분야에서 다수의 전시와 활발한 전승활동을 진행하고 있습니다.","a":"색지장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093013512300.JPG"},{"q":"○○○○○은 ○○군 용평면 일대에서 전승되어 온 농악으로 지리적인 특성상 영동과 영서농악의 특성을 함께 갖추고 있으면서 독창적인 개성도 갖추고 있고, 각 지역의 농악들이 대부분 사라져 가는 실정에서도 원형을 잘 계승하여 왔다. 특히 산업사회로의 이행과 급격한 농촌지역의 기계화로 각 지역의 농경민속들이 점차 사라져 가는 실정에서 가장 기초가 되는 것이 농악이라는 점에서 전통문화의 체계적인 보존·전승을 위해 가치가 크다. 최승철과 고완재는 어려서부터 용평지역의 농악과 함께 생활해오면서 ○○○○○의 상쇠로서 농악대를 이끄는 기능이 우수할 뿐만 아니라 농악의 전반적인 부문을…","a":"평창 둔전평농악","c":"시도무형유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052016423600.JPG"},{"q":"○○○은 서울을 비롯한 한강 이북지방과 수원·인천 등지에서 마을의 평화와 풍년을 목적으로 매년 또는 2년이나 그 이상의 해를 걸러 정월초나 봄·가을에 정기적으로 행해지는 굿을 말한다. ○○○○○은 ○○○ 일대의 한강 이남지역에 전해져 오는 마을굿으로, 지금은 부천의 장말에서만 완전한 형태의 ○○○○○을 볼 수 있다. ○○○○○의 정확한 기원은 알 수 없지만 마을 동산의 소나무 숲속에 300년이 넘은 도당할아버지와 할머니를 모신 당가리가 있는 것으로 보아 조선시대를 통해 대대로 전해진 것으로 보인다. 굿은 오전에 시작해서 다음날 아침에 끝나며, 집안의 대를 이어 기능을…","a":"경기도도당굿","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623603.jpg"},{"q":"<○○○○>에 대한 문헌적 기록은 찾아보기 어려우나 일반적으로 통일신라시대의 <삼현삼죽(三絃三竹)>에서 출발한 것으로 보며, 삼현은 현악기를, 삼죽(三竹)은 관악기를 각각 지칭한다고 할 수 있다. 그러나 현재 ‘○○○○’이라 함은 현악기를 가리키는 삼현의 의미는 사라지고, 피리와 해금, 북 등이 추가 편성된 관악기 위주의 악기편성을 가리킨다. 따라서 신라시대의 <삼현삼죽>이 시대를 거치면서, <○○○○>으로 변화한 것으로 추측하는 것이 정설이다. 2014년 5월 15일에 최경만(피리), 김무경(해금), 이철주(대금)가 보유자로 인정받아 활동하고 있다.","a":"삼현육각","c":"시도무형유산","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409310800.jpg"},{"q":"우리 문화의 근원은 무굿과 풍물놀이에서 시작되었다. 풍물놀이에서 유래한 북놀이는 가장 오래된 놀이로 소리와 춤이 절묘한 조화를 이루고 있다. 북놀이는 지역에 따라 각기 특성을 지니는데 전라도의 경우 외북치기와 양북치기로 나뉜다. 외북치기는 전라도지역의 보편적인 형식이며, 양북치기는 진도에 한하여 전승되고 있다. ○○○○○는 보통의 외북치기와 달리 양손에 북채를 쥐고 장구 치듯이 느린 굿거리에서 시작하며 빠른 굿거리, 자진모리, 휘모리가락으로 풀어 나간다. 다양한 기법을 구사하는 북장단과 더불어 ○○○○○는 뛰어난 춤사위를 가지고 있다. ○○○○○는 북소리의 강열함과…","a":"진도북놀이","c":"시도무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644201.jpg"},{"q":"○○○은 김세종제<○○○>의 보유자로, 김세종제 ○○○는 오늘날 전승되고 있는 ○○○ 가운데 가장 인기있고 기품있는 소리로 평가되고 있다. 현재 ○○○ 명창으로 이어지고 있는 ○○○는 명창 정응민이 젊은 시절부터 여러 대가들에게 물려받은 고형의 ○○○를 집대성하고 평생을 연마하여 이루어낸 소리이다. 정응민 명창의 수제자가 정권진과 성우향이며 ○○○이 그 계보를 잇고 있다. ○○○의 김세종제 ○○○는 우아하면서도 아름다운 대목이 많은 소리재이며, 판을 이끌어 나가는데 탁월한 기량을 보여줄 뿐 아니라 계면조의 표정적 언행, 예술적 아름다움을 훌륭하게 표출하여 김세종제 ○…","a":"판소리 춘향가 이용길","c":"시도무형유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060215101000.jpg"},{"q":"○○○은 글자를 새기는 장인으로, 각자 작품은 인쇄를 목적으로 하는 목판(木版)과 목활자(木活字), 건물에 거는 편액(扁額)·시판(詩板) 등 현판류(縣板) 등이 주종을 이루며, 의걸이장과 책장 등 목가구에도 활용되는 등 그 쓰임새가 다양하였다. 그러나 이러한 전통적인 각자문화는 근래에 이르러 사진술과 인쇄물의 발달로 인해 급속히 사라져 가고 있는 실정이므로 전통기술의 보존·계승을 위하여 무형유산으로 지정되었다. 이창석은 1978년부터 각자를 해 온 장인으로, 『월인석보(月印釋譜)』 권22, 『훈민정음(訓民正音)』 해례본(解例本)과 언해본(諺解本), 『집왕성교서(集王聖…","a":"각자장","c":"시도무형유산","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643783.jpg"},{"q":"함경도의 대표적 관악기 ○○로 연주하는 시나위로 북청사자놀음, 관원놀이 등의 반주음악, 유랑예인의 악기로 자주 활용됨. 육자배기 토리를 근간으로 하는 남한지역 시나위와 구분하여 ○○○라는 용어를 사용한다.","a":"퉁소 신아우","c":"이북5도 무형유산","r":"함경남도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2018052917444900.jpg"},{"q":"갓은 갓양태와 갓모자로 나누어지는데 갓양태는 갓밑 둘레 바깥으로 넓게 바닥이 된 부분을 말하는 것으로 ‘양태’ · ‘갓양’이라고도 하며, 제주에서는 ‘양태’라 부르기도 한다. 갓양태의 재료는 대오리이다. ○○○○는 양태의 종류 중 최상품의 것을 의미하는 것으로 양태의 품질은 ‘쌀’과 ‘벗대’의 수효 및 ‘도리’ 수의 많고 적음에 따라 결정된다. ○○○○는 쌀과 벗대수가 500, 도리수는 90인 경우가 상품이다.","a":"고분양태","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644704.jpg"},{"q":"주물이란 금속을 용해한 뒤 주형에 주입하여 성형한 것을 말한다. 경기도 지정 ○○○은 전통방식으로 쇠를 녹이고 형틀을 짜서 가마솥을 만드는 기술을 가진 장인이다. ○○○ 김종훈이 가업으로 운영하고 있는 ‘안성주물’은 1910년 중조부 김대선이 가마솥을 때워주는 일을 하면서 시작되었고, 1924년 조부 김순성이 안성시 봉산동 물문거리에 공장을 설립하면서 본격화되었다. 1953년 조부가 병환이 들어 공장 운영이 불가능하게 되자, 현재 ○○○ 보유자인 김종훈이 가업을 이어받으면서 명맥이 유지되었고, 지금은 그의 아들이자 전수 자인 김성태가 운영을 맡으면서 4대째 이어지고…","a":"주물장","c":"시도무형유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411350100.jpg"},{"q":"○○○○○는 충청북도 ○○군 덕산면 일대에서 농사를 하면서 전래되어 온 ○○이다. ○○○○○는 모찌는 소리, 모심는 소리, 논매는 소리, 논 뜯는 소리로 구성되어 있다. 가창방법은 선소리꾼 3명이 각 단계마다 돌아가며 하기도 하는데 한사람이 메기면 전체가 후렴구를 받는 형식으로 되어 있다. 가락은 금강 유역의 한 줄기인 미호천 유역의 음성, 청주 특히 넓은 들을 형성하고 있는 미호천 유역 들노래의 특성을 잘 갖고 있다. 사설은 주로 은근하게 이어져 일의 과정과 동작이 적합하게 짜여져 있어 농사일에 지친 농부들의 피로를 잊게 하고 흥을 돋운다. ○○○○○는 중원마수리○…","a":"진천 용몽리 농요","c":"시도무형유산","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643896.jpg"},{"q":"전통(箭筒)은 전쟁을 하거나 사냥을 할때 화살을 담아서 가지고 다니던 화살통을 말하며, 화살통을 만드는 기술과 그 기술을 가진 사람을 ○○○이라 한다. 우리나라 전통의 역사는 오래되어 이미 신석기시대부터 발달하기 시작하였다. 삼국시대에는 고구려 쌍영총의 기마도와 수렵도 등의 벽화에서 그 모습이 보이고, 신라와 백제 고분에서는 화살통을 꾸몄던 꾸미개가 출토되었다. 고려시대와 조선시대에는 군인들의 사격연습이 실행되어 군수용품으로 없어서는 안될 필수품이 되었으나, 임진왜란 이후 총포와 화약의 발달로 활의 중요성이 감소하여 화살통을 만들던 사람들은 직업을 바꾸게 되었다. 조…","a":"전통장","c":"국가무형유산","r":"경상북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624037.jpg"},{"q":"충청남도 예산 법륜사에서 출가하여 한국전통불교 의례의식인 ○○○○를 오랜기간 전승발전시키고 있다. 국내는 물론 네덜란드, 벨기에, 오스트리아, 폴란드, 중국 등 해외에서 초청받아 공연하는 등 충청남도 만이 독특하게 간직한 소리인 범패 및 무용과 더불어 전통적으로 전승되어지는 불교의식을 널리 전승하고 있는 스님이다. 이처럼 충청도 예산을 중심으로 지역적인 소리와 무용이 잘 전승되고 있다는 것은 방현(보명)스님의 30년 이상 예산의 문화를 이어가는데 지킴이가 되었기 때문이다.","a":"내포영산대재","c":"시도무형유산","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644041.gif"},{"q":"○○○○은 경상북도 남부지방에 보이는 전형적인 모의농사굿 형식이면서도 다른 지역과 달리 글자놀이가 발달한 특수성을 지니고 있다. 이에 덩덕궁 가락의 섬세함과 삼채가락이 조화를 이루고, 특유의 별다드래기장단과 덧뵈기장단이 가락의 주를 이루어 화려하고 웅장한 소리를 만들어내는 것이 특징이다. 이러한 ○○○○의 특징들은 앞으로 보존하고 전승해야 할 가치가 충분한 것으로 파악되며, 무형유산으로서의 가치가 인정된다.","a":"경산 보인농악","c":"시도무형유산","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2017020117212402.jpg"},{"q":"○○○은 건물의 창호, 목기, 목가구(장롱·궤·경대·책상·문갑 등)를 제작하는 목수를 말한다. 기록상으로 보면 목수는 신라때부터 있었고, ○○○이라는 명칭은 고려때부터 사용되었다. 조선 전기까지는 주로 왕실과 상류계층을 위한 목가구가 만들어졌으나, 조선 후기에는 민간에 널리 보급되어 자급자족에 따른 지역적 특성이 나타나게 되었다. 장롱은 재료에 따라 귀목장롱·솔장롱·오동장롱이 있고 칠을 안한 백골 장롱, 칠을 한 칠장롱, 무늬가 없는 민장롱, 들기름을 먹인 종이를 바른 발림장롱으로 분류된다. 즐겨 사용하는 무늬는 삼호장·성티무늬·뇌문(번개무늬)·겹귀무늬·홑귀무늬 등이…","a":"소목장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623873.jpg"},{"q":"북메우기는 전통 북을 제작하는 기술을 일컫는다. 북을 메우는 장인은 한자말로 고장鼓匠이라 하였다. 짐승 가죽을 울려 소리를 내는 북은 가장 원초적인 악기의 하나로 꼽힌다. 가죽의 울림이 다른 재료보다 인간 보편의 기본 감성을 움직인다고 보기 때문이다. 따라서 북은 어느 나라 할 것 없이 각기 매우 오랜 역사를 지녔으며, 한국도 예외가 아니다. 북은 용도에 따라 정악용과 사찰용, 민간용 등으로 나뉘며, 그 종류가 매우 많다. 흔히 알려진 사찰의 법고나 농악용 매구북, 판소리의 소리북 외에도 정악의 좌고座鼓, 용고龍鼓, 영고靈鼓, 교방고敎坊鼓 등 14종에 이르고, 민간용…","a":"악기장(북메우기)","c":"시도무형유산","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018090716200900.jpg"},{"q":"다례란 사람 또는 신불(神佛)에게 차를 달여 바치는 예의 범절로서,○○○○를 비록하여 유가,불가,도가의 다례가 있다. 명(茗) 또는 천(荈)이라고도 쓴 차(茶)는 언제부터 음료로 마시기 시작했는지 정확히 알 수 없다.<삼국사기>에 \"차는 선덕여왕 때부터 있었다.'라고 한 기록으로 보아 적어도 7세기에는 차를 마셨음을 알 수 있다.또 흥덕왕 3년(828)에 \"중국 종의 차나무 씨를 들여와 지리산에 심어 늘어나는 수요에 충당하였다.\"라는 기록이 있다.<삼국유사>가라국기조에서 \"661년 신라 문무왕 때 가야의 종묘에 시절제사인 다례를 지내는 음식으로서 떡,과일 등과 함께…","a":"궁중다례의식","c":"시도무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317432200.jpg"},{"q":"○○○○○은 사찰에서 낙화봉지를 제작하고 의식에 맞추어 낙화를 태우며 재앙소멸과 복을 기원하던 ○○의례로 의례는 예비의식, 본의식, 소재(消災)의식, 축원과 회향(回向) 의식 순으로 진행을 한다. 절차에 따라 종이, 숯, 소금, 향을 준비하고 축원 발원 후 낙화봉지를 제작하고, 낙화 점화와 함께 수구즉득다라니 등을 염송하며 재난·재앙 예방 기원과 함께 의식에 참여한 모든 이들의 축원과 회향을 기원하며 의례를 마친다. ○○○○○보존회는 ‘○○○○○’의 전승에 필요한 전승기량, 전승기반, 전승의지, 전승활동 등이 탁월하여 ‘○○○○○’의 보유단체로 인정 되었다.","a":"세종 불교 낙화법","c":"시도무형유산","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025010720110700.jpg"},{"q":"방짜수저는 전통적인 금속공예품인 유기(鍮器)제품의 하나로서 우리 생활공간에서 다양하게 사용되어 왔던 실용성이 높은 공예품이었으나, 현대화의 과정에서 대체용기의 사용으로 점차 인멸되어 가고 있는 실정이다. 유기는 일반적으로 놋쇠라고 부르며 구리에다 주석이나 아연 또는 니켈을 혼합하여 만든 합금물체로 제작 성분에 따라 다소의 차이를 가지고 있다. 유기의 제작방법은 크게 주물(鑄物), 방자(方字), 반방자(半方字)로 나누어진다. 방짜는 양대(良大)라고도 하는데 동과 주석의 합금을 도가니에 녹여 바둑형태와 같은 놋덩어리를 만든 후 이것을 불에 달구어 두들겨서 늘리고 다듬어서…","a":"방짜수저장","c":"시도무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643776.jpg"},{"q":"-1970년 ○○○에 처음 입문, -1983년 문화유산수리기술자 자격 취득. 1996년부터 ○○시에서 거주하여 현재는 불교 목예원을 운영하고 있으며 40여 년간 불교조각과 후진양성 등 활동하고 있음. -석정(石鼎)스님의 제자인 전기만(田基萬 국가무형유산 제108호 ○○○○)선생의 전수자로 불감, 불상, 불교 ○○○ 등을 중심으로 전승과 보전에 역점두고, 나무가 주는 자연스러운 무늬결을 이용하여 불교문화의 멋과 맥을 이어가고 있다.","a":"영천 목조각장","c":"시도무형유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020040209332000.png"},{"q":"전북무용의 뿌리는 주로 기방무용(妓房舞踊)에 뿌리를 두고 있는데, ○○○○○ 역시 그러하다. 특히 최정철(예명 최선)의 ○○○○은 스승으로부터 배운 수건춤을 오랜 세월동안 무대화로 승화시킨 춤이라 하겠다. 그의 춤은 한(恨)의 정서가 짙게 깔려 있으며, 맺고 풀고 얼르는 묘미와 함께 고도의 절제미는 춤의 특징을 잘 나타내 주고 있다. 최정철은 1945년 10세때부터 춤을 추기 시작하여 1946년에는 김미화 무용연구소에 입소, 1952년부터 추월 선생 및 정인방선생으로부터 ○○○○○ 사사, 1960년에는 전주 도립극장에서 처음으로 무용발표회 개최, 1961년에는 최선…","a":"호남살풀이춤","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644122.jpg"},{"q":"• 환도(環刀)란 칼집이 있어 고리를 달고, 이고리에 끈을 드리우고 그것을 허리에 찬다는 데에서 유래한 명칭임. 요도(腰刀),패도(佩刀)라고 부르기도 함. 환도(環刀)라는 명칭은 고려 말기부터 사용됨. 조선시대 칼자루가 짧은 외날의 칼을 대부분 `환도(環刀)`라고 부름. 휴대하기 간편하고 비상시에 사용하기 용이하도록 길이가 짧고, 무게도 가벼움. 임진왜란(任辰倭亂) 이후 필요에 의해환도의 길이를 상대적으로 길게 제작함. 환도의 제작은 국가에서 직접 관리함. 군기감(軍器監)에 소속된 ○○○들이 만듦. • ○○○의 보유기능은 사철 쇠부림기능(제련기능), 대장공예기능(접쇠…","a":"환도장","c":"시도무형유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018090714263100.jpg"},{"q":"○○○○는 고려 때 중국 원나라에서 들어왔다는 소주에서 그 근원을 찾을 수 있다. 그래서 학자들은 삼별초를 토벌하러 온 몽고인들이 홍주(紅酒) 내리는 비법을 전한 것이 아닐까 하는 주장을 하지만, 재료로 쓰이는 지초(芝草)는 황폐한 몽고땅에서 재배가 힘들기 때문에 생약(生藥)을 활용한 홍주를 전래했다고 보기는 어렵다. 고려 후기 이후 우리 선인들은 어느 지방에서나 한주, 백주라 하여 소주를 제조하여 마셔왔다. 원래 소주는 조정에서만 사용하였으나 차츰 서민층에 대중화된 것으로 보인다. 이 과정에서 소주에 약제를 가미하는 지혜가 생겼고, 약소주 또는 한소주로 발전되어 지…","a":"진도홍주","c":"시도무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101615053600.jpg"},{"q":"○○○○○는 대덕구 목상동 일원에서 전래되어 오던 논농사와 관련된 일노래이다. 갑천과 금강이 만나는 넓은 들에 자리잡은 목상동은 땅이 기름져 예로부터 이곳에서는 농사일이 성했고 농요 또한 많이 불리었다. 모를 심고 논을 매는 일은 집약적인 노동력을 요구하기 때문에 예전에는 마을 단위로 공동작업을 하기 위한 두레가 조직되었다. 농번기가 되어 두레를 짤 때에는 보통 한 집에서 한 사람이 참가한다. 들말에 80호 정도가 살았다고 하니 들말의 두레는 80명 규모의 큰 노동조직이었던 셈이다. 논일을 하러 나갈 때에는 마을 빈터에 두레꾼이 모두 모인 후 농기를 앞세우고 풍장을…","a":"들말두레소리","c":"시도무형유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643584.jpg"},{"q":"김은숙은 국가무형유산 보유자 정달영 선생에게 고제(古制) ○○○ 산조 및 ○○을 사사받았다. 한숙구류에 속하는 정달영 선생의 ○○○ 산조 및 ○○은 1997년 선생이 작고한 후 강정열 선생에게 전수되었다. 김은숙은 강정열 선생에게 고제 ○○○ 산조 및 ○○ 이수를 한 후, 광주 ․ 전남지역을 중심으로 연주 및 제자 양성 등의 활동을 하며 남도에서 발현한 고제 ○○○○○을 보존하고 계승 및 발전시키는데 힘쓰고 있다.","a":"가야금 병창","c":"시도무형유산","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018112115281300.JPG"},{"q":"별신굿놀이는 가무신(歌舞神)적 제의이다. 가정에서 거행하는 무제(巫祭)가 아니고 마을공동으로 행하는 특별 제의라는 점과 제를 주관하는 무격(巫覡:사내무당)이 강신무(降神巫)나 독경무가 아닌 세습무(世襲巫)라는 점이 놀이의 특징이다. 다른 무제보다 굿거리수가 많으며, 장편의 서사가(敍事歌)가 풍부하며, 그 내용면에서 해학성, 그리고 각종의 민속문학을 보유하고 있어서 구연문학의 총체이자 미분화된 종합적인 예술이라 할 수 있다. 그리고 굿에는 우주관, 영혼관, 내세관, 신화등이 표현되어 있으며 가무연회를 숙련하여 촌락민들에게 안식과 활력을 제공해 준다. 대개 별신굿은 3～…","a":"영덕별신굿","c":"시도무형유산","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644269.jpg"},{"q":"북은 나무로 짠 통에 가죽을 씌우고 채로 두드려 연주하는 악기이다. 악기분류법에 의해 혁부(革部)에 드는 장구와 갈고(鞨鼓)를 제외한 정악과 민속악에 쓰이는 종류를 말한다. 대고(大鼓)는 북 중에서 큰북을 말하는 것이다. 한국의 큰북은 우리나라의 신화(단군신화·주몽신화), 전설(낙랑공주와 자명고)에서부터 등장하여 고대사회의 습속(부여의 영고)에도 이미 정착되어 있던 한국 악기 중에서 가장 역사가 오랜 악기로서 정악과 민속악에 구분없이 사용되어온 필수적인 악기이다. 큰북의 제작과정 중 가죽가공은 생가죽을 소금쳐서 저장한 다음 40시간 정도 물에 담구어 불린 다음 털을…","a":"대고장","c":"시도무형유산","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643485.jpg"},{"q":"○○○ 흥보가란 ○○○ 다섯 마당 중 하나로 마음씨 착한 동생 흥보가 다리가 부러진 제비를 살려 보내주어 복을 받는 반면, 욕심 많은 형 놀보는 욕심을 부리다 패가망신하는 권선징악(勸善懲惡)과 형제 사이의 우애를 강조하는 내용의 ○○○이다. 2014년 충청남도 무형유산으로 인정받은 김수향 보유자는 1960년 충남 아산 출생으로 1986년에 진봉규 명창으로부터 춘향가를 배우면서 ○○○를 시작하였으며, 1995년에 성우향 명창에게 「심청가」, 2002년 전정민 명창에게 「흥보가」, 2004년 박양덕 명창에게 「수궁가」, 2007년 전라남도 무형유산 「흥보가」 김향순 보유…","a":"판소리(흥보가)","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019051415141109.jpg"},{"q":"죽염은 대나무 속에 천일염(소금)을 넣고 황토로 입구를 막은 뒤 소나무 장작불로 아홉 번을 구워 만든다. 이 과정에서 소금 속에 들어있는 독소 및 불순물 등이 모두 없어지고 대나무와 황토의 유효성분이 조화되는 건강염이 된다. 이러한 죽염제조기법은 개암사 주지 스님에게 전수되어 오고 있다. 현재 죽염제조 기능보유자인 효산 스님(허재근)도 개암사 주지를 지내면서, 죽염제조 기술을 전수받아 이를 더욱 연구·개발하여 효능이 뛰어난 양질의 완벽한 죽염을 제조하고 있다. 죽염은 우리 민족 고유의 민간신약으로서 역사적 전통과 독창성에 있어 그 예를 찾아볼 수 없는 독특한 것으로…","a":"죽염제조장","c":"시도무형유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644140.jpg"},{"q":"○○○ 덩굴은 한자로 용린(龍鱗)·상춘등(常春藤)·목방기(木防己)등으로 불리며 지방에 따라 경남지방에서는 장태미 또는 장드레미, 제주지방에서는 정당·정등·정동 등으로 불린다. ○○○ 덩굴의 줄기는 내구성이 강하고 탄력성이 매우 좋으며 축축한 상태에서는 잘 구부러지는 특징이 있으며 풀공예 재료중 장점이 가장 많은 재료이다. 또 줄기의 직경이 2㎜미만이므로 공예품을 만들면 그 짜임새가 섬세하고 고운 질감을 준다. 이러한 장점으로 일찍부터 우리 선조들은 ○○○덩굴로 삼태기·수저집·바구니·채반 등 생활기물을 만들어 사용하였다. 그러나 급격한 산업화의 물결속에 모든 전통 수공…","a":"홍성댕댕이장","c":"시도무형유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644019.jpg"},{"q":"나비춤은 부처님의 정법을 상징하는 무용이다. 일명 해탈무 (解脫舞)라 하며 인천의 나나니춤과 어우러져 민속무(民俗舞) 에도 영향을 준 춤으로 승속(僧俗)이 하나 되어 예술성이 한층 승화된 춤이다. 이는 자비(慈悲)의 발견과 참된 마음의 발견, 법보(法寶)의 발견을 위하여 추는 춤으로 부처님의 가르침을 받고 법열(法悅)에 도달하기 위하여 향화게(香花偈), 운심게(運心偈), 삼적의(三的依), 오공양(五供養) 등과 같은 범패(梵唄)에 맞추어 춤을 추거나 호적(胡笛), 징 등의 반주나 삼현육각(三絃六角)으로 연주하기도 한다.","a":"범패와 작법무(나비춤)","c":"시도무형유산","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010411501300.jpg"},{"q":"○○○○는 비산동 일대의 주민들이 옛날부터 신(神)으로 받들어 온 기천왕·중천왕·말천왕에게 매년 1월 초에 해오던 지신풀이를 말한다. 지신풀이는 음력 1월에 지신(地神:땅을 맡아 다스리는 신)을 진압함으로써 악귀와 잡신을 물리치고 마을의 평화와 풍년 및 가정의 다복을 축원하는 신앙적 마을행사로, 꽹과리·징·북·장구·쇠납 등의 민속악기를 선두로 소고패·양반·포수·머슴과 탈을 쓴 각시 등이 집집마다 다니며 지신풀이 노래를 부르면서 춤과 익살·재주를 부리는 것이다. 각 천왕들이 자리잡고 있는 곳에는 천왕나무와 사당 그리고 조산(造山)이 있었으며, 사당 안에는 천왕의 모습이…","a":"천왕메기","c":"시도무형유산","r":"대구광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643469.jpg"},{"q":"단청은 건물에 색을 입히는 기술이나 그 기술이 발휘된 결과를 말하며, ○○○은 단청일을 하는 장인을 일컫는다. 단청의 영역은 전통적으로 불화를 아우르는 경향이 있으며, 근래의 학습과정도 이런 인식을 뒷받침한다. 단청의 역사는 삼국시대로 거슬러 올라간다. 고구려의 담징曇徵, 백제의 백가白加, 신라의 솔거率居가 모두 사찰에 벽화를 그린 화승으로서 단청의 소임을 담당한 것으로 간주된다. 불교신앙과 특수한 권위를 지닌 사찰과 궁궐에 칠하는 단청은 건물의 수명을 늘리고 장엄을 겸할 목적으로 사용하였다. 단청을 입히는 건물 사이에도 무늬의 선택과 치장의 정도를 다르게 하여 위격…","a":"단청장","c":"시도무형유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643664.jpg"},{"q":"김광숙은 1944년에 태어나, 정형인, 최선, 박금슬로부터 무용을 사사받았으며, 특히 박금슬로부터 조선시대 관기(官妓)들이 췄던 '○○○'(교방무) 등을 전수받았다. 김광숙은 대한민국 무용제, 전국 국악경연대회 등 다수 대회에서 입상하였다. ○○○는 악가무가 특출하게 뛰어난 교방의 기녀들이 잔치판이나 놀이판에서 참석자들의 흥을 돋우기 위해 추는 일종의 놀이적 성격의 춤이다. 이 춤을 한편에서는 교방춤이라고도 하는데, ○○○를 출 정도의 기녀라면 기예능적으로 상당히 수준을 갖추어야 할 뿐만 아니라 향유자들을 쉽게 흥에 젖어들게 하는 능수능란한 재취도 함께 겸비해야 한다…","a":"예기무","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644172.jpg"},{"q":"『○○○○○』는 ○○○ 일대에 전승되어 온 ○○를 묶어 무형유산으로, 여기에는 논농사 시 부르는 노동요, 비를 기원하는 기우제 소리, 장례의식에서 부르는 의식요, 백중놀이에서 부르는 유희요 등 다양한 ○○가 총망라되어 있다. 이 ○○들은 특정 마을에서만 전승된 소리뿐 아니라 인근 마을에서 함께 전해져 내려온 소리들도 포함하고 있다. 옛날에는 모내기철에 가뭄이 들어 비가 내리지 않으면 모를 심지 못해, 마을에서는 첫 아들을 낳은 아낙네들이 키를 들고 시냇가로 나가 ‘물까부리 비나리소리’를 불렀다고 한다. 이는 천지 신명께서 비를 내려주신다는 믿음에서 비롯된 의례였다.…","a":"동두천 민요","c":"시도무형유산","r":"경기도","s":"동두천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091413485500.jpg"},{"q":"파주 지역은 경기도 서북 지역에 위치하여 인접한 황해도 문화의 영향을 받아 독특한 문화를 형성하고 있다. 파주 ○○○ 지역에는 다양한 논농사소리와 장례의식요가 전승되고 있어서 이를 묶어 ○○○○○라는 이름으로 무형유산을 지정하였다. ○○○ 지역에는 논농사소리 8종과 장례의식요 3종이 전승되고 있다. 논농사를 지을 때 모판에 볍씨를 뿌려 어느 정도 크면 이를 뽑아내어 논으로 옮겨 심게 되는데, 모판에서 모를 뽑는 작업을 ‘모를 쪘다’고 하므로 ‘쪘네’라는 후렴구가 있는 ‘쪘네소리’를 부른다. 모를 옮겨 심는 작업에는 하나 둘씩 모를 심는다는 뜻에서 ‘하나- 둘’ 숫자를…","a":"파주금산리민요","c":"시도무형유산","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018010218294000.jpg"},{"q":"한국자수는 삼국시대부터 인간의 본능에 의한 장식수단으로 나타나고 있으며, 토속적인 신앙에서 우러나온 믿음에 의한 상징으로서, 신분과 지위 등을 표시하기 위한 수단으로 발전하였다. 자수는 천과 바늘, 실, 그 밖의 재료와 용구를 사용하여 여러 가지 기법으로 아름다운 효과를 나타내는 섬유예술의 한 분야로써, 한국의 전통자수는 사실적이고 장식적인 문양과 선명한 색채, 단순한 수법을 많이 사용하고 있음이 특징이다. 기능보유자 강소애는 50여년간 전통적인 무늬와 색채기법을 연구·제작하고 있으며, 여러 차례에 걸쳐 전시회를 가진 바 있다. 특히 사라져 가는 고유의 전통자수를 온…","a":"자수장","c":"시도무형유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644148.jpg"},{"q":"소목장은 나무로 여러 가지 가구나 문방구를 전문적으로 만드는 장인이다. 조선 초 주로 왕실과 상류 계층의 수요로 ○○○ 등을 제작하였으나, 조선 후기에 들어서며 민간에 널리 보급되고 그 종류도 다양해져 지역별 특성이 현저히 나타나게 되었다. 전북특별자치도 무형유산 소목장으로 지정된 천철석 장인은 前전북특별자치도 무형유산 소목장인 고 조석진의 공방에서 소목 기술(전주장)을 전승을 받아 현재까지 전통 공예 기술을 이어나가고 있으며, 주로 느티나무와 참죽나무를 활용한 가구를 만들고 있다.","a":"목가구(소목장)(천철석)","c":"시도무형유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060915080300.jpg"},{"q":"조선시대 6진 정책으로 새 땅을 일구어내는 시기에 원주민과 각처에서 온 이주민들의 생활사를 담은 함경도의 대표적 민요이다. 혼자서 산길을 걸을 때에나 혼자 김을 맬 때에 흥얼거리며 부른다고 한다. 임과의 이별의 슬픔, 고단한 살림살이, 유랑민의 애환 들과 같이 주로 변방 사람들이 겪는 생활 주변의 이야기를 소재로 삼고 있어서 제목 그대로 애원이 깃든 노래이다. 높은 음으로 질러 내는 부분이 많아 마치 슬픔이나 시름을 한껏 토해 내는 듯한 느낌을 준다. 그러나 음의 조직이 독특해서 〈신고산타령〉이나 〈궁초 댕기〉와 같은 '라', '도', '레', '미', '솔'이 아니…","a":"애원성","c":"이북5도 무형유산","r":"함경북도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669648.jpg"},{"q":"○○○은 화문석을 만드는 기술과 그 기능을 가진 사람을 말한다. 화문석이란 염색을 한 왕골을 손으로 엮어 무늬에 따라 잘라낸 돗자리를 말한다. 화문석은 겉이 매끄럽고 시원해 주로 여름에 사용했으며, 찬기운을 막아주고 보온성이 있어 겨울에도 사용했다. 신라에 이미 화문석의 생산을 담당하는 관청이 있었고, 고려시대에 들어와서는 외국에까지 널리 알려져 중국 요나라에 용무늬를 넣은 화문석을 특산품으로 보내기도 하였다. 조선시대에 이르러 화문석의 수요는 더욱 늘어났다. 화문석을 만드는 과정은 먼저 왕골을 3, 4일 동안 바짝 말린다. 하얗게 바래서 윤기가 나면 하루쯤 물에 담…","a":"초고장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643393.jpg"},{"q":"충청남도 ○○시 ○○면 일원에서 집을 지으면서 했던 노동과 제의, 놀이 성격이 결합된 민속 문화로 ○○○○○는 유래나 형성 과정을 정확히 알 수 없지만, 주춧돌을 놓는 건축문화와 함께 시작되었을 것으로 보인다. 이러한 ○○○○○는 ○○면에서 1970년대 중반까지 전승되다가 시멘트 구조물이나 벽돌을 사용하게 되면서 자연스럽게 소멸되었다. 이후 ○○○○○는 1985년에 채록되었으며, 10여년이 흐른 1999년에 드디어 재현하게 되었다. 2008년 전국민속예술경연대회에 참가하여 은상을 수상하였고 2013년에는 이러한 의미와 가치를 인정받아 충청남도 무형유산으로 지정되었다.","a":"공주 의당 집터다지기","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026022315202900.JPG"},{"q":"○○○○○는 ○○군 현남면 화상천을 중심으로 형성된 입암리, 상월천리 등 6개 마을에서 오래전부터 전승되어 내려오는 ○○○○다. 가락과 사설이 잘 보존되어 있을 뿐만 아니라, 현재까지 상두계가 조직되어 장례절차를 제대로 지키면서 「옥산가, 회심곡」 등 다양한 소리를 보존 전승하고 있다.","a":"양양 수동골상여소리","c":"시도무형유산","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643842.jpg"},{"q":"○○○은 익산시 ○○면의 주산인 천호산(天壺山) 주변에 거주하는 사람들에 의해서 빚어지는 술이었기에 ○○○이라고 지칭하게 되었으며, 시조시인 가람 이병기의 25대 조부인 이현려(1136~1216)가 지다방사(고려시대 궁중의 살림·특히 임금의 음식관리)로 있으면서 궁중에서 궁중에서 빚어지던 술이라하여 궁중주라고도 불리었다. ○○○은 음식 관련 산림경제·양주방·임원경제십육지 등 16개 고문헌에 전부 소개되어 있으며, 조선시대 이규경(1788~1863)이 쓴 백과사전 형식의 책인 오주연문장전산고에 조선의 4대 명주로 ○○○을 극찬한 바 있다. 1943년 전북 익산에서 태어…","a":"여산 호산춘","c":"시도무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060810261302.jpg"},{"q":"○○는 한국의 전통적 해양문화와 여성 어로문화를 대표하는 산 증인이다. 시대적 변천을 넘어 ○○는 공동체 문화를 만들어 왔으며, ○○의 생업과 문화에는 자연과 인간의 공존 및 공유지의 지속적인 이용과 분배에 관한 여러 가지 지혜들을 발견할 수 있다. ○○에 관한 기록은 17세기 제주도 관련 기록에서 보이듯이 오랜 역사를 가지고 있고, ○○들의 ‘물질’은 원초적인 어로 형태로 다른데서는 찾아볼 수 없는 우리나라 전통적인 어로법이다. 또한, 물질경험에서 축적된 생태환경에 대한 민속지식이 상당하고 동료○○에 대한 배려와 협업, ○○들의 신앙과 의례 등 ○○만의 독특한 공동…","a":"해녀","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2017060510162500.png"},{"q":"떡은 곡식가루를 시루에 안쳐 찌거나, 쪄서 치거나, 물에 삶거나, 혹은 기름에 지져서 굽거나, 빚어서 찌는 음식으로, 우리나라에서는 예로부터 일생의례(백일·돌·혼례·상장례·제례)를 비롯하여 주요 절기 및 명절(설날·정월대보름·단오·추석) 등에 다양한 떡을 만들고 나누어 먹는다. 또한 떡은 마을신앙 의례, 가정신앙 의례, 각종 굿 의례에 사용되는 대표적인 제물(祭物)일 뿐만 아니라 오늘날에도 개업떡·이사떡 등을 만들어서 이웃 간에 나누는 문화가 지속적으로 유지·전승되고 있다. 이처럼 떡은 한국인이 일생동안 거치는 각종 의례와 행사 때마다 만들어서 사회구성원들과 함께 나…","a":"떡 만들기","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2021110115502400.jpg"},{"q":"○○○○는 진도지방에서 초상이 났을 때, 특히 타고난 수명을 다 누리며 행복하게 살다 죽은 사람의 초상일 경우 동네 상여꾼들이 상제를 위로하고 죽은 자의 극락왕생을 축원하기 위해 전문예능인들을 불러 함께 밤을 지새우면서 노는 민속극적 성격이 짙은 상여놀이이다. 놀이의 정확한 유래는 알 수 없으나 고구려의 옛 무덤에서 보여지는 벽화와 고구려·신라의 역사를 기록한 사서를 통해 오랜 옛날부터 장례에서 가무가 행해졌음을 알 수 있다. ○○○○○는 다섯마당으로 이루어져 있다. 첫째마당은 가상제놀이로 가짜 상제가 나와 상여꾼들과 농담을 주고 받는다. 둘째마당은 봉사인 거사와 사…","a":"진도다시래기","c":"국가무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623912.jpg"},{"q":"배첩이란 글씨나 그림에 종이, 비단 등을 붙여 족자·액자·병풍 등을 만들어서 아름다움은 물론 실용성 및 보존성을 높여주는 전통적인 서화처리법을 가리키며, 일제강점기에 들어온 말로 오늘날에는 “표구(表具)”라고도 한다. 배첩장은 조선 전기에 회화를 담당하던 국가기관인 도화서 소속으로 궁중의 서화처리를 전담하던 사람을 말한다. 배첩은 통일신라와 고려를 거쳐 발전하였으며, 조선시대에는 배첩장이라는 전문가가 등장할 만큼 성황을 이루었다. 배첩의 제작기법과 형태는 액자·병풍·족자·장정 및 고서화 처리의 다섯 가지이다. 액자는 비단 재단 ―그림 초배(初褙) ―재배(再褙) ―건조…","a":"전주배첩장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093016092600.jpg"},{"q":"단오는 음력 5월 5일로 ‘높은 날’ 또는 ‘신 날’이란 뜻의 수릿날이라고도 한다. ○○○○○는 우리나라에서 가장 역사가 깊은 축제로, 마을을 지켜주는 대관령 산신을 제사하고, 마을의 평안과 농사의 번영, 집안의 태평을 기원한다. ○○○○○가 언제부터 시작되었는지는 정확히 알 수 없으나, 매년 3, 4, 5월 중 무당들이 산신에게 제사를 지내고 3일동안 굿을 벌였다는 남효온(南孝溫)의 문집(『추강냉화(秋江冷話)』) 기록과, 1603년(선조 36년)에 ○○○○○를 구경하였다고 기록한 허균(許筠)의 문집(『성소부부고(惺所覆瓿藁)』) 등이 있다. 마을사람들은 단오제를 드리…","a":"강릉단오제","c":"국가무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623631.jpg"},{"q":"소반(小盤)이란 음식을 담은 그릇을 올려 놓는 작은 상으로, 한국의 식생활에서 부터 제사의례에 이르기까지 여러 용도로 쓰이는 부엌가구이다. 소반을 만드는 기술 또는 그 장인(匠人)을 ○○○이라 한다. 고구려 각저총·무용총 등의 고분벽화에는 여러 유형의 소반이 나타나고 있으며, 『삼국사기(三國史記)』, 『별사 (別賜)』, 『경국대전 (經國大典)』등의 기록에 의하면 국가에 소속된 상을 만드는 기관이 분업화되어 생산을 담당하였던 것을 알 수 있다. 조선시대에는 유교이념의 영향으로 겸상보다는 독상이 주로 사용되었고, 제례·혼례 등 크고 작은 많은 행사들로 인하여 여러 용도의…","a":"소반장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623353.jpg"},{"q":"용암 ○○○○는 세종특별자치시 연서면 용암리 마을에서 매년 음력 1월 16일에 행해지는 민속놀이이다. 용암은 용암리의 지명을 딴 것이며, ○○○○는 세종특별자치시 일대에서 사용되던 줄○○○의 방언이다. ○○○○○의 기원은 임진왜란 때 비암사의 승려들이 왜군들과의 전투에서 참패하고 절과 마을이 파괴되자 힘을 키우기 위한 방법으로 시작되었다는 전설이 있지만 뒷받침할 사료나 기록이 없어 명확하지 않다. ○○○○○는 마을의 안녕과 풍요를 기원하는 의식으로서의 성격을 포함한다. ○○○○는 남성과 여성으로 편을 갈라 진행하는데 결혼하지 않은 남자는 여성의 편으로 한다. 줄을 매…","a":"용암강다리기","c":"시도무형유산","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023050111333000.JPG"},{"q":"○○○○은 조선중기 이래로 굿판 등에서 나쁜 기운을 푸는 춤에서 비롯된 춤으로, 전통춤의 특징인 정중동(靜中動)·동중정(動中靜)의 미가 극치를 이루는 춤이다.","a":"살풀이춤","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101116083200.JPG"},{"q":"공연 형태를 갖춘 검무는 삼국시대 신라의 황창랑 설화에 기인한 것으로 기록에 나타난다. 이는 가면을 쓴 동자가 춤을 추는 형식으로, 조선시대 초까지 처용 무와 함께 공연됐다. 조선 숙종 이후로 가면을 벗고 여기검무女妓劍舞가 등장했다. 여기검무는 정조 때 궁중정재宮中呈才로 정착되면서 궁중연향의 성격에 맞도록 연행 규모가 커졌다. 의상도 화려해지고 참여하는 여기의 숫자도 많아졌다. 조선후기 각종 연향의 공연 종목으로 자리매김하면서 예술적으로 한층 다듬어지고 세련되어진 여기검무는 궁중연향에 참가했던 각 지방 교방의 기녀들에 의해 전국적으로 전파되면서 지방마다의 독특한 특색…","a":"경기검무","c":"시도무형유산","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091413430500.jpg"},{"q":"겨리란 두 마리 소가 끄는 쟁기를 뜻하는 것으로 중북부 산간지역에서 주로 행해진 논밭갈이 방식이다. 1970년대 농기계 보급으로 급속히 사라져갔으나 ○○군은 경사가 급한 지형상 특성으로 비교적 오랫동안 남아 있었다. 산간 지역은 토질이 척박하고 일조량이 적어 빠른 시간 안에 갈이와 파종을 끝내야 하고 땅을 깊이 갈아야하기 때문에 견인력이 큰 겨리가 효율적이었다. 두 마리 소가 서로 보조를 맞추어 나아갈 수 있도록 해야 하기 때문에 소와 쟁기질꾼 사이의 의사소통이 매우 중요하였고 이 과정에서 소모는 소리를 비롯한 독특한 ○○○○○가 형성되었다. ○○○○○는 두 마리 소…","a":"홍천 겨리농경문화","c":"시도무형유산","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023052415261000.jpg"},{"q":"○○○는 쌀 등의 곡물과 누룩, 물로 빚는 우리 고유의 술로서 삼국시대 이전 농경이 이루어진 시기부터 빚었을 것으로 추정된다. 고려시대 선비의 문집(文集) 등에서‘○○○’로 추측되는 기록이 확인되며, 조선시대‘규합총서’,‘음식디미방’등의 조리서류에서 ○○○의 제조 방법을 구체적으로 확인할 수 있다. 또한 당대 한글 소설 등에서 ○○○의 한글 표현이 확인된다. ○○○는 물과 쌀, 누룩만 있으면 누구나 쉽게 만들 수 있는 것이 가장 큰 특징이다. 이로 인해 많은 사람이 쉽게 접할 수 있었고, 서민의 애환을 달래주는 술의 대명사가 되었다. 농사꾼들 사이에서는 “같은 품삯을…","a":"막걸리 빚기","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2021061613311700.jpg"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 경남농악의 한 종류인 ○○○○○은 마을 사람들이 마을 앞의 큰나무를 성황나무로 정하여 해마다 9월 그믐과 상월(上月) 초하루에 제사를 지내고 마을의 평화와 풍년을 기원하며, 농악을 울린데서 비롯되었다. 농악은 상쇠의 가락에 맞추어 모두 세로 1줄로 행진하다가 원형으로 도는 길굿·살풀이가락에 맞추어 3개의 원을 만들며 춤추는 살풀이굿·덧뵈기가락에 따라 각각의 원끼리 노는 덧뵈기굿·3개의 원을 만든 상태에서 영산다드래기가 각을 치는 영산다드래…","a":"함안 화천농악","c":"시도무형유산","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644470.jpg"},{"q":"○○○는 소리꾼 한 명이 고수(북치는 사람)의 장단을 맞추어 창(소리), 말(아니리), 몸짓(너름새)을 섞어가며 긴 이야기를 엮어가는 것을 말한다. ○○○는 순조(재위 1800∼1834) 무렵부터 ○○○ 8명창이라 하여 권삼득, 송흥록, 모흥갑, 염계필, 고수관, 신만엽 등이 유명하였는데 이들에 의해 장단과 곡조가 오늘날과 같이 발전하였고, 동편제(전라도 동북지역), 서편제(전라도 서남지역), 중고제(경기도·충청도) 등 지역에 따라 나뉘어 졌다. 이 중 동편제는 송흥록을 시조로 송광록, 박만순, 송우룡, 송만갑, 유성준으로 전해지는 소리가 큰 줄기를 이루었다. 동편제…","a":"판소리","c":"시도무형유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020061908243600.jpg"},{"q":"○○○이란 불에 달군 인두를 대나무에 지져가면서 장식적인 그림이나 글씨를 새기는 기능 또는 그 기술을 가진 사람을 말한다. 우리나라에서는 매우 드문 기술이었으나 조선 순조(재위 1800∼1834)때 박창규에 의해 일제강점기까지 전승되었다. 낙죽은 온도를 맞추어 그려야 하고 인두가 식기 전에 한 무늬나 글씨를 마무리지어야 하기 때문에 작업 경험과 속력을 필요로 하는데, 주로 화살대·침통·칼자루·병풍·담뱃대·부채·대나무필통 등에 쓰인다. 낙죽은 접는 부채의 맨 처음과 마지막에 쓰이는 두꺼운 대나무(합죽선)살에 가장 많이 쓰인다. 합죽선에는 나비무늬를 많이 사용하지만 간혹…","a":"낙죽장","c":"국가무형유산","r":"경상남도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623838.jpg"},{"q":"징은 타악기의 하나로 금정(金鉦) 또는 단순히 금(金)이라고도 한다. 중국 고대로부터 널리 쓰여 온 악기로 우리나라에는 고려 공민왕(재위 1351∼1374) 때 중국 명나라로부터 들여와 군대의 악기로 사용했고, 또 종묘악·무악·법악·농악에도 널리 사용하였다. 징은 구리 160, 상납 43의 무게비율로 녹여 만드는데 대정, 가질대정, 앞매꾼, 전매꾼, 센매꾼, 풀무꾼이 한 조가 되어 제작을 한다. 제작과정은 놋쇠녹임, 늘품질, 도둠질, 냄질, 싸개질, 달금질, 울음잡기, 가질, 재울음의 순인데 재울음은 망치질 한번으로도 완전히 다른 소리가 나는 예민한 작업이다. 징의…","a":"김천징장","c":"시도무형유산","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644312.jpg"},{"q":"농요는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로 ‘들노래’ 또는 ‘농사짓기소리’라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며 지방에 따라서 달라질 수 있다. ○○○○는 노동요로서 먼저 선소리꾼이 노래를 부르면 농부들이 받아서 뒷소리를 받아 부르는 문답창(問答唱) 형식이다. 내용은 어사용(나무꾼노래)·망깨노래·도리깨·타작노래·모찌기노래·모심기노래·논매기노래·벼베기노래 등으로 되어 있다. 어사용노래는 나무를 베거나 풀벨 때 부르는 노래이고, 모찌기는 모를 찌으면서, 모심기는 모를 심을 때 부르는 노래이다. 논매기는 논을 매면…","a":"공산농요","c":"시도무형유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643475.jpg"},{"q":"○○○○○는 가야금으로 연주하도록 짜여진 산조를 가리킨다. 산조란 악기를 혼자서 연주하는 형식을 말하며, 느린 장단으로 시작하여 차츰 빠른 장단으로 바뀌는데, 이는 듣는 사람을 서서히 긴장시키면서 흥겨움을 끌어올리게 한다. ○○○○○는 4∼6개의 장단으로 짜여진다. 각 장단의 느낌을 살펴보면 진양조는 아주 느려서 서정적이고, 중모리는 안정적이며, 중중모리는 흥취를 돋운다. 자진모리는 밝고 경쾌하고, 휘모리는 흥분과 급박감이 있다. 다른 악기로 연주하는 산조보다 먼저 만들어졌으며, 뛰어난 기교로 인해 사람들의 관심을 많이 끌어서 여러 유파가 형성되었다. 강태홍류 ○○○…","a":"가야금산조(강태홍류)","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643425.jpg"},{"q":"침선이란 바느질로 옷과 장신구를 만드는 기술을 말하며 그 기술을 가진 사람을 ○○○이라 한다. 사람이 바느질을 시작한 것은 역사시대 이전부터였다고 한다. 지금의 바늘과 흡사한 신라시대 금속제가 발견되었으며, 고구려 고분벽화나『삼국사기』를 통해 볼때 삼국시대부터 이미 상당한 수준의 침선이 발달했음을 알 수 있다. 침선은 고려시대와 조선시대로 이어지면서 더욱 발달하여 오늘날까지 전승되고 있다. 침선에 필요한 용구로는 옷감, 바늘, 실, 실패, 골무, 가위, 자, 인두, 인두판, 다리미, 다리미판, 못바늘 등이다. 옷감으로는 주로 비단, 무명, 모시, 마 등이 쓰인다. 실…","a":"침선장","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623328.jpg"},{"q":"안 곤은 어려서부터 배호진, 최창한 선생에게 옻칠을 사사 받았고, ○○○ 양성에 노력하고 있으며 특히 생칠 기능 보유자이다. 남원시 조산동에 소재하고 있는 정일품공예사를 20여년 동안 운영해 오면서 옻칠 발전을 위한 꾸준한 연구 및 작품 활동과 더불어 후진 양성에 심혈을 기울이고 있다.","a":"옻칠장(옻칠)(안곤)","c":"시도무형유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023070719481900.JPG"},{"q":"목가구의 결합부분을 보강하고 열고 닫을 수 잇는 자물쇠 등의 금속제 장식을 장석이라고 하며, 구리와 주석을 함금한 황동(놋쇠) 장석을 만드는 장인을 ○○○이라 부른다. 장석의 재료로는 황동과 백동을 사용하며, 보다 사치스러운 장석으로 꾸미기 위해서는 백동을 쓴다. 주석이나 백동을 넣어 가열해 녹이고 이것을 망치로 두들겨 0.5㎜두께의 판철로 늘이고 면을 반듯하게 다듬는다. 여기에 본을 따라 작도와 정으로 오리고 줄로 다듬고 활비비와 정으로 문양을 새긴 뒤 사기분말을 묻힌 천으로 문질러 광택을 내 완성한다. 장석의 종류로는 장석을 붙이는 물건에 따라 농장석, 궤장석,…","a":"두석장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624353.jpg"},{"q":"○○○○○ Jeonbuk Kyorugi Taekwondo(Jeonbuk Sparring Taekwondo) ○○○○○는 1947년 이후 대한민국 ○○특별자치도 지역에서 형성·발전한 ○○○ 중심의 ○○○ 수련 문화이다. ○○○는 두 사람이 마주하여 공격과 방어의 기술을 주고받는 대련 형식의 수련방식으로, ○○○의 핵심 구성 요소로서 신체 기술과 규범을 통합적으로 습득하는 과정이다. 이 유산은 전일섭에 의해 군산에서 시작되어 전주를 중심으로 ○○특별자치도 전역으로 확산되었으며, 한국전쟁 이후 지역 공동체 속에서 지속적으로 전승되었다. 특히 1960~70년대 전국체육대회…","a":"전북 겨루기 태권도","c":"시도무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026032609484700.jpg"},{"q":"판소리, 가곡과 함께 우리나라 삼대 성악곡 중의 하나인 범패는 불교음악으로 죽은 사람을 극락으로 보내는 천도의식에서 부르는 의식음악이다. 넓은 의미의 범패에는 소리 이외에 춤이 포함되는데, 이때의 춤을 가리켜 작법이라 한다. 작법은 재(명복을 빌기 위하여 드리는 불공)에서만 볼 수 있는 독특한 불교무용으로 나비춤, 바라춤, 법고춤 세 종류로 나눌 수 있으며, 전북지역에서는 나비춤을 어산춤이라 부른다. ○○○○은 전북지역의 문화예술적인 특성을 지니고 있어 서울지역의 작법과는 차이를 보이는데 서울지역에서는 향화계를 주로 행하는데 반해 전북지역에서는 운심계를 주로 행한다.…","a":"영산작법","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644123.jpg"},{"q":"○○○은 시조시(우리나라 고유의 정형시)를 가사로 노래부르는 것을 말하며, 시절가, 시절단가, 단가라고도 한다. 고려 후기부터 시작되었을 것으로 추측되지만 가장 오래된 기록을 보면, 영조(재위 1724∼1776) 때 학자 신광수의『석북집』「관서악부」에 이세춘이 시조에 장단을 붙였다는 시가 나온다. 순조(재위 1800∼1834) 때 간행된『유예지』에서는 경제(京制) 평시조 악보가 처음으로 나타난다. ○○○은 가곡의 영향을 받아 시조곡조가 발생·보급됨에 따라 서울·경기 지역의 경제(京制), 전라도의 완제(完制), 경상도의 영제(嶺制), 충청도의 내포제(內浦制)로 지역적…","a":"시조창","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644118.jpg"},{"q":"○○○○는 마산·창원지방에서 전래해 온 백중(음력 7월 15일) 놀이로서, 근원은 마을의 공동작업을 하기 위한 조직인 두레에서 찾을 수 있다. 창원의 어복골에 상투바위가 신령스럽다 하여 상투바위 앞자리를 먼저 차지하여 축원하면 큰 덕을 얻는다는 믿음에서 유래되었다고 한다. ○○○○는 기제, 쟁기전, 축원, 흥취와 회향으로 나눌 수 있다. 상투바위로 떠나기 전에 제사를 올리는데, 길이 8m나 되는 깃발을 세우고 간단한 제물로 고유제를 지냄으로써 기세를 올리고는 상투바위로 향한다. 장정들이 호위하는 깃발을 중심으로 풍물을 울리며 행진하다가 다른 농청을 만나면 기싸움을 벌…","a":"마산농청놀이","c":"시도무형유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644444.jpg"},{"q":"○○○○○는 경기도 양주군 주내면 유양리 지역에서 전승되는 ○○○○ 계통의 탈놀이다. 고려~조선 후기까지 전승되던 산대잡희(山臺雜戱)가 민간화되어 예인집단을 중심으로 서울에 본산대가 형성되었고, 양주에 전승된 것이다. 이 놀이는 중부지방의 탈춤을 대표하는 놀이로서 해서지역 탈춤과 함께 한국 가면극 중 연극적인 볼거리가 풍부한 가면극이다. 이 놀이는 제1과장 상좌 춤, 제2과장 옴중과 상좌, 제3과장 목중과 옴중, 제4과장 연잎과 눈끔적이, 제5과장 팔목중놀이, 제6과장 노장, 제7과장 샌님, 제8과장 신할아비와 미얄할미 등 전체 8개 과장으로 구성되어 있다. 놀이에는…","a":"양주별산대놀이","c":"국가무형유산","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623538.jpg"},{"q":"정문길은 1958년부터 부친으로부터 기와제작의 기능을 전수받아 전통기와의 맥을 잇고 있고, 영주 부석사와 ○○ 불국사, 양산 통도사 등의 불교사찰과 안동 도산서원과 하회마을 고택 등 유적의 문화유산 보수에 기여하였다. 정문길은 전통 기와가마를 복원하겠다는 의지를 가지고 노력한 결과 2017년 6월에 전국에서 유일하게 전통 기와가마를 축조하였으며, 향후 전통가마에서 전통기와를 소성하고자 실험과 노력을 거듭하고 있다.","a":"경주 와장","c":"시도무형유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020030210270800.jpg"},{"q":"바탕에 아무런 장식을 하지 않은 단색의 기물은 단정하고 깔끔한 느낌을 주지만, 밋밋하고 지루하다. 인류는 지각이 발달하면서 민무늬의 바탕에 무언가를 표현하고 그것에 상징적 의미를 부여하고자 했다. 그래서 문양이 탄생하였고, 인류는 다양한 재료에 장식적, 상징적 목적으로 문양이나 도상을 그리거나 새기고, 색감을 더했다. 금속 재질에는 그림을 그리거나 색깔을 칠하기 어렵다. 그래서 끌을 이용하여 점, 선, 면을 새긴 다음, 그래서 생긴 홈에 금은의 실이나 판을 박아 넣어 문양이나 도상을 표현했다. 이를 입사공예入絲工藝 라 부르고, 그 장인을 ○○○이라 한다. 입사공예는…","a":"입사장","c":"시도무형유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643639.jpg"},{"q":"만구대택굿은 옹진, 해주, 연백, 재령, 안악 등을 중심으로 황해도 전 지역에서 널리 행해져 온 큰 굿이다. 이 굿은 만물이 생성하는 봄이나 햇곡식을 거두는 가을에 신령님을 대접하기 위해 치러지는 무속적 의례로서, 신령의 영험력을 얻어 만 인간들의 구설수를 막고 크게는 국가의 안전과 발전을 도모하게 된다. 만구대택굿은 종교 신앙 목적의 감사제 형태로 발전된 것이며, 역사적 유래는 적어도 고대시대까지 거슬러 올라간다. 고대사회에서 하느님께 감사의 뜻으로 베풀어졌던 부여의 영고(迎鼓), 고구려의 동맹, 예(濊)의 무천, 진한의 소도 등의 제천의식에서 그 뿌리를 찾을 수가…","a":"만구대탁굿","c":"이북5도 무형유산","r":"황해도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2716897.jpg"},{"q":"○○○○○란 불자들이 살아 있는 동안 ‘미리(豫) 닦는(修) 재(齋)’ 의식으로 단순한 의식이 아니라 스스로를 위한 수행이다. 우리나라의 ○○○○○는 시왕신앙이 활발하였던 고려시대부터 시작되어 조선중기에 성행하였다. 그러나 현존하는 문헌에서 최초로 기록되어 있는 것은 조선후기의 『동국세시기』(東國歲時記)이다. ‘경기도 광주 봉은사에서는 윤달이 되면 장안의 부녀자들이 몰려들어 많은 돈을 불단에 놓고 불공을 드린다. 이 같은 행사는 달이 다가도록 계속된다. 이렇게 하면 죽어서 극락으로 간다고 믿어 사방의 노파들이 와서 정성을 다해 불공을 드린다. 서울과 그 밖의 다른 지…","a":"생전예수재","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060715250700.jpg"},{"q":"춘포란 명주실과 모시를 사용하여 짠 옷감을 말하는 것이다. 청양의 ○○○○의 연원은 조선 후기까지 거슬러 올라가며 1940년경부터 청양의 춘포시장은 전국적으로 유명했다. 청양 중에서도 운곡지방은 집집마다 ○○○○를 전문으로 할 정도였다고 한다. 춘포의 제작 방법은 누에고치에서 직접 실(명주)을 뽑아 얼레에 감고 날틀에 걸어 치자물을 들이고 베틀에 도토마리(베틀을 짤 때 날을 감는 틀)를 올려놓고 잉아(베틀의 날실을 한칸씩 걸어서 끌어 올리도록 맨 굵은 실)를 걸어 명주실과 모시로 옷감을 짜는 것이다. ○○○○ 기능보유자인 백순기씨는 초대 기능보유자인 시어머니 양이석씨…","a":"청양춘포짜기","c":"시도무형유산","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644001.jpg"},{"q":"평안북도「○○○○○」는 지역성을 가지고 전승되어 온 마을 굿으로 1980년 한국민속종합조사에서도 확인된 평안북도의 고유한 민속의례이다. 「○○○○○」의 재단은 북당과 남당이 있어 북부동, 남부동의 수호신으로 숭앙되었는데 북당에는 시장상인들이 중심이 되어 장터계를 조직하여 경비를 부담하고 일부는 읍민으로 부터의 기부로 충당할 수 있어 남당보다 북당의 세가 우세하였다.1972년 전국민속경연대회에 참가하여 세간의 많은 사람들로부터 찬사를 받았다.","a":"영변성황대제","c":"이북5도 무형유산","r":"평안북도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669658.jpg"},{"q":"○○○○○는 전남 ○○○의 어민들이 고기를 잡으며 부르는 노동요이다. 반주악기는 북, 꽹과리, 장구 등이며, 선소리꾼이 소리를 메기면 다른 뱃사람들이 뒷소리를 받는 형태로 노래한다. 작업에 따라 노래가 달라서 여러 종류의 ○○○가 있다. 그 종류에는 배에서 쓰는 밧줄을 꼬면서 부르는 세마치장단의 술비소리, 배가 떠나기 전 용왕에게 풍요를 기원하며 부르는 자진모리장단의 고사소리, 노를 저어가면서 부르는 늦은 자진모리장단의 놋소리, 그물을 당길 때 부르는 월래소리, 고기를 퍼 올릴 때 부르는 세마치장단의 가래소리, 배가 가득 차서 돌아올 때 부르는 썰소리가 있다. 순박하…","a":"거문도뱃노래","c":"시도무형유산","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644173.jpg"},{"q":"○○○○○는 해변가에서 멸치잡이 후리질을 하면서 부르는 노동요로서 작업의 순서에 따라 그 동작이 함께 곁들여진다. 토속민요의 하나로 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수도 있다. ○○○○○는 한 사람이 노래를 부르면 다른 여러 사람이 그 노래를 받아 부르는 선후창(先後唱)형식이다. 내용은 그물을 어장으로 옮겨 배에 실으면서 부르는 그물을 배에 싣는 소리, 용왕고사(제사)를 지내며 풍어를 기원하는 용왕제, 고깃배의 노를 저으면서 부르는 노젓는 소리, 어부들이 양쪽에서 벼릿줄(그물)을 당기면서 부르는 ○○○○, 후리질을 하며 그물을 쪼으면서 부르…","a":"다대포후리소리","c":"시도무형유산","r":"부산광역시","s":"사하구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643419.jpg"},{"q":"「○○」은 두 사람이 샅바를 맞잡고 힘과 기술을 이용해 상대를 넘어뜨려 승부를 겨루는 경기로서, 한민족 특유의 공동체 문화를 바탕으로 유구한 역사를 거쳐 현재까지 전승되어 온 민속놀이이다. 「○○」은 한국을 대표하는 세시풍속 놀이로서, ▲다양한 놀이의 형태가 오늘날까지 온 국민에 의해 활발히 전승되고 있다는 점, ▲고대 삼국 시대부터 근대 시대에 이르기까지 각종 유물, 문헌, 회화 등에서 명확한 역사성이 확인된다는 점, ▲○○판의 구성과 기술 방식 등에서 우리나라만의 고유성과 표현미가 확연히 드러난다는 점, ▲한국 전통놀이의 속성을 이해하는 데 중요한 연구대상이라는…","a":"씨름","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2017010410482800.jpg"},{"q":"○○○이란 건물의 문, 창문이라든가 장롱, 궤, 경대, 책상, 문갑 등 목가구를 제작하는 기술과 그 기술을 가진 목수를 말하는 것으로 건축을 주로 하는 대목장(大木匠)에 대칭되는 말이다. 기록상으로 보면 목수는 신라시대부터 있었고, ○○○이라는 명칭은 고려시대부터 불리웠다. 조선 전기까지는 목가구가 주로 왕실과 상류계층을 위해 만들어졌으나, 조선 후기에는 민간에 널리 보급되어 자급자족에 따른 지역적 특성이 나타나게 되었다. ○○○ 기능보유자 조찬형씨는 안건사 가구공장에 발을 들여놓은 후 크고 작은 30여 건의 공사를 맡으면서 10여 년에 걸쳐 솜씨를 다듬었다. 전통적…","a":"소목장","c":"시도무형유산","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643991.jpg"},{"q":"'○○○'이란 지붕의 기와를 잇는 장인을 말한다. 우리나라에서 언제부터 기와를 사용했는지 정확히 알 수 없지만 출토유물로 보아 삼국시대부터 본격적으로 사용되었던 것으로 추정된다. 따라서 이 시기부터 번와와공이 시작되었다고 할 수 있다. 이후 삼국시대의 기와기술은 더욱 발달하여 기록에 의하면 ‘와박사(瓦博士)’라는 장인이 있었고, 이들은 일본에 건너가 기와기술을 전해주기도 하였다고 한다. 조선시대에는 태조 원년(1392)에 ‘와서(瓦署)’를 설치하여 기와를 생산하도록 하였으며, 태종 6년(1406)에는 ‘별와요(別瓦窯)'에서 기와를 보급하도록 하였다. 별와요에는 와장을…","a":"번와장","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623408.jpg"},{"q":"○○○○○는 정월 대보름날 달이 떠오를 때 솔가지 등을 쌓아올린 무더기에 불을 지르며 노는 세시풍속의 하나이다. 액막이 풍습이자 풍년을 기원하는 제례의 일종으로 남부의 산악지방에서 널리 행하고 있으며, 중국·일본 등지에서도 널리 분포하는 민속놀이라는 점을 생각할 때 그 역사는 매우 오래된 것으로 보인다. 승주 ○○○○○는 순천시 월등면 송천리 송산마을에 전승되고 있으며, 여러모로 다른 지역과 구별되는 특징을 지니고 있다. 농악소리가 울려 퍼지면 마을 사람들은 지게를 지고 대나무와 솔가지를 베러 가는데 일부는 이웃 마을 달집을 부수고 대나무를 빼앗아 오기도 한다. 마을…","a":"송천달집태우기","c":"시도무형유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644222.jpg"},{"q":"도자기(陶瓷器)는 도기와 자기를 합쳐서 부르는 용어이다. 도기란 도토(陶土)를 가지고 도공(陶工)이 원하는 형태를 만들어 도기가마에서 구워낸 그릇을 말하는 것으로 흔히 질그릇이라고 불리며, 자기란 자토(瓷土)를 가지고 사기장(沙器匠)이 원하는 형태를 만들어 자기가마에서 구워낸 그릇을 말하는 것으로 흔히 사기그릇이라고 한다. 옹기는 이 가운데 도기에 속한다. 「○○○」이란 독과 항아리 등을 만드는 장인을 가리킨다. 옹기는 흙을 채취해서 가공한 후 원하는 형태로 성형하여 시유·건조하고, 가마에 쌓아서 불에 굽는 것으로 마무리된다. 이러한 전반적인 제작과정은 어느 지역이나…","a":"옹기장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623938.jpg"},{"q":"○○○이란 여러 가지 흙을 혼합하여 1,300℃이상의 높은 온도에서 사기그릇을 구워내는 기능을 가진 사람을 말한다. ○○○ 보유자였던 故 김윤태는 문경사람으로, 문경은 도자기의 원료가 되는 적토, 백토, 사질점토, 도석 등이 널리 분포되어 있고 계곡의 물이 좋아 1700년경 영․정조시대의 공장안 폐지에 따라 문경새재를 넘어온 장인들이 정착하면서 처음으로 가마가 만들어졌으며, 찻잔과 반상기를 주로 제작하였다. 문경의 갈전요(葛田窯)는 김윤태의 조부가 운영했던 가마로 해방 후 한국전쟁기까지 몇 년의 공백이 있었으나 김윤태의 숙부 김종성이 계승하였다. 우리나라의 전통적인…","a":"사기장","c":"시도무형유산","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643439.jpg"},{"q":"화각(華角)은 쇠뿔을 얇게 갈아 투명하게 만든 판을 말하며, 이것을 이용해서 공예품을 만드는 사람을 ○○○이라 한다. 화각공예는 재료가 귀하고 공정이 까다로와서 생산이 많지 않았으므로 특수 귀족층들의 기호품이나 애장품에 주로 이용되었다. 화각공예가 언제부터 만들어졌는지 정확하게는 알 수 없다. 고려시대 나전칠기인 경함(經函)과 염주합(念珠盒)에는 복채기법으로 된 대모(玳瑁)가 나전과 같이 사용되었고, 이러한 기법은 조선 전기와 중기의 나전에까지 이어졌으나 조선 중기 이후부터는 화각으로만 장식한 화각공예품이 발달하였다. 화각공예는 투명도가 높은 쇠뿔을 종잇장처럼 얇게…","a":"화각장","c":"국가무형유산","r":"인천광역시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623511.jpg"},{"q":"○○○○○은 죽은 이의 영혼이 이승에서 풀지 못한 원한을 풀고서 즐겁고 편안한 세계로 갈 수 있도록 기원하는 진도지역의 굿으로, 원한을 씻어준다해서 씻김굿이라 한다. 씻김굿은 불교적인 성격이 강하기 때문에 고려시대에 만들어진 것으로 보이며, 시간과 장소에 따라 굿의 내용이 다르다. 초상이 났을 때 시체 옆에서 직접하는 곽머리씻김굿과 죽은지 1년 되는 날 밤에 하는 '소상씻김굿', 죽은지 2년 되는 날 밤에 하는 '대상씻김굿', 집안에 병자가 있거나 좋지 않은 일들이 자주 일어날 때 벌이는 '날받이씻김굿', 임시로 무덤을 만든 후 묘를 만들 때(초분이장 때) 하는 씻김…","a":"진도씻김굿","c":"국가무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623900.jpg"},{"q":"단청이란 청색, 적색, 황색, 백색, 흑색 등 다섯가지 색을 기본으로 사용하여 건축물이나 공예품등에 무늬와 그림을 그려 아름답게 채색하는 것을 말한다. 이러한 단청을 하는 기술과 그 기술을 가진 사람을 ○○○이라고 하는데, 단청에 종사하는 사람이 승려인 경우에는 금어 또는 화승으로 불렀다. 우리나라 단청은 삼국시대의 여러 고분벽화를 통해 찾아볼 수 있는데, 특히 고구려 고분벽화에는 당시의 건축양식과 단청의 모습을 보여주어, 그 유래가 오래되었음을 알 수 있다. 고분에서 출토된 채화, 칠기 등의 그릇에서도 단청이 발견되나 주로 목조건축물에 많이 쓰였다. 단청은 건물벽체…","a":"단청장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644141.jpg"},{"q":"봉화유기는 500여년의 장구한 역사를 가지고 있으며, 전국의 많은 장인들에게 유기제조 기술을 전파한 우리나라 유기제조의 발상지이다. 특히, 안성의 유기제조법도 봉화로 부터 전래되었다고 한다. 19세기초까지만 해도 봉화유기의 명성은 전국적으로 널리 알려져 이곳을 놋점거리라고 불리기도 했다. 이는 쇠를 녹이는데 필요한 숯의 생산이 쉽고 내성천의 풍부한 물이 천혜적인 입지조건이었기 때문이다. 그러나 1919년 태백산 일대의 산림벌채 금지조치와 일제말기의 시대적 변화에 이기지 못하여 쇠퇴해 버렸고 현재 두가구만 겨우 옛 명성의 명맥을 유지하고 있는 실정이다. 타 지방의 경우…","a":"봉화유기장","c":"시도무형유산","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018103110014300.JPG"},{"q":"농요는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로 ○○○ 또는 농사짓기 소리라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수 있다. 고흥 ○○○○○는 음악적인 면에서 육자배기권의 소리에 메나리권의 소리가 가미되어 중요한 위치에 있다. 분포권상으로는 전남 산아지타령권에 속한다. 내용은 모찌기노래·모심기노래·논매기노래·질가락으로 구성되어 있다. 모찌기와 모심기는 여자들이 주로 하며, 모찌기노래는 새벽부터 아침까지 모를 찌면서 부른다. 모찌기에는 식전에 부르는 방애타령과 먹은 후에 부르는 두허래소리…","a":"고흥한적들노래","c":"시도무형유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052413533500.JPG"},{"q":"○○○○는 경상남도 고성지역에서 전승되어오고 있는 전통농요이다. ○○○○는 하지무렵부터 시작되는 농사소리가 주축을 이루며 이를 ‘등지’라고도 하는데, 등지는 모내기소리의 경상도 방언이다. ○○○○는 모판에서 모를 찌면서 부르는 모찌기소리, 모를 심을 때 부르는 모심기소리, 보리타작하며 부르는 도리깨질소리, 김맬 때 부르는 상사소리 및 방아타령 등으로 이밖에 부녀자들이 삼을 삼으면서 부르는 삼삼기소리, 물레질하며 부르는 물레타령 등이 있다. ○○○○의 노랫말에는 이 고장 농민들의 생활감정이 풍부하게 담겨 있으며 향토적인 정서가 물씬 풍긴다. ○○○○는 투박하고 억센 경…","a":"고성농요","c":"국가무형유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624174.jpg"},{"q":"○○○는 경남 통영에서 전승되어 온 북춤, 칼춤, 입춤이다. 이 춤은 삼도수군통제영의 영문(營門)에서 각종 의식․하례(賀禮), 이순신 사당의 춘추향사․생신제․기신제에 헌무(獻舞)한 춤이다. ○○○의 북춤은 궁중의 무고와 흡사한 춤으로 활옷을 입고 양손에는 한삼을 낀 원무 4명이 중앙에 북을 놓고 동서남북으로 나뉘어 북을 울리며 춤을 추고, 협무 12명이 주위를 둘러싸고 돌면서 창(唱)을 부른다. ○○○의 흩어졌다 모여드는 형태는 삼진삼퇴를 뜻하며, 전체가 화려하고 웅장하면서 경쾌한 것이 특징이다. ‘영산회상’가운데 삼현도드리와 타령을 반주음악으로 쓰며, 춤가락은 순박…","a":"승전무","c":"국가무형유산","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624105.jpg"},{"q":"예로부터 호남은 예술이 발달하여 ‘예향’이라는 별칭을 받았고, 그 이름에 걸맞게 유명한 예인들이 많았다. 그렇기에 예술활동에 쓰이는 국악기 제작은 당연하였고, 오랜 전통과 명성은 현대까지 이어지고 있다. 그러나 현재 광주ㆍ전남에는 현악기 중심의 장인만 남아있을 뿐 북과 장구 등은 그 전통이 희미해져가고 있다. 오경식씨의 스승인 강사원씨가 악기 제작에 투신한 것은 1950년대 초반으로 60여년이 된다. 그는 어렸을 적부터 목기 제작에 참여하며 기술을 배우다가 장구 기술을 익혔고, 전국적으로 유명한 악기 제작 장인이었던 광주 양동의 박일호씨에게 악기제작기술을 배운 바도…","a":"악기장","c":"시도무형유산","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026040215450500.jpg"},{"q":"○○이란 발을 만드는 장인을 말한다. 발의 재료에는 대나무(대나무발), 갈태(갈대발), 겨릅(겨릅발), 달풀(달발) 등이 사용된다. 전통가옥인 한옥에서의 생활에는 발이 필수품이었다. 발은 특히 여름철에 강한 햇볕을 막아주어 실내에 있는 사람에게는 시원함을 느끼게 해줄 뿐만 아니라 밖에서는 안을 볼 수 없도록 하는 기능도 한다. 발은 가마의 문을 가리는 발에서부터 집의 문을 가리는 발까지 다양한 크기로 만들어졌다. 시누대는 음력 11~12월 사이에 채취하는데 3년생이 가장 좋은 것으로 알려져 있다. 2개월간 햇볕과 이슬 맞히기를 반복한 시누대로 발을 엮는데 보통 만 번…","a":"염장","c":"국가무형유산","r":"경상남도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624179.jpg"},{"q":"목조각은 조각의 소재인 나무가 가진 양감과 질감을 표현하는 전통조각이다. 주로 사용하는 재료로는 결이 아름답고 견실한 오동나무, 소나무, 전나무, 은행나무, 느티나무, 회화나무 등이 많이 사용된다. 목조각은 삼국시대에 불교가 전해지면서 사찰 건축과 불상 등 불교 의식과 관련된 조각들이 제작되면서 시작한 것으로 보인다. 그러나 여러 차례의 전란으로 인해 대부분 소실, 분실되어 전하는 것은 많지 않다. 기능보유자 이방호 선생은 목조각 가운데서도 불교조각을 대표하는 불상을 주로 제작하고 있으며, 조각의 특징은 불상제작을 마무리할 때에 표면을 매끄럽게 하는 과정에서 사포를…","a":"목조각장","c":"시도무형유산","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643524.jpg"},{"q":"시조창은 시조시(우리나라 고유의 정형시)를 가사로 하여 노래 부르는 것을 말하며, 시절가, 시절단가, 단가라고도 한다. 가장 오래된 기록은 영조(재위 1724∼1776)때 학자 신광수의『석북집』관서악부로 이세춘이 시조에 장단을 붙였다는 시가 나온다. 순조(재위 1800∼1834) 때 간행된『유예지』와『구라철사금자보』에서는 시조의 악보가 처음으로 나타난다. 그후 가곡의 영향을 받아 시조곡조가 보급됨에 따라 지역적 특징을 지니고 나뉘게 되었다. ○○○○○는 충청남도 서북부지역의 시조창이다. 내포라는 말은 충청도에서 서산·당진·예산·홍성을 가리키기 때문에 붙여진 이름으로…","a":"내포제시조(아랫내포제)","c":"시도무형유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643988.jpg"},{"q":"단이란 단독(丹毒)이라고도 하는데, 피부에 붉은 반점 또는 흰반점이 생기고 얼굴이 벌겋게 부어오르는 괴질로 알려진 질병이다. 이병은 마을과 집안에 부정이 있거나 잡귀나 잡신이 침범하여 발병하는 것으로 알려지고 있다. 단은 남녀노소 불문하고 발병하며 단이 발병한 부위는 42도정도 고열이 오르기도 한다. 단의 생김과 형태에 따라 청단, 태단, 황단, 홍단, 팥단, 풍단, 띠단, 녹두단, 토단, 메밀단, 백단, 구목 광솔단 등 12단으로 나뉜다. 단이 발병하는 것을 \"단이 들었다\"라고 하는데 발병하면 침을 놓거나, 백반, 자라피 등을 바르는 민간요법이나 부정 퇴치법으로 단…","a":"내지리단잡기","c":"시도무형유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644016.jpg"},{"q":"○○○○는 정월 대보름에 하는 놀이로 자기 나이만큼 개울가 다리를 밟으면 다리에 병이 나지 않고, 모든 재앙을 물리칠 뿐만 아니라 복도 불러들인다는 신앙적인 풍속에서 나왔다. 특히 우리나라에서 ○○○○를 하면 다리병을 앓지 않는다는 관념이 강한 것은 다리(脚)와 다리(橋)의 발음이 같은데서 생긴 민간신앙이며, 언어의 유희성이 작용한 결과로 보인다. ○○○○는 답교 또는 답교놀이라고도 하며 강릉지방에서는 다리빼앗기라고도 한다. ○○○○놀이는 양반에서부터 서민까지 구분없이 즐겼으며, ○○○○를 할 때에는 사대문도 닫지 않았다는 기록으로 보아 매우 중요하게 여겼던 것을 알…","a":"송파다리밟기","c":"시도무형유산","r":"서울특별시","s":"송파구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643375.jpg"},{"q":"우리말로 ‘자개공예’라고도 부르는 ‘나전칠기’는 목칠공예의 장식기법 중 하나로, 옻칠한 목제품의 표면에 얇게 간 조개껍데기를 여러 가지 형태로 오리고 붙여 넣어 장식한 공예품을 말한다. 조개껍데기를 붙인 방향과 빛이 비추는 방향에 따라 다양한 색을 내기때문에, 그 신비로움과 아름다움이 상당하다. 무엇보다 뛰어난 보존성을 갖춰 세월이 지나도 그 빛깔이 변치 않는 특징을 가지고 있다. 나전칠기가 완성되기까지는 수많은 과정이 필요하다. 먼저 전복의 속껍질을 가는 전복껍질 갈기부터 줄로 모서리를 갈아 부식시키는 줄로 썰기, 칼로 껍질을 가늘게 자르는 상사썰기, 실상사를 끊어…","a":"나전칠기장(나전장)","c":"시도무형유산","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091317121800.jpg"},{"q":"우리나라 금속 공예의 주요한 기술인 주조 기술은 불교문화와 함께 발달하였고 범종 제작이 그 주류를 이룬 우리나라 범종은 세부장식이 정교하고 소리가 웅장한 것이 특징이며, 전통적인 범종제작 방식은 밀랍 주조 기법이다. 먼저 밀랍으로 종의 모형을 만들고 그 위에 활석과 점토 등을 혼합해 만든 주물사를 일정한 두께로 바른 뒤 그늘에서 말린다. 그 다음 열을 가해 내부의 밀랍을 녹여내고 밀랍이 제거된 외형과 내형을 결합한 빈 공간에 쇳물을 부어 제작한다. 종체는 상하에 견대肩帶와 구대口帶로 구분되며 총 8등분으로 나뉜다. 견대 및 네 곳에 유곽乳廓이 있고 유곽 안에 9개의…","a":"주성장(범종)","c":"시도무형유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643698.jpg"},{"q":"충렬사는 임진왜란(1592) 때 나라를 지키다 순절한 동래부사 송상현·부산진첨사 정발 등을 비롯한 부산지방의 관리·군인·백성 91명의 넋을 모셔놓은 곳이다. 효종 3년(1652) 동래부사 윤문거가 송상현의 학문과 충절을 기리기 위해 지은 안락서원의 주관으로 매년 음력 2월과 8월에 제사를 지내고 있다. ○○○○○은 선조 38년(1605) 당시의 동래부사 윤훤이 동래읍성 남문 밖의 농주산에 송상현의 위패를 모신 송공사(宋公祠)를 지어 매년 제사를 지낸데서 비롯되었다. 1652년 동래부사 윤문거는 안락서원을 짓는 한편 송공사가 좁고, 성문 가까이에 있어 시끄러움을 한탄하…","a":"충렬사제향","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643412.jpg"},{"q":"1936년에 태어난 이성근은 무형유산 보유자 김동준으로부터 고법을 배웠다. 그는 또 소리고법을 익히기 위해 김동수, 박록수, 강도근, 김연수 등에게 판소를 공부했다. 이성근은 높은 수준의 고법 소유자로서 판소리 고법 발전에 기여한 바가 크다. 1961년 호남 전국명창대회 최우수상, 1986년 경북 개천예술제 대상, 1987년 남도예술제 특장부 수상, 1990년 전국 고수대회 명고부 등에서 수상했다.","a":"판소리장단","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644102.jpg"},{"q":"<○○○○○>은 평안남도의 역사와 문화를 기반으로 한국 전통춤의 근 현대 과정 속에서 성장하고 꽃피운 우리나라의 대표적인 춤이다. <○○○○○>의 형태적 특징은 중후함, 유연함, 탄력성을 들 수 있으며 부드러운 곡선과 음양의 조화로 이루어지는 다양한 춤사위 그리고 한국적 정서가 깊게 묻어나는 ○○○만의 독특한 예술미학적 기법 등이 그 춤의 철학으로 삼고 있다. 굿거리와 자진모리장단으로 이루어진 반주음악은 흥겹고 경쾌한 리듬이 약동적인 춤사위로 창출되며 八字형과 之字형으로 태극선과 포물선상의 곡선을 만들어가는 부채사위의 기본적 구조는 자연의 이치를 근본으로 삼아 묘사된…","a":"김백봉 부채춤","c":"이북5도 무형유산","r":"평안남도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2737040.jpg"},{"q":"○○은 시조시(우리나라 고유의 정형시)에 곡을 붙여서 관현악 반주에 맞추어 부르는 우리나라 전통음악으로, ‘삭대엽(數大葉)’ 또는 ‘노래’라고도 한다. ○○의 원형은 고려가요에서 생겨난 만대엽·중대엽·삭대엽 순이나 느린 곡인 만대엽은 조선 영조(재위 1724∼1776) 이전에 없어졌고, 중간 빠르기의 중대엽도 조선 후기에는 부르지 않았던 것으로 알려져 있다. 지금의 ○○은 조선 후기부터 나타난 빠른 곡인 삭대엽에서 발생한 것으로, 가락적으로 관계가 있는 여러 곡들이 하나의 노래모음을 이룬 것이다. ○○은 시조시 한 편을 5장형식으로 구분하여 부르는데 전주곡인 대여음과…","a":"가곡","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093010594400.JPG"},{"q":"이상옥 장인은 경남 함양군 마천면 창원마을에서 60년이 넘는 세월동안 전통한지 제조기술인 흘림뜨기(외발지, 음양지)로 전통한지를 생산하고 있으며 1만평의 재배지에 약 7만 그루의 닥나무를 직접 재배하고 있다. 이상옥 장인의 증조부 고 이규태 선생이 1882년(고종19년)부터 관청 별감(세무책임자)에 임명되어 지리산 일대 사찰의 종이부역으로 생산된 사찰종이와 관청 지소에서 만든 종이를 관리하였고, 이를 시작으로 약 140년 동안 전통한지를 보존·전승하며 4대째 가업을 잇고 있다.","a":"한지장","c":"시도무형유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023050121541200.jpg"},{"q":"유배근은 1953년에 태어났으며, 부친 유양수로부터 한지발을 사사받았다. 전북공예품경진대회, 전승공예대전 등 다수 대회에서 입상하였다. 한지발은 고유 한지를 뜨는데 없어서는 안되는 가장 핵심적인 도구로써, 특히 한지발이 없으면 고유한지를 뜰 수 없다. 생산품목은 한지 외발, 한지 쌍발, 무늬발 등이고, 우리의 한지를 활성화시키는 데 더 없이 중요한 것이 한지발이며, 특히 현재 일본식의 쌍발에 밀려 사라져 가는 우리의 전통한지 외발을 되살리기 위해서는 가장 필요로 하는 것이 한지외발 제작이라 할 수 있다. 유배근은 대나무와 말총을 가공하는 복잡하고 세밀한 공정에 정통해…","a":"한지발장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644151.jpg"},{"q":"○○○○은 대구의 비산동 일대에서 전승되어 오는 북춤이다. 정확한 유래는 알 수 없으나 산 모양의 구름이 날아오다 어느 여인의 비명소리에 놀라 땅에 떨어져서 동산이 되었다는 전설에 의해 날아온 산이라 하여 ‘날뫼(飛山)’라 부르게 되었고, 옛날 지방관리가 순직했을 때 백성들이 이를 추모하기 위해 봄·가을에 북을 치며 춤을 추어 제사를 지냈다고 한다. ○○○○은 흰 바지저고리에 감색 전투복을 입고 머리에 흰 띠를 두른다. 북만이 연주악기로 사용되며, 경상도 특유의 덧배기가락(굿거리장단)에 맞추어 춤을 춘다. 연출과정은 덩덕궁이, 자반득이(반직굿), 엎어빼기, 다드래기,…","a":"날뫼북춤","c":"시도무형유산","r":"대구광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643464.gif"},{"q":"영감이란 도깨비의 제주도말인 도채비를 높여서 부르는 말이다. ○○○○는 제주도의 무당굿 중 놀이굿의 한 종류로 도깨비신에 대한 굿인 동시에 가면놀이이며, 물고기가 많이 잡히길 기원하거나 병이 낫기를 기원하는 의미에서 행해진다. ○○○○는 마당에 제삿상을 차린 후 밤에 행해진다. 제삿상 위에는 돼지머리, 수수떡, 소주 따위의 영감신이 즐겨먹는 음식을 차린다. 한 사람이 나와 영감신에게 굿하는 시간과 이유, 그리고 참여하는 사람들의 이름을 알린 후 영감신을 부르면, 종이로 된 도깨비탈과 헌 도포, 헌 짚신, 헌 갓, 곰방대로 분장한 무당 두 사람이 들어온다. 영감신은 해…","a":"영감놀이","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644672.jpg"},{"q":"'○○○'이란 전통한지를 제작하는 장인을 말한다. 한지는 닥나무와 황촉규(黃蜀葵)를 주재료 하여 고도의 숙련된 기술과 장인의 오랜 경험을 바탕으로 완성된다. 닥나무를 베고, 찌고, 삶고, 말리고, 벗기고, 다시 삶고, 두들기고, 고르게 섞고, 뜨고, 말리는 아흔아홉 번의 손질을 거친 후 마지막 사람이 백번째로 만진다 하여 옛사람들은 한지를 '백지(百紙)'라 부르기도 하였다. 우리나라의 한지는 고려시대부터 그 명성이 높아 중국인들도 제일 좋은 종이를 '고려지(高麗紙)'라 불렀다. 송나라 손목(孫穆)은 『계림유사(鷄林類事)』에서 고려의 닥종이는 빛이 희고 윤이 나서 사랑…","a":"한지장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623612.jpg"},{"q":"○○○○○은 무업을 전문으로 하는 무당이 소모양으로 꾸미고 농사의 풍년과 장사의 번창, 자손의 번영을 기원하며 노는 굿놀이로서 정확한 기원은 알 수 없으나 조선시대에 형성된 것으로 보인다. ○○○○은 단독으로 하지 않고 제석거리에 이어서 하는데, 이것은 제석거리가 자손의 번창과 수명을 연장하는 성격을 띠고 있어서 ○○○○과 비슷하기 때문이다. ○○○ 평산 ○○○○은 기호와 해서 지방에서 놀던 놀이로 강한 종교적 성격을 띤다. 굿은 해질 무렵에 시작해서 다음날 새벽까지 계속된다. 굿판은 앞마당에서 6명의 여자무당이 장구와 징, 저나 피리를 가지고 굿놀이를 벌인다. 마당…","a":"황해도평산소놀음굿","c":"국가무형유산","r":"인천광역시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623491.jpg"},{"q":"○○○○○은 사회 상류층이나 부유층에서 죽은 사람의 넋을 위로하고 좋은 세상으로 인도하기 위해 행했던 ○○지역의 전통적인 망자천도굿이다. ○○○은 조선시대에 형성되었다가 17·18세기경에 오늘날의 형태로 행해졌던 것으로 보인다. ○○○은 안당사경맞이와 ○○○으로 구성된다. 안당사경맞이는 ○○○이 벌어지는 전날 밤부터 다음날 새벽까지, 주당물림을 시작으로 부정, 가망천배, 진적, 불사거리, 도당거리, 초가망거리, 본향거리, 조상거리, 상산거리, 별상거리, 신장, 대감거리, 성주거리, 창부거리, 뒷전거리 등의 순서로 진행된다. 다음날 아침부터 이어지는 ○○○은 많은 시간…","a":"서울 새남굿","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623360.jpg"},{"q":"○○○○○는 진주의 세시풍속으로 전승되어 오다가 1920년대 일제의 민족문화 말살정책으로 쇠퇴하여 1937년 무렵에 중단된 이후 1998년에 경상남도 진주지방의 탈놀이로 복원되었다. 이 놀이는 음력 정월 보름날 저녁에 행해졌는데, 춤이 주가 되고 재담과 몸짓, 노래가 곁들여 연희된다. 꽹과리·북·장구·징·해금·피리·젓대 등으로 주로 굿거리 장단을 연주하고, 이에 맞추어 덧뵈기춤을 바탕으로 등장인물의 성격에 따라 진춤·문둥춤·중춤 등을 춘다. 놀이의 구성은 다섯마당으로 짜여져 있다. 첫째는 오방신장무(五方神將舞)마당으로, 동방 청제장군(東方 靑帝將軍), 서방 백제장군(…","a":"진주오광대","c":"시도무형유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644542.jpg"},{"q":"충청남도 공주시 우성면 ○○○에서 전승되는 ○○○○로 상례를 치르는 일련의 과정에 ○○○○가 불렸다. 크게 망자를 장지로 모시는 행상(行喪)소리, 묘소의 광중(壙中)을 발로 밟아서 다지는 달공 소리, 봉분을 만들기 위해 흙을 모으는 흙 가래질 소리로 나뉘며 1996년에는 전국민속예술경연대회에 참가하여 문화관광부장관상을 수상하였고 1997년에는 이러한 의미와 가치를 인정받아 충청남도 무형유산으로 지정되었다.","a":"공주봉현리상여소리","c":"시도무형유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026022315150801.jpg"},{"q":"남원시 옻칠공예관 운영으로 옻칠 및 정제 기술보급에 앞장서고 있다. 남원시 조산동에 소재하고 있는 목운공예사를 운영해 오면서 옻칠 발전을 위한 꾸준한 연구 및 작품 활동과 더불어 후진 양성에 심혈을 기울이고 있다. 특히 커피잔 및 받침접시(제03940185호), 다기세트(제0403094호),우수 산업디자인 상품선정(제04Q085호) 등 꾸준한 작품활동으로 전승활동 중이다.","a":"옻칠장(정제)(박강용)","c":"시도무형유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023070719431400.JPG"},{"q":"○○○○은 ○○시 무을면 일대에서 전승되는 농악이다. 무을면은 신라시대(121년 경)에는 무을동방(舞乙洞坊)이라 하였고, 676년 경 풍헌(風憲)으로 개칭했다. 조선시대에는 무을방이라 하였고, 1914년 면리동(面里洞) 통폐합으로 바뀌어 오늘에 이른다. ○○○○에 가장 큰 영향을 미친 정재진은 상송리 수다사 승려라 하는데, 조선 영조 때 수다사 승려인 정재진이 현몽한 일과 구전되어 오는 내용을 소재로 하여 풍물가락을 만들어 인근 부락으로 전파시켰다고 한다. 그러나 그의 단순한 쇠가락의 전승만으로 오늘의 ○○○○이 형성되었다고 보기는 어렵다. 전통적인 농촌사회에서는 동…","a":"구미 무을농악","c":"시도무형유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020040117135100.jpg"},{"q":"보령시 남포면에 있는 오석(烏石)으로 만든 벼루로, 남포지방에서 많이 생산된다 하여 ○○○○라고 부르게 되었다. 벼루는 낙랑 때부터 사용되었으며 고려 때 성리학의 성행으로 벼루의 사용도가 넓어졌다. 따라서 기술도 발전하게 되었고 1961년 이후에는 수출도 하고있다. 제작과정은 오석을 가져다가 손으로 가공을 한 후에 각기 다른 문양과 무늬를 조각하여 완성하면 끝이다. 무늬로는 용·봉황·소나무·대나무 등 전통적인 무늬를 조각한다. ○○○○의 특징은 먹이 잘 갈리고, 먹물이 마르지 않고 오래도록 남아있는 것이다. 보령 ○○○○ 제작기술은 3대에 걸친 체계화된 기법으로서 무…","a":"보령남포벼루제작","c":"시도무형유산","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643958.jpg"},{"q":"‘○○○’는 온 천지와 수륙에 존재하는 모든 고혼(孤魂)의 천도를 위하여 지내는 의례로 개인 천도의 성격을 띤 영산재에 비해 공익성이 두드러지는 불교 의례이다. 조선초기부터 국행 ○○○로서 대규모로 설행되어 왔던 사실이 『조선왕조실록』을 비롯한 문헌에 나타나 있다. 동해 ○○○는 조선전기 국행○○○의 전통을 계승하는 동시에 지역사회 통합을 위한 고혼 천도의 ○○○ 전통을 가진 사찰이며, 의식과 범패, 장엄 등을 아울러 전승하고 있다.","a":"삼화사 수륙재","c":"국가무형유산","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623658.jpg"},{"q":"농악은 농부들이 두레(마을의 공동작업을 하기 위한 조직)를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리킨다. 호남우도농악은 전라남도의 서부평야지대를 중심으로 발달한 농악이며, 그 일종인 ○○○○은 예로부터 전승되어 온 마륵동 판굿농악을 중심으로 칠석동의 고싸움놀이농악과 소촌동의 당산농악, 산월동의 풍장농악 등 광산지역에서 연주되는 다양한 농악을 집대성한 것이다. 악단의 편성은 꽹과리·장구·작은북으로 구성된 앞치배와 대포수·양반·할미·조리중·각시·참봉·남녀무동으로 구성된 뒤치배로 이루어지며, 여기에 나팔수와 쇄납이 더하…","a":"광산농악","c":"시도무형유산","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643539.jpg"},{"q":"○○○○는 대마라는 섬유 원료에서 삼베라는 직물을 짜는 모든 과정을 말하는 것으로, 삼베는 땀을 빨리 흡수하고 건조가 빠르며, 통풍이 잘되고 열전도성이 커서 시원할 뿐만 아니라 마찰에 대한 내구성이 커서 세탁할 때 손상이 적은 장점 때문에 삼한시대부터 선조들이 손수 길쌈을 통해 입어온 옷감이다. 그 가운데서도 이번에 인정된 보유단체가 속한 경북 안동 지방에서 생산하는 안동포는 조선 시대 궁중 진상품이었으며 지방특산물로 지정되어 널리 알려져 있다. ※ 삼베는 예부터 개인이 아닌 마을 사람들의 협업을 통해 생산되고 후대로 전승된 집단적 기술이기에 특정 보유자를 인정하지…","a":"삼베짜기","c":"국가무형유산","r":"경상북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2020010614092600.jpg"},{"q":"○○○은 금속에 조각을 하는 기능이나 그 기능을 가진 사람으로, 조이장이라고도 한다. 금속조각은 금속제 그릇이나 물건의 표면에 무늬를 새겨 장식하는 것을 말한다. 출토된 유물에 의하면 금속조각은 청동기시대에 처음 발견되었고, 삼국시대에는 여러 가지 조각기법이 사용되었으며, 고려시대에 크게 발전하였다. 그 후 조선시대에는 경공장(京工匠)의 금속공예 분야가 세분화되면서 ○○○이 따로 설정되어 있었다. 금속조각 기법으로는 평각(平刻)·투각·고각·육각·상감입사(象嵌入絲) 등이 있다. 평각이란 일명 음각이라고도 하는데 평면에 여러 가지 문양을 쪼아서 나타낸다. 투각은 바탕면의…","a":"조각장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623173.jpg"},{"q":"○○○○○은 설과 입춘을 맞아 가족의 번창과 풍년을 기원하는 굿으로, 소굿·쇠굿·소놀음굿·마부타령굿이라고도 한다. ○○○○○의 유래는 양주지방에서 산신으로 여기는 감악사(紺岳祠)에서 나왔다는 설과 농경의례의 하나로 풍년을 비는데서 나왔다는 설, 소장수가 잘 되기를 바라는데서 나왔다는 설, 궁중의례에서 나왔다는 설, 굿의 여흥으로 이루어졌다는 설이 있으나 정확한 유래는 밝혀지지 않았다. 다만 소와 말, 하늘을 숭배하는 소멕놀이에 기원을 두고 무속의 제석거리와 마마배송굿 등에서 자극을 받아 형성된 놀이로 보고 있으며, 양주지역에서 만이 아니라 서울과 경기·강원·충청·황해…","a":"양주소놀이굿","c":"국가무형유산","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623594.jpg"},{"q":"○○○○○는 부산 수영 지역에 전승되는 놀이로, 어업의 작업과정과 노동요를 놀이화한 것이다. 새해를 맞이하여 바다에 나가기 전에 굿과 놀이를 하면서 많은 고기를 잡아 만선으로 돌아오기를 기원했다. ○○○○○는 어부들이 그물로 고기를 잡으며 여러 가지 노래를 부르는 내용이 중요부분을 이룬다. 즉 어로작업을 하면서 작업과정에 따른 앞소리, 뒷소리, 맞는소리를 맞추며 부르는 것을 말한다. 놀이의 내용을 살펴보면, 그물로 고기를 잡기 위하여 줄틀로 줄을 꼬며 부르는 내왕소리, 친 그물을 끌어당길 때 부르는 사리소리, 고기를 많이 잡은 어부들이 풍어를 축하하며 부르는 칭칭소리…","a":"좌수영어방놀이","c":"국가무형유산","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623455.jpg"},{"q":"민요는 백성들 사이에서 저절로 생겨나 불러지는 노래로 입에서 입으로 전해진다. 직업·풍속·놀이 등을 기능으로 하여 생활과 밀접한 관련이 있으며, 지역이나 부르는 사람의 취향 또는 즉흥성에 따라 달라질 수 있다. ○○○○○는 장례행사 때 죽은 사람을 묻고 묘를 만들기 위해 사람들이 회(灰)를 섞은 흙을 다지면서 부르는 민요이다. 처음에는 느린 가락으로 시작되어 점차 빨라지며 후에는 사람들의 흥을 돋구는 메나리조로 변화되어 간다. ○○○○○는 선후창(先後唱) 형식을 취하고 있으며, 상주(喪主)의 슬픔을 달래주는 한편 무덤을 만드는 사람들의 흥을 돋게 한다. 우리 조상들은…","a":"횡성회다지소리","c":"시도무형유산","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643728.jpg"},{"q":"○○○이란 전통음악에 쓰이는 악기를 만드는 기능 또는 그러한 기능을 가진 사람을 말한다. 고구려의 벽화 속에는 이미 관악기와 현악기, 타악기가 모두 출현하고 있어 악기를 만드는 장인은 이미 삼국시대부터 있었을 것으로 짐작된다. 조선시대에는 악기조성청이라는 독립된 기관을 설치하여 악기를 제작하여 사용하였다. 우리나라 국악기는 가야금과 거문고가 가장 대표적이다. 그 다음으로 아쟁･대쟁･호금 등이 주류를 이루고 있다. 현악기는 울림통을 오동나무로 하고 밑판을 밤나무로 하는 것이 일반적이며, 장식품의 조각은 대추나무나 흑단, 향나무 등을 많이 이용한다. 오동나무는 음향이 잘…","a":"악기장","c":"시도무형유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020051416112200.pdf"},{"q":"시조는 시조시(우리나라 고유의 정형시)에 곡을 붙여서 반주에 맞추어 부르는 우리나라 전통음악의 한 장르로, 오랜 세월의 경과에도 현재까지 큰 변화 없이 명맥을 유지해왔으며, 역사적・예술적 가치가 높은 음악임. 지역적으로는 서울지방을 중심으로 한 경제(京制), 전라도의 완제(完制), 충청도의 내포제(內浦制), 경상도의 영제(嶺制) 등으로 분류할 수 있고 각각의 지역적 특색에 맞게 전승되어 왔음. 이중, ○○○○○는 내포지역(충남 서북부지역)의 대표적인 가악으로 주로 전승되어 온 시조임. ○○○○○는 우리 道에 기존에 지정되어 있는 ○○○○○와 비교하여 전승계보, 가락,…","a":"내포제시조(윗내포제)","c":"시도무형유산","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020032610052700.jpg"},{"q":"○○○은 대목장이 지은 집과 궁궐, 사찰 등의 내실에 사용하는 가구와 창호 등을 제작하는 장인을 지칭하는 것으로 사랑방, 안방, 부엌 등에서 사용하는 가구를 제작하는 목수를 말한다. 소목의 재료에는 대부분의 나무가 사용가능하나 전통가구의 특징과 용도에 따라 괴목, 가죽나무, 혹시, 오동나무, 대추나무, 소나무, 돌배나무, 소태나무, 은행나무 등이 주로 사용된다. 경남지역은 지리산의 풍부한 임산자원과 임진왜란 당시 통제영 산하에 설치되었던 12공방의 영향으로 전통공예가 다양하게 전승되고 있으며. 진주와 통영은 예로부터 상, 장, 농 등의 가구 또는 나전칠기로 유명하여…","a":"소목장","c":"시도무형유산","r":"경상남도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644557.jpg"},{"q":"경남 함양군 안의면에서는 유래는 확실하지 않으나 신라시대부터 징을 만들어 온 본 고장으로 알려져 오고 있으며 인근에 70년도까지만 해도 징을 만드는 곳이 10개소가 있었다. 기능인의 아버지 이용구(81세)씨는 9세때 부친을 여의고 모친의 먼 친척집에 머슴살이로 들어간 집이 ○○○○ 원대정인 김성노-김동춘-김달용의 뒤를 이어 전통의 징제작 기술을 보유하고 있는 오덕수(20년생, 亡)씨의 집에서 징만드는 기술을 배워 기능인게도 전수되었다.","a":"함양방짜유기장","c":"시도무형유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2024091214354600.jpg"},{"q":"서울과 경기지방에서 부르던 잡가로, 소리꾼이 앉아서 혼자 장구를 연주하며 노래하므로 좌창으로 분류된다. 잡가라는 명칭은 양반들의 정가의 상대적 의미로 붙여진 이름이다. 긴잡가와 휘몰이잡가가 있는데, 긴잡가에는 12곡이 있어서 12잡가라 부르기도 한다. 19세기 중엽에 발생하였으며 지금의 서울 청파동 일대의 사계축四契軸 소리꾼들 사이에서 널리 불렸다. 긴잡가는 과거 8잡가와 잡잡가雜雜歌로 구분하였는데, 8잡가란 ‘유산가遊山歌’, ‘적벽가赤壁歌’·‘제비가’, ‘집장가執杖歌’, ‘소춘향가小春香歌’, ‘선유가船遊歌’, ‘형장가刑杖歌’, ‘평양가平壤歌’ 등이고, 잡잡가는 ‘달…","a":"경기소리(긴잡가)","c":"시도무형유산","r":"경기도","s":"과천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643669.jpg"},{"q":"목장, 목공, 목수는 전통적으로 나무를 다루는 사람을 뜻하며, 궁궐이나 사찰 또는 가옥을 짓고 건축과 관계된 일을 하는 사람을 대목(大木)이라 하고, 그 일을 하는 장인을 ○○○이라 한다. ○○○은 목조건축의 설계, 시공, 감리 등 집을 짓는 전 과정의 책임을 지는 장인이다. 목재의 구입에서 건물의 설계 과정을 비롯하여 목재의 치목과 조립을 통한 건물의 뼈대 완성, 벽을 만들고 지붕을 올리고 기와, 단청에 이르는 여러 단계의 후반 작업 등 전 과정을 총괄한다. 우리나라 전통 목조건축의 역사와 함께 하며 무형유산으로서 역사적 가치가 탁월하여 2019년 충청남도 무형유산…","a":"대목장(서산)","c":"시도무형유산","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020032610132701.jpg"},{"q":"청양의 하동정씨 종가에서 전수되고 있는 ○○○○○는 양질의 쌀과 ○○○를 주원료로 ○○○ 뿌리, 잎, 줄기, 두충등을 첨가하여 전래의 비법으로 빚어지는 술로써 150여년전부터 이어져 오고 있다. ○○○는 정력증강, 성인병치료, 시력보호, 피부미용, 정신집중력 향상, 청결작용 등 그 효능이 인정되어 한방의 필수 약제일뿐만 아니라 현재는 드링크재 원료로 널리 사용되고 있으며, 특히 음주자들이 복용하는 경우 지방간이 형성되는 것을 방지하는 것으로 밝혀져 있다. 이처럼 효능이 우수한 ○○○를 이용해서 담근술은 ○○○의 약효 성분을 함유한 술로써 색깔이 붉은 빛으로 그윽한 향…","a":"청양구기자주","c":"시도무형유산","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644017.jpg"},{"q":"○○○란 소리하는 사람 한 명과 북치는 사람 한 명, 그리고 판을 이루는 구경꾼으로 이루어지는 무대예술을 말한다. 소리하는 사람은 소리와 대사(아니리), 몸짓(발림)을 하며, 북치는 사람은 소리하는 사람의 가락에 따라 북을 쳐서 장단을 맞추며 신명난 분위기를 이끌어 간다. ○○○는 지역적 특성과 전승계보에 따라 전라도 동북지역의 동편제·전라도 서남지역의 서편제·경기도와 충청도의 중고제로 나뉜다. ○○○는 서편제의 명창 박유전의 소리를 이어받은 것으로 서편제의 일종을 말한다. ○○○는 원래 열두 마당이었으나 일제시대에 거의 사라졌고 춘향가·심청가·흥보가·수궁가·적벽가의…","a":"판소리강산제(심청가)","c":"시도무형유산","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643548.jpg"},{"q":"소반은 음식을 담은 그릇을 올려 놓은 상으로, 우리 식생활에서 부터 제사 의례에 이르기까지 여러 용도로 쓰이는 부엌살림이다. 소반을 짜는 장인을 소반장이라 한다. 소반은 산지, 형태, 용도에 따라 약 60여종으로 분류된다. 크게는 해주반, 나주반, 통영반, 충주반 등으로 나누는데 그중에 나주반은 장식이 간결하지만 짜임이 정교하고 튼튼하며, 투명한 생칠로 나뭇결이 살아 있고 광택이 좋다. 나주반은 박판구, 이석규(1833~1940)와 그의 아들 이운영(1895~1972)우상숙, 장인태에 의해 전수되었으나, 현재는 모두 세상을 떠나고 기능 보유자인 김춪식에 의해 명맥이…","a":"나주반장","c":"시도무형유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060214424600.jpg"},{"q":"연죽(煙竹)이란 일반적으로 담뱃대를 말한다. 백동으로 만든 담뱃대를 백동연죽이라 하며, 백동담뱃대를 만드는 기술과 그 기술을 가진 사람을 ○○○○○이라고 한다. 담뱃대를 만들기 시작한 것은 임진왜란 후 일본을 통해 담배가 전래되면서라고 전해지며, 그래서인지 대일무역의 중심지였던 동래가 전통적인 명산지이다. 담뱃대의 구조는 입에 물고 연기를 빨아들이는 물부리와 담배를 담아 태우는 대꼬바리 그리고 그것을 잇는 가는 대나무 설대 세 부분으로 구성된다. 대꼬바리는 열을 받는데다가 구조상 파손되기 쉬워서 구리, 놋쇠, 백동과 같은 금속으로 만든다. 간혹 사기제품도 볼 수 있으…","a":"백동연죽장","c":"국가무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623767.jpg"},{"q":"大木은 전통 목조건축물의 뼈대를 만드는 가장 중요한 기능으로 큰 부재의 목재를 치목⋅조립하는 일을 하는 목수이다. 우리나라 국가유산 중에는 목조 건축문화유산이 차지하는 비중이 높지만 노후되거나 자연재해⋅인재 등으로 피해를 입을 가능성 또한 높기 때문에 효율적인 유지⋅보수와 전통 건축문화의 계승 차원에서도 그 기능을 보존⋅육성하는 것이 매우 중요하다. 특히, 예로부터 산 높고 골 깊은 강원특별자치도에서 산출되는 질좋은 목재들이 궁궐⋅사찰건축 등에 많이 사용되면서 강원특별자치도만의 특성을 지닌 전통 건축문화가 형성되었다는 점에서 전통 건축문화의 체계적 전승⋅보존을 위해…","a":"대목장","c":"시도무형유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643826.jpg"},{"q":"○○○이란 쇠를 녹여 쇳물을 거푸집에 부어 원하는 물품을 만드는 주물기술을 가진 장인을 말한다. 조선시대 ○○○은 군기감이나 주자소에서 무기나 금속활자를 만드는 경공장이 중심이었다. 영·정조시대 이후 공장안이 폐지되자 17세기부터 개인적인 경영을 하는 사장(私匠)이 나타났는데, 이들은 18세기에 들어 사찰의 범종, 금고, 향로, 시루 ,주자 등의 수요를 담당하였고, 19세기부터는 점차 쇠퇴하였다. 이후 대한제국 시절에는 ○○○의 맥이 거의 단절되다시피 하였으나 오히려 일제강점기에는 군수물자 제작으로 인해 주물의 수요가 늘어나 점차 부활하였다. ○○○ 기능보유자 박한종…","a":"주성장","c":"시도무형유산","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052120052500.jpg"},{"q":"‘○○○○’은 ‘불교의 정신을 담아 사찰에서 전승해 온 음식’으로, 승려들의 일상적인 수행식과 발우공양으로 대표되는 전통적인 식사법을 포괄한다. 사찰마다 다양한 음식이 전승되고 있지만, 공통적으로 불교 사상에 기초하여 육류와 생선, 오신채(마늘, 파, 부추, 달래, 흥거) 없이 조리하는 채식이라는 점이 특징이다. ‘○○○○’은 불교가 우리나라에 전래된 이후 오랜 기간 동안 한국의 식문화와 상호 영향을 주고받으며 발전해왔다. 고려시대 『동국이상국집(東國李相國集)』,『조계진각국사어록(曹溪眞覺國師語錄)』,『목은시고(牧隱詩藁)』와 같은 문헌에서 채식만두와 산갓김치 등 사찰의…","a":"사찰음식","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2025051909125200.jpg"},{"q":"<○○○>는 ‘저녁에 빚으면 다음날 새벽닭이 울 때까지는 다 익는다.’고 하여 붙여진 술 이름이다. 『동의보감』을 비롯하여 『임원십육지』에 ‘○○○’ 술 빚는 방법이 수록된 것으로 미루어, 이미 1500년대 이전부터 빚어 마셔왔던 것으로 여겨진다. 급하게 술을 빚을 필요가 있을 때 만들었던 속성주速成酒로 일일주一日酒, 삼일주三一酒, ○○○ 등이 이에 속하고 일명 엿탁주라고도 한다. ○○○는 크게 누룩으로 빚는 일반적인 속성주법을 기본으로 엿기름이나 조청, 사탕을 넣어 당화를 촉진하는 방법과 효모를 이용한 속성주법 등 두 가지 주방문이 존재하며, 특별한 목적에 따라 여…","a":"계명주(엿탁주)","c":"시도무형유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643606.jpg"},{"q":"○○○는 서민예술의 하나로, 서민의 삶을 구체적으로 반영시켜 노래한 창악이다. ○○○는 광대가 병충을 두르고 돗자리를 펼친 마당이나 공연장에서 고수의 북 반주로 짧게는 세 시간, 길게는 여덟 시간 정도 걸리는 긴 이야기를, 몸짓을 섞어 가며 흥미롭게 노래하는 판의 예술이다. 연행하는 형태로 보자면 음악극의 모습이기도 하며, 담고 있는 내용으로 보자면 이야기를 연극으로 보여주는 서사극이기도 하다. '판'에서 이야기와 노래 및 연행이 함께 이루어지는 종합예술의 형태가 바로 ○○○인 것이다. 2004년 1월 15일에 이옥천이 흥보가 보유자로 인정받았으며, 2013년 1월…","a":"판소리","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317520700.jpg"},{"q":"산조란 장구반주에 맞추어 다른 악기를 독주형태로 연주하는 것을 말하며, 4∼6개의 악장을 구분하여 느린 장단에서 빠른 장단 순서로 연주한다. ○○○○○는 거문고로 연주하는 민속 기악 독주곡이다. 고구려의 왕산악이 처음 만들었다고 하는 거문고는 우리 민족 고유의 현악기로 ‘현금(玄琴)’이라고도 한다. 길이 1.5m, 폭 25㎝ 정도 되는 나무통에 명주실로 꼰 6개의 줄을 매어 연주하는 악기이다. 거문고 머리를 무릎에 놓고 왼손가락으로 괘(줄받침)를 짚어 운율을 맞추며 오른손으로 가느다란 대나무로 만든 술대를 쥐고 줄을 쳐서 소리를 낸다. ○○○○○는 고종 33년(189…","a":"거문고산조","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624290.jpg"},{"q":"○○○○○는 ○○○으로 연주하도록 짜여진 산조를 가리킨다. 산조란 악기를 혼자서 연주하는 형식을 말하며, 느린 장단으로 시작하여 차츰 빠른 장단으로 바뀌는데, 이는 듣는 사람을 서서히 긴장시키면서 흥겨움을 끌어올리게 한다. ○○○○○는 4∼6개의 장단으로 짜여진다. 각 장단의 느낌을 살펴보면 진양조는 아주 느려서 서정적이고, 중모리는 안정적이며, 중중모리는 흥취를 돋운다. 자진모리는 밝고 경쾌하고, 휘모리는 흥분과 급박감이 있다. 다른 악기로 연주하는 산조보다 먼저 만들어졌으며, 뛰어난 기교로 인해 사람들의 관심을 많이 끌어서 여러 유파가 형성되었다. ○○○○○의 특…","a":"신관용류가야금산조","c":"시도무형유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644533.jpg"},{"q":"○○○은 생옻으로 목기 등에 칠을 하는 장인이다. 양질의 생칠을 사용하여 목기에 칠을 하면 처음에는 검은색의 칠기제품이 되지만 세월이 지나면서 원래 무늬가 서서히 나타나 은은한 광이 살아날 뿐 아니라 오래되면 될수록 아름답게 변화하기 때문에 생옻칠은 오래전부터 널리 사용되어 왔다. 그러나 근래에 이르러 옻칠 산업이 쇠퇴해 감에 따라 생옻칠 기법이 현저히 줄어들고 있는 실정이다. 보유자 이돈호는 1977년부터 생옻칠을 해 온 장인으로, 신중현(서울시무형유산 칠장), 이성구 등 우리나라 생옻칠계 거장들에게 전통기법과 기능을 전수받았다.","a":"생칠장","c":"시도무형유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643798.jpg"},{"q":"휘몰이잡가는 빨리 몰아서 부르는 잡가라는 뜻이다. 긴잡가의 상대적인 의미로 휘몰이잡가라는 명칭이 붙었다. 경기의 긴잡가와 휘몰이잡가 등 앉아서 부르는 좌창계열의 악곡은 조선후기에 서울 사계축이라 불리던 만리재·청파도 소리꾼을 중심으로 하여 서울 도성 안팎의 소리꾼들에 의해 발전된 것이다. 잡가꾼들이 노래할 때에는 먼저 가사와 시조를 부른 다음 긴잡가와 수잡가首雜歌, 휘몰이잡가를 부른 후에 통속민요로 판을 끝냈다고한다. 즉 휘몰이잡가는 주로 끝판에 불렀던 노래였음을 알 수 있는데 이처럼 끝에 불렸던 것은 휘몰이잡가의 익살스러운 가사가 분위기를 흥겹게 만드는 역할을 했기…","a":"경기소리(휘몰이잡가)","c":"시도무형유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091410425400.jpg"},{"q":"단청은 안료를 이용하여 건물,조각상,불화,공예품 등에 칠하는 행위를 말한다. 따라서 바탕재료는 돌,흙벽,나무,쇠붙이,가죽,종이 등 다양하고, 서 회 화의 개념을 두루 아우르는 말이나 목조건축의 부자재에 채색하는 단청이 가장 대표적이다. 특히 목조건물에서는 단청의 역할이 중요하다. 건물의 목재나 벽면에 칠해 덮음으로서 비바람과 기후변화에 다른 부식과 건습을 막아 내구성을 높인다. 각각 칠해지는 건축 부자재의 종류와 건물의 성격에 따라 단천의 문양은 매우 다양하다. ○○○은 단순히 건물에 채색하거나 문양을 그리는 작업만 하는 것이 아니라 회화적 기량이 요구되는 탱화 등의…","a":"단청장","c":"시도무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317505000.jpg"},{"q":"시흥 ○○○○○는 시흥시와 안산시의 경계에 위치한 ○○○ 성 황단城隍壇에서 김부대왕을 주신으로 모시고 행하는 굿이다. 음력 10월 3일에 본격적인 의례를 거행하며, 안산 잿머리 ○○○와 성격 이 유사하다. ○○○은 시흥시 군자동과 안산시 선부동의 경계에 위치한 산이며, 해변에서 멀지 않은 곳에 있다. 현재 경기도 남부 서해안 지 역에서 무속인들의 발길이 가장 잦은 산으로 주위에는 여러 개의 굿 당들이 들어서 있다. ○○○에는 군자산성君子山城터와 함께 성황단이 남아 있다. 성황 단은 산성이나 고을 관아의 주위에 나타나는데, 고을이나 성城 안의 안녕을 빌기 위해서 수령이…","a":"시흥군자봉성황제","c":"시도무형유산","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018081010272600.jpg"},{"q":"○○○○는 용과 범의 싸움을 놀이화한 것으로, 경상남도 밀양시 무안을 중심으로 정월 대보름을 전후하여 3일 동안 행해지는 민속놀이이다. 줄다리기의 앞놀이에서 파생된 것으로 보고있으나 기원과 유래에 대해서는 정확히 알 수 없다. 무안마을 뒤편의 산등성이가 좌청룡·우백호와 같다하여 마을의 동부를 용마을, 서부를 범마을로 나누어 불러왔다. ○○○○는 지신밟기, 놀림마당, 부름마당, 빌마당, 싸움마당, 열림마당 등 총 6마당으로 구성된다. 첫째마당은 앞마당이라 하여 대보름 전날인 14일에 집집마다 지신밟기를 하여 악귀를 쫓고 복을 빌어준다. 둘째마당은 놀림마당으로 대보름 아…","a":"용호놀이","c":"시도무형유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644428.jpg"},{"q":"서각은 나무나 돌에 글자를 새기는 일을 말하며, ○○○은 이 일을하는 장인이다. 서각은 본디 책을 인출하거나 편액을 새겨 걸기 위해 글자를 새기던 각자장刻字匠의 소임과 다르지 않다. 각자가 근래 들어 벽에 걸고 감상하는 예술의 영역으로 나아가면서 붙은 별칭인 셈이다. 각자의 영역은 규모가 작은 인장이나 전각 등 신표의 기능을 가진 것에서 인출용 각자, 건물에 거는 편액 등으로 다양하다. 다만 인출용 각자는 인쇄를 위해 글자를 거꾸로 새기는 점이 다르다. 한국의 각자기술은 인쇄기술과 함께 우수성이 널리 알려져 있다. 그 증거인 목판 가운데 가장 오래된 유물로 통일신라시…","a":"서각장","c":"시도무형유산","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411014300.jpg"},{"q":"가구를 만드는 과정 중에 칠을 하거나 조각 등을 하기 전 단계인, 나무로만 제작된 상태를 백골이라 한다. 이 상태의 소반은 백골소반이라 하고, 건축에서도 단청을 입히지 않은 집은 백골집이라 부른다. 이 백골에 칠을 하고 나전이나 조각으로 장식하면 가구가 완성되는 것이다. 치장 전의 민낯과 같은 것인데, 나전장, 칠장, 화각장은 많아도 백골장은 드물다. 백골가구는 좋은 나무를 골라 켜고 다듬고 짜맞추는 과정을 거쳐 형태를 갖춘다. 가구의 겉을 부드럽게 하기 위해 밀납으로 광을 내고 어피가죽으로 문지른다. 그리고 표면 전체에 들기름칠을 한다. 보유자 김의용은 열다섯에 상…","a":"소목장(백골)","c":"시도무형유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091316394200.jpg"},{"q":"○○○○○는 해마다 음력 정월 15일 자시(子時)에 여산송씨의 ○○ 입향조인 송간이 심었다고 전하는 ‘충강목(忠剛木)’에서 유교식 제례 형태로 ○○를 치며 마을 번영과 안녕을 기원하며 지내고 있으며, 특히 ○○마을 별신제는 남자들만 참석하여 ‘별신제의절(別神祭儀節)’에 따라 그 절차와 음식 상차림을 정성스럽게 준비하여 지낸다. 또한, ○○○○○의 구성은 샘굿, 들당산굿, 별신제, 마당밟기, 판굿, 문굿으로 나누며 ○○○○ 보존회는 마을주민과 재향인사로 일찍이 조직되어 확실한 계보로 전승활동을 이어가고 있으며, 보존회를 중심으로 마을의 단합된 모습을 볼 수 있다. 그리…","a":"고흥 마동 별신제와 매구","c":"시도무형유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093012524100.JPG"},{"q":"○○○○○는 충청남도 부여군 은산면 은산리 마을 사당인 별신당에서 열리는 제사를 말한다. 옛날 은산 마을에 큰 병이 돌아 젊은 사람들이 많이 죽어 나갔다. 어느날 밤 마을 어른의 꿈에 백제를 지키다 억울하게 죽은 장군이 나타나 병을 없애 줄테니, 자신과 부하들을 양지바른 곳에 묻어 달라고 했다. 꿈에서 깨어 장군이 말한 곳으로 가 보니 오래된 유골들이 널려 있었다. 마을사람들은 이 유골들을 잘 묻고 그들의 영혼을 위해 굿을 하니, 그 후 병이 사라졌고, 마을에 평화가 찾아왔다고 한다. 이후 마을사람들은 장군과 병사들을 위로하는 뜻으로 제사를 지내왔는데, 이것이 바로…","a":"은산별신제","c":"국가무형유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623703.jpg"},{"q":"○○은 문방사우(文房四友)의 하나인 붓을 만드는 사람 또는 기술을 말한다. 붓은 털의 품질이 가장 중요한데, 첨(尖)·제(濟)·원(圓)·건(健)의 네 가지 덕을 갖추어야 한다고 한다. 이는 붓끝이 뾰족해야 하고 가지런해야 하며, 털 윗부분이 끈으로 잘 묶여서 둥근 것, 오래 써도 힘이 있어 한 획을 긋고 난 뒤에 붓털이 다시 일어나야 한다는 것이다. 털의 재료로는 양·여우·토끼·호랑이·사슴·이리·개·말·산돼지·족제비 등의 털이 사용되며, 붓의 대는 대나무를 많이 사용한다. 제작과정을 살펴보면 우선 털을 고르게 한 후에 적당량을 잡아 말기를 한다. 말고 나서 털끝을 가…","a":"필장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643377.jpg"},{"q":"동장각은 국새, 옥새 등 도장으로 사용할 수 있는 금속에 인문(印文)을 새기는 기술을 말한다. ○○○○의 전승 계보는 황소산(黃蘇山), 석불(石佛) 정기호(鄭基浩), 목불(木佛) 정민조(鄭民朝)로 이어진다. 목불 정민조는 1944년생으로, 호(號)를 목불(木佛), 목인(木人), 고죽산인(古竹山人), 올좌실(兀坐室), 태고암(太古庵) 등을 사용하고 있으나 도필계(刀筆界)에서는 통칭 목불로 많이 알려져 있다. 정민조는 어린 시절부터 집안의 분위기로 일찍이 전각과 서예를 자연스레 받아들여 한학과 서예를 10대 때부터 익혔다. 중학 시절부터 서예를 본격적으로 배우기 시작하였…","a":"동장각장","c":"시도무형유산","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019051511130800.png"},{"q":"보유자 故김계순씨는 우리나라 현대 자수계의 1세대이자 원로로써 오늘날 우리 자수 발전에 많은 기여를 하였다. 지난 50∼60여년간 오로지 자수인의 길을 걸어왔으며 자신의 영달보다는 후학 양성과 자수연구에 전력해왔다. 특히 대체로 궁중에서 성행하고 여인들의 규방에서 행하여진 관계로 문헌자료가 많지 않은 상황에서 옛날 작품을 분석 연구하여 도안과 작품 재현에 헌신하여 자수 발전에 많은 기여를 하였다.","a":"자수장","c":"시도무형유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643516.jpg"},{"q":"참빗이란 빗살이 가늘고 촘촘한 머리빗을 말한다. 크기에 따라 대소(大梳)·중소(中梳)·어중소(於中梳)·진양소·화각소(畵角梳)·민갑소·밀소(密梳)·써울치 등이 있다. 우리나라 빗의 역사는 매우 길어 기원전 1세기 경의 낙랑고분에서도 이미 빗이 출토되었고, 조선시대에는 공조(工曹)에 참빗을 만드는 죽소장(竹梳匠)을 두었다. 참빗은 얼레빗으로 머리를 대강 정리한 뒤 머리카락을 보다 가지런히 하기 위해 사용하는 것으로 때로는 머리카락의 불순물을 제거하기 위해 쓰이기도 하였다. 대개 대나무로 빗살을 촘촘히 박아 만들지만 대모로 만든 것도 있으며, 빗살 역시 성긴 것과 촘촘한…","a":"참빗장","c":"시도무형유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644180.jpg"},{"q":"장도(粧刀)는 몸에 지니는 조그마한 칼로서 남녀 구별없이 호신용 또는 장신구로 사용되었고 장도를 만드는 기술과 그 기술을 가진 사람을 장도장이라 한다. 고려시대부터 성인 남녀들이 호신용으로 지니고 다녔으며 특히 임진왜란(1592) 이후부터 사대부 양반가문의 부녀자들이 순결을 지키기 위해 필수적으로 휴대했다. 조선 후기 이후부터는 손칼로서의 실질적인 기능보다 상징성과 장식성이 강조되어 여인들의 노리개장식 일부가 되면서 정교하고 화려한 장도가 다양하게 만들어졌다. 장도 중에서 몸에 차고 다니는 것을 패도(佩刀)라 하고, 주머니 속에 넣고 다니는 것을 낭도(囊刀)라 한다.…","a":"영풍장도장","c":"시도무형유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644339.jpg"},{"q":"민화란 생활공간의 장식을 위주로 한 일상생활과 풍습에 따라 그려진 실용적 그림을 말하며 이런 민화를 그리는 사람을 ○○○이라 한다. 민화는 조선 후기에 특히 일반민중이나 서민층의 그림으로 유행하였다. 대부분 그림공부를 제대로 하지 못한 무명화가나 떠돌이 화가들에 의해서 그려졌기 때문에 그림을 그린 화가의 낙관(이름이나 호가 새겨진 도장)이 없는 것이 특징이다. 민화는 위로 궁중에서부터 아래로는 일반서민들의 생활속에 깊숙히 뿌리를 내려 오랜 세월에 걸쳐 끊임없이 그려져 왔다. 그 소재 또한 다양해서 소재의 제한이 없는 것이 특징이다. 단순히 장식적 목적을 위한 산수·화…","a":"민화장","c":"시도무형유산","r":"서울특별시","s":"영등포구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643395.jpg"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로, 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 굿·매구·풍장·금고·취군 등으로도 불린다. ○○○○○은 충청·경기지역의 농악을 가리킨다. 농악의 과정은 인사굿·돌림벅구·당산벌림·칠채오방감기와 풀기·무동쾌자놀이·소고절굿대놀이·십자걸이·사통백이·원좌우치기·네줄좌우치기·쩍찌기·풍년굿·고사리꺾기·도둑굿·소고판굿놀이·무동꽃받기·개인놀이·뒷풀이·퇴장굿의 순서로 진행된다. ○○○○○은 다른 충청·경기농악들과 구성에 있어서 서로 유사성을 갖는데 이것은 각 농악단의 상쇠들이 1950년에 만들어진 남사…","a":"웃다리농악","c":"시도무형유산","r":"대전광역시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643562.jpg"},{"q":"○○○는 무용극 형식의 춤으로, 배역에 따른 연기와 춤, 장단이 어우러져 종합예술적 성격을 띄는 특징이 있다. 한량과 승려가 한 여인을 유혹하는 내용으로 색시를 사이에 두고 벌이는 한량과 먹중(승려)의 애정 춤사위가 보는 이의 재미를 더한다. ○○○와 같은 가면무극은 오랜 세월동안 전국에서 성행하였다고 볼 수 있는데, 먼저 교방가요에 나타난 ○○○를 살펴본다면, 1872년 진주목사 정현덕에 의해 당시 진주교방에서 행해지던 가무(歌舞)를 정리한 “교방가요”에 나타난 승무(僧舞)는 한량, 기생, 노승, 상좌, 소기(어린기생)이 등장하는 무용극 형태로 진행과정과 내용면에서…","a":"한량무","c":"시도무형유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102609380700.jpg"},{"q":"○○○○○은 전통적인 기법으로 자기를 만드는 사람 또는 기술을 말한다. 우리나라는 신석기부터 흙으로 토기를 만들어 사용했으며, 10세기 초에는 중국 당나라의 도자기 기술을 받아들여 상감청자를 만들게 되었다. 그 후 몽고의 침입으로 청자 제작기법은 쇠퇴하고, 조선 전기에 분청사기와 조선백자의 제작이 활발해졌다. 그러나 임진왜란(1592)을 거치면서 가마가 파괴되고 많은 도공들이 일본에 끌려가면서 도자기술이 쇠퇴하기에 이르렀는데, 다행히도 광주관요(官窯)가 유일하게 남게되어 조선백자를 중심으로 하는 큰 줄기를 이루게 되었다. ○○○○의 제작과정은 제토(製土)·성형(成形)…","a":"전통자기도공(백자장)","c":"시도무형유산","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643732.jpg"},{"q":"징은 타악기의 하나로 금정(金鉦) 또는 단순히 금(金)이라고도 한다. 중국 고대로부터 널리 쓰여 온 악기로 우리나라에는 고려 공민왕(재위 1351∼1374) 때 중국 명나라로부터 들여와 군대의 악기로 사용했고, 또 종묘악·무악·법악·농악에도 널리 사용하였다. 징을 만드는 일은 음력 11월부터 다음해 2월까지 농한기의 밤에 대정, 가질대정, 앞마치꾼, 전마치꾼, 센마치꾼, 풀무꾼이 한 조가 되어 놋쇠를 두들겨서 만든다. 제작과정은 놋쇠녹임, 늘품질, 돋음질, 냄질, 싸게질, 부질, 담금질, 트집잡기, 풋울음잡기, 가질, 울음잡기 순인데 특히 마지막에 징의 소리를 조율하…","a":"징장","c":"시도무형유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644477.jpg"},{"q":"○○지역에는 예로부터 남포오석(藍浦烏石)으로 불리는 우수한 돌이 생산되어 전국적으로 유명한 고을이었다. 남포오석은 석질이 좋아 오랫동안 글씨를 보존하는 관계로 비석으로 많이 사용되었고, 조선시대 왕릉의 절반 정도도 남포 오석으로 비석을 만들 정도였으며, 오늘날 대통령 묘비도 남포오석을 사용하였다. 그러다 보니 ○○지역에는 어느 곳 보다 석공업이 발달하였고 우수한 ○○이 나타났다. 현재 ○○ 지역에는 많은 ○○이 있는데 그 중 고석산(高錫山, 1955~ )은 ○○ 웅천 출신으로 ○○에서 뛰어난 ○○으로 활동하며 불상 등 많은 우수한 석공예품을 제작하고 있으며, 충청남도…","a":"보령 석장","c":"시도무형유산","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019042713505400.jpg"},{"q":"○○○이란 왕골로 기물을 만드는 사람을 말한다. 왕골은 논 또는 습지에서 자라는 1, 2년생 풀로서 키는 60∼200㎝에 이르며 완초, 용수초, 현완, 석룡초라고도 한다. 왕골제품으로는 자리, 돗자리, 방석, 송동이, 합 등이 있다. 왕골이 신라시대에 이미 사용되었음은 『삼국사기』의 기록을 통해 알 수 있다. 고려때에는 사직신(社稷神)의 신위에 왕골자리를 깔았으며, 왕실에서 주로 사용하였고 중국에 보내는 증여품으로도 사용되었다. 조선시대에는 매우 귀한 제품으로 궁중이나 상류계층에서 사용하였고, 외국과의 중요한 교역품으로도 쓰였다. 현존하는 왕골제품을 통해 본 제작기법…","a":"완초장","c":"국가무형유산","r":"인천광역시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623503.jpg"},{"q":"○○○은 종이를 비벼 꼬아서 만든 끈인 지승을 활용하여 그릇, 바구니, 함, 항아리 등 다양한 공예품을 만드는 장인을 말한다. 먼저 종이발이 얇고 고운 한지로 만든 책을 너비 1㎝ 정도로 잘라놓고 노를 낱낱이 꼰다. 이 꼰 끈으로 그릇을 만든 뒤 칠을 하게 되는데, 안팎으로 옻칠을 하거나 주칠(朱漆)을 한다. 종이는 만드는 사람의 의도에 따라 각종 용도에 맞는 다양한 형태의 기형(器形)을 이룰 수 있는 장점을 지녔기 때문에, 이러한 특징을 활용하여 전통적인 공예품은 물론, 바구니·합·소반·바리때·망태기·멜빵·미투리 등 현대적인 감각에 맞는 공예품으로 개발할 수 있다.…","a":"지승장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093014073100.jpg"},{"q":"○○○은 벼루를 만드는 기술 또는 그 기능을 가진 장인을 말한다. 유길훈(1949년생, 68세)은 1967년 3월, 충북 진천 상산벼루 제작의 대가 故김인수 문하에 입문하여 현재까지 줄곧 벼루제작에만 종사하고 있다. 그는 벼루의 재료인 자석(紫石 :붉은 돌)이 나는 청주의 두타산 자락에서 작업을 하다 1993년에 더 나은 벼룻돌을 찾아 경주로 내려왔고, 2001년에는 언양읍 반구대 일대에서 최상의 벼룻돌을 발견, 현재의 작업장에 정착하여 15년째 벼루를 제작하고 있다. 언양 벼룻돌은 색이 쑥색[綠色]과 검붉은색[紫色]의 두 종류로 벼룻돌로 많이 사용되는 오석(烏石)인…","a":"벼루장","c":"시도무형유산","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2017110213414800.jpg"},{"q":"○○○○○은 판소리가 정착한 조선 중기 이후에 생겨난 것으로 판소리에 맞추어 고수(鼓手:북치는 사람)가 북으로 장단을 쳐 반주하는 것을 말한다. 고법은 판소리의 반주이기 때문에 고수를 내세우는 일이 없어 조선시대에는 이름난 명고수가 매우 드물었다. 또한 고수를 판소리수업의 한 방편으로 여겨 고법의 발달은 미미하였다. 조선 후기에 들어 판소리가 매우 다양한 특성을 지니고 발전함에 따라 고법도 발전하나, 19세기 말에 이르러서야 전문적인 고수들이 나와 고법은 비약적인 발전을 하게 되었다. ○○○○○에는 여러가지 이론이 있으나 크게 자세론(姿勢論)·고장론(鼓長論)·연기론(…","a":"판소리고법","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643545.jpg"},{"q":"1947년 태어난 박양덕은 박복선․성우향․남해성 등에게 ○○○를 사사받았다. 박양덕은 완창발표를 수차례 가졌으며, 전국○○○경연대회 대통령상 수상 등 다수의 입상 경력을 가지고 있으며, 수궁가의 진면목을 잘 보유하고 있다.","a":"판소리(수궁가)(박양덕)","c":"시도무형유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644085.jpg"},{"q":"침선이란 바늘에 실을 꿰어 꿰맴을 말하는 것으로 복식 전반을 만드는 일이라고 할 수 있으며 그것은 옷을 마름질하여 꿰매는 바느질, 또는 더 아름답게 하기 위하여 수를 놓는 것 또는 옷에 장식하는 노리개 등을 만드는 것을 말함. 옷을 만드는 일은 바느질 기술은 물론 여러 공정을 거쳐 완성되는 복잡한 작업임. 침선의 도구로 바늘은 그 쓰임새가 천과 천을 꿰매는데 사용됨. 바늘은 굵이에 따라 고운 바늘, 중바늘, 굵은 바늘로 나누어 사용함. 고운 바늘은 명주나 비단 등과 같이 올이 가는 천으로 옷을 지을 때 사용하거나 깃, 섶 등과 같이 섬세한 부분을 꿰매는 데 사용함.…","a":"서천침선장","c":"시도무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052709530100.png"},{"q":"○○○○○는 안산시 단원구 성곡동 ○○○에서 전해 내려오고있는 마을의 공동 제사이다. 이 마을제의는 ○○○의 성격을 지니고 있다는 점에서 구체적인 특징을 갖추고 있는 것으로 평가된다. 성곡동 ○○○○○는 ○○○마을 주민들이 마을 수호신에게 안녕과 무병·풍년을 빌기 위하여 올리는 마을 제사이다. 고려 성종 때부터 내려오는 마을신앙으로 제당에는 신라 마지막 임금인 경순왕의 비妃 홍씨와 장모인 안씨를 모시고 있다. 마을굿 형태로 전승되고 있으며, 성곡동 ○○○○○는 매년 10월 초순에 길일을 잡아 안말·도란말·벌말 등 인근의 10여 개 마을 주민들이 참여하고 있다. 삼현육…","a":"잿머리성황제","c":"시도무형유산","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018081010314500.jpg"},{"q":"한지는 자연에서 얻은 재료를 이용하여 필사가 가능한 종이를 만드는 기술인데, 닥나무를 채취하여 이를 삶아서 껍질을 벗기고, 피닥의 겉부분을 제거해 낸 후 잿물에 삶아내 이를 짓이겨 으깨서 섬유질을 만들어내서 이를 황촉규에서 욹어낸 물과 섞어 닥죽을 만든다. 그런 후에 한지발에 닥죽을 흘려보내는 방식으로 종이를 뜬다. 보유자 김일수씨는 할아버지 김북실, 아버지 김귀윤을 이어 3대째 한지 제지에 종사하고 있다. 1949년생으로 8세때 아버지를 도와 자연스럽게 일을 시작하여 6년만인 14살 무렵 처음 한지를 떠낸 이래 지금까지 58년간 한지를 뜨고 있다. 김일수씨는 전통한…","a":"지장(김일수)","c":"시도무형유산","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019060414211300.JPG"},{"q":"○○○이란 목조건축의 집을 짓는 대목장 이외에 건물의 문, 창문이라든가 장롱, 궤, 경대, 책상, 문갑 등 목가구를 제작하는 기술과 그 기능을 가진 목수를 말한다. 목가구는 꾸준한 수요가 있던 일상생활용품이므로 특정한 한 지역에서 생산되어 전국적으로 공급되지 않고 각 지역의 특성에 따라서 달리 생산되었다. 한국은 앉아서 생활하는 온돌방구조이므로 천장이 낮고 실내도 비교적 좁다. 따라서 시각적 부담을 줄이고 넓은 생활공간을 확보하기 위하여 작고 간결한 실용적인 가구를 정형화하였다는 점에서 규격이 크고 장식적인 면이 강조된 중국의 가구와는 다른 특징을 갖고 있다. 먹감나…","a":"소목장","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643576.jpg"},{"q":"나무판에 글자나 그림을 새긴 목각판을 각자 또는 서각이라 하는데, 인쇄를 목적으로 할 경우에는 목판본이라 한다. 글자를 반대로 새겨 인쇄방식에 따라 인쇄하는 과정도 각자라 하며 그 기술을 가진 사람을 ○○○ 또는 각수라 한다. 각자는 가장 오래된 목판본으로 알려진 신라시대의 『무구정광대다라니경』과 현존하는 가장 훌륭한 목각판인『팔만대장경』이 만들어 지는 등 사찰을 중심으로 최전성기를 이루었다. 조선시대에 들어와서도 그 기술이 전해져 훈민정음 원본을 비롯한 많은 목판 인쇄물이 간행되었다. ○○○의 기량은 각질의 흔적, 글자체의 균형도, 잘못된 글자나 글자획이 빠진 것…","a":"각자장","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623361.jpg"},{"q":"○○군 ○○면 대룡리 대춘마을을 중심으로 전승되고 있는 마을제다. 연초 정월 보름에 진행되는데 정월 초사흗날부터 마당밟기를 하고 열나흗날 별신제를 지내는 방식으로 진행된다. ○○○○○는 제례를 위해 신을 맞이하고 보내는 의례가 명확하다는 특징이 있는데, 일반적인 마을 제사와는 달리 신이 마을에 좌정해 있지 않기 때문에 별신제 때 신을 모셔와 좌정시키고 제를 마치면 다시 신을 보내드리는 순서이다. 혼맞이 절차인 청신, 제사를 모시는 오신, 보내드리는 송신의 순으로 순서가 명확하다. 또, 별신제의 제사를 포함한 모든 절차를 농악으로 행하기 때문에 농악 역시 절차와 가락이…","a":"고흥 점암 대춘별신제","c":"시도무형유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025071014504092.JPG"},{"q":"○○○○○은 동래의 지역색이 강하고, 독특한 춤가락이 가미된 남성춤이다. 이 춤은 예로부터 동래 지역 한량들이 추었던 춤으로서 전체적인 춤사위는 이 지역에서 전래되는 덧배기, 배김사위를 바탕으로 하고 있다. 일정하게 정해진 춤의 형식이나 구성 방식이 있는 것이 아니라 한량들이 놀이판을 벌일 때 흥이 고조되면 즉흥적으로 추는 개인적인 춤인 허튼춤(입춤)을 중심으로 한, 호방하고 선이 굵은 홑 춤인 남성무로서의 여유와 함께 마당춤과 기방춤이 복합되어 나타나는 특징을 가지고 있다. 본래 동래 지역의 관속들이나 기방을 출입하는 한량들이 췄던 춤인 만큼 천박하지 않고 기품이…","a":"동래한량춤","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643440.jpg"},{"q":"○○은 우리 문화 전통 안에서 전래되어 내려온 맨손 격투문화이자 민속문화로 민간에서 널리 행해졌다. ○○은 ‘각희(脚戱)’, ‘비각술(飛脚術)’이라 표현될 정도로 발기술이 탁월한 무예이다. ○○의 수련과정은 크게 혼자 익히기(개인 수련), 마주메기기(상대 수련) 등이 기본이며, 이 과정을 거친 뒤 하는 견주기(겨루기), 본때뵈기(품새 또는 형) 등의 과정이 있다 각 과정은 세분되어 있으며, 과정에 따라 발질과 손질의 동작이 거듭되어 나온다. 혼자익히기는 서서익히기와 나아가며 익히기로 구성되어져 있으며, 마주메기기는 막음질, 얼러메기기, 마주차기, 마주걸이로 구성되어…","a":"택견","c":"국가무형유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623672.jpg"},{"q":"궁(弓)은 활을 말하는 것으로써, 선사시대부터 전투용으로 사용되던 활을 전통적으로 제작할 수 있는 기술과 그 기능을 가진 사람을 ○○이라고 한다. 선사시대에 사용되었던 돌로 된 화살촉이 우리나라 전역에 걸쳐 발견되고 있으며, 기록에 의하면 삼국 이전의 부족국가였던 부여, 옥저, 마한, 진한, 변한 등에서 활을 많이 사용하였다고 한다. 활을 만드는데는 약 80일이 걸리며 재료로는 느티나무, 뽕나무, 버드나무와 소뿔을 쓰는데 시기와 재료에 따라 차이가 있다. ○○은 전통적인 공예기술로서 기능보유자로 권무석씨가 전통 활의 명산지인 경북 예천에서 대를 이어 활을 제작해 그…","a":"궁장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317403200.jpg"},{"q":"○○○○○는 전주 유씨 가문에서 대대로 빚어온 술로, 제사 때 조상에게 바치는 제사술로 사용되었고, 귀한 손님을 접대할 때도 쓰였다. 언제부터 빚기 시작했는지는 알기 어려우나 정재 선생(1777∼1861) 때에 이미 제사술로 써왔다고 하니 그 역사가 200년 이상임을 알 수 있다. 밑술을 바탕으로 덧술을 빚고 용수를 받아 걸러내는 송화주는 알콜도수가 15°∼ 18°내외의 맑은 술이다. 솔잎과 누른국화, 금은화(金銀花) 등의 첨가 재료가 풍기는 향이 매우 독특한 것으로 평가된다.","a":"안동송화주","c":"시도무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644363.jpg"},{"q":"자수는 인간의 미적욕구를 따라 복식과 함께 발달해온 분야로, 바늘을 사용하여 직물 위에 오색실로 무늬를 놓는 작업을 말한다. 자수를 놓는 기술과 그 기능을 가진 사람을 ○○○이라고 한다. 옛부터 종교적 장식 또는 의례적 행사의 복장과 함께 발달된 자수는 삼국시대 이전 부여시대부터 복식에 응용되었다. 삼국시대에는 크게 성행하여『삼국사기』중에는 고구려에서 관인들이 회의로 모일 때 수놓은 비단 옷을 입었다는 기록이 남아있다. 통일신라시대, 고려시대를 거쳐 조선시대에 이르기까지 자수는 의생활의 범주를 넘어 생활용품 속에서 광범위하게 그 장식적인 기능을 담당하여 왔다. 자수에…","a":"자수장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643387.jpg"},{"q":"○○은 조선 시대 문학 장르 가운데 하나인 시조시를 5장 형식의 선율에 얹어 노래하는 악곡 양식을 말하며 가사, 시조와 함께 정가(正歌)로 불리며 범패, 판소리와 함께 한국의 3대 성악곡으로 꼽히기도 한다. 조선 후기 양반과 중인을 중심으로 하는 풍류객들의 대표적인 연주악곡이었으며, 그들의 생활음악이기도 하였다. 줄풍류 반주에 맞춰 연주하며, 곡조는 맑고 씩씩한 우조와 슬픈 느낌의 계면조로 구별되고 남창과 여창으로 나뉜다.","a":"가곡(남창)","c":"시도무형유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/0000000001643503.jpg"},{"q":"「○○○○○」는 과거부터 현재까지 지역적, 사회적, 경제적 차이를 넘어 대한민국 국민 전체가 공동체로 참여하는 일상적 반복적 문화임. ○○는 지역을 막론하고 한국인의 식사에서는 빠질 수 없는 음식이고, 국제적으로도 그 우수성을 인정받아 한국을 대표하는 음식중의 하나로 자리매김하였다. 그리고 역사적으로 상당기간 한국문화의 중요한 구성요소로 협동과 나눔이라는 공동체 정신이 담겨진 문화로, 이러한 문화를 통해 개개인은 문중, 친․인척, 마을, 이웃, 新공동체와의 관계에서 결속을 갖게 되며 정체성을 형성하게 되었다. ○○○○○의 핵심인 ‘김장’은 자연과 인간이 함께 어우러져…","a":"김치 담그기","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2018022616350400.jpg"},{"q":"‘○○’은 오랜 역사와 전통 속에서 다양한 형태로 지속하여 왔으며, 우리 민족의 정체성과 가치를 대표해 온 전통생활관습이자 전통지식이다. ○○은 음력 팔월 보름에 해당하며, ○○은 수확기가 시작되는 ‘보름 명절’이라는 의미에서 중요하게 여겨졌다. ○○은 그동안 농사가 잘되게 해준 것을 감사하는 농공감사일(農功感謝日)이며, 곧 농사의 결실을 보게 되는 절일(節日)이다. 아울러 한 해 농사를 마무리하는 시기로서, 또 이듬해 풍농(豐農)을 기리는 시기로서 깊은 의미가 있다. 특히 전통시대 농경사회에서 ‘보름의 만월(滿月)’은 농사의 풍작(豐作)을 비롯하여 풍요 다산을 상징…","a":"추석","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2023121814531800.jpg"},{"q":"○○○○는 궁중에서 행했던 춤과 노래 중 하나로 공을 구멍에 던져 넣는 놀이를 표현한 것이다. 『고려사』, 『악학궤범』등에 의하면 ○○○○는 고려시대 때 중국에서 들어와 조선 전기까지 전승되었으며, ○○○○○는 고종(재위 1863∼1907) 때 진주부사를 지낸 정현석의 교방가요(길에서 임금을 환영할 때 행하던 노래와 춤)에서 비롯되었다고 한다. ○○○○는 몽두리(기녀나 무당이 입는 옷)에 화관(춤추고 노래할 때 쓰는 모자)을 쓴다. 진행순서를 보면 먼저 중앙에 세워진 포구문(抛毬門)을 사이에 두고 두편으로 나누어 선다. 시작을 알리는 음악을 연주하면 죽간자(대나무로…","a":"진주포구락무","c":"시도무형유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644467.jpg"},{"q":"○○○ 애○○○○은 서울 지역의 대표적인 마을굿으로서 오랜 전통을 지니고 있는데 그 역사는 적어도 257년 이상이 된다. 마을굿이지만 일반적으로 알려진 농경문화나 어촌문화와는 전혀 다른 도심의 당굿 형태를 띠고 있다. 마을 주민들은 능동적이고 적극적으로 참여하고 있으며, 당굿을 통하여 대동단결을 모색하고 있다. 뿐만아니라 관할 구청 및 문화원에서도 적극적으로 협조하여 당굿이 민관의 유기적인 협조체제로 진행되고 있다. 2005년 1월 10일 서울시무형유산 종목으로 지정되었다. 당주 무녀 보유자로는 김옥렴이 2008년 3월 17일에 인정받아 활동해 오다 2017년 11월…","a":"행당동아기씨당굿","c":"시도무형유산","r":"서울특별시","s":"성동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317544600.jpg"},{"q":"‘○○○○○’은 오랜 역사와 전통 속에서 다양한 형태로 지속하여 왔으며, 우리 민족의 정체성과 가치를 대표해 온 전통생활관습이자 전통지식이다. ○○○○○은 음력 정월 초하루에서 보름까지 해당하며, 한 해의 시작을 기념하는 인류 보편적 ‘신년맞이 명절’이다. 설은 ‘원일(元日)’,‘원단(元旦)’ 등 한 해의 첫 날임을 뜻하는 여러 이칭이 있으며, 15세기 중세국어에서 ‘새해의 첫 날, 새해의 처음’이라는 의미 외에 나이를 세는 단위로도 쓰였다. ○○○은 ‘상원(上元)’이라고도 하는데, 이는 중원(中元, 7월 15일), 하원(下元, 10월 15일)과 연관해서 부르는 한자…","a":"설과 대보름","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2023121813483500.jpg"},{"q":"○○○는 바다가 생활터전인 어촌마을에서 바다에서의 여러가지 사고를 막고 마을의 평안과 풍어를 기원하는 제사의식을 말한다. 황도에서도 매년 음력 1월이면 2일과 3일 이틀에 걸쳐 풍어와 마을의 평안을 비는 당제를 벌인다. 황도 ○○○○○의 유래에 대하여는 옛날 안개 자욱한 밤이면 지금의 황도 당산에서 밝은 불빛이 발하여 항로를 잃고 표류하는 배들이 무사히 귀향할 수 있게 하여 당집을 짓고 제사를 모시며 신성하게 여겼다 한다. 제의식을 주관하는 제주는 1년간 부정하지 않은 사람으로 선출하며 제물로는 동쪽에서 구한 부정하지 않은 소를 잡아 사용하는데, 돼지는 제신으로 모시…","a":"황도붕기풍어제","c":"시도무형유산","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643977.jpg"},{"q":"○○○○○은 ○○광역시 서구 서대신동 일대의 옛 지명인 ○○○○ 지역에서 행해졌던 걸립으로, 한 해를 시작하는 정초에 나쁜 일은 물리치고 좋은 일만 있기를 바라는 뜻에서 가가호호 방문하여 제액초복(除厄招福) 또는 벽사진경(辟邪進慶)을 기원했던 풍물굿으로, 복을 빌어준 대가로 쌀이나 돈을 조금씩 받았기 때문에 걸립굿이라 부르기도 했다. 걸립을 할 때 1860년경에 세워진 대신동 지역의 당산인 “시약산 당산”에서 당산제를 지내는 것을 감안하면 ○○○○○은 약 150년 이상의 역사를 가진 전통민속이다. ○○○○○은 기수, 악사, 잡색 등 총 37명으로 구성되어 있으며, 먼…","a":"부산 고분도리걸립","c":"시도무형유산","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643455.jpg"},{"q":"「○○○」은 전통 부채를 만드는 기술과 그 기능을 보유한 장인을 말한다. 우리나라의 부채는 형태상으로 크게 둥근 모양의 부채와 접고 펼 수 있는 접(摺)부채로 나눌 수 있다. 그 중 접부채인 합죽선(合竹扇)은 현재까지 전승되는 최고 수준의 정교함과 세련미를 갖춘 부채이다. 합죽(合竹)이란 부채를 만들 때 대나무의 겉대와 겉대를 붙여서 부채살을 만드는 기법으로 조선 후기 정조대 이후 전라감영이 있는 전주의 선자청(扇子廳)이나 통제영이 있던 통영의 선자방(扇子房)이라는 관청에서 군영 소속의 장인들이 주로 제작하였다. 합죽선은 국가의 수요와 대외무역에 활용되었으며, 192…","a":"선자장","c":"국가무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2586074.jpg"},{"q":"‘○○○○○’는 ○○특별자치시 부강면 ○○○에서 음력 정월 열나흗날 마을의 안과태평(安過太平)과 재액소멸(災厄消滅)을 빌며 지내던 마을의 제의로, 탑제를 지내기 전 똥수깐태우기, 낙화내리기를 진행하는 것은 여타 지역의 유사한 동제와 비교했을 때에도 차별성과 특수성을 가지고 있음","a":"세종 등곡리동제(똥수깐태우기, 낙화내리기, 탑제)","c":"시도무형유산","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025030414560390.JPG"},{"q":"○○○○는 농경의식의 하나인 일종의 편싸움 놀이로 길쌈이라고도 한다. 마을을 육지와 바닷가쪽 두 편으로 나누는데 생산의 의미에서 여성을 상징하는 바닷가 쪽이 이겨야 풍년이 든다고 한다. ○○○○는 윤년 음력 3월초에 재앙을 막고 풍년을 기원하는 당제를 지낸 다음 행해졌다. 전설에 의하면 당진의 ○○○리는 풍수적으로 옥녀가 베짜는 형국이어서 베를 양쪽에서 잡아당기는 시늉을 한데서 ○○○○가 생겼다고도 하고, 지형이 지네형이라서 지네모양의 큰 줄을 만들어 ○○○○를 했다고도 전해진다. 줄의 길이는 50∼60m이며 지름이 1m가 넘는 경우도 있어 사람이 줄을 타고 앉으면…","a":"기지시줄다리기","c":"국가무형유산","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623746.jpg"},{"q":"제주특별자치도 무형유산으로 지정된 ○○○○는 제주 지역에서 불리는 대표적인 밭일노래이다. 제주 지역은 화산회토의 자연 환경이 말해 주듯 밭일과 관련한 민요들이 많이 불렸다. 무형유산으로 지정된 ○○○○는「밧 불리는 소리」·「진사대 소리」·「타작질 소리」등 세 수이며, 기능 보유자는 이명숙(여, 74)이다.","a":"제주농요","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644729.jpg"},{"q":"명주는 누에고치에서 풀어낸 견사(絹紗)로 짠 무늬가 없는 평직 직물이다. 일반적으로 견사로 만든 견직물을 ‘비단’이라고 하지만 견사 종류와 세직 및 무늬에 따라 종류가 다양하다. 우리나라의 양잠은 그와 관련된 기록이 고조선 때부터 나타날 정도로 오랜 역사를 가지고 있다. 신라시대에는 정교한 직물을 당나라에 보내기도 하였을 정도로 섬세한 기술을 가지고 있었다. 고려시대에는 보다 질이 좋은 견직물이 생산되었고, 조선시대에는 종류가 다양해서 색과 품질로 이름이 붙게 되었다. 그 중 명주가 가장 많이 생산되어 일상적인 옷감재료로 사용되었다. 제직방법과 제직상태, 산지와 원료…","a":"명주짜기","c":"국가무형유산","r":"경상북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624035.jpg"},{"q":"‘○○○○’는 콩을 사용하여 만든 식품인 장(醬) 그 자체의 효능을 넘어, 재료를 직접 준비해서 장을 만들고 발효시키는 전반적인 과정을 포괄하는 개념이다. 두장(豆醬)문화권에 속한 우리나라에서는 삼국시대부터 장을 만들어서 먹은 것으로 알려져 있다. 또한, 조선시대 왕실에서는 장을 따로 보관하는 장고(醬庫)를 두었으며, ‘장고마마’라 불리는 상궁이 직접 장을 담그고 관리하는 등 전통적으로 우리나라의 장은 식생활에서 중요한 위치를 차지해 왔다. 우리나라의 ‘○○○○’는 콩 재배, 메주 만들기, 장 만들기, 장 가르기, 숙성과 발효 등으로 이어지는 과정을 발전시켜왔다는 점…","a":"장 담그기","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2018122811081400.JPG"},{"q":"○○○○는 우리나라 전통의 운반수단이었던 지게를 이용한 민속놀이이다. 산이 많고 따로 길이 없는 농촌과 산촌에서는 지게가 필수적인 운반수단이었다. 강원특별자치도 양구지방에서는 노동의 고달픔과 단조로움을 잊고 즐거움을 얻고자 지게를 이용한 놀이를 했다. 양구 ○○○○○이에는 개인적으로 승부를 내는 지게걸음싸움과 단체로 하는 상여놀이가 있다. 지게걸음싸움은 지게의 두 다리 위에 올라가 지게 머리를 잡고 걸어가서 상대를 부딪쳐 쓰러뜨리는 놀이이다. 상여놀이는 편을 갈라 지게를 서로 묶어서 상여를 만들어 메고 구성진 상여소리를 부르며 어르다가 상대의 상여를 밀어 쓰러뜨린다.…","a":"양구돌산령지게놀이","c":"시도무형유산","r":"강원특별자치도","s":"양구군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643734.jpg"},{"q":"○○○○○ 들노래는 ○○군 신북면 ○○○에서 전승되어 오는 영산강 하류 논농사 노래를 대표하는 들노래로 원형대로 보존 전승되고 있다. ○○○ 들노래는 벼 농사의 전 과정을 담았고 농사로 인한 피로를 노래로 풀며 일을 했던 우리 조상들의 지혜도 담겨 있다. 노래의 구성은 ①모찌기소리 ②모심기소리 ③논매기소리 - 초벌매기 (오전 들내기 소리, 오후 들내기 소리) ④두벌매기(오전 들내기소리, 오후 들내기소리), 만드리(우야소리), 장원풍장소리(아롱대롱)이다. ‘○○○ 들노래’는 오전 들내기와 오후 들내기라는 독특한 특징이 있다. 이는 전통적인 농요의 형식에 얽매이지 않는…","a":"영암 갈곡리 들소리","c":"시도무형유산","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101715440200.JPG"},{"q":"배첩이란 글씨나 그림에 종이, 비단 등을 붙여 족자·액자·병풍 등을 만들어서 아름다움은 물론 실용성 및 보존성을 높여주는 전통적인 서화처리법을 가리키며, ○○○은 조선 전기에 회화를 담당하던 국가기관인 도화서 소속으로 궁중의 서화처리를 전담하던 사람을 말한다. 배첩은 통일신라와 고려를 거쳐 발전하였으며, 조선시대에는 ○○○이라는 전문가가 등장할 만큼 성황을 이루었다. 배첩의 제작기법과 형태는 액자·병풍·족자·장정 및 고서화 처리의 다섯 가지이다. 액자는 비단 재단 ―그림 초배(初褙) ―재배(再褙) ―건조·액자틀 준비 ―조립의 작업과정을 거친다. 병풍의 한 폭 처리도…","a":"배첩장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623604.jpg"},{"q":"누비는 옷감의 보강과 보온을 위해 옷감의 겉감과 안감사이에 솜, 털, 닥종이 등을 넣거나 또는 아무것도 넣지 않고 안팎을 줄지어 규칙적으로 홈질하여 맞붙이는 바느질 방법이다. 우리나라의 누비는 면화재배 이후 적극적으로 활성화되었으며 조선시대의 다양한 실물자료들이 전해지고 있다. 승려들이 일상복으로 입는 납의(衲衣)는 헤진 옷을 수십 년 동안 기워 입은 것에서 유래하였으며, 이는 점차 누비기법으로 발전하여 방한과 내구성, 실용성 등이 뛰어나 일반인들 사이에서도 널리 사용되었다. 누비는 누비 간격이나 바느질 땀수에 따라 세누비·잔누비·중누비 등으로 나뉘며, 형태에 따라…","a":"누비장","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624057.jpg"},{"q":"‘○○○○’은 서도지방(황해도와 평안도)에서 전문 소리꾼들이 부르던 민속 성악의 한 갈래로, 앉아서 부른다 하여 좌창(坐唱)이라 부른다. 황해도 출신의 실향민들이 많이 정착한 인천에서도 서도소리의 전통이 이어지고 있다.","a":"서도좌창","c":"시도무형유산","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025032509320790.jpg"},{"q":"○○○은 예전에 공조工曹 교서관校書館, 선공감膳工監에서 조각일을 맡았던 장인을 말한다. 조각은 쇠끌로 선이나 면을 파고 표면에 무늬를 만드는 기법이다. 우리말로는 ‘파기’인데 주금鑄金이나 단금鍛金 따위의 표면을 장식하는 기술이다. 기법으로는 평각平刻, 육각肉刻, 투각透刻, 고각高刻, 상감象嵌 등 여러 가지가 있다.","a":"조각장","c":"시도무형유산","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022092109071900.jpg"},{"q":"밤섬 ○○○○○은 제례 형식과 무굿이 복합된 마을굿이다. 애초에 밤섬 ○○○은 한강 밤섬에 위치했었다. 1968년 한강 개발에 의해 마을이 해체되고 주민들이 마포구와 와우산에 모여 살게 되면서 ○○○○ 현재 마포구 창전동 28번지에 세워지게 되었다. 마을굿이지만 한강문화와 직접적으로 관련되어 있어 주목할 만하다. 이는 서울문화와 역사 속에서 신앙행위의 한 면을 알아보는 데 중요한 의미를 갖고 있는 당굿이다. 2005년 1월 10일 서울시무형유산 종목으로 지정되었다. 당주 무녀 보유자로는 김춘강이 2008년 3월 17일에 인정받아 활동해 오고 있다. 악사 분야의 보유자…","a":"밤섬부군당도당굿","c":"시도무형유산","r":"서울특별시","s":"마포구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409132400.jpg"},{"q":"○○○○는 우리나라 서남부의 남도민요, 서북부의 서도민요, 중부의 경기민요와 구별하여 붙여진 이름으로 함경도, 강원특별자치도, 경상도 및 동해안 일대에서 전승되는 민요를 일컫는다. 보유자 박수관이 보유하고 있는 보유곡은 백발가, 영남모노래, 상여소리, 치이야 칭칭나네, 장타령 5곡으로 ○○○○로서의 음악적, 문학적, 민속학적 특징을 대체로 잘 간직하고 있다. 박수관은 ○○○○권의 메나리토리를 가지고 소리하는 향토소리꾼으로 지금까지 소외되었던 ○○○○의 전승을 위해 국내외를 망라하여 활발한 전승활동을 하는 등 ○○○○의 보존과 육성을 위해 애쓰고 있다.","a":"동부민요","c":"시도무형유산","r":"대구광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016030817201501.jpg"},{"q":"‘○○○○’은 제주지역에서 오랫동안 전승되어 온 굿으로, 그 안에 음악·춤·놀이 등이 한데 어우러지고 지역민의 살아온 내력이 온전히 담겨있는 종합적 형태의 무속의례이다. 의례는 보통 큰 심방을 포함하여 5명 이상으로 구성하여 짧게는 7일에서 길게는 대략 보름 정도 진행한다. ‘○○○○’은 오랜 역사적 내력을 지니고 있고, 우리나라 굿의 원형을 간직하고 있으며, 제주지역 음악·춤·구비서사시·놀이 등을 다양하게 포함하고 있어 학술적 가치가 높다. 또한, 수많은 신(神)들을 초대하여 제청(祭廳)에 앉히는 의식부터 시작하여, 영신(迎神)-오신(娛神)-송신(送神)의 완벽한 제…","a":"제주큰굿","c":"국가무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2021122216303200.JPG"},{"q":"가야금은 삼국시대부터 제작 보급된 우리의 전통 국악기로서 가얏고라고도 한다. 오동나무 공명반에 명주실을 꼬아서 만든 12줄을 세로로 매어 각 줄마다 안족(雁足)을 받쳐놓고 손가락으로 뜯어서 소리를 낸다. 줄풍류를 비롯해 가곡반주ㆍ가야금산조ㆍ가야금병창 등 한국음악 전반에 걸쳐 사용되고 있는데, 다행히 우리시 관내에서 가야금 제작만을 외길로 해오고 있는 장인이 있어 가야금 제작 종목을 전통문화의 보존 및 전승 차원에서 우리시의 무형유산으로 지정함.","a":"악기장(가야금)","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643593.jpg"},{"q":"모시는 오랜 기간동안 이용되어 온 직물로서 일명 저포·저치라고도 하며, 모시풀을 베어 그 껍질을 벗긴 것을 재료로 한다. 통일신라 경문왕(재위 861∼875) 때 당나라에 보낸 기록으로 보아 외국과의 교역품으로 이용되었음을 짐작할 수 있다. 모시풀은 다년생으로 뿌리쪽 줄기가 황갈색으로 변하며, 밑의 잎이 시들어 마를 때 수확한다. 보통 1년에 3번 정도 수확하는데 5월∼6월초, 8월초∼8월하순, 10월초∼10월하순이며 두번째 수확한 모시가 품질이 제일 좋다. ○○○○는 한산에서 만드는 모시로 예로부터 다른 지역에 비해서 품질이 우수하며 섬세하고 단아하여 모시의 대명사…","a":"한산모시짜기","c":"국가무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623725.jpg"},{"q":"○○○○란 공자를 모시는 사당인 문묘에서 지내는 제사의식으로, 문묘대제 또는 석전제(고기를 올리고 음악을 연주하는 의식)이라고도 한다. 유교가 언제부터 우리나라에 전래되었는지에 대한 기록은 없지만 고구려 소수림왕 2년(372)에 태학(유교 교육을 위한 국립대학)을 설립하였다는 기록을 통해 고대 중국의 제사 관례에 따라 의식을 행하였을 것으로 추측된다. ○○○○는 매년 2월과 8월 정해 놓은 날에 공자를 비롯한 옛 성인들의 학덕을 추모하며 지낸다. 절차는 영신례, 전폐례, 초헌례, 공악, 아헌례, 종헌례, 음복례, 철변두, 송신례, 망료의 순서로 진행된다. 연주 음악은…","a":"석전대제","c":"국가무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623311.jpg"},{"q":"○○○○은 꽃피는 봄철을 맞이하여 신(神)의 음덕에 감사 하기 위해 행하는 무속 의례이다. 이 굿에는 무당이 자기 자신을 위해 하는 것과 재가집(단골집)의 요청으로 하는 것이 있다. 무당이 자신이 모신 신령님과 자신을 위해 하는 신굿은 자신의 건강과 무업(巫業) 번창을 재가집을 위한 굿은 집안의 평안을 감사하는 것이 목적이다. 즉 ○○○○은 신에게 감사하는 것이 목적이며, 무사태평, 무병장수, 부귀공명을 비는 기복적 내용이 담겨 있다","a":"꽃맞이굿","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010414565100.jpg"},{"q":"목조각은 목재를 소재로 나무가 가진 양감과 질감을 표현하는 조각이다. 목조각의 재료로는 결이 아름답고 견실한 오동나무, 소나무, 전나무, 은행나무, 느티나무, 회화나무 등이 많이 사용되어 왔다. 우리나라는 삼국시대때 불교가 전해지면서부터 사찰 건축과 불상 등 불교 의식과 관련된 조각들이 제작되기 시작한 것으로 보이지만 여러 차례의 전란으로 인해 대부분 소실되거나 분실되어 전하는 것은 많지 않다. 목조각의 제작과정을 살펴보면 먼저 잘 건조된 목재 위에 밑그림을 그린 뒤 목재의 필요 없는 부분을 쳐내는데 이것을 걷목이라고 한다. 걷목으로 대충의 행태가 드러나면 불상의 속…","a":"목조각장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624425.jpg"},{"q":"「○○○○○ 소리」는 ○○○일대에서 벌목 및 뗏목 제작, 목재운반 등 노동을 하면서 불려진 노래이다. 함경도의 개마공원에는 하늘이 보이지 않을 정도로 우거진 낙엽송 삼림이 있으며, 이 원목을 채벌하여 ‘소발귀’라는 썰매로 백두산 동남부의 해발 1500미터 이상되는 무산고원 하구인 삼장까지 운반한 후, 뗏목으로 묶어서 ○○○에 띄워 운반하였다. 이 과정에서 노동자들이 각 작업과정별로 불렀던 수많은 노래들이 구전되어「○○○○○ 소리」로 불려지게 되었다.","a":"두만강뗏목놀이소리","c":"이북5도 무형유산","r":"함경북도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2669385.jpg"},{"q":"○○○○○의 유래는 오랜 옛날부터 고창고을의 허(虛)를 메꾸기 위하여 5방에 세운 자연신체의 당산으로 유지되어 왔으나, 조선후기 정조 년간(1790년대)에 전라도 일대에 홍수피해로 엄청난 질병 때문에 피막(避幕)에서 시달림을 겪자, 어명에 의하여 화주(化主)를 자청한 고을 아전들이 민심수습을 위해 고을의 수구막을 보호하고자, 인공적 역사를 시작하여 중거리․중앙․하거리의 저지대 당산을 완공하였다. 마을신앙의 표적으로서의 의미도 있거니와, 전국에서 유일한 가족 당산형태로 된 고을의 풍수적인 집단 신앙적 화표로서도 유명하며, ○○○○○보존회에서는 매년 ○○○○○ 및 대보름…","a":"고창오거리당산제","c":"시도무형유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644158.jpg"},{"q":"○○○○○는 큰 건물이나 집을 지을 때 망깨라는 도구를 이용하여 담장이나 기둥을 세울 곳의 땅을 다지던 작업(망깨질)과 그 과정에서 소리꾼이 부르는 노동요(○○○○)가 포함된 전통민속으로 각 지방에 따라 특색이 있으며 부산지역의 망깨질은 오행법과 오행지신누르기가 특색이다. 망깨란 넓적한 돌 또는 쉿덩이를 4∼5개의 손잡이나 줄에 매어 만든 것인데, 부산에서는 다른 곳과는 달리 넓적한 돌을 사용한다. 일꾼들이 줄을 힘껏 당겨 올렸다가 놓으면 망깨가 땅에 부딪치면서 점점 견고하게 다져진다. 이처럼 터를 다지기 위해 망깨로 땅을 다지는 일을 망깨질이라고 하고, 망깨질을 할…","a":"구덕망깨소리","c":"시도무형유산","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643436.jpg"},{"q":"제주도의 ○○○○은 부처님께 드리는 음성공양과 재(齋)공양의 측면에서 육지부의 지역과는 다른 모습을 하고 있다. 특히 음성공양인 범음(梵音) 곧 범패(梵唄)는 ○○○○ 중에서 재를 올리기 위해 부처님께 바치는 음악으로, 인간의 염원을 부처님께 전달하는데 사용된 현재까지 전하는 의식요(儀式謠)이다. ○○○○○은 제주에 불교가 유입, 전승되면서 제주의 전통문화와 연계되어 육지 지방과는 차별되는 특징이 있다. 즉 ○○○○ 세시의례 중 칠성제와 산신제가 육지지방에 비해 성대히 진행되고 있다. 이는 제주의 무속의례 중 산신제와 칠성제가 ○○○례와 연계되어 전승되고 있기 때문이…","a":"제주불교의식","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644718.jpg"},{"q":"○○○○은 우리나라 사람들이 그해의 나쁜 운을 풀기 위해 벌였던 굿판에서 무당이 나뿐 기운을 풀기 위해 추는 즉흥적인 춤을 말하며, ‘도○○○○’ 또는 ‘허튼춤’이라고도 한다. 원래는 수건춤, 산조춤, 즉흥춤 이라는 이름의 수건춤이었으나 춤꾼 한성준이 1903년에 극장공연에서 살풀이란 말을 쓴 데서부터 살풀이라는 이름이 비롯되었다. 춤꾼은 고운 쪽머리에 비녀를 꽂고 백색의 치마 저고리를 입으며, 멋스러움과 감정을 한껏 나타내기 위해 하얀 수건을 들고 살풀이 곡에 맞추어 춤을 춘다. 지금의 ○○○○은 경기지방과 호남지방에서 계승된 춤으로 알려지고 있으며, 조선 중기 이…","a":"살풀이춤","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623351.jpg"},{"q":"전통사냥 방법은 여러가지가 있으나 매를 길들여 꿩이나 토끼 등을 잡는 ○○○은 그 역사가 오래 되어 고대 이집트, 페르시아 등지에서 행하였다는 기록이 있다. 이 사냥법은 인도에서 기원하였다는 설이 있을 만큼 인도지방에서 크게 성행하였고, 중국에서는 원나라 때에 유행하였다. 고구려 고분벽화의 ○○○ 그림이나 『삼국유사』,『삼국사기』등의 ○○○ 기록을 보면 우리나라도 오랜 옛날부터 ○○○이 성행되었음을 알 수 있다. 간도(間島)와 북한지방에서 해동청(海東靑)이라는 우수한 매가 산출되어 중국과 일본에 수출하기도 했다. ○○○은 특히 귀족층 사이에서 성행되어 고려시대에 매의…","a":"매사냥","c":"시도무형유산","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643577.jpg"},{"q":"농요는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로 들노래 또는 농사짓기소리라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수도 있다. 예천 ○○○○는 낙동강 연안을 중심으로 널리 전승되던 노동요이다. 내륙의 외딴 마을이었기에 이웃 문화의 유입과 혼합됨이 없이 오직 이 마을에서만 불려진 순수한 민요이다. 내용은 모심기노래·논매기소리·타작소리·걸채소리·칭칭이(쾌지나칭칭) 등으로 짜여진다. 모심기노래는 모를 심으면서, 논매기소리는 논을 매면서, 타작소리는 보리를 타작하면서, 칭칭이는 논매기 후에 밭을…","a":"예천공처농요","c":"시도무형유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644314.jpg"},{"q":"○○○은 문방사우(文房四友)의 하나인 붓을 만드는 사람과 그 기술을 말한다. 붓은 먹을 함유하되 균일하게 발산할 수 있어야 하고, 마모에 오래 견딜 수 있는 내구력과 붓끝인 호의 갈라짐이 없어야 하고, 탄력과 유연성을 유지해야 한다. 이런 조건을 충족시킬 수 있는 재료로 양의 겨드랑이 털, 족제비 꼬리털, 산토끼털 등 여러 동물들의 털이 사용되는데, 추운 내륙지방의 짐승일수록 품질이 좋다. 붓의 구성은 촉과 붓대롱, 그리고 큰붓의 경우 붓촉과 붓대롱을 연결하는 각통으로 되어있는데, 붓대롱은 주로 대나무를 사용하고, 각통은 참죽나무를 많이 쓴다. 붓의 제작과정은 선별-…","a":"모필장","c":"시도무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2024031517554902.jpg"},{"q":"○○○○은 예로부터 고창, 무장, 영광 등지의 해변을 끼고 형성된 농악이다. 호남 우도 농악의 일반적인 성격을 지니면서도 잡색놀음이 다양하게 발달한 점과 고깔소고놀음이 잘 정리되어 있다는 점이 특징이다. 고깔소고놀이는 머리에 고깔을 쓰고 삼채가락에 맞추어 춤을 흥겹게 추는 것으로서 가락의 진행과 상황전개에 따라 즉흥적인 동작을 유연하게 구사하는 것이 특징이다. 강모질의 제자인 정창환 씨는 소고 부문에서 보유자로 인정되어 현재는 고창동리국악당 및 ○○○○전수관에서 후진양성을 위해 심혈을 기울이고 있다.","a":"고창농악","c":"시도무형유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644101.jpg"},{"q":"탈춤이란 한사람 또는 여러 사람이 가면으로 얼굴이나 머리 전체를 가리고 다른 인물, 동물 또는 초자연적 존재(신) 등으로 분장하여 음악에 맞추어 춤과 대사로써 연극하는 것을 말한다. 탈춤은 조선 전기까지 각 지방에서 행해지던 가면놀이이다. 17세기 중엽에 이르러 궁중의 관장하에 “산대”라 불리는 무대에서 상연된 산대도감극(山臺都監劇)의 형태로, 조선 인종 12년(1634)에 궁중에서 상연이 폐지되자 민중에게 유입되어 전국으로 전파되었다. ○○○○은 단오에 2∼3일 동안 행해지고 그 밖에 석가탄신일과 7월 백중놀이로도 행해진다. 약 200∼300년 전에 난리를 피하기…","a":"은율탈춤","c":"국가무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623483.jpg"},{"q":"구리시 ○○○○○은 구리시에 소재하고 있으며 보유자는 악사로 허용업이 무녀로는 조순자가 지정되어 있으며, 전수조교는 허재훈이다. 이 굿은 전형적인 ○○○의 명칭을 사용하지만, 경기도 북부의 마을 당굿 형태로 되어 있는 것이 주요한 특징이다. 경기도 남부의 화랭이가 하는 당굿과 다르다. ○○○은 달리 속칭으로 ‘갈매울’이라고도 하는데 이 마을에 전승되는 굿을 ○○○○○이라고 일컫는다. 경기도 남부의 ○○○과는 다르게 경기도 북부에서 강신무와 마을 사람들에 의해서 주도되는 ○○○이라는 점에서 차별화된다. ○○○○○의 제일은 음력 3월2일에서 3월 3일까지이므로 음력 3월…","a":"구리갈매동도당굿","c":"시도무형유산","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643636.jpg"},{"q":"이원진이 쓴『탐라지』에 다용소주(多用燒酒)라는 기록이 있는데 바로 이 ○○○○을 두고 하는 말이다. 이 술은 발효주인 오메기술을 증류시킨 것으로 조를 비롯한 잡곡을 재료로 삼았다. 술독에 묻어둔 밑술을 솥에 넣어 고소리로 증류해서 소주를 고아내는 것을 ‘술닦는다’라고 하고, 그 술을 두고 ○○○○이라고 한다. 제주도에서 소주를 빚는 전통적인 용구로는 소줏돌과 고소리 두 가지가 있다. 소줏돌은 솥뚜껑처럼 돌을 다듬어 만든 것인데, 한가운데 구멍이 나 있다. 고소리는 소주를 고아내리는 오지그릇이다. ○○○○을 만들 때 누룩이 썩어서 검은색이 나지 않아야 하고, 술이 신맛…","a":"고소리술","c":"시도무형유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644702.jpg"},{"q":"악기를 만드는 장인을 ○○○이라 한다. 조선시대 경국대전의 공전(工典)공장조(工匠條)등에 풍물장(風物匠)쟁장(錚匠),고장(鼓匠)등의 악기와 관련된 장인들의 명칭이 보인다. 우리나라에서 제작되어 현재까지 전승되는 악기는 대략 60~70여 종으로 그 중에는 우리 고유의 악기와 중국 또는 서역에서 유래한 것들이 있다. 이 모두를 만드는 장인은 없으나 각각의 종목을 통합하여 ○○○으로 분류하여 지정하고 있다. 명확한 기록은 없지만 악기를 만드는 전문적인 장인들은 삼국시대부터 있었을 것으로 생각된다. 고구려 고분벽화에느 다양한 관악기,현악기.타악기 등이 등장하며, 신라 범종…","a":"악기장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022071411292300.JPG"},{"q":"○○○은 얇게 저민 대나무 껍질을 색색으로 물을 들여 다채로운 기하학적 무늬로 고리 등을 엮는 기능 또는 기능을 가진 사람을 말한다. 언제부터 ○○○이 있었는지 확실하지는 않지만 채상은 고대 이래로 궁중과 귀족계층의 여성가구로서 애용되었고, 귀하게 여겨졌던 고급공예품의 하나였다. 조선 후기에는 양반사대부 뿐만 아니라 서민층에서도 혼수품으로 유행하였으며, 주로 옷·장신구·침선구·귀중품을 담는 용기로 사용되었다. 채상의 제작기술은 대나무 껍질을 균등하게 떠내는 데에서 시작된다. 대나무껍질을 입으로 물어 얇게 떠낸 다음, 떠낸 대나무 껍질을 물에 불린 후 그것을 무릎에 대…","a":"채상장","c":"국가무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623858.jpg"},{"q":"○○○○란 중부지방의 탈춤을 가리키는 말이다. ○○○○○는 서울·경기 지방에서 즐겼던 산대도감극(山臺都監劇)의 한 갈래로 춤과 무언극, 덕담과 익살이 어우러진 민중의 놀이이다. 이 놀이는 매년 정월 대보름과 단오·백중·추석에 명절놀이로 공연되었다. 송파마을은 경기일원의 상업근거지였는데 약 200년전 송파장이 가장 번성하던 때에 ○○○○가 성행하여 오늘날까지 전하는 놀이형태로 완성되었다고 한다. ○○○○○는 전체 7과장으로 구성되어 있으며, 놀이에 앞서 가면과 의상을 갖추고 음악을 울리면서 공연장소까지 행렬하는 길놀이를 하고, 가면을 배열해 놓고 고사를 지낸다. 놀이내…","a":"송파산대놀이","c":"국가무형유산","r":"서울특별시","s":"송파구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623244.jpg"},{"q":"지성자는 1945년에 태어나 모친인 성금련에게 가양금산조를 전수받았다. 8세때 발표회를 시작하여 다수공연과 연주회를 통해 입상하였다. 성금련류 ○○○○○는 전통을 중시하는 고집스러움과 투철한 예술감각으로 국내 최초 15현 가야금 개량 및 연주곡들을 작곡하여 ○○○○○의 신기원을 이룩하였다.","a":"가야금산조","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644162.jpg"},{"q":"당진 ○○○은 사라져가고 있는 야장기술의 전통을 4대째 100여년 이상 가업으로 계승해 오고 있는 곳이다. 당진은 예로부터 아산만을 중심으로 해양과 육지의 문화가 접목된 독특한 내포문화권을 형성하고 있는 곳으로 야장분야에서도 타 지역과 다른 농경 . 어업 도구를 제작하였다. 구체적으로는 장어잡이용 창, 고기잡이용 창, 수초제거용 낫, 긁갱이, 닻, 굴따기 조새, 갯벌용 호미, 갯벌용 쇠스랑 등을 비롯하여 각종 그물 수선도구와 배 수선용 도구 등의 어로도구 및 자귀, 가래, 천치 등의 농경도구 등에 당진 ○○○ 만의 철물강화 기술 및 전통기법을 적용한 점이 돋보인다.…","a":"대장장(당진)","c":"시도무형유산","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019042410083100.jpg"},{"q":"○ 우리나라 유기는 청동기의 주조로부터 시원을 찾을 수 있으며 이러한 유기의 제조방법은 단 조(두드림)로 만드는 방짜유기와 주조(틀에 무어 제작)로 만드는 주물 유기로 구분된다. 방짜유기는 향동이라고도 하며 전통악기나 식기류를 만들고 주물유기는 추동이라 하여 거푸집을 쓰는 주물기법으로 만든다. ○ 박갑술(朴甲述)은 50년 이상을 주물 유기 제작에 종사하였으며 사라져가는 전통기법인 구름식 돌림틀을 직접 제작하여 가질작업을 하는 등 전통 주물 유기의 명맥을 유지하고 있어 전승 보존의 필요가 있어 지정하고자 하는 것임.","a":"주물유기장","c":"시도무형유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643928.jpg"},{"q":"○○○는 조선초기부터 모든 수륙의 고혼 천도를 위하여 행해졌던 불교의례로 『조선왕조실록』에 설행기록이 나타나는 등 역사성과 예술성이 높으며, 개인 천도의 성격을 띤 영산재에 비해 대중적 성격이 두드러지고 낮재 · 밤재 합설이라는 의례상 특수성을 지니고있다. ○○○○○는 경남 일대에서 전승되던 범패의 맥을 이어 의례와 음악적 측면에서 경남 지방의 지역성을 내포하고 있는 불교의례로 가치가 크다.","a":"아랫녘 수륙재","c":"국가무형유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1755845.jpg"},{"q":"옹기는 질그릇과 오지그릇에 대한 총칭으로 질그릇은 유약을 시유하지 않은 도기陶器이고, 오지그릇은 잿물 유약을 시유한 도기로 좁은 의미에서의 옹기에 해당한다. 고려시대까지는 유약을 바르지 않은 도기가 위주가 되었으나 조선시대 중기부터 옹기에 해당하는 약토藥土를 바른 흑갈색의 도기가 제작되면서 조선후기에는 유약을 입힌 시유도기施釉陶器가 일반화된다. 기록에 의하면 고려시대 이전부터 ‘옹甕(瓮)’으로 지칭되는 대형의 도기 항아리가 술·물·장·젓갈 등 액체나 음식을 담거나 저장하는 용도로 사용된 것으로 나타난다. 최근 태안 마도해역에서 출토된 다량의 고려시대 도기 항아리들이…","a":"옹기장","c":"시도무형유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091410540200.JPG"},{"q":"옹기는 도자기의 도기에 해당하는 것으로 질그릇이나 오지그릇처럼 진흙만으로 반죽해 구운 그릇을 말한다. ○○○ 보유자 방춘웅 씨는 옹기점을 운영하던 증조부 방호연, 조부 방연하, 부친 방순복의 뒤를 이어 옹기 작업을 생업으로 해왔다. 부친이 일찍 작고하시어 12살(1954년) 때부터 이영준 씨를 스승으로 삼고 전통옹기 제작 기법과 기능을 전수받았다. 그후 옹기수품대장으로 인정받아 가마짓기, 충청도 정통옹기 만들기(큰독, 작은독, 각종 오짓그릇 및 질그릇, 푸레독), 불떼기 등을 계승하였다. 2001년부터 옹기체험 및 교육프로그램을 운영하여 전승활동을 이어가고 있다.","a":"옹기장(홍성)","c":"시도무형유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644040.jpg"},{"q":"○○○이란 인류가 오랫동안 사용하였던 쇠를 녹여서 각종 기물을 만드는 장인을 말한다. 우리나라에서 주조물을 사용하기 시작한 시기는 대략 기원전 6세기∼5세기 경으로 추정되며, 문헌 자료로는 『삼국지』「위지 동이전」에 쇠가 생산되고 매매되었다는 기록이 있다. 인류문명 발달에서 쇠가 매우 중요한 역할을 하였으므로 고대부터 쇠를 이용하여 필요한 물품을 만드는 기술과 장인은 국가적인 관심사였다. 또한 한반도에 불교가 정착되면서 사찰이 건립되었고 이와 관련하여 많은 범종이 제작되었다. 이처럼 쇠를 녹여서 범종을 비롯한 각종 쇠제품을 만드는 장인을 ○○○이라고 한다. 우리나라…","a":"주철장","c":"국가무형유산","r":"충청북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623690.jpg"},{"q":"싱싱한 소나무 마디 삶은 물과 쌀로 빚어 만들며, 약으로도 쓰이는 술이다. 송절주를 언제부터 빚어 마셨는지 그 유래에 관해 정확히 알수는 없지만, 『동의보감』·『고사십이집』·『규합총서』·『임원경제지』·『부인필지』등의 기록으로 보아 조선시대 서울 부근의 중류계층에서 빚어 마시던 것으로 추측된다. 만드는 방법은 멥쌀과 물, 누룩가루, 밀가루, 찹쌀, 소나무 마디 삶은 물을 잘 혼합해서 너무 차지도 덥지도 않게 하여 익힌다. 봄에는 진달래, 가을에는 국화를 넣고, 겨울에는 유자껍질을 위에 매달아 익히면 솔향기와 꽃향기가 입에 가득하여 맛이 더욱 좋다. 송절주는 독특한 소나…","a":"서울송절주","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643373.jpg"},{"q":"오죽은 예로부터 충효정절을 상징하여 매우 신성시 여기던 대나무로, 중국에서는 자죽, 일본에서는 흑죽이라 불러왔다. 오죽의 색채는 매우 아름답고 다양하며 표면 또한 칠이 필요없는 뛰어난 재료이다. 이러한 오죽으로 공예품을 만드는 기술과 그 기능을 가진 사람을 ○○○이라고 한다. 최소한 5년 이상된 대나무를 베어다 5년 이상 건조시켜 대나무장을 만들고, 통대로 쓸 수 있는 것은 10년 이상 건조시킨 것으로 사용해야 오랜 시간이 지나도 터지지 않고 틀어지지 않는다. ○○○은 전통적인 공예기술로서, 1996년 12월 31일 무형유산 ○○○ 기능보유자로 윤병훈씨가 인정받아 오…","a":"오죽장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643392.jpg"},{"q":"○○○은 우리 전통 배인 한선韓船을 만드는 장인을 말한다. 한선의 경우 큰 배는 2~3명, 작은 배는 1~2명이 배의 종류에 따라 일주일에서 한 달씩 걸려 제작한다. ○○○에게는 배의 구조에 대한 지식뿐만 아니라 건축공학적 기술도 요구된다. 또한 수많은 부재를 짜 맞추어 견고한 목구조물인 배를 제작해야 하기 때문에 정확성이 필요하고 경험도 풍부해야 한다. 한선 중, 강에서 운행하는 배를 강선江船이라 한다. 강선은 바다를 운행했던 병선兵船과 조운선漕運船과는 달리 우리나라의 강에 잘 맞게 만들어졌다. 대표적인 강선은 나룻터에서 강을 건널 때 사용하는 나룻배와 거룻배이다.…","a":"조선장","c":"시도무형유산","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643627.jpg"},{"q":"호남의 지붕으로 불리는 ○○○○은 도요지의 보고이다. ○○○○에서도 도요지의 밀집도가 가장 높은 곳은 전북 진안군으로, 옹기의 몸을 이루는 태토가 많고 땔감이 풍성하여 옹기생산이 왕성하였다. 지정학적 이점이나 문화접변 지역으로서의 역동성이 ○○○○ 지역의 옹기문화에 내재되어 있으며 이는 해당 지역 옹기점 관습과 옹기의 조형성에서 구체적으로 드러난다. 현재 전북 진안군 백운면 평장리의 손내옹기도 옛날 화려했던 ○○○○ 도자문화의 전통과 그 맥락을 같이하며, 마을지명과 관계된 지역 옹기의 역사성, 지속성이 현재까지도 유효하여 ○○○○○ 옹기를 생산해오고 있는 대표적인 옹…","a":"진안고원형옹기장","c":"시도무형유산","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2017090311300300.jpg"},{"q":"○○○고법(鼓法)은 ○○○가 정착한 조선 중기 이후에 생겨난 것으로 ○○○에 맞추어 고수(북치는 사람)가 북으로 장단을 쳐 반주하는 것을 말한다. 고법은 ○○○의 반주이기 때문에 고수를 내세우는 일이 없어 조선시대에는 이름난 명고수가 드물었다. 또한 고수를 ○○○수업의 한 방편으로 여겨 고법의 발달은 미미하였다. 조선 후기에 들어 ○○○가 매우 다양한 특성을 지니고 발전함에 따라 고법도 발전하나, 19세기 말에 이르러서야 전문적인 고수들이 나와 고법의 비약적인 발전이 있게 된다. ○○○고법의 이론은 여러 가지가 있으나 크게 자세론(姿勢論), 고장론(鼓長論), 연기론(…","a":"판소리(고법)","c":"시도무형유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644448.jpg"},{"q":"○○○이란 끈목을 이용해 여러 가지 종류의 매듭을 만들거나 술을 다는 기술을 가진 사람을 말한다. 끈목은 여러 가닥의 실을 합해서 3가닥 이상의 끈을 엮는 것을 말하며, 술이란 끈이나 매듭의 아래에 장식을 위해 다는 것으로 각종 악기, 불교용기 등에 쓰였다. 복식이나 의식도구 장식으로 사용되는 매듭은 격답, 결자라고도 한다. 매듭의 기원은 원시시대부터 볼 수 있으나 그 목적이 장식을 위한 것이든, 실용적인 것이든 오늘날까지 이어져온 매듭의 기법은 삼국시대에 보급되었다. 조선시대에는 국가소속의 ○○○이 있었음을『대전회통』의 기록을 통해 알 수 있다. 매듭의 재료로는 명…","a":"매듭장","c":"시도무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643389.jpg"},{"q":"농요란 농민들이 힘들고 바쁜 일손으로부터 피로를 잊고 능률을 올리기 위해 부르는 노래로, 들노래 또는 농사짓기소리라고도 한다. 예천 ○○○○는 경북 예천군 예천읍 통명리의 농민들이 매년 모심기를 할 때 힘겨운 노동으로 인한 고달픔을 해소하기 위하여 부르는 농요로 조선 중기에 시작된 것으로 추정된다. 모심기할 때 부르는 <아부레이수나>와 모를 다 심고 논에서 나오면서 부르는 <도움소소리>, 논을 맬 때 부르는 <애벌매기소리>와 <상사디야>, 논을 다 매고 나오면서 부르는 <방애소리>·<에이용소리>, 집으로 돌아오면서 부르는 <캥마쿵쿵노세>, 마당논매기, 타작소리인 <봉…","a":"예천통명농요","c":"국가무형유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624024.jpg"},{"q":"일상적으로 사용하는 기물이나 용기에 옻칠을 하면 습기와 병충해의 피해를 막아 줄 뿐만 아니라 고온에도 잘 견디게 해 준다. 이런까닭에 선사시대부터 칠기가 널리 사용되었고, 역사시대로 들어오면서 화려한 보석으로 장식한 칠기들이 등장했다. 통일신라시대에는 값비싼 서역의 주옥珠玉이나 거북등껍데기 등으로 장식한 칠기가 등장하였고, 흥덕왕 9년(834)에는 사치금지령이 내려진다. 그 이후로 칠기의 장식에는 주변에서 흔히 구할 수 있는 조개껍데기가 이용되었다. 즉 나전칠기가 우리나라 유일의 장식칠기가 된 것이고, 그 전통이 지금까지 이어져 오고 있다. 보유자 배금용은 전북 고창…","a":"나전칠기장(칠장)","c":"시도무형유산","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643658.gif"},{"q":"시조창은 시조시(우리나라 고유의 정형시)를 가사로 하여 노래부르는 것을 말하며, ‘시절가’, ‘시절단가’, ‘단가’라고도 한다. 가장 오래된 기록은 영조(재위 1724∼1776) 때 학자 신광수의『석북집』「관서악부」로 이세춘이 시조에 장단을 붙였다는 시가 나온다. 순조(재위 1800∼1834) 때 간행된『유예지』와『구라철사금자보』에서는 시조의 악보가 처음으로 나타난다. 그 후 가곡의 영향을 받아서 시조곡조가 보급됨에 따라 지역적 특징을 지니고 나뉘게 되었다. ○○○○는 경상도를 중심으로 한 시조창이다. 평시조와 사설시조가 가장 많고, 뚝뚝 끊어지게 불러서 경상도 특유…","a":"영제시조","c":"시도무형유산","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643473.jpg"},{"q":"감내 ○○○○○는 밀양 감내에서 정월 대보름을 전후하여 마을 사람들이 시합으로 즐기던 놀이로 일반적인 마을 단위 줄싸움의 변형된 놀이라 할 수 있다. 유래에 대하여는 옛부터 감천지역에 게가 많아 서로 좋은 게잡이터를 차지하려고 싸워 인심이 나빠지자 이를 해결하기 위해 마을 어른들이 게 모양의 줄을 만들어서 당겨 이긴 편이 먼저 터를 잡도록 한 것이 오늘에 이르고 있다고 한다. ○○○○놀이에 앞서 당산굿으로 마을의 안녕과 시합에서의 우승을 기원한다. 원줄에 곁줄을 다는 동안 밀양아리랑을 부르고 덧뵈기춤을 추어 흥을 돋우면 수농부끼리 젓줄과 대박을 당기고 밀면서 게잡이터…","a":"감내게줄당기기","c":"시도무형유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644446.jpg"},{"q":"웅상읍 명곡리를 무대로 이어져 오는 ○○○○○는 마을 농사꾼들이 공동으로 농사일을 마치고 마을에서 농사가 제일 잘 된 집을 장원가로 선정하면 그 장원가가 낸 술과 음식의 장원턱을 나눠 먹으면서 며칠동안 한 해 농사일의 힘겨움을 풀고 풍년을 구가한다는 내용을 상황의 순서와 동작에 따라 소리를 곁들여 입체화한 놀이이다. 이 놀이는 힘겨운 농사일을 마을 공동으로 해내는 작업과정과 당시 농경의례를 잘 보여 준다. ○○○○○는 산업화에 의해 사라지려던 것을 마을의 60∼80대 노인들이 주축이 돼 재현했다. 노인들이 직접 참여하여 놀이가 소박하나 짜임새가 있고 소리도 수준에 도…","a":"웅상농청장원놀이","c":"시도무형유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644514.jpg"},{"q":"○○○은 짚과 풀로 전통 생활용구와 농업 도구, 민속신앙 도구 등을 만드는 기술이다. 재료의 변화로 잊혀져가는 기술이 돼가고 있다. 곡성 임채지 장인이 전통 짚풀공예 기술을 원형으로 체득해 전승해 오고 있다.","a":"초고장","c":"시도무형유산","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101018033400.JPG"},{"q":"문경시 산북면 대상리 주변에 한데 모여 살고 있는 장수 황씨 후예들이 빚어 먹던 술로 손님을 대접할 때도 사용했던 유명한 술이다. 약 200년 전 장수 황씨들은 모두 집안살림이 넉넉하고 생활이 호화로와서 보다 향기롭고 맛이 있는 술을 빚기 시작했다. 그중 황의민이란 시를 즐기는 풍류가가 자기집에서 빚은 술에 자기 시호인 ‘호산’과 술에 취했을 때 홍취를 느끼게 하는 춘색을 상징하는 ‘춘’자를 따서 ‘호산춘’이라고 이름을 지었다고 한다. 호산춘은 멥쌀, 찹쌀, 곡자, 솔잎, 물로 담그고 술이 완성되는 기간은 약 30일이 걸린다. 이 술은 매우 향기롭고 약간 짠득한 끈기…","a":"문경호산춘","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644354.jpg"},{"q":"○○○는 고려시대부터 전해 내려온 궁중술로, 조선시대에 이르러 순조(재위 1800∼1834)의 딸인 복온 공주가 안동 김씨댁에 시집오면서 그 가문에 대대로 이어져 내려오게 되었다고 한다. 정월의 첫 돼지날에 담기 시작하여 돼지날마다 세 번에 걸쳐 빚는다고 해서 ○○○라고 하는데 그 기간이 100여 일 걸린다고 하여 백일주라고도 하며, 정월 첫 돼지날에 담가 버들가지가 날릴 때쯤 먹는다고 하여 유서주(柳絮酒)라고도 부른다. 『동국이상국집』, 『산림경제』등의 문헌에 그 제조방법이 기록되어 있는데, 서울로 들어오는 쌀이 ○○○를 담그는데 쏠리지 않도록 막아달라는 상소의 기…","a":"삼해주","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643380.jpg"},{"q":"‘○○○’은 종이, 나무, 가죽 등의 바탕소재를 인두로 지져서(烙) 산수화, 화조화 등의 그림(畵)을 그리는 기술과 그 기능을 보유한 장인을 말한다. 우리나라 낙화에 대한 기원은 조선후기 실학자 이규경(李圭景, 1788~1863)이 쓴 ｢오주연문장전산고(五洲衍文長箋散稿)｣에 수록된 ‘낙화변증설(烙畵辨證設)’에서 찾을 수 있으며, 19세기 초부터 전북특별자치도 임실 지역을 중심으로 전승되어 왔다. 한국의 낙화기법은 본래 전통회화에 바탕을 두고 있기 때문에 기본 화법은 전통 수묵화 화법과 크게 다르지 않다. 다만 동양화의 부벽준(斧劈皴), 우점준(雨點皴) 등과 같은 각종…","a":"낙화장","c":"국가무형유산","r":"충청북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2018122811210200.jpg"},{"q":"인천지역에서 전승되어 온 수륙재는 49재, 백일재, 기재, 담재, 수륙재, 예수재, 백종재, 외왕재, 산신재, 용왕재, 조왕재, 신중재, 제석재 등이 있고 모든 재를 천도재라 한다. ○○○○○ 의식이 타지역과 다른점은 소리부분이다. 타지역 소리는 5음을 사용하는 반면 ○○○○○는 간성이란 소리를 곁들여 6가지 소리를 낸다. 또한 의식 중 회심곡 소리와 가사가 타지역과 달리 서민들과 어업에 종사하는 어부들의 애환을 기리는 간절한 음절이 나온다. 이는 바다에 나아가 고기를 잡으며 어부들이 슬프거나 흥겨울때 부르는 노랫가락의 영향을 받았기 때문이며 이런 점이 인천지역 수륙…","a":"인천수륙재","c":"시도무형유산","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016080811122900.JPG"},{"q":"○○○는 처용가면을 쓰고 추는 궁중무용이다. ○○○의 기원은 정확히 알 수 없지만, 통일신라 헌강왕(재위 875∼886) 때 처용이 아내를 범하려던 역신(疫神 : 전염병을 옮기는 신) 앞에서 자신이 지은 노래를 부르며 춤을 춰서 귀신을 물리쳤다는 설화를 바탕으로 하고 있다. ○○○는 5명이 동서남북과 중앙의 다섯 방향을 상징하는 옷을 입고 추는데, 동쪽은 파란색, 서쪽은 흰색, 남쪽은 붉은색, 북쪽은 검은색, 중앙은 노란색이다. 춤의 내용은 음양오행설의 기본정신을 기초로 하여 악운을 쫓는 의미가 담겨 있다. 춤사위는 화려하고 현란하며, 당당하고 활기찬 움직임 속에서…","a":"처용무","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623194.jpg"},{"q":"○○○○○은 400여년 동안 주민의 안녕과 결속을 위하고 대동의식을 고취시켜 온 서울의 마을굿으로, 서울시 중랑구 신내동 산 141번지에 위치한 ○○○의 도당에서 음력 3월 3일(삼짇날)에 지내는 마을굿이다. ○○○○○은 처음에 중화동, 상봉동, 신내동이 함께 힘을 합쳐 지내오다가 근래에는 마을을 나누어 한 해는 신내동이 다음 해에는 중화동과 상봉동이 ○○○을 주관해 오다가 최근부터 중랑문화원의 ○○○○○제 보존위원회를 중심으로 매년 개최되고 있다. 2005년 1월 10일 서울시무형유산 종목으로 지정되었다. 당주 무녀 보유자로는 신위행이 2008년 3월 17일에 인정…","a":"봉화산도당굿","c":"시도무형유산","r":"서울특별시","s":"중랑구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643399.jpg"},{"q":"제주에서 식수 운반도구로 사용되는 허벅을 만드는 기능이나 그 기능을 가진 사람을 말한다. 허벅은 전통적으로 제주에서 사용되는 식수 운반도구로서 제주의 자연 환경과 인문적 배경에서 자연 발생된 특유의 양식으로 제작되었다. 특히 유약을 바르지 않고 ○○○에서 나는 점토만을 사용하여 독특한 제작기법과 감각으로 실용성을 토대로 만들어졌다. 점차 기능에 따라 독특한 모양으로 만들어지고 색깔이나 문양에서도 ○○○만의 특징을 가지고 있다. 제주의 옹기를 만드는 집안에서 태어나 15세부터 옹기 만드는 기술을 익힌 신창현 씨는 허벅의 원형 보존과 그 기술의 전승에 힘쓰고 있다. ※…","a":"제주도 옹기장","c":"시도무형유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644712.jpg"},{"q":"○○○는 평안도 지방에서 전승되어 오는 술로 술의 향기가 문배나무의 과실에서 풍기는 향기와 같아 붙여진 이름이다. ○○○는 해방전에는 평양 대동강 유역의 석회암층에서 솟아나는 지하수를 사용하였다고 한다. 원료는 밀·좁쌀·수수이며, 누룩의 주원료는 밀이다. 술의 색은 엷은 황갈색을 띠며 문배향이 강하고, 알코올 도수는 본래 40도 정도이지만 증류 및 숙성이 끝난 ○○○는 48.1도에 달하므로 장기간 저장이 가능하다. 보통 6개월∼1년 동안 숙성시켜 저장하는데 문배나무의 과실을 전혀 사용하지 않고도 문배향을 풍기는 특징이 있다.","a":"문배주","c":"국가무형유산","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623322.jpg"},{"q":"굿은 형태에 따라 크게 선굿과 ○○○으로 구분할 수 있다. 선굿은 무당이 서서하는 일반적인 굿을 뜻하고, ○○○은 충청지역에서 무당이 앉아서 주로 경을 읽는다하여 붙여진 이름이다. 역사적으로 불교, 도교 등 다른 종교와 상호관계를 맺으며 형성되었을 것으로 추정되는 ○○○은 굿에 춤이 더해져 한국 무속의 한 갈래로서 오랜 역사를 지니고 있다. 대전을 중심으로 한 충청지역은 ○○○의 전통이 강해 우리나라에서 유일한 ○○○ 중심 무속문화권을 이룬다. ○○○○○은 안택굿과 미친굿, 설경이 있는데, 안택굿과 미친굿의 예능보유자는 방성구로 고(故) 신석봉으로부터 전수받은후, 1…","a":"대전의앉은굿","c":"시도무형유산","r":"대전광역시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643565.jpg"},{"q":"○○은 닥나무와 닥풀[황촉규(黃蜀葵)]을 주재료로 하여 전통한지를 제작하는 장인을 말한다. 우리의 전통한지는 두 장을 겹쳐서 한 장의 종이를 만들며, 중국의 걸러뜨기, 일본의 쌍발뜨기와 달리, 외발뜨기 방식을 사용한다. 신라시대부터 만들었던 한지는 고려시대에 중국 송나라에서 극찬받기도 하였다. 조선시대에는 각 분야의 장인중 ○○의 수가 가장 많을 정도로 기반이 탄탄하였으나 일제강점기때 일본에서 서양종이를 대량 생산하는 방식을 들여온 후 지금은 일부에서만 명맥을 유지하고 있다. 12~2월에 닥나무 1년생을 채취하여 찌기, 닥나무껍질 벗기기(백피), 잿물로 삶기, 세척…","a":"지장","c":"시도무형유산","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091316484200.jpg"}]);